/* ================================================================
   shared.js — gemeinsamer Code für Firnspur (Skitour) & Fixseil
   (Hochtour/MSL). Wird von beiden Apps eingebunden, damit Agenda,
   Sortierung, Regionen und Basis-Hilfsfunktionen nur an einer
   Stelle gepflegt werden müssen.
   ================================================================= */

/* ================= Debug-Log ================= */
let debugLog = [];
let debugPanelOpen = false;
function dlog(message, kind){
  const entry = {t: new Date().toLocaleTimeString('de-CH'), message, kind: kind||'info'};
  debugLog.push(entry);
  if(debugLog.length > 60) debugLog.shift();
  if(kind==='err') console.error(message); else console.log(message);
  if(debugPanelOpen) renderDebugPanel();
}
function toggleDebugPanel(){
  debugPanelOpen = !debugPanelOpen;
  renderDebugPanel();
}
function renderDebugPanel(){
  const root = document.getElementById('debug-panel-root');
  if(!debugPanelOpen){ root.innerHTML = ''; return; }
  const rows = debugLog.slice().reverse().map(e=>
    `<div class="row ${e.kind==='err'?'err':(e.kind==='ok'?'ok':'')}">[${e.t}] ${esc(e.message)}</div>`
  ).join('') || '<div class="row">Noch keine Einträge.</div>';
  root.innerHTML = `<div class="debug-panel">
    <div class="head"><strong>Diagnose-Log</strong><button onclick="debugLog=[];renderDebugPanel();">leeren</button></div>
    ${rows}
  </div>`;
}

/* ================= Firebase ================= */
const FIREBASE_URL = 'https://firnspur-default-rtdb.europe-west1.firebasedatabase.app';
const STORAGE_BUCKET = 'firnspur.firebasestorage.app'; // Cloud Storage, appübergreifend geteilt
// Foto-Scan für Kletterrouten: URL der Cloud Function, siehe functions/README.md.
// Leer = noch nicht deployt — der "Foto scannen"-Knopf zeigt dann nur eine Fehlermeldung,
// der Rest der App bleibt davon komplett unberührt. Bewusst "var" (statt "const"), damit
// Tests sie über window.SCAN_KLETTERROUTEN_URL überschreiben können.
var SCAN_KLETTERROUTEN_URL = 'https://europe-west1-firnspur.cloudfunctions.net/scanKletterrouten';
// Wie SCAN_KLETTERROUTEN_URL, aber für ein Foto mit MEHREREN Sektoren gleichzeitig (z. B.
// eine ganze Führerbuch-Seite mit Sektor A–G) — siehe functions/README.md.
var SCAN_KLETTERGEBIET_URL = 'https://europe-west1-firnspur.cloudfunctions.net/scanKlettergebiet';
// Foto-Scan für einen einzelnen Zustieg/Abstieg (Hütte, Tour oder Sektor — gleiche
// Feldstruktur überall) — siehe functions/README.md.
var SCAN_ZUSTIEG_URL = 'https://europe-west1-firnspur.cloudfunctions.net/scanZustieg';
// Tour aus Foto (Führerseite, Screenshot, Notiz): ganze Tour vorschlagen, Felder mit Originalzitat.
var SCAN_TOUR_URL = 'https://europe-west1-firnspur.cloudfunctions.net/scanTour';
async function fbGet(path){
  try{
    await ensureValidAuthToken();
    const authParam = authState.idToken ? ('?auth=' + authState.idToken) : '';
    const res = await fetch(FIREBASE_URL + '/' + path + '.json' + authParam);
    if(!res.ok){ fsGetFailed.add(path); dlog('Firebase GET fehlgeschlagen ('+res.status+'): '+path, 'err'); return null; }
    let data = await res.json();
    fsGetFailed.delete(path);
    // Lokale Merker aus der Datenbank nie übernehmen (ältere Fassungen enthielten _unsynced)
    if(data && typeof data === 'object' && !Array.isArray(data) && !/^versions\//.test(path)){
      if(FS_VERSIONED.includes(path) || path === 'orte') Object.keys(data).forEach(id=>{ if(data[id] && typeof data[id] === 'object') data[id] = fsStripLocal(data[id]); });
      else if(fsVersionedSplit(path)) data = fsStripLocal(data);
    }
    if(typeof FS_OWNED_COLLS !== 'undefined' && FS_OWNED_COLLS.includes(path) && path === fsTourColl()) setTimeout(()=> fsSugLoad(path), 0);
    if(FS_VERSIONED.includes(path) && data && typeof data === 'object') Object.keys(data).forEach(id=>{ fsBaseStamp.set(path + '/' + id, (data[id] && data[id].updatedAt) || ''); fsBaseRemember(path + '/' + id, data[id]); });
    else{ const v = fsVersionedSplit(path); if(v && !FS_FILE_COLLS.includes(v.coll) && data && typeof data === 'object'){ fsBaseStamp.set(path, data.updatedAt || ''); fsBaseRemember(path, data); } }
    return data;
  }catch(e){
    fsGetFailed.add(path);
    dlog('Firebase GET Fehler für "'+path+'": '+(e && e.message ? e.message : e), 'err');
    return null;
  }
}
// Pfade, deren letztes Lesen scheiterte (Netzfehler) – im Unterschied zu «leer» (null)
const fsGetFailed = new Set();
// Beim Laden: Konnte EINE Sammlung nicht gelesen werden (schwaches Netz), deren Gerätekopie nehmen
// statt sie als leer zu behandeln (sonst Rettung/Überschreiben mit alten Kopien, leere Auswahllisten).
function fsLoadOrCache(path, obj, cached, key){
  if(!fsGetFailed.has(path)) return obj;
  const cap = key.charAt(0).toUpperCase() + key.slice(1);
  const arr = [...((cached && cached[key]) || []), ...((cached && cached['trashed' + cap]) || [])].filter(x=> x && x.id);
  fsRememberCachedBases(path, arr);
  if(typeof showToast === 'function') setTimeout(()=> showToast('Ein Teil konnte nicht geladen werden (Internet?) – zeigt dafür die Kopie auf diesem Gerät.', true), 800);
  dlog('Laden: ' + path + ' aus der Gerätekopie (' + arr.length + ')', 'err');
  const out = {}; arr.forEach(x=>{ out[x.id] = x; });
  return out;
}
// Schutz: nie eine ganze Sammlung überschreiben oder löschen. Jeder Schreibpfad endet mit einer
// gültigen ID (z. B. "fixseil/tours/t_abc"); eine leere ID ("fixseil/tours/") würde sonst die
// komplette Sammlung durch einen einzelnen Eintrag ersetzen.
// Sammlungen selbst (z. B. "fixseil/tours") dürfen nie als Ganzes geschrieben oder gelöscht werden
const FB_COLLECTION_ROOTS = ['fixseil', 'wandern', 'versions', 'fixseil/tours', 'fixseil/sektoren', 'fixseil/klettergebiete', 'fixseil/gipfel',
  'fixseil/huts', 'fixseil/gpxTracks', 'fixseil/gpxTracksAlt', 'wandern/tours', 'wandern/gebiete', 'wandern/gpxTracks', 'wandern/gpxTracksAlt'];
function fbPathOk(path){
  const segs = String(path || '').split('/');
  return segs.length >= 2 && !FB_COLLECTION_ROOTS.includes(String(path)) && !/^versions\/[^/]+$/.test(String(path))
    && segs.every(s=> s && s !== 'undefined' && s !== 'null' && !/[.#$\[\]]/.test(s));
}
/* Versionen und Schutz bei gleichzeitigem Bearbeiten (Touren, Hütten, Gebiete, Sektoren, Gipfel,
   Termine): Vor jedem Überschreiben oder Löschen wird die bisherige Fassung unter versions/…
   abgelegt (nur hinzufügen, nie überschreiben) und lässt sich in der App zurückholen. Hat jemand
   anderes den Eintrag geändert, seit dieses Gerät ihn geladen hat, fragt die App nach, statt
   still dessen Änderungen zu überschreiben. */
const FS_VERSIONED = ['tours', 'huts', 'gebiete', 'agenda', 'orte', 'fixseil/tours', 'fixseil/sektoren', 'fixseil/klettergebiete', 'fixseil/gipfel', 'fixseil/huts', 'wandern/tours', 'wandern/gebiete',
  'gpxTracks', 'fixseil/gpxTracks', 'wandern/gpxTracks',
  'hutGpxTracksSummer', 'hutGpxTracksWinter', 'hutAccessRouteGpxTracks', 'mslAccessRouteGpxTracks', 'mslDescentRouteGpxTracks',
  'sektorAccessRouteGpxTracks', 'sektorDescentRouteGpxTracks'];
// GPX-Originaldateien aus einem Formular: erst beim Speichern des Eintrags hochladen, beim Verwerfen
// des Formulars fallen lassen (siehe confirmDiscardIfDirty). So passen Linie und Datei immer zusammen.
const fsPendingFiles = new Map(); // Pfad → Wert
function fsQueueFile(path, value){ fsPendingFiles.set(path, value); }
function fsDropPendingFiles(){ fsPendingFiles.clear(); }
async function fsFlushPendingFiles(entryId, entry){
  // Nur die Dateien des eben gespeicherten Eintrags (nicht die eines anderen, noch offenen Formulars).
  // Routen-Dateien tragen die Routen-ID: gehört, wenn die Route im gespeicherten Eintrag steht.
  let txt = ''; try{ txt = entry ? JSON.stringify(entry) : ''; }catch(e){}
  const list = Array.from(fsPendingFiles.entries()).filter(([p])=>{
    const id = p.split('/').pop();
    return !entryId || id === entryId || p.split('/').slice(-2, -1)[0] === entryId || (id && txt.indexOf('"' + id + '"') >= 0);
  });
  list.forEach(([p])=> fsPendingFiles.delete(p));
  const res = await Promise.all(list.map(([p, v])=> fbSet(p, v).catch(()=> false)));
  if(res.some(x=> !x)){ list.forEach(([p, v], i)=>{ if(!res[i]) fsPendingFiles.set(p, v); }); if(typeof showToast === 'function') showToast('Eine GPX-Originaldatei konnte nicht gespeichert werden (Internet?).', true); }
}
const FS_FILE_COLLS = ['gpxTracks', 'fixseil/gpxTracks', 'wandern/gpxTracks', 'hutGpxTracksSummer', 'hutGpxTracksWinter', 'hutAccessRouteGpxTracks', 'mslAccessRouteGpxTracks', 'mslDescentRouteGpxTracks', 'sektorAccessRouteGpxTracks', 'sektorDescentRouteGpxTracks'];
const fsBaseStamp = new Map(); // Pfad → updatedAt beim Laden
function fsVersionedSplit(path){
  const i = String(path).lastIndexOf('/');
  const coll = path.slice(0, i);
  return FS_VERSIONED.includes(coll) ? {coll, id: path.slice(i + 1), key: coll.replace(/\//g, '_')} : null;
}
async function fsRawFetch(path, opts){
  await ensureValidAuthToken();
  const authParam = authState.idToken ? ('?auth=' + authState.idToken) : '';
  return fetch(FIREBASE_URL + '/' + path + '.json' + authParam, opts);
}
// Bisherige Fassung sichern; Fehler hier blockieren das Speichern nicht
async function fsSaveVersion(v, cur, reason){
  try{
    const stamp = new Date().toISOString().replace(/[.:]/g, '-');
    const by = (typeof state !== 'undefined' && state.myName) || '';
    const res = await fsRawFetch('versions/' + v.key + '/' + v.id + '/' + stamp, {method:'PUT', headers:{'Content-Type':'application/json'},
      body: JSON.stringify(Object.assign(fsStripLocal(cur), {_versionAt: new Date().toISOString(), _versionBy: by, _versionReason: reason || ''}))});
    if(!res.ok) dlog('Version nicht gesichert (' + res.status + '): ' + v.key + '/' + v.id, 'err');
  }catch(e){ dlog('Version nicht gesichert: ' + (e && e.message ? e.message : e), 'err'); }
}
/* ===== Sicher speichern: drei Fassungen vergleichen =====
   Wie bei Git: Ausgangsstand (beim Laden gesehen) + meine Fassung + aktueller Stand in der Datenbank.
   Gespeichert werden nur MEINE Änderungen, eingetragen in den aktuellen Stand. Listen (Begehungen,
   Fotos, Punkte, Routen …) werden pro Eintrag zusammengeführt. Haben beide dasselbe Feld verschieden
   geändert, wird nachgefragt. Geschrieben wird nur, wenn sich der Stand seit dem Lesen nicht geändert
   hat (Firebase-ETag); sonst von vorn. Offline wird der Ausgangsstand im Gerät festgehalten. */
const fsBase = new Map(); // Pfad → JSON der zuletzt gesehenen Datenbank-Fassung
let fsEtagOff = false;    // Browser darf die Versionskennung nicht nutzen → ohne sie weiter
function fsBaseRemember(path, obj){ try{ fsBase.set(path, JSON.stringify(obj === undefined ? null : obj)); }catch(e){} }
function fsBaseGet(path){
  try{ const p = localStorage.getItem('fs-base:' + path); if(p != null) return JSON.parse(p); }catch(e){}
  const m = fsBase.get(path);
  return m === undefined ? undefined : JSON.parse(m);
}
// Offline: den Ausgangsstand vor der ERSTEN lokalen Änderung festhalten (spätere Änderungen nicht)
function fsBasePin(path){
  try{ if(localStorage.getItem('fs-base:' + path) == null && fsBase.has(path)) localStorage.setItem('fs-base:' + path, fsBase.get(path)); }catch(e){}
}
function fsBaseUnpin(path){ try{ localStorage.removeItem('fs-base:' + path); }catch(e){} }
// Vergleich wie Firebase speichert: leere Liste, leeres Objekt, '' und null = fehlt; Reihenfolge der Felder egal
function fsCanon(v){
  if(v === undefined || v === null || v === '') return null;
  if(Array.isArray(v)){ const a = v.map(fsCanon); return a.length ? a : null; }
  if(typeof v === 'object'){
    const o = {};
    Object.keys(v).sort().forEach(k=>{ const c = fsCanon(v[k]); if(c !== null) o[k] = c; });
    return Object.keys(o).length ? o : null;
  }
  return v;
}
function fsEq(a, b){ return JSON.stringify(fsCanon(a)) === JSON.stringify(fsCanon(b)); }
function fsIsPlainObj(o){ return o !== null && typeof o === 'object' && !Array.isArray(o); }
function fsIsCoordList(a){ return Array.isArray(a) && a.length > 0 && Array.isArray(a[0]); }
// Liste pro Eintrag zusammenführen (Schlüssel: id, sonst by/date/lat/lon/…, siehe fsImportKey)
function fsMergeList(b, m, t){
  b = Array.isArray(b) ? b : []; m = Array.isArray(m) ? m : []; t = Array.isArray(t) ? t : [];
  const bMap = new Map(b.map(x=> [fsImportKey(x), x])), mMap = new Map(m.map(x=> [fsImportKey(x), x]));
  const out = [], used = new Set();
  t.forEach(x=>{
    const k = fsImportKey(x);
    if(used.has(k)) return;
    used.add(k);
    const inB = bMap.has(k), inM = mMap.has(k);
    if(inB && !inM) return;                                              // von mir entfernt
    if(inM && (!inB || !fsEq(mMap.get(k), bMap.get(k)))) out.push(mMap.get(k)); // von mir geändert oder beide neu
    else out.push(x);
  });
  m.forEach(x=>{
    const k = fsImportKey(x);
    if(used.has(k)) return;
    used.add(k);
    if(!bMap.has(k) || !fsEq(x, bMap.get(k))) out.push(x);               // neu von mir, oder von mir geändert und anderswo entfernt
  });
  return out;
}
function fsMergeField(b, m, t, path, conflicts){
  // Fehlt ein Feld in meiner Fassung ganz, habe ich es nicht angefasst (bewusstes Leeren setzt '' oder [])
  if(m === undefined) return t;
  if(fsEq(m, b)) return t;
  if(fsEq(t, b)) return m;
  if(fsEq(m, t)) return m;
  if(Array.isArray(m) && Array.isArray(t) && !fsIsCoordList(m) && !fsIsCoordList(t) && (b == null || Array.isArray(b))) return fsMergeList(b, m, t);
  if(fsIsPlainObj(m) && fsIsPlainObj(t) && (b == null || fsIsPlainObj(b))) return fsMerge3(b || {}, m, t, path, conflicts);
  conflicts.push({path, mine: m, theirs: t});
  return m;
}
function fsMerge3(b, m, t, prefix, conflicts){
  const out = {};
  new Set([...Object.keys(b || {}), ...Object.keys(m || {}), ...Object.keys(t || {})]).forEach(k=>{
    if(!prefix && (k === 'updatedAt' || k === 'updatedBy')){ if(t && t[k] !== undefined) out[k] = t[k]; return; }
    if(!prefix && k[0] === '_'){ if(m && m[k] !== undefined) out[k] = m[k]; return; } // nur lokal
    const v = fsMergeField(b ? b[k] : undefined, m ? m[k] : undefined, t ? t[k] : undefined, prefix ? prefix + '.' + k : k, conflicts);
    if(v !== undefined && v !== null) out[k] = v;
    else if(v === null && ((m && m[k] === null) || (t && t[k] === null))) out[k] = null;
  });
  return out;
}
const FS_FIELD_LABELS = {name:'Name', tourName:'Name', notes:'Notizen', description:'Beschreibung', crux:'Schlüsselstelle', special:'Spezielles',
  ascent:'Aufstieg', descent:'Abstieg/Abfahrt', approach:'Anfahrt', tourLink:'Link zur Tour', gpxLink:'GPX-Link', trackSimplified:'GPX-Track',
  manualTrack:'Gezeichnete Linie', targetAltitude:'Gipfelhöhe', elevationGain:'Höhenmeter Aufstieg', elevationLoss:'Höhenmeter Abstieg',
  duration:'Zeitbedarf', descentDuration:'Zeit Abstieg', difficulty:'Schwierigkeit', region:'Region', status:'Status', date:'Datum', title:'Titel',
  material:'Material', exposition:'Exposition', gefahren:'Gefahren', glacier:'Gletscher', crevasseRisk:'Spaltengefahr', ropeType:'Seil',
  ropeLength:'Seillänge', climbGrade:'Klettergrad', subregion:'Teilgebiet', approachTypes:'Anfahrt', stayTypes:'Übernachtung', points:'Punkte',
  completions:'Begehungen', topoImages:'Topo-Bilder', altTracks:'Weitere Routen', moreLinks:'Weitere Links', hutId:'Hütte', gebietId:'Gebiet',
  summitIds:'Gipfel', participants:'Teilnehmende', conditions:'Verhältnisse', routeName:'Routenname'};
function fsConflictShort(v){
  if(v === undefined || v === null || v === '') return '(leer)';
  if(fsIsCoordList(v)) return 'Linie mit ' + v.length + ' Punkten';
  if(Array.isArray(v) && !v.length) return '(leer)';
  if(Array.isArray(v) && v.every(x=> typeof x !== 'object')) return v.join(', ');
  const s = typeof v === 'string' ? v : JSON.stringify(v);
  return s.length > 140 ? s.slice(0, 140) + ' …' : s;
}
function fsSetPath(obj, path, val){
  const parts = path.split('.'); let o = obj;
  for(let i = 0; i < parts.length - 1; i++){ if(!fsIsPlainObj(o[parts[i]])) o[parts[i]] = {}; o = o[parts[i]]; }
  if(val === undefined) delete o[parts[parts.length - 1]]; else o[parts[parts.length - 1]] = val;
}
// Rückfrage pro Feld, das beide verschieden geändert haben
function fsResolveConflicts(result, conflicts, cur){
  const me = (typeof state !== 'undefined' && state.myName) || '';
  const who = cur && cur.updatedBy ? (cur.updatedBy === me ? 'dir auf einem anderen Gerät' : cur.updatedBy) : 'jemand anderes';
  const title = (cur && (cur.name || cur.tourName || cur.title)) || 'Dieser Eintrag';
  let tookTheirs = 0;
  conflicts.forEach(c=>{
    const top = c.path.split('.')[0];
    const label = FS_FIELD_LABELS[top] || top;
    const keepMine = window.confirm(`«${title}»: ${label} wurde inzwischen auch von ${who} geändert.\n\nDeine Fassung:\n${fsConflictShort(c.mine)}\n\nAndere Fassung:\n${fsConflictShort(c.theirs)}\n\nOK: deine behalten\nAbbrechen: die andere übernehmen\n(Beide bleiben unter «Frühere Versionen» erhalten.)`);
    if(!keepMine){ fsSetPath(result, c.path, c.theirs); tookTheirs++; }
  });
  return tookTheirs;
}
// Notbremse: Was ginge beim Speichern gegenüber dem aktuellen Stand verloren? Erfasst grössere
// Verluste (ausgefülltes Feld wird leer, Linie fällt weg oder schrumpft stark, mehrere Listeneinträge
// auf einmal, langer Text stark gekürzt). Einzelne entfernte Listeneinträge gelten als bewusst.
const FS_LOSS_IGNORE = new Set(['updatedAt', 'updatedBy', 'deletedAt', 'deletedBy', 'status', 'conditions', 'summitIdsParked',
  'hutId', 'gebietId', 'sektorId', 'klettergebietId', 'createdAt', 'createdBy']);
const FS_LOSS_STRICT = new Set(['points', 'altTracks', 'topoImages', 'erfahrungen', 'accessRoutes', 'descentRoutes', 'kletterrouten', 'orte', 'moreLinks']);
function fsDetectLosses(cur, res){
  const out = [];
  Object.keys(cur || {}).forEach(k=>{
    if(k[0] === '_' || FS_LOSS_IGNORE.has(k)) return;
    const c = cur[k], r = res ? res[k] : undefined, label = FS_FIELD_LABELS[k] || k;
    if(fsCanon(c) === null) return;
    if(fsIsCoordList(c)){
      const n = Array.isArray(r) ? r.length : 0;
      if(n < c.length * 0.5) out.push({key:k, restore:c, text: n ? `${label}: von ${c.length} auf ${n} Punkte gekürzt` : `${label} (${c.length} Punkte)`});
      return;
    }
    if(Array.isArray(c)){
      const keep = new Set((Array.isArray(r) ? r : []).map(fsImportKey));
      const lost = c.filter(x=> !keep.has(fsImportKey(x)));
      // Punkte, Routen, Fotos, Erfahrungen, Orte: schon ein einzelner verschwundener Eintrag fragt nach
      if(lost.length >= (FS_LOSS_STRICT.has(k) ? 1 : 2)) out.push({key:k, restore:(Array.isArray(r) ? r : []).concat(lost), text: `${label}: ${lost.length === 1 ? '1 Eintrag' : lost.length + ' Einträge'}${k === 'points' ? ' (' + lost.map(x=> (x && x.label) || 'ohne Namen').join(', ') + ')' : ''}`});
      return;
    }
    if(fsCanon(r) === null){ out.push({key:k, restore:c, text: `${label}${typeof c === 'string' && c.length > 30 ? ' (' + c.length + ' Zeichen)' : ''}`}); return; }
    if(typeof c === 'string' && typeof r === 'string' && c.length >= 40 && r.length < c.length * 0.5) out.push({key:k, restore:c, text: `${label}: von ${c.length} auf ${r.length} Zeichen gekürzt`});
  });
  return out;
}
/* ===== Eigentümer und Vorschläge (Touren) =====
   Eine Tour gehört ihrem Ersteller (owner, sonst createdBy; ohne Angabe FS_DEFAULT_OWNER). Wer nicht
   Eigentümer oder Mitbearbeiter ist, darf ERGÄNZEN (leeres Feld füllen, Listeneinträge hinzufügen,
   eigene Einträge entfernen) direkt. ÄNDERN oder ENTFERNEN von Bestehendem wird ein Vorschlag unter
   suggestions/<Sammlung>/<TourId>/<Id>; die Tour bleibt so, bis der Eigentümer annimmt.
   Gilt nicht, wenn der Eigentümer die Tour auf «alle dürfen ändern» (open) gestellt hat. */
const FS_DEFAULT_OWNER = 'Dome';
// Admins: dürfen jede Tour direkt ändern und löschen und Vorschläge überall annehmen/ablehnen.
// Erkannt am eingegebenen Namen (wie Eigentümer), nicht an einem eigenen Login.
const FS_ADMINS = ['Dome'];
function fsIsAdmin(me){ const k = fsNameKey(me !== undefined ? me : (typeof state !== 'undefined' && state.myName)); return !!k && FS_ADMINS.some(a=> fsNameKey(a) === k); }
const FS_OWNED_COLLS = ['tours', 'fixseil/tours', 'wandern/tours'];
const FS_OWNER_FIELDS = ['owner', 'editors', 'open'];
const FS_SUG_EMPTY = '(leer)'; // Firebase speichert leere Listen nicht — «leeren» als Marker
function fsNameKey(n){ return String(n || '').trim().toLowerCase(); }
function fsOwnerOf(t){
  const o = (t && (t.owner || t.createdBy)) || '';
  return (!o || o === 'Name') ? FS_DEFAULT_OWNER : o;
}
function fsCanEditDirect(t, me){
  if(!t) return true;
  me = fsNameKey(me !== undefined ? me : (typeof state !== 'undefined' && state.myName));
  if(!me) return false;
  if(fsIsAdmin(me)) return true;
  if(t.open === true) return true;
  if(fsNameKey(fsOwnerOf(t)) === me) return true;
  return Array.isArray(t.editors) && t.editors.some(e=> fsNameKey(e) === me);
}
// Eigentümer-Rechte (Vorschläge entscheiden, Eigentümerfelder): Eigentümer oder Admin
function fsIsOwner(t, me){ const m = me !== undefined ? me : (typeof state !== 'undefined' && state.myName); return fsNameKey(fsOwnerOf(t)) === fsNameKey(m) || fsIsAdmin(m); }
function fsSugKey(coll){ return coll.replace(/\//g, '_'); }
// Trennt meine Änderungen (result gegenüber cur) in direkt erlaubte und Vorschläge.
// Gibt {changes, before} zurück und setzt die vorgeschlagenen Felder in result auf den Stand von cur.
function fsSplitForSuggestion(cur, result, me){
  const changes = {}, before = {};
  const meK = fsNameKey(me);
  new Set([...Object.keys(cur || {}), ...Object.keys(result || {})]).forEach(k=>{
    if(k[0] === '_' || k === 'updatedAt' || k === 'updatedBy' || k === 'createdAt' || k === 'createdBy') return;
    const c = cur[k], r = result[k];
    if(fsEq(c, r)) return;
    if(FS_OWNER_FIELDS.includes(k)){ if(c === undefined) delete result[k]; else result[k] = c; return; } // nur der Eigentümer
    if(k !== 'deletedAt' && k !== 'deletedBy' && fsCanon(c) === null) return;              // leeres Feld füllen = ergänzen
    if(k === 'deletedBy') return;
    if(Array.isArray(c) && Array.isArray(r) && !fsIsCoordList(c) && !fsIsCoordList(r)){
      const rKeys = new Set(r.map(fsImportKey));
      const removed = c.filter(x=> !rKeys.has(fsImportKey(x)) && !(x && typeof x === 'object' && fsNameKey(x.by || x.uploadedBy || x.addedBy) === meK && meK));
      const cMap = new Map(c.map(x=> [fsImportKey(x), x]));
      const changed = r.filter(x=> cMap.has(fsImportKey(x)) && !fsEq(cMap.get(fsImportKey(x)), x) && !(x && typeof x === 'object' && fsNameKey(x.by) === meK && meK));
      const reordered = !removed.length && r.length >= c.length && c.some((x, i)=> fsImportKey(x) !== fsImportKey(r[i]));
      if(!removed.length && !changed.length && !reordered) return;                         // nur hinzugefügt
      changes[k] = r.length ? r : FS_SUG_EMPTY; before[k] = c;
      // direkt: bisherige Einträge (unverändert) + meine neuen
      result[k] = c.concat(r.filter(x=> !cMap.has(fsImportKey(x))));
      return;
    }
    changes[k] = fsCanon(r) === null ? FS_SUG_EMPTY : r; before[k] = c === undefined ? null : c;
    if(c === undefined) delete result[k]; else result[k] = c;
  });
  if(changes.deletedAt === FS_SUG_EMPTY){ delete changes.deletedAt; delete before.deletedAt; }
  return {changes, before};
}
async function fsSaveSuggestion(coll, id, cur, changes, before){
  const me = (typeof state !== 'undefined' && state.myName) || 'Unbekannt';
  const sid = 's_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  const sug = {id: sid, by: me, at: new Date().toISOString(), entryName: cur.name || '', changes, before, status: 'offen'};
  const ok = await fbSet('suggestions/' + fsSugKey(coll) + '/' + id + '/' + sid, sug).catch(()=> false);
  if(ok){ (fsSug[coll] = fsSug[coll] || {})[id] = Object.assign({}, (fsSug[coll] || {})[id], {[sid]: sug}); }
  return ok;
}
// Geladene Vorschläge: fsSug[coll][tourId][sid]
const fsSug = {};
const fsSugLoading = {};
let fsSugAnnounced = false;
async function fsSugLoad(coll){
  if(fsSugLoading[coll]) return fsSugLoading[coll];
  fsSugLoading[coll] = fbGet('suggestions/' + fsSugKey(coll)).then(d=>{
    fsSug[coll] = d || {};
    if(!fsSugAnnounced && typeof state !== 'undefined' && state.myName){
      const mine = fsSugOpenForOwner(coll);
      if(mine.length){ fsSugAnnounced = true; setTimeout(()=> showToast(mine.length === 1 ? '1 Vorschlag zur Prüfung: ' + mine[0].name : mine.length + ' Vorschläge zur Prüfung, z.B. bei ' + mine[0].name), 1500); }
    }
    if(typeof render === 'function') render();
  }).catch(()=>{}).finally(()=>{ setTimeout(()=>{ fsSugLoading[coll] = null; }, 60000); });
  return fsSugLoading[coll];
}
function fsSugOpen(coll, id){
  const all = (fsSug[coll] || {})[id] || {};
  return Object.values(all).filter(s=> s && s.status === 'offen' && s.changes && Object.keys(s.changes).length).sort((a, b)=> (a.at || '').localeCompare(b.at || ''));
}
function fsSugOpenForOwner(coll){
  const out = [];
  Object.keys(fsSug[coll] || {}).forEach(id=>{
    const t = (state.tours || []).find(x=> x.id === id);
    if(t && fsIsOwner(t) && fsSugOpen(coll, id).length) out.push(t);
  });
  return out;
}
function fsTourColl(){ return typeof OWN_TOURS_PATH !== 'undefined' ? OWN_TOURS_PATH : 'tours'; }
function fsSugValHtml(v){ return esc(fsConflictShort(v)); }
// Box in der Tourenansicht: offene Vorschläge, für alle sichtbar
function fsSuggestionsHtml(t){
  if(!t || !t.id) return '';
  const coll = fsTourColl();
  if(!fsSug[coll]) fsSugLoad(coll);
  const list = fsSugOpen(coll, t.id);
  if(!list.length) return '';
  const owner = fsIsOwner(t), me = fsNameKey(state.myName);
  return `<div class="detail-section fs-sug">${list.map(s=>{
    const fields = Object.keys(s.changes);
    const when = new Date(s.at).toLocaleString('de-CH', {day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit'});
    return `<div class="fs-sug-card">
      <p class="fs-sug-h">Offener Vorschlag von ${esc(s.by)} · ${when}</p>
      <p class="hint" style="margin:0 0 6px;">Noch nicht übernommen — wartet auf ${esc(fsOwnerOf(t))}.</p>
      ${fields.map(f=> `<div class="fs-sug-row">
        <b>${esc(FS_FIELD_LABELS[f] || f)}</b>
        ${f === 'deletedAt' ? '' : `<span class="old">bisher: ${fsSugValHtml(s.before ? s.before[f] : null)}</span>`}
        <span class="new">neu: ${f === 'deletedAt' ? (s.changes[f] === FS_SUG_EMPTY ? 'Tour wiederherstellen' : 'Tour löschen') : fsSugValHtml(s.changes[f])}</span>
        ${owner ? `<div class="fs-sug-btns"><button type="button" class="btn" onclick="fsSugDecide('${esc(t.id)}','${esc(s.id)}','${esc(f)}',true)">Übernehmen</button><button type="button" class="btn secondary" onclick="fsSugDecide('${esc(t.id)}','${esc(s.id)}','${esc(f)}',false)">Ablehnen</button></div>` : ''}
      </div>`).join('')}
      ${owner && fields.length > 1 ? `<button type="button" class="btn" style="width:100%; margin-top:6px;" onclick="fsSugDecide('${esc(t.id)}','${esc(s.id)}','*',true)">Alles übernehmen</button>` : ''}
      ${!owner && fsNameKey(s.by) === me ? `<button type="button" class="btn secondary" style="width:100%; margin-top:6px;" onclick="fsSugWithdraw('${esc(t.id)}','${esc(s.id)}')">Vorschlag zurückziehen</button>` : ''}
    </div>`;
  }).join('')}</div>`;
}
async function fsSugWrite(coll, id, s){
  if(!Object.keys(s.changes || {}).length && s.status === 'offen') s.status = 'erledigt';
  return fbSet('suggestions/' + fsSugKey(coll) + '/' + id + '/' + s.id, s).catch(()=> false);
}
async function fsSugDecide(tourId, sid, field, accept){
  const coll = fsTourColl(), t = state.tours.find(x=> x.id === tourId);
  const s = ((fsSug[coll] || {})[tourId] || {})[sid];
  if(!t || !s || !fsIsOwner(t)) return;
  const fields = field === '*' ? Object.keys(s.changes) : [field];
  if(accept && fields.includes('deletedAt') && !confirm('Vorschlag annehmen und die Tour löschen (in den Papierkorb)?')) return;
  if(!accept && !confirm(fields.length > 1 ? 'Diese Vorschläge ablehnen?' : 'Diesen Vorschlag ablehnen?')) return;
  if(accept){
    fields.forEach(f=>{
      const v = s.changes[f], before = s.before ? s.before[f] : undefined;
      // Listen: nur die vorgeschlagene Änderung anwenden (entfernt/neu gegenüber damals) – Einträge,
      // die seither dazugekommen sind, bleiben (sonst würde die alte Liste sie still entfernen)
      if(Array.isArray(t[f]) && (Array.isArray(v) || v === FS_SUG_EMPTY) && Array.isArray(before)){
        const sug = Array.isArray(v) ? v : [];
        const sugK = new Set(sug.map(fsImportKey)), befK = new Set(before.map(fsImportKey));
        const removed = new Set(before.filter(x=> !sugK.has(fsImportKey(x))).map(fsImportKey));
        const added = sug.filter(x=> !befK.has(fsImportKey(x)));
        const kept = t[f].filter(x=> !removed.has(fsImportKey(x)));
        const have = new Set(kept.map(fsImportKey));
        t[f] = kept.concat(added.filter(x=> !have.has(fsImportKey(x))));
      }else if(v === FS_SUG_EMPTY || v === null || v === undefined) t[f] = Array.isArray(before) ? [] : '';
      else t[f] = v;
      if(f === 'deletedAt'){ t.deletedBy = s.by; }
    });
    const ok = await saveTourCloud(t).catch(()=> false);
    if(!ok){ showToast('Konnte nicht speichern (Internet?).', true); return; }
  }
  fields.forEach(f=>{ delete s.changes[f]; if(s.before) delete s.before[f]; });
  s.decidedAt = new Date().toISOString(); s.decidedBy = state.myName;
  if(!Object.keys(s.changes).length) s.status = accept ? 'angenommen' : 'abgelehnt';
  await fsSugWrite(coll, tourId, s);
  showToast(accept ? 'Übernommen.' : 'Abgelehnt.');
  render();
}
async function fsSugWithdraw(tourId, sid){
  const coll = fsTourColl(), s = ((fsSug[coll] || {})[tourId] || {})[sid];
  if(!s || !confirm('Vorschlag zurückziehen?')) return;
  s.status = 'zurückgezogen';
  await fsSugWrite(coll, tourId, s);
  render();
}
// Formular: Eigentümer stellt ein, wer direkt ändern darf; alle anderen sehen den Hinweis
function fsOwnerFieldHtml(t){
  if(!t || !t.id || !(state.tours || []).some(x=> x.id === t.id)) return ''; // neue Tour: gehört mir
  if(!fsIsOwner(t)){
    return fsCanEditDirect(t) ? '' : `<div class="field fs-owner-note"><p class="hint" style="margin:0;">Diese Tour gehört ${esc(fsOwnerOf(t))}. Ergänzungen (leere Felder füllen, neue Begehungen, Fotos, Links) gehen direkt; Änderungen an Bestehendem werden als Vorschlag gespeichert, bis ${esc(fsOwnerOf(t))} sie übernimmt.</p></div>`;
  }
  return `<div class="field"><label>Wer darf diese Tour direkt ändern?</label>
    <select name="ownerOpen"><option value="">Nur ich und Mitbearbeiter</option><option value="1" ${t.open === true ? 'selected' : ''}>Alle direkt</option></select>
    <input type="text" name="ownerEditors" value="${esc((t.editors || []).join(', '))}" placeholder="Mitbearbeiter, z.B. Anna, Beat" style="margin-top:8px;"/>
    <div class="hint">Alle anderen dürfen ergänzen; Änderungen an Bestehendem kommen als Vorschlag zu dir.</div></div>`;
}
function fsApplyOwnerFromForm(t, form){
  if(!t.owner) t.owner = fsOwnerOf(t);
  if(form.ownerOpen === undefined || !fsIsOwner(t)) return;
  t.open = form.ownerOpen === '1';
  t.editors = String(form.ownerEditors || '').split(',').map(x=> x.trim()).filter(Boolean);
}
// Liest den aktuellen Stand mit Versionskennung; fällt ohne Kennung zurück, falls der Browser sie nicht darf
async function fsGetWithEtag(path){
  let etagFailed = false;
  if(!fsEtagOff){
    try{
      const r = await fsRawFetch(path, {headers:{'X-Firebase-ETag':'true'}});
      if(r.ok){ const etag = r.headers.get('ETag'); if(!etag) fsEtagOff = true; return {ok:true, cur: await r.json(), etag}; }
      return {ok:false, status:r.status};
    }catch(e){ etagFailed = true; } // evtl. CORS: ohne Kennung nochmals versuchen
  }
  try{
    const r = await fsRawFetch(path);
    // Erst wenn das Lesen ohne Kennung klappt, lag es an der Kennung (nicht am fehlenden Netz)
    if(r.ok){ if(etagFailed) fsEtagOff = true; return {ok:true, cur: await r.json(), etag:null}; }
    return {ok:false, status:r.status};
  }catch(e){ return {ok:false, offline:true}; }
}
// Lokale Merker (_unsynced, _versionAt …) gehören nie in die Datenbank: sonst hielte ein anderes
// Gerät die Fassung für «noch nicht hochgeladen» und überschriebe damit neuere Daten.
function fsStripLocal(o){
  if(!o || typeof o !== 'object' || Array.isArray(o)) return o;
  const out = {};
  Object.keys(o).forEach(k=>{ if(k[0] !== '_') out[k] = o[k]; });
  return out;
}
async function fsPutWithEtag(path, value, etag){
  const body = JSON.stringify(fsStripLocal(value));
  if(etag && !fsEtagOff){
    try{ return await fsRawFetch(path, {method:'PUT', headers:{'Content-Type':'application/json', 'if-match': etag}, body}); }
    catch(e){
      // Offline oder Netzfehler: nicht als «Versionskennung nicht unterstützt» werten
      if(typeof navigator !== 'undefined' && navigator.onLine === false) throw e;
      const res = await fsRawFetch(path, {method:'PUT', headers:{'Content-Type':'application/json'}, body});
      if(res.ok) fsEtagOff = true; // ohne Kennung ging es: der Server/Browser lässt if-match nicht zu
      return res;
    }
  }
  return fsRawFetch(path, {method:'PUT', headers:{'Content-Type':'application/json'}, body});
}
async function fsSafeSet(path, value, v){
  for(let attempt = 0; attempt < 4; attempt++){
    const g = await fsGetWithEtag(path);
    if(!g.ok){
      // Ohne Lesen kein sicheres Zusammenführen: nicht blind überschreiben, bleibt «noch nicht hochgeladen»
      if(g.offline){ fsBasePin(path); dlog('Offline – später hochladen: ' + path); return false; }
      if(g.status !== 404){ dlog('Lesen vor dem Speichern fehlgeschlagen (' + g.status + '): ' + path, 'err'); return false; }
    }
    const cur = g.ok ? g.cur : null;
    let result = JSON.parse(JSON.stringify(value));
    const sent = JSON.parse(JSON.stringify(value)); // Stand beim Absenden: was danach lokal dazukommt, bleibt
    if(cur && typeof cur === 'object'){
      const base = fsBaseGet(path);
      if(base !== undefined){
        const conflicts = [];
        result = fsMerge3(base || {}, result, cur, '', conflicts);
        // Andere Fassung gewählt: die eigene trotzdem unter «Frühere Versionen» ablegen (wie im Dialog versprochen)
        if(conflicts.length && fsResolveConflicts(result, conflicts, cur)) await fsSaveVersion(v, value, 'eigene Fassung, andere übernommen');
      }else{
        // Ausgangsstand unbekannt (z. B. offline geöffnet): bisherige Prüfung per Zeitstempel
        const stampBase = fsBaseStamp.get(path), curStamp = cur.updatedAt || '';
        if(v.coll !== 'agenda' && stampBase !== undefined && curStamp && curStamp !== stampBase){
          const who = cur.updatedBy || 'jemand anderes';
          const when = new Date(curStamp).toLocaleString('de-CH', {day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit'});
          if(!window.confirm(`«${cur.name || cur.tourName || 'Dieser Eintrag'}» wurde inzwischen von ${who} geändert (${when}).\n\nOK: deine Fassung speichern — die andere bleibt unter «Frühere Versionen» erhalten.\nAbbrechen: die neuere Fassung laden — deine bleibt unter «Frühere Versionen» erhalten.`)){
            await fsSaveVersion(v, value, 'eigene Fassung, nicht übernommen');
            Object.keys(value).forEach(k=> delete value[k]); Object.assign(value, cur);
            fsBaseRemember(path, cur); fsBaseStamp.set(path, curStamp); fsBaseUnpin(path);
            if(typeof showToast === 'function') showToast('Nicht gespeichert — die neuere Fassung ist geladen.');
            if(typeof render === 'function') setTimeout(render, 0);
            return true;
          }
        }
        if(v.coll === 'agenda' && Array.isArray(cur.participants)){
          const me = (typeof state !== 'undefined' && state.myName) || '';
          result.participants = cur.participants.filter(p=> p && p.by && p.by !== me).concat((result.participants || []).filter(p=> p && p.by === me));
        }
      }
      // Eigentümer: Änderungen anderer an Bestehendem werden ein Vorschlag
      if(FS_OWNED_COLLS.includes(v.coll) && !fsCanEditDirect(cur)){
        const sp = fsSplitForSuggestion(cur, result, (typeof state !== 'undefined' && state.myName) || '');
        if(Object.keys(sp.changes).length){
          const okS = await fsSaveSuggestion(v.coll, v.id, cur, sp.changes, sp.before);
          const labels = Object.keys(sp.changes).map(k=> FS_FIELD_LABELS[k] || k).join(', ');
          // Vorschlag nicht gespeichert: auch die Tour nicht speichern, sonst wäre die Änderung nirgends mehr
          if(!okS){ setTimeout(()=> showToast('Vorschlag konnte nicht gespeichert werden (Internet?) – bleibt auf dem Gerät und wird später nochmals versucht.', true), 400); return false; }
          setTimeout(()=> showToast(okS ? 'Als Vorschlag an ' + fsOwnerOf(cur) + ' geschickt: ' + labels + '.' : 'Vorschlag konnte nicht gespeichert werden (Internet?).', !okS), 400);
          dlog('Vorschlag statt Änderung (' + labels + '): ' + path);
        }
      }
      const losses = fsDetectLosses(cur, result);
      if(losses.length){
        const title = cur.name || cur.tourName || cur.title || 'Dieser Eintrag';
        const go = window.confirm(`«${title}»: Beim Speichern würde Folgendes entfernt:\n\n– ${losses.map(l=> l.text).join('\n– ')}\n\nOK: so speichern (die bisherige Fassung bleibt unter «Frühere Versionen»)\nAbbrechen: deine Änderungen speichern, diese Angaben aber behalten`);
        if(!go){ losses.forEach(l=>{ result[l.key] = l.restore; }); dlog('Notbremse: Verlust verhindert (' + losses.map(l=> l.key).join(', ') + '): ' + path); }
      }
      if(!fsEq(cur, result)) await fsSaveVersion(v, cur, 'vor dem Speichern');
    }
    if(FS_OWNED_COLLS.includes(v.coll) && !(cur && typeof cur === 'object') && !result.owner && typeof state !== 'undefined' && state.myName) result.owner = state.myName;
    // Wie die Datenbank-Regel: Touren und Hütten nie ohne Namen
    if(/(^|\/)(tours|huts)$/.test(v.coll) && !(typeof result.name === 'string' && result.name.trim())){
      dlog('Speichern blockiert (kein Name): ' + path, 'err');
      if(typeof showToast === 'function') showToast('Nicht gespeichert: Der Eintrag hat keinen Namen.', true);
      return false;
    }
    result.updatedAt = new Date().toISOString();
    if(typeof state !== 'undefined' && state.myName) result.updatedBy = state.myName;
    let res;
    try{ res = await fsPutWithEtag(path, result, g.ok ? g.etag : null); }
    catch(e){ fsBasePin(path); throw e; }
    if(res.status === 412){ dlog('Inzwischen geändert, führe erneut zusammen: ' + path); continue; }
    if(!res.ok){ dlog('Firebase PUT fehlgeschlagen (' + res.status + '): ' + path, 'err'); fsBasePin(path); return false; }
    // Die gespeicherte Fassung wird zur lokalen (inkl. der Änderungen anderer)
    // Was während des Speicherns lokal weiter geändert wurde (zweite Eingabe, nächster Vorschlag …), bleibt:
    // pro Feld drei Fassungen – beim Absenden, jetzt lokal, gespeichert
    new Set([...Object.keys(value), ...Object.keys(result), ...Object.keys(sent)]).forEach(k=>{
      if(k[0] === '_') return;
      const nv = (k === 'updatedAt' || k === 'updatedBy') ? result[k] : fsMergeField(sent[k], value[k], result[k], k, []);
      if(nv === undefined) delete value[k]; else value[k] = nv;
    });
    fsBaseRemember(path, result); fsBaseUnpin(path);
    fsBaseStamp.set(path, result.updatedAt);
    dlog('Sicher gespeichert ' + (g.ok && g.etag && !fsEtagOff ? 'mit' : 'ohne') + ' Versionskennung: ' + path);
    return true;
  }
  dlog('Speichern nach mehreren Versuchen aufgegeben (ständig geändert): ' + path, 'err');
  return false;
}
// Speichern desselben Pfads nacheinander statt gleichzeitig: sonst setzt das Ende des ersten
// Speicherns das Objekt auf seinen Stand zurück und das zweite verliert seine Änderung.
const fsSaveChain = new Map();
// Gerätekopie sofort schreiben (z. B. bevor das Netz antwortet: wird der Tab dabei beendet,
// bleibt die Änderung als «noch nicht hochgeladen» erhalten)
function fsCacheNow(path){
  try{ if(typeof state !== 'undefined' && !state.loading && typeof cacheLocalSnapshot === 'function') cacheLocalSnapshot(); }catch(e){}
  try{ if(/^orte\//.test(path || '') && typeof fsOrteCacheWrite === 'function') fsOrteCacheWrite(); }catch(e){}
}
function fbSet(path, value){
  const prev = fsSaveChain.get(path) || Promise.resolve();
  const p = prev.catch(()=>{}).then(()=> fbSetNow(path, value));
  fsSaveChain.set(path, p);
  p.finally(()=>{ if(fsSaveChain.get(path) === p) fsSaveChain.delete(path); });
  return p;
}
async function fbSetNow(path, value){
  if(!fbPathOk(path)){ dlog('Speichern blockiert (ungültiger Pfad): "' + path + '"', 'err'); return false; }
  const v0 = value && typeof value === 'object' && !Array.isArray(value) ? fsVersionedSplit(path) : null;
  const isEntry = !!(v0 && !FS_FILE_COLLS.includes(v0.coll));
  // Bis das Speichern bestätigt ist, gilt der Eintrag als «noch nicht hochgeladen»
  if(isEntry){ value._unsynced = true; fsBasePin(path); fsCacheNow(path); }
  const ok = await fbSetInner(path, value);
  if(isEntry){ value._unsynced = !ok; fsCacheNow(path); }
  return ok;
}
async function fbSetInner(path, value){
  try{
    const v = value && typeof value === 'object' && !Array.isArray(value) ? fsVersionedSplit(path) : null;
    // Einträge (Touren, Hütten, Termine …): sicher zusammenführen
    if(v && !FS_FILE_COLLS.includes(v.coll)){
      const ok = await fsSafeSet(path, value, v);
      if(ok && fsPendingFiles.size) fsFlushPendingFiles(v.id, value);
      return ok;
    }
    // Dateien (GPX-Originale): alte Fassung sichern, dann ersetzen
    if(v){
      let cur = null;
      try{ const r = await fsRawFetch(path); if(r.ok) cur = await r.json(); }catch(e){ cur = null; }
      if(cur && typeof cur === 'object' && JSON.stringify(cur) !== JSON.stringify(value)) await fsSaveVersion(v, cur, 'vor dem Speichern');
    }
    const res = await fsRawFetch(path, {method:'PUT', headers:{'Content-Type':'application/json'}, body: JSON.stringify(value)});
    if(!res.ok){ dlog('Firebase PUT fehlgeschlagen ('+res.status+'): '+path, 'err'); return false; }
    return true;
  }catch(e){
    dlog('Firebase PUT Fehler für "'+path+'": '+(e && e.message ? e.message : e), 'err');
    return false;
  }
}
async function fbDelete(path){
  if(!fbPathOk(path)){ dlog('Löschen blockiert (ungültiger Pfad): "' + path + '"', 'err'); return false; }
  try{
    const v = fsVersionedSplit(path);
    if(v){
      try{ const r = await fsRawFetch(path); const cur = r.ok ? await r.json() : null; if(cur && typeof cur === 'object') await fsSaveVersion(v, cur, 'vor dem endgültigen Löschen'); }catch(e){}
    }
    await ensureValidAuthToken();
    const authParam = authState.idToken ? ('?auth=' + authState.idToken) : '';
    const res = await fetch(FIREBASE_URL + '/' + path + '.json' + authParam, {method:'DELETE'});
    if(!res.ok){ dlog('Firebase DELETE fehlgeschlagen ('+res.status+'): '+path, 'err'); return false; }
    return true;
  }catch(e){
    dlog('Firebase DELETE Fehler für "'+path+'": '+(e && e.message ? e.message : e), 'err');
    return false;
  }
}

/* ================= Namen-Schutz & persönliche Merkliste =================
   Kein echtes Login — das gemeinsame App-Passwort (signInWithPassword) regelt bereits den
   Zugriff auf die Daten insgesamt. Das hier verhindert nur Verwechslungen: wer einen Namen
   zum ersten Mal einträgt, vergibt ein frei wählbares Passwort dafür; will jemand denselben
   Namen später wieder benutzen (anderes Gerät, versehentlich derselbe Name), muss das
   Passwort übereinstimmen. Gespeichert wird nur ein Hash, kein Klartext. */
async function sha256Hex(text){
  const enc = new TextEncoder().encode(text);
  const buf = await crypto.subtle.digest('SHA-256', enc);
  return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
}
function sanitizeNameKey(name){
  return (name||'').trim().toLowerCase().replace(/[.#$\[\]\/]/g, '_');
}
async function claimOrVerifyName(name, pin){
  const key = sanitizeNameKey(name);
  if(!key) return {ok:false, reason:'empty-name'};
  let existing, fetchFailed = false;
  try{
    await ensureValidAuthToken();
    const authParam = authState.idToken ? ('?auth=' + authState.idToken) : '';
    const res = await fetch(FIREBASE_URL + '/' + USERS_PATH + '/' + key + '.json' + authParam);
    if(!res.ok){ fetchFailed = true; }
    else{ existing = await res.json(); }
  }catch(e){ fetchFailed = true; }
  if(fetchFailed){
    // Offline/Fehler: nicht aussperren, aber auch keinen neuen Eintrag anlegen — sonst könnte
    // später beim Synchronisieren versehentlich ein bestehendes Passwort überschrieben werden.
    return {ok:true, unverified:true};
  }
  if(!existing){
    if(!pin) return {ok:false, reason:'need-pin'};
    const pinHash = await sha256Hex(pin);
    fbSet(USERS_PATH + '/' + key, {name: name.trim(), pinHash, createdAt: new Date().toISOString()}).catch(()=>{});
    return {ok:true};
  }
  if(!existing.pinHash) return {ok:true}; // Alter Eintrag von vor diesem Feature — nicht aussperren
  const pinHash = await sha256Hex(pin||'');
  if(pinHash === existing.pinHash) return {ok:true};
  return {ok:false, reason:'wrong-pin'};
}
// Persönliche Merkliste (★) — pro Namen in der Cloud gespeichert, damit sie geräteübergreifend
// erhalten bleibt, aber beim Anzeigen nur die eigenen markierten Einträge gezeigt werden.
async function loadFavorites(){
  if(!state.myName){ state.favorites = new Set(); return; }
  const key = sanitizeNameKey(state.myName);
  const obj = await fbGet(USERS_PATH + '/' + key + '/favorites').catch(()=>null);
  state.favorites = new Set(obj ? Object.keys(obj) : []);
  render();
}
function isFavorite(id){ return !!(state.favorites && state.favorites.has(id)); }
async function toggleFavorite(id){
  if(!state.myName){ ensureName(()=>toggleFavorite(id)); return; }
  const key = sanitizeNameKey(state.myName);
  const already = isFavorite(id);
  if(already) state.favorites.delete(id); else state.favorites.add(id);
  render();
  if(already) await fbDelete(USERS_PATH + '/' + key + '/favorites/' + id).catch(()=>{});
  else await fbSet(USERS_PATH + '/' + key + '/favorites/' + id, true).catch(()=>{});
}
function favoriteToggleButtonHtml(id){
  const on = isFavorite(id);
  return `<button type="button" class="fav-toggle-btn ${on ? 'on' : ''}" data-act="toggle-favorite" data-id="${esc(id)}" title="${on ? 'Von Merkliste entfernen' : 'Zur Merkliste hinzufügen'}" aria-label="${on ? 'Von Merkliste entfernen' : 'Zur Merkliste hinzufügen'}" aria-pressed="${on ? 'true' : 'false'}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${FS_ICON_PATHS.star}"/></svg></button>`;
}

/* ================= Basis-Hilfsfunktionen ================= */
function uid(prefix){ return prefix + '_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,8); }
// Offline geänderter Eintrag (_unsynced) beim Laden: nicht durch die Fassung aus der Datenbank
// ersetzen. Ist die lokale Änderung neuer, gewinnt sie (die Datenbank-Fassung fliegt aus list und wird
// beim erneuten Speichern unter versions/ gesichert). Ist die Datenbank neuer, wurde der Eintrag auch
// anderswo geändert: lokal behalten, aber fbSet fragt beim Speichern nach (Basisstempel leer).
// Noch nicht hochgeladene Einträge (Gerät und Gerätekopie) über die geladene Fassung legen – auch offline
// in den Papierkorb gelegte oder daraus zurückgeholte: sie landen in der Liste, die ihr deletedAt sagt
function fsUnsyncedSplit(coll, active, trashed, prevActive, prevTrashed, cached, ck){
  const tk = 'trashed' + ck[0].toUpperCase() + ck.slice(1);
  const local = dedupeById([].concat(prevActive || [], prevTrashed || [], (cached && cached[ck]) || [], (cached && cached[tk]) || []).filter(x=> x && x._unsynced));
  local.forEach(x=>{
    const i = trashed.findIndex(y=> y.id === x.id);
    if(i >= 0){ trashed.splice(i, 1); fsKeepUnsynced(x, [{id: x.id}], coll); } // Ausgangsstand wie bei aktiven
    else fsKeepUnsynced(x, active, coll);
  });
  return {local, active: local.filter(x=> !x.deletedAt).concat(active), trashed: local.filter(x=> x.deletedAt).concat(trashed)};
}
function fsKeepUnsynced(x, list, coll){
  const i = list.findIndex(y=> y.id === x.id);
  if(i < 0) return true;
  if(coll){
    const path = coll + '/' + x.id;
    let pinned = null;
    try{ pinned = localStorage.getItem('fs-base:' + path); }catch(e){}
    // Ausgangsstand meiner lokalen Änderung bekannt (beim Speichern festgehalten): sauber zusammenführen.
    // Sonst NICHT die eben geladene Fassung als Ausgangsstand nehmen (dann gälte jedes abweichende Feld
    // als «meine Änderung» und neuere Änderungen anderer würden still zurückgesetzt) – lieber nachfragen.
    if(pinned == null){ fsBase.delete(path); fsBaseStamp.set(path, ''); }
  }
  list.splice(i, 1);
  return true;
}
// Offline gestartet: die Gerätekopie ist der zuletzt bekannte Stand der Datenbank – als Ausgangsstand
// merken, damit spätere Änderungen beim Hochladen sauber zusammengeführt werden.
function fsRememberCachedBases(coll, list){
  (Array.isArray(list) ? list : []).forEach(x=>{
    if(!x || !x.id || x._unsynced) return;
    const path = coll + '/' + x.id;
    if(!fsBase.has(path)) fsBaseRemember(path, fsStripLocal(x));
    if(!fsBaseStamp.has(path)) fsBaseStamp.set(path, x.updatedAt || '');
  });
}
function dedupeById(arr){
  const map = new Map();
  arr.forEach(x=>{ if(x && x.id) map.set(x.id, x); });
  return Array.from(map.values());
}

/* ================= Papierkorb (Soft-Delete) ================= */
// Gelöschte Touren/Hütten/Sektoren/Klettergebiete/Gipfel werden nicht sofort und endgültig aus
// Firebase entfernt, sondern nur markiert (deletedAt/deletedBy) und aus der aktiven state.xyz-
// Liste in eine separate state.trashedXyz-Liste verschoben. Die App lebt von den über die Zeit
// gesammelten Touren aller Nutzer:innen — ein Fehlklick soll niemanden endgültig etwas kosten.
// Nach TRASH_RETENTION_DAYS werden Einträge beim nächsten App-Start automatisch endgültig entfernt
// (siehe purgeExpiredTrash, aufgerufen aus loadAll() in index.html/fixseil.html).
const TRASH_RETENTION_DAYS = 30;

// Teilt eine frisch aus Firebase geladene Sammlung (das Objekt aus fbGet(), noch nicht
// Object.values()'t) in {active, trashed} -- an jeder Ladestelle statt eines rohen
// Object.values(...).filter(x=>x&&x.id) verwenden.
function splitTrash(rawObj){
  const all = (rawObj ? Object.values(rawObj) : []).filter(x=>x && x.id);
  return { active: all.filter(x=>!x.deletedAt), trashed: all.filter(x=>x.deletedAt) };
}
// Verschiebt ein Objekt von der aktiven Liste in die Papierkorb-Liste (beide Arrays werden
// in-place mutiert, wie es die bestehenden removeXyz()-Funktionen erwarten) und speichert es mit
// deletedAt/deletedBy zurück in Firebase -- der Eintrag bleibt dort vollständig erhalten, nur die
// App zeigt ihn nicht mehr in normalen Listen. Gibt das verschobene Objekt zurück (oder null),
// damit Aufrufer z. B. weiterhin darauf verweisende Einträge entlinken können.
function moveToTrash(id, activeList, trashedList, saveFn){
  const idx = activeList.findIndex(x=>x.id===id);
  if(idx<0) return null;
  const item = activeList[idx];
  activeList.splice(idx, 1);
  item.deletedAt = new Date().toISOString();
  item.deletedBy = state.myName;
  trashedList.unshift(item);
  saveFn(item).catch(()=>{ item._unsynced = true; });
  return item;
}
function restoreFromTrash(id, activeList, trashedList, saveFn){
  const idx = trashedList.findIndex(x=>x.id===id);
  if(idx<0) return null;
  const item = trashedList[idx];
  trashedList.splice(idx, 1);
  // Leeren statt entfernen: ein fehlendes Feld gilt beim Speichern als unverändert, sonst bliebe der Eintrag in der Datenbank gelöscht
  item.deletedAt = '';
  item.deletedBy = '';
  activeList.unshift(item);
  saveFn(item).catch(()=>{ item._unsynced = true; });
  return item;
}
// Endgültig löschen -- auf Wunsch aus dem Papierkorb heraus, oder automatisch nach Ablauf der
// Aufbewahrungsfrist (siehe purgeExpiredTrash).
function purgeFromTrash(id, trashedList, path){
  const idx = trashedList.findIndex(x=>x.id===id);
  if(idx<0) return;
  trashedList.splice(idx, 1);
  fbDelete(path+'/'+id).catch(()=>{});
}
/* ================= Rettung aus dem Gerätespeicher =================
   Fehlen Einträge in der Datenbank, die im lokalen Speicher dieses Geräts (App oder Beta) noch
   vorhanden sind, werden sie sicher beiseitegelegt (fs-rescue-<app>) und zum Wiederherstellen
   angeboten. Wird beim Laden aufgerufen, bevor der lokale Speicher mit dem neuen Stand
   überschrieben wird. */
const FS_RESCUE_COLLS = {tours:['Touren','saveTourCloud'], huts:['Hütten','saveHutCloud'], gebiete:['Gebiete','saveGebietCloud'],
  sektoren:['Sektoren','saveSektorCloud'], klettergebiete:['Klettergebiete','saveKlettergebietCloud'], gipfel:['Gipfel','saveGipfelCloud']};
const fsRescueCap = s=> s[0].toUpperCase() + s.slice(1);
// Für den Import: nur Einträge mit Namen, und jede fehlende/ungültige ID durch eine neue ersetzen
function fsImportPrep(list, prefix, nameField){
  return (Array.isArray(list) ? list : []).filter(x=> x && typeof x === 'object' && x[nameField || 'name']).map(x=>{
    if(typeof x.id !== 'string' || !fbPathOk('x/' + x.id)) x.id = uid(prefix);
    return x;
  });
}
// Import ergänzt statt ersetzt: Werte aus der Datei überschreiben nur, wenn sie etwas enthalten —
// leere Felder in der Datei löschen nie vorhandene Daten (GPX, Punkte, Fotos, Routen, Begehungen).
function fsImportIsEmpty(v){
  return v === '' || v === null || v === undefined || (Array.isArray(v) && !v.length) || (typeof v === 'object' && !Array.isArray(v) && !Object.keys(v).length);
}
// Import ergänzt nur: leere Felder werden gefüllt, Listen vereinigt (Begehungen, Fotos, Routen,
// Punkte …), vorhandene Texte und Linien bleiben. Eine ältere Exportdatei kann so nichts zurückdrehen.
function fsImportKey(x){
  if(x === null || typeof x !== 'object') return 'v:' + JSON.stringify(x);
  if(x.id) return 'id:' + x.id;
  const parts = [x.by, x.date, x.lat, x.lon, x.storagePath, x.url].filter(v=> v !== undefined && v !== null && v !== '');
  return parts.length ? 'k:' + parts.join('|') : 'j:' + JSON.stringify(x);
}
function fsImportMerge(existing, incoming){
  const out = Object.assign({}, existing);
  Object.keys(incoming || {}).forEach(k=>{
    if(k === 'id' || fsImportIsEmpty(incoming[k])) return;
    const cur = out[k], inc = incoming[k];
    if(fsImportIsEmpty(cur)){ out[k] = inc; return; }
    // Linien (Listen von Koordinaten) nie mischen — die vorhandene bleibt
    if(Array.isArray(cur) && Array.isArray(inc) && !Array.isArray(cur[0]) && !Array.isArray(inc[0])){
      const seen = new Set(cur.map(fsImportKey));
      out[k] = cur.concat(inc.filter(x=> !seen.has(fsImportKey(x))));
    }
  });
  out.id = existing.id;
  return out;
}
// Vorschau vor dem Import: was kommt neu, was wird ergänzt. rows: [[Bezeichnung, importierte Liste, bestehende Liste]]
function fsImportConfirm(rows){
  const lines = [];
  rows.forEach(([label, list, existing])=>{
    const ids = new Set((existing || []).map(x=> x && x.id));
    const upd = (list || []).filter(x=> ids.has(x.id)), add = (list || []).filter(x=> !ids.has(x.id));
    const nm = x=> x.name || x.tourName || x.id;
    if(add.length) lines.push(`${label} neu (${add.length}): ${add.map(nm).slice(0, 8).join(', ')}${add.length > 8 ? ' …' : ''}`);
    if(upd.length) lines.push(`${label} ergänzt (${upd.length}): ${upd.map(nm).slice(0, 8).join(', ')}${upd.length > 8 ? ' …' : ''}`);
  });
  if(!lines.length) return;
  const ok = window.confirm('Import prüfen:\n\n' + lines.join('\n') + '\n\nBestehende Einträge werden nur ergänzt: leere Felder gefüllt, Listen (Begehungen, Fotos, Routen, Punkte) um Neues erweitert. Vorhandene Texte, Linien und Einträge bleiben. Die bisherige Fassung wird zusätzlich unter «Frühere Versionen» gesichert.\n\nImportieren?');
  if(!ok) throw new Error('Import abgebrochen — nichts wurde verändert.');
}
function fsRescueCollect(appKey, cacheKeys){
  const storeKey = 'fs-rescue-' + appKey;
  let store = {};
  try{ store = JSON.parse(localStorage.getItem(storeKey) || '{}') || {}; }catch(e){ store = {}; }
  Object.keys(FS_RESCUE_COLLS).forEach(coll=>{
    if(!Array.isArray(state[coll]) || typeof window[FS_RESCUE_COLLS[coll][1]] !== 'function') return;
    const have = new Set([...(state[coll] || []), ...(state['trashed' + fsRescueCap(coll)] || [])].map(x=> x && x.id));
    const found = new Map((store[coll] || []).map(x=> [x.id, x]));
    cacheKeys.forEach(k=>{
      let c = null;
      try{ c = JSON.parse(localStorage.getItem(k) || 'null'); }catch(e){ c = null; }
      if(!c) return;
      [...(c[coll] || []), ...(c['trashed' + fsRescueCap(coll)] || [])].forEach(x=>{
        if(!x || typeof x.id !== 'string' || !fbPathOk('x/' + x.id) || have.has(x.id) || isTrashExpired(x)) return;
        const prev = found.get(x.id);
        if(!prev || (x.updatedAt || x.createdAt || '') > (prev.updatedAt || prev.createdAt || '')) found.set(x.id, x);
      });
    });
    const left = [...found.values()].filter(x=> !have.has(x.id));
    if(left.length) store[coll] = left; else delete store[coll];
  });
  try{ if(Object.keys(store).length) localStorage.setItem(storeKey, JSON.stringify(store)); else localStorage.removeItem(storeKey); }catch(e){}
  fsBetterCollect(appKey, cacheKeys);
  if(Object.keys(store).length) setTimeout(()=> fsRescueOffer(appKey), 600);
  setTimeout(()=> fsBetterOffer(appKey), 1500);
  setTimeout(()=> fsGpxRepairCheck(appKey), 2500);
  return store;
}
/* ================= Frühere Versionen einer Tour ansehen und zurückholen ================= */
function fsOwnToursPath(){ return {firnspur: 'tours', fixseil: 'fixseil/tours', wandern: 'wandern/tours'}[fsAppKey()] || 'tours'; }
// Frühere Versionen eines Eintrags (Tour, Termin …). path: Datenbankpfad; bei Touren zusätzlich die
// früheren GPX-Originaldateien (gpxPath) – Zurückholen stellt Datei UND Linie wieder her.
async function fsOpenVersions(id, path, gpxPath){
  path = path || (fsOwnToursPath() + '/' + id);
  const v = fsVersionedSplit(path);
  const isAgenda = v && v.coll === 'agenda';
  const box = document.createElement('div');
  box.id = 'fs-versions';
  box.className = 'fs-rescue';
  box.innerHTML = `<div class="fs-rescue-card" role="dialog" aria-modal="true"><h3>${fsIconHtml('clock')} Frühere Versionen</h3><p class="fs-rescue-muted">Wird geladen …</p></div>`;
  box.addEventListener('click', e=>{ if(e.target === box) box.remove(); });
  document.body.appendChild(box);
  const card = box.querySelector('.fs-rescue-card');
  const gv = gpxPath ? fsVersionedSplit(gpxPath) : null;
  const [data, gdata, gcur] = await Promise.all([
    fbGet('versions/' + v.key + '/' + id),
    gv ? fbGet('versions/' + gv.key + '/' + gv.id) : null,
    gv ? fbGet(gpxPath) : null
  ]);
  const list = data && typeof data === 'object' ? Object.keys(data).sort().reverse().map(k=> Object.assign({_key: k}, data[k])) : [];
  const glist = gdata && typeof gdata === 'object' ? Object.keys(gdata).sort().reverse().map(k=> Object.assign({_key: k}, gdata[k])).filter(x=> x && x.gpx && (!gcur || x.gpx !== gcur.gpx)) : [];
  const cnt = (a)=> Array.isArray(a) ? a.length : 0;
  const sum = x=> isAgenda ? [
    x.startDate ? fmtDateShort(x.startDate) : '',
    cnt(x.participants) ? cnt(x.participants) + ' dabei' : '',
    x.status || ''
  ].filter(Boolean).join(' · ') : ([
    cnt(x.points) ? cnt(x.points) + ' Punkte' : '',
    cnt(x.trackSimplified) || cnt(x.manualTrack) ? 'Linie' : '',
    cnt(x.altTracks) ? cnt(x.altTracks) + ' weitere Routen' : '',
    cnt(x.topoImages) ? cnt(x.topoImages) + ' Fotos' : '',
    cnt(x.completions) ? cnt(x.completions) + ' Begehungen' : '',
    x.deletedAt ? 'im Papierkorb' : ''
  ].filter(Boolean).join(' · ') || 'ohne Kartendaten');
  const findObj = ()=>{
    const lists = isAgenda ? [state.agenda] : [state.tours, state.trashedTours];
    let obj = null; lists.filter(Array.isArray).forEach(l=>{ const f = l.find(y=> y.id === id); if(f) obj = f; });
    return obj;
  };
  const when = iso=> iso ? new Date(iso).toLocaleString('de-CH', {weekday:'short', day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit'}) : '?';
  const gpts = x=>{ try{ return parseGpxTrackPoints(x.gpx).length; }catch(e){ return 0; } };
  card.innerHTML = `<h3>${fsIconHtml('clock')} Frühere Versionen</h3>
    ${list.length ? `<p class="fs-rescue-muted">Vor jedem Speichern wird die bisherige Fassung hier abgelegt. Zurückholen sichert die aktuelle Fassung ebenfalls zuerst.</p>
    <div class="fs-ver-list">${list.slice(0, 30).map((x, i)=>{
      // Was danach (nächste Fassung bzw. heute) anders war: macht sichtbar, was eine Speicherung entfernt hat
      const after = i === 0 ? findObj() : list[i - 1];
      const diff = isAgenda ? '' : fsCheckDiffText(x, after);
      return `<div class="fs-ver-row">
      <div><b>${esc(when(x._versionAt))}</b>${x._versionBy ? ' · gespeichert von ' + esc(x._versionBy) : ''}<br/>
        <span>${esc(x.name || x.title || '')}</span> <span class="fs-rescue-muted">${esc(sum(x))}${x.updatedBy ? ' · Stand von ' + esc(x.updatedBy) : ''}</span>
        ${diff ? `<div class="fs-ver-diff">Danach geändert: ${esc(diff)}</div>` : ''}</div>
      <button type="button" class="btn secondary" data-ver="${i}">Diese Fassung zurückholen</button>
    </div>`; }).join('')}</div>` : `<p>Noch keine früheren Versionen. Ab jetzt wird vor jeder Änderung die bisherige Fassung gesichert.</p>`}
    ${glist.length ? `<h4 style="margin:16px 0 6px;">Frühere GPX-Dateien</h4>
    <p class="fs-rescue-muted">Zurückholen ersetzt die GPX-Datei und die Linie der Tour; die jetzige Datei wird vorher gesichert.</p>
    <div class="fs-ver-list">${glist.slice(0, 20).map((x, i)=> `<div class="fs-ver-row">
      <div><b>${esc(when(x._versionAt || x.uploadedAt))}</b><br/><span>${esc(x.fileName || 'track.gpx')}</span> <span class="fs-rescue-muted">${gpts(x)} Punkte</span></div>
      <button type="button" class="btn secondary" data-gver="${i}">Zurückholen</button>
    </div>`).join('')}</div>` : ''}
    <div class="fs-rescue-actions" style="margin-top:12px;"><button type="button" class="btn secondary" data-close>Schliessen</button></div>`;
  card.querySelector('[data-close]').onclick = ()=> box.remove();
  card.querySelectorAll('[data-ver]').forEach(b=> b.onclick = async ()=>{
    const old = list[+b.getAttribute('data-ver')];
    if(!window.confirm(`Fassung vom ${when(old._versionAt)} zurückholen?\n\nDie jetzige Fassung wird vorher als Version gesichert.`)) return;
    b.disabled = true; b.textContent = '…';
    const obj = findObj();
    // Auf einer Kopie arbeiten (scheitert das Speichern, bleibt die Tour im Speicher unverändert).
    // Felder der alten Fassung übernehmen; was die alte Fassung nicht kannte (z. B. später dazugekommene
    // Erfahrungen, Orte, Links – Firebase speichert auch leere Listen nicht), bleibt erhalten.
    const restored = JSON.parse(JSON.stringify(fsStripLocal(obj || {})));
    Object.keys(old).forEach(k=>{ if(!k.startsWith('_')) restored[k] = old[k]; });
    restored.id = id;
    const ok = await fbSet(path, restored);
    if(!ok){ b.disabled = false; b.textContent = 'Diese Fassung zurückholen'; showToast('Zurückholen fehlgeschlagen (keine Verbindung?).', true); return; }
    if(obj){ Object.keys(restored).forEach(k=>{ obj[k] = restored[k]; }); obj._unsynced = false; }
    box.remove();
    render();
    showToast('Frühere Fassung zurückgeholt.');
  });
  card.querySelectorAll('[data-gver]').forEach(b=> b.onclick = async ()=>{
    const old = glist[+b.getAttribute('data-gver')];
    if(!window.confirm(`GPX-Datei «${old.fileName || 'track.gpx'}» vom ${when(old._versionAt || old.uploadedAt)} zurückholen?\n\nDatei und Linie der Tour werden ersetzt, die jetzige Datei wird vorher gesichert.`)) return;
    b.disabled = true; b.textContent = '…';
    const pts = parseGpxTrackPoints(old.gpx);
    const okF = await fbSet(gpxPath, {gpx: old.gpx, uploadedAt: new Date().toISOString(), fileName: old.fileName || 'track.gpx'});
    const t = findObj();
    let okT = true;
    if(t && pts.length){
      t.trackSimplified = simplifyTrackForStorage(pts, 200).map(p=> [Math.round(p.lat*1e6)/1e6, Math.round(p.lon*1e6)/1e6]);
      okT = await saveTourCloud(t).catch(()=> false);
    }
    if(!okF || !okT){ b.disabled = false; b.textContent = 'Zurückholen'; showToast('Zurückholen fehlgeschlagen (keine Verbindung?).', true); return; }
    box.remove();
    render();
    showToast('GPX-Datei und Linie zurückgeholt.');
  });
}
document.addEventListener('click', (e)=>{
  const b = e.target.closest && e.target.closest('[data-act="fs-versions"]');
  if(!b) return;
  e.preventDefault(); e.stopPropagation();
  const det = b.closest('details'); if(det) det.open = false;
  const id = b.getAttribute('data-id'), path = b.getAttribute('data-path');
  fsOpenVersions(id, path, path ? null : (typeof GPX_TRACKS_PATH !== 'undefined' ? GPX_TRACKS_PATH + '/' + id : null));
}, true);
/* ================= GPX-Dateien wieder mit ihren Touren verbinden =================
   Die Original-GPX liegen getrennt von den Touren (gpxTracks/<tourId>, gpxTracksAlt/<tourId>/<altId>).
   Fehlt einer Tour die Linie (z. B. nach dem Zurückholen eines älteren Stands), obwohl ihre
   GPX-Datei noch da ist, wird die Linie daraus neu erstellt. GPX-Dateien ganz ohne Tour lassen
   sich als Entwurf-Tour anlegen. Prüft beim Laden nur die Schlüssel (wenig Daten). */
async function fsShallowKeys(path){
  try{
    await ensureValidAuthToken();
    const r = await fetch(FIREBASE_URL + '/' + path + '.json?shallow=true' + (authState.idToken ? '&auth=' + authState.idToken : ''));
    if(!r.ok) return [];
    const d = await r.json();
    return d && typeof d === 'object' ? Object.keys(d) : [];
  }catch(e){ return []; }
}
function fsGpxToSimplified(gpx){
  const pts = parseGpxTrackPoints(gpx || '');
  if(!pts.length) return null;
  return simplifyTrackForStorage(pts, 200).map(q=> [Math.round(q.lat * 1e6) / 1e6, Math.round(q.lon * 1e6) / 1e6]);
}
let fsGpxRepairRunning = false;
async function fsGpxRepairCheck(appKey){
  if(fsGetFailed.has(fsOwnToursPath())) return; // Touren nicht gelesen: jede GPX-Datei sähe verwaist aus
  if(fsGpxRepairRunning || typeof GPX_TRACKS_PATH === 'undefined' || !Array.isArray(state.tours)) return;
  fsGpxRepairRunning = true;
  try{
    const ignore = new Set(JSON.parse(localStorage.getItem('fs-gpx-ignore-' + appKey) || '[]'));
    const all = [...state.tours, ...(state.trashedTours || [])];
    const byId = new Map(all.map(t=> [t.id, t]));
    const [mainKeys, altTourKeys] = await Promise.all([fsShallowKeys(GPX_TRACKS_PATH), fsShallowKeys(GPX_TRACKS_PATH + 'Alt')]);
    const lineFix = mainKeys.filter(id=> byId.has(id) && !(byId.get(id).trackSimplified || []).length);
    const orphans = mainKeys.filter(id=> !byId.has(id) && !ignore.has(id));
    const altFix = [];
    for(const tid of altTourKeys.filter(id=> byId.has(id))){
      const have = new Set((byId.get(tid).altTracks || []).map(a=> a.id));
      (await fsShallowKeys(GPX_TRACKS_PATH + 'Alt/' + tid)).forEach(aid=>{ if(!have.has(aid)) altFix.push([tid, aid]); });
    }
    if(!lineFix.length && !orphans.length && !altFix.length) return;
    // Namen der verwaisten Dateien holen (nur dafür die Datei laden)
    const orphanData = [];
    for(const id of orphans){
      const d = await fbGet(GPX_TRACKS_PATH + '/' + id);
      if(d && d.gpx) orphanData.push({id, d, name: String(d.fileName || 'GPX-Track').replace(/\.gpx$/i, '')});
    }
    fsGpxRepairOffer(appKey, lineFix.map(id=> byId.get(id)), altFix, orphanData);
  }catch(e){ dlog('GPX-Prüfung fehlgeschlagen: ' + (e && e.message ? e.message : e), 'err'); }
  finally{ fsGpxRepairRunning = false; }
}
function fsGpxRepairOffer(appKey, lineTours, altFix, orphanData){
  if(document.getElementById('fs-gpxfix') || document.getElementById('fs-rescue')){ setTimeout(()=> fsGpxRepairOffer(appKey, lineTours, altFix, orphanData), 1500); return; }
  const box = document.createElement('div');
  box.id = 'fs-gpxfix';
  box.className = 'fs-rescue';
  const altTours = [...new Set(altFix.map(x=> x[0]))].map(id=> state.tours.find(t=> t.id === id) || (state.trashedTours || []).find(t=> t.id === id)).filter(Boolean);
  box.innerHTML = `<div class="fs-rescue-card" role="dialog" aria-modal="true">
    <h3>${fsIconHtml('compass')} GPX-Dateien gefunden</h3>
    ${lineTours.length ? `<p><b>${lineTours.length} Touren</b> fehlt die Linie, ihre GPX-Datei ist aber noch da:<br/>${lineTours.map(t=> esc(t.name || t.id)).join(' · ')}</p>` : ''}
    ${altTours.length ? `<p><b>${altFix.length} weitere Routen</b> fehlen bei: ${altTours.map(t=> esc(t.name || t.id)).join(' · ')}</p>` : ''}
    ${orphanData.length ? `<p><b>${orphanData.length} GPX-Dateien ohne Tour</b> — als Entwurf-Tour anlegen?</p>
      <div class="fs-rescue-list">${orphanData.map((o, i)=> `<label class="fs-gpx-orphan"><input type="checkbox" data-o="${i}" checked/> ${esc(o.name)} <span class="fs-rescue-muted">${o.d.uploadedAt ? '· ' + esc(new Date(o.d.uploadedAt).toLocaleDateString('de-CH')) : ''}</span></label>`).join('')}</div>` : ''}
    <div class="fs-rescue-actions">
      <button type="button" class="btn" data-g="go">Wiederherstellen</button>
      <button type="button" class="btn secondary" data-g="later">Später</button>
    </div>
    ${orphanData.length ? `<p class="fs-rescue-muted">Nicht angehakte Dateien werden nicht mehr angeboten (sie bleiben in der Datenbank).</p>` : ''}
  </div>`;
  document.body.appendChild(box);
  box.querySelector('[data-g="later"]').onclick = ()=> box.remove();
  box.querySelector('[data-g="go"]').onclick = async ()=>{
    const btn = box.querySelector('[data-g="go"]');
    btn.disabled = true; btn.textContent = 'Wird wiederhergestellt …';
    let ok = 0;
    const touched = new Set();
    for(const t of lineTours){
      const d = await fbGet(GPX_TRACKS_PATH + '/' + t.id);
      const line = d && fsGpxToSimplified(d.gpx);
      if(line){ t.trackSimplified = line; touched.add(t); ok++; }
    }
    for(const [tid, aid] of altFix){
      const t = state.tours.find(x=> x.id === tid) || (state.trashedTours || []).find(x=> x.id === tid);
      const d = await fbGet(GPX_TRACKS_PATH + 'Alt/' + tid + '/' + aid);
      const line = d && fsGpxToSimplified(d.gpx);
      if(t && line){
        if(!Array.isArray(t.altTracks)) t.altTracks = [];
        t.altTracks.push({id: aid, name: String(d.fileName || 'Weitere Route').replace(/\.gpx$/i, ''), type: 'variante', trackSimplified: line});
        touched.add(t); ok++;
      }
    }
    for(const t of touched) await saveTourCloud(t).catch(()=> false);
    const ignore = new Set(JSON.parse(localStorage.getItem('fs-gpx-ignore-' + appKey) || '[]'));
    for(const [i, o] of orphanData.entries()){
      const cb = box.querySelector(`[data-o="${i}"]`);
      if(!cb || !cb.checked){ ignore.add(o.id); continue; }
      const line = fsGpxToSimplified(o.d.gpx);
      if(!line) continue;
      const t = {id: o.id, name: o.name, trackSimplified: line, status: 'idee', createdBy: state.myName || '', createdAt: o.d.uploadedAt || new Date().toISOString()};
      if(appKey === 'fixseil') t.tourCategory = 'hochtour';
      if(appKey === 'wandern') t.tourCategory = 'wanderung';
      const saved = await saveTourCloud(t).catch(()=> false);
      if(saved){ state.tours.unshift(t); ok++; }
    }
    try{ localStorage.setItem('fs-gpx-ignore-' + appKey, JSON.stringify([...ignore])); }catch(e){}
    box.remove();
    render();
    showToast(ok + ' GPX-Linien wiederhergestellt.');
  };
}
/* Bessere Fassung vom Gerät: Gibt es einen Eintrag in der Datenbank, hat dieses Gerät aber in
   Feldern Daten, die dort leer sind (z. B. Linie, Punkte, Fotos, Routen), wird das beiseitegelegt
   (fs-better-<app>) und angeboten. Übernommen werden nur die leeren Felder — nichts wird ersetzt. */
const FS_BETTER_LABELS = {trackSimplified:'GPX-Linie', manualTrack:'gezeichnete Linie', points:'Punkte', altTracks:'weitere Routen',
  topoImages:'Fotos/Topos', accessRoutes:'Zustiege', descentRoutes:'Abstiege', kletterrouten:'Kletterrouten', completions:'Begehungen'};
function fsBetterCollect(appKey, cacheKeys){
  const key = 'fs-better-' + appKey;
  let store = {};
  try{ store = JSON.parse(localStorage.getItem(key) || '{}') || {}; }catch(e){ store = {}; }
  Object.keys(FS_RESCUE_COLLS).forEach(coll=>{
    if(!Array.isArray(state[coll]) || typeof window[FS_RESCUE_COLLS[coll][1]] !== 'function') return;
    const cloud = new Map([...(state[coll] || []), ...(state['trashed' + fsRescueCap(coll)] || [])].map(x=> [x && x.id, x]));
    const found = new Map((store[coll] || []).map(x=> [x.id, x]));
    cacheKeys.forEach(k=>{
      let c = null;
      try{ c = JSON.parse(localStorage.getItem(k) || 'null'); }catch(e){ c = null; }
      if(!c) return;
      [...(c[coll] || []), ...(c['trashed' + fsRescueCap(coll)] || [])].forEach(x=>{
        const cur = x && cloud.get(x.id);
        if(!cur) return;
        const fields = {};
        Object.keys(FS_BETTER_LABELS).forEach(f=>{ if(fsImportIsEmpty(cur[f]) && !fsImportIsEmpty(x[f])) fields[f] = x[f]; });
        if(!Object.keys(fields).length) return;
        const prev = found.get(x.id);
        found.set(x.id, {id: x.id, name: x.name || cur.name || x.id, fields: Object.assign({}, prev ? prev.fields : {}, fields)});
      });
    });
    // Was inzwischen in der Datenbank wieder gefüllt ist, fällt raus
    const left = [...found.values()].map(b=>{
      const cur = cloud.get(b.id);
      if(!cur) return null;
      const f = {};
      Object.keys(b.fields).forEach(k=>{ if(fsImportIsEmpty(cur[k])) f[k] = b.fields[k]; });
      return Object.keys(f).length ? Object.assign({}, b, {fields: f}) : null;
    }).filter(Boolean);
    if(left.length) store[coll] = left; else delete store[coll];
  });
  try{ if(Object.keys(store).length) localStorage.setItem(key, JSON.stringify(store)); else localStorage.removeItem(key); }catch(e){}
  return store;
}
function fsBetterOffer(appKey){
  if(document.getElementById('fs-rescue') || document.getElementById('fs-better')){ if(!document.getElementById('fs-better')) setTimeout(()=> fsBetterOffer(appKey), 1500); return; }
  let store = {};
  try{ store = JSON.parse(localStorage.getItem('fs-better-' + appKey) || '{}') || {}; }catch(e){ return; }
  const colls = Object.keys(store).filter(c=> (store[c] || []).length);
  if(!colls.length) return;
  const total = colls.reduce((n, c)=> n + store[c].length, 0);
  const box = document.createElement('div');
  box.id = 'fs-better';
  box.className = 'fs-rescue';
  box.innerHTML = `<div class="fs-rescue-card" role="dialog" aria-modal="true">
    <h3>${fsIconHtml('download')} Dieses Gerät hat mehr Daten</h3>
    <p>Bei ${total} Einträgen sind hier Daten gespeichert, die in der Datenbank fehlen. Übernommen werden nur die fehlenden Teile, nichts wird ersetzt:</p>
    <div class="fs-rescue-list">${colls.map(c=> store[c].map((b, i)=> `<label class="fs-gpx-orphan"><input type="checkbox" data-b="${c}:${i}" checked/> <span><b>${esc(b.name)}</b> <span class="fs-rescue-muted">${Object.keys(b.fields).map(f=> esc(FS_BETTER_LABELS[f] || f)).join(', ')}</span></span></label>`).join('')).join('')}</div>
    <div class="fs-rescue-actions">
      <button type="button" class="btn" data-r="go">Übernehmen</button>
      <button type="button" class="btn secondary" data-r="later">Später</button>
    </div>
    <p class="fs-rescue-muted">Nicht angehakte Einträge werden nicht mehr angeboten. Die bisherige Fassung bleibt unter «Frühere Versionen» erhalten.</p>
  </div>`;
  document.body.appendChild(box);
  box.querySelector('[data-r="later"]').onclick = ()=> box.remove();
  box.querySelector('[data-r="go"]').onclick = async ()=>{
    const btn = box.querySelector('[data-r="go"]');
    btn.disabled = true; btn.textContent = 'Wird übernommen …';
    let ok = 0;
    for(const c of colls){
      const save = window[FS_RESCUE_COLLS[c][1]];
      for(const [i, b] of store[c].entries()){
        const cb = box.querySelector(`[data-b="${c}:${i}"]`);
        if(!cb || !cb.checked) continue;
        const obj = (state[c] || []).find(x=> x.id === b.id) || (state['trashed' + fsRescueCap(c)] || []).find(x=> x.id === b.id);
        if(!obj) continue;
        Object.keys(b.fields).forEach(f=>{ if(fsImportIsEmpty(obj[f])) obj[f] = b.fields[f]; });
        if(await save(obj).catch(()=> false)) ok++;
      }
    }
    // Erledigt oder abgewählt: nicht mehr anbieten (Schlüssel bleibt leer, bis neue Unterschiede auftauchen)
    try{ localStorage.removeItem('fs-better-' + appKey); localStorage.setItem('fs-better-done-' + appKey, '1'); }catch(e){}
    box.remove();
    render();
    showToast(ok + ' Einträge ergänzt.');
  };
}
function fsRescueOffer(appKey){
  let store = {};
  try{ store = JSON.parse(localStorage.getItem('fs-rescue-' + appKey) || '{}') || {}; }catch(e){ return; }
  const colls = Object.keys(store).filter(c=> (store[c] || []).length);
  if(!colls.length || document.getElementById('fs-rescue')) return;
  const total = colls.reduce((n, c)=> n + store[c].length, 0);
  const box = document.createElement('div');
  box.id = 'fs-rescue';
  box.className = 'fs-rescue';
  box.innerHTML = `<div class="fs-rescue-card" role="dialog" aria-modal="true">
    <h3>${fsIconHtml('alert')} ${total} Einträge fehlen in der Datenbank</h3>
    <p>Sie sind auf diesem Gerät noch gespeichert und können zurückgeholt werden:</p>
    <div class="fs-rescue-list">${colls.map(c=> `<div><b>${esc(FS_RESCUE_COLLS[c][0])} (${store[c].length})</b><br/>${store[c].map(x=> esc(x.name || x.id) + (x.deletedAt ? ' <span class="fs-rescue-muted">(Papierkorb)</span>' : '')).join(' · ')}</div>`).join('')}</div>
    <div class="fs-rescue-actions">
      <button type="button" class="btn" data-r="go">Alle wiederherstellen</button>
      <button type="button" class="btn secondary" data-r="later">Später</button>
    </div>
    <p class="fs-rescue-muted">«Später» behält die Kopie auf diesem Gerät; die Frage kommt beim nächsten Öffnen wieder.</p>
  </div>`;
  document.body.appendChild(box);
  box.querySelector('[data-r="later"]').onclick = ()=> box.remove();
  box.querySelector('[data-r="go"]').onclick = async ()=>{
    const btn = box.querySelector('[data-r="go"]');
    btn.disabled = true; btn.textContent = 'Wird wiederhergestellt …';
    let ok = 0, fail = 0;
    for(const c of colls){
      const save = window[FS_RESCUE_COLLS[c][1]];
      const keep = [];
      for(const x of store[c]){
        const item = Object.assign({}, x); delete item._unsynced;
        const res = await save(item).catch(()=> false);
        if(res){
          ok++;
          const list = item.deletedAt ? state['trashed' + fsRescueCap(c)] : state[c];
          if(Array.isArray(list) && !list.some(y=> y.id === item.id)) list.unshift(item);
        }else{ fail++; keep.push(x); }
      }
      if(keep.length) store[c] = keep; else delete store[c];
    }
    try{ if(Object.keys(store).length) localStorage.setItem('fs-rescue-' + appKey, JSON.stringify(store)); else localStorage.removeItem('fs-rescue-' + appKey); }catch(e){}
    box.remove();
    render();
    showToast(fail ? ok + ' wiederhergestellt, ' + fail + ' noch offen (keine Verbindung?).' : ok + ' Einträge wiederhergestellt.', !!fail);
  };
}
function isTrashExpired(item){
  if(!item || !item.deletedAt) return false;
  return (Date.now() - new Date(item.deletedAt).getTime()) > TRASH_RETENTION_DAYS*24*60*60*1000;
}
function purgeExpiredTrash(trashedList, path){
  trashedList.filter(isTrashExpired).forEach(item=> purgeFromTrash(item.id, trashedList, path));
}
function trashCountTotal(groups){ return groups.reduce((n,g)=> n + g.trashedList.length, 0); }
// groups: [{kind, icon, label, trashedList}] -- ein Eintrag pro Entitätstyp der jeweiligen App.
function papierkorbViewHtml(groups){
  const total = trashCountTotal(groups);
  return `
    <div class="hero-top" style="margin-bottom:14px;"><h1 style="font-size:20px;">🗑️ Papierkorb</h1></div>
    <p style="font-size:13px; color:var(--ink-soft); margin:0 0 16px 0;">Gelöschte Einträge bleiben ${TRASH_RETENTION_DAYS} Tage lang hier und lassen sich wiederherstellen — danach werden sie automatisch endgültig entfernt.</p>
    ${!total ? `<div class="empty"><h3>Papierkorb ist leer</h3><p>Gelöschte Einträge erscheinen hier.</p></div>` : groups.filter(g=>g.trashedList.length).map(g=>`
      <h4 style="margin:18px 0 8px;">${g.icon} ${esc(g.label)} (${g.trashedList.length})</h4>
      <div class="grid">${g.trashedList.map(item=>trashItemCardHtml(item, g.kind)).join('')}</div>
    `).join('')}
  `;
}
function trashItemCardHtml(item, kind){
  return `<div class="card">
    <div class="card-top"><h3 style="color:var(--ink-soft);">${esc(item.name||'(ohne Namen)')}</h3></div>
    <p class="excerpt">Gelöscht von ${esc(item.deletedBy||'?')} · ${fmtDate(item.deletedAt)}</p>
    <div class="form-actions" style="margin-top:10px;">
      <button type="button" class="btn secondary" data-act="restore-trash-item" data-kind="${esc(kind)}" data-id="${esc(item.id)}">↺ Wiederherstellen</button>
      <button type="button" class="btn danger" data-act="purge-trash-item" data-kind="${esc(kind)}" data-id="${esc(item.id)}">Endgültig löschen</button>
    </div>
  </div>`;
}
function esc(s){
  if(s===undefined||s===null) return '';
  return String(s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
// Liefert die repräsentative Koordinate einer Tour für den Kartenstreifen: bevorzugt einen manuell
// gesetzten Kartenpunkt, fällt sonst auf den Startpunkt eines GPS-/GPX-Tracks zurück -- so
// erscheinen auch Touren, die nur per Live-GPS-Aufzeichnung oder GPX-Upload einen Streckenverlauf
// haben (trackSimplified/manualTrack), aber (noch) keinen eigenen Punkt gesetzt bekamen.
// Gipfel einer Tour: Punkt der Art «Gipfel», sonst höchster Punkt der Linie (falls mit Höhe),
// sonst der Punkt der Linie, der am weitesten vom Start entfernt ist.
function fsTourSummitPoint(t){
  const g = (t.points || []).find(p=> p && p.category === 'gipfel' && isFinite(p.lat) && isFinite(p.lon));
  if(g) return {lat: +g.lat, lon: +g.lon};
  // Verknüpfter Gipfel (Hochtour): dessen Lage; bei mehreren (Überschreitung) der höchste
  if(Array.isArray(t.summitIds) && t.summitIds.length && typeof state !== 'undefined' && Array.isArray(state.gipfel)){
    const gs = t.summitIds.map(id=> state.gipfel.find(x=> x && x.id === id)).filter(Boolean)
      .map(x=>{ const pt = (x.points || []).find(q=> q && isFinite(q.lat) && isFinite(q.lon)) || (isFinite(x.lat) && isFinite(x.lon) && x.lat !== '' ? x : null); return pt ? {lat:+pt.lat, lon:+pt.lon, alt: parseFloat(x.altitude) || 0} : null; })
      .filter(Boolean);
    if(gs.length) return gs.reduce((a, b2)=> b2.alt > a.alt ? b2 : a);
  }
  const line = (t.trackSimplified && t.trackSimplified.length > 1) ? t.trackSimplified : ((t.manualTrack && t.manualTrack.length > 1) ? t.manualTrack : null);
  if(!line) return null;
  const ll = line.map(q=> Array.isArray(q) ? {lat:+q[0], lon:+q[1], ele: q[2] != null ? +q[2] : NaN} : {lat:+q.lat, lon:+(q.lon != null ? q.lon : q.lng), ele: q.ele != null ? +q.ele : NaN}).filter(q=> isFinite(q.lat) && isFinite(q.lon));
  if(ll.length < 2) return null;
  const withEle = ll.filter(q=> isFinite(q.ele));
  if(withEle.length > ll.length / 2) return withEle.reduce((a, b)=> b.ele > a.ele ? b : a);
  const s0 = ll[0];
  const d = q=> (q.lat - s0.lat) ** 2 + ((q.lon - s0.lon) * Math.cos(s0.lat * Math.PI / 180)) ** 2;
  return ll.reduce((a, b)=> d(b) > d(a) ? b : a);
}
// Hütte aus dem Text erkennen («ab Wiwannihütte»), wenn die Tour keine verknüpft hat
function fsHutKey(n){ return String(n || '').toLowerCase().replace(/hütte|huette|cabane|capanna|rifugio|refuge|hut/g, '').replace(/[^a-zäöüéèà0-9]/g, ''); }
function fsGuessHut(t){
  if(!t || t.hutId || typeof state === 'undefined' || !Array.isArray(state.huts)) return null;
  const text = [t.routeName, t.approach, t.ascent].filter(Boolean).join(' ').toLowerCase().replace(/[^a-zäöüéèà0-9]/g, '');
  if(!text) return null;
  const norm = n=> String(n || '').toLowerCase().replace(/[^a-zäöüéèà0-9]/g, '');
  // ganzer Name («domhütte») oder der Kern ohne «Hütte» ab 4 Zeichen («wiwanni»)
  return state.huts.find(h=>{ const full = norm(h && h.name), k = fsHutKey(h && h.name); return (full.length >= 4 && text.includes(full)) || (k.length >= 4 && text.includes(k)); }) || null;
}
function fsLinkHutBtnHtml(t, h){
  return `<button type="button" class="btn secondary" data-act="fs-link-hut" data-id="${esc(t.id)}" data-hut="${esc(h.id)}">Hütte «${esc(h.name)}» fest verknüpfen</button>`;
}
document.addEventListener('click', async (e)=>{
  const el = e.target.closest && e.target.closest('[data-act="fs-link-hut"]');
  if(!el) return;
  e.stopPropagation();
  const t = (state.tours || []).find(x=> x.id === el.getAttribute('data-id'));
  if(!t) return;
  t.hutId = el.getAttribute('data-hut');
  t.updatedAt = new Date().toISOString(); t.updatedBy = state.myName;
  const ok = await saveTourCloud(t).catch(()=> false);
  t._unsynced = !ok;
  render();
  showToast(ok ? 'Hütte verknüpft.' : 'Lokal gespeichert, wird später hochgeladen.', !ok);
}, true);
// Auswahl-Knöpfe im Formular: Standardliste plus alle schon gespeicherten Werte, die nicht darin
// stehen (z. B. aus einem Import oder einer anderen App). Sonst hätten sie keinen Knopf und würden
// beim Speichern still wegfallen (das Formular übernimmt nur gedrückte Knöpfe).
function fsChipOptions(list, selected){
  const base = Array.isArray(list) ? list.slice() : [];
  (Array.isArray(selected) ? selected : []).forEach(v=>{ if(v != null && String(v).trim() && base.indexOf(v) < 0) base.push(v); });
  return base;
}
function tourMapPoint(t){
  if(t.points && t.points.length) return {lat: t.points[0].lat, lon: t.points[0].lon};
  if(t.trackSimplified && t.trackSimplified.length) return {lat: t.trackSimplified[0][0], lon: t.trackSimplified[0][1]};
  if(t.manualTrack && t.manualTrack.length) return {lat: t.manualTrack[0][0], lon: t.manualTrack[0][1]};
  return null;
}
// Kartenstreifen über Touren-/Gebiets-Listen: bewusst KEIN Leaflet, keine Kacheln, sondern eine
// einmal offline vereinfachte/projizierte CH-Silhouette (Kantonsgrenzen, 20 Seen, Relief-Hillshade
// aus DHM200 — siehe 0-geo-ch.js) fest in die App eingebettet. Punkte werden über dieselbe
// Projektion wie die Silhouette platziert (echte, konstante Lage zueinander statt Min/Max-
// Streckung auf die jeweils aktuelle Liste), dadurch bleiben nahe Gebiete/Touren bei kleinem
// Massstab zu einem Sammel-Pin zusammengefasst und lassen sich per Pinch/Doppeltipp wieder
// auftrennen. Dadurch entsteht beim Öffnen einer Liste weiterhin kein zusätzlicher Netzwerk-
// Traffic — Kartendaten sind Teil des App-Shells (Service-Worker-Precache), es werden nur die
// ohnehin schon geladenen .points der jeweiligen Tour/Klettergebiete verwendet.
const MAP_STRIP_ZOOM_MIN = 1;
const MAP_STRIP_ZOOM_MAX = 12;
const MAP_STRIP_ZOOM_STEP = 2.4;
// Abstand (in % der Kartenstreifen-Fläche) unter dem zwei Punkte bei Zoom 1x zu einem Sammel-Pin
// zusammengefasst werden — schrumpft mit dem Zoom, damit Reinzoomen nahe Punkte wieder trennt.
// 5.0% entspricht bei Zoom 1x (ganze Schweiz) ca. 19 km (in dieser Grössenordnung überlappen sich
// die Pins sowieso schon rein optisch), bei ZOOM_MAX 1x/12 davon ca. 1.6 km -- reicht, um auch nah
// beieinander liegende, aber klar unterschiedliche Gebiete/Touren (Beispiel aus dem Vorschlag:
// zwei ca. 2 km entfernte Gipfel) beim Reinzoomen wieder zu trennen.
const MAP_STRIP_CLUSTER_BASE_PCT = 5.0;

function mapStripPositions(points){
  const valid = points.filter(p=> p && typeof p.lat==='number' && typeof p.lon==='number');
  if(!valid.length) return [];
  return valid.map(p=>{
    const proj = projectLatLon(p.lat, p.lon);
    return {
      ...p,
      xPct: Math.max(1, Math.min(99, proj.x / GEO_CH_VIEWBOX.w * 100)),
      yPct: Math.max(1, Math.min(99, proj.y / GEO_CH_VIEWBOX.h * 100))
    };
  });
}
// Fasst Punkte zusammen, die beim aktuellen Zoom näher als der Schwellwert liegen. Greedy statt
// optimal (erster nicht zugeordneter Punkt "zieht" alle in Reichweite mit) — für die paar Dutzend
// Punkte einer Liste reicht das, ein Sammel-Pin trägt seine Mitglieder für Popup/Rein-Zoomen mit.
function mapStripClusterPoints(positioned, zoom){
  const threshold = MAP_STRIP_CLUSTER_BASE_PCT / Math.max(MAP_STRIP_ZOOM_MIN, zoom);
  const remaining = positioned.slice();
  const out = [];
  while(remaining.length){
    const seed = remaining.shift();
    const group = [seed];
    for(let i=remaining.length-1; i>=0; i--){
      const d = Math.hypot(remaining[i].xPct-seed.xPct, remaining[i].yPct-seed.yPct);
      if(d <= threshold){ group.push(remaining[i]); remaining.splice(i,1); }
    }
    if(group.length>1){
      out.push({
        isCluster: true,
        id: 'cluster-'+group.map(p=>p.id).join('-'),
        xPct: group.reduce((s,p)=>s+p.xPct,0)/group.length,
        yPct: group.reduce((s,p)=>s+p.yPct,0)/group.length,
        points: group
      });
    }else{
      out.push(group[0]);
    }
  }
  return out;
}
// Hintergrund-SVG (Relief + Seen + Kantonsgrenzen) ist unabhängig von der jeweiligen Liste immer
// gleich — einmal pro Farb-Thema (Firnspur/Fixseil, siehe GEO_CH_HILLSHADE) bauen und cachen statt
// bei jedem render() die ~30 KB Pfad-Strings neu zusammenzusetzen.
let _mapStripBgSvgCache = {};
function mapStripBackgroundSvg(){
  const key = fsAppKey();
  if(_mapStripBgSvgCache[key]) return _mapStripBgSvgCache[key];
  const vb = GEO_CH_VIEWBOX, hs = GEO_CH_HILLSHADE;
  const cantonPaths = Object.values(GEO_CH_CANTON_PATHS).map(d=>`<path d="${d}"/>`).join('');
  const lakePaths = Object.values(GEO_CH_LAKE_PATHS).map(d=>`<path d="${d}"/>`).join('');
  // Neuer Look: Relief nur innerhalb der Landesgrenze (clipPath aus den Kantonsflächen) statt als
  // Rechteck mit ausgefransten Kachel-Rändern, darunter eine helle Landfläche mit weichem Schatten.
  const clipId = 'ch-clip-' + key;
  const svg = `<svg class="map-strip-bg" viewBox="0 0 ${vb.w} ${vb.h}" preserveAspectRatio="xMidYMid meet">
    <defs><clipPath id="${clipId}">${cantonPaths}</clipPath></defs>
    <g class="map-strip-land">${cantonPaths}</g>
    <image class="map-strip-relief" href="${'../' + hs.srcFirnspur}" x="${hs.x}" y="${hs.y}" width="${hs.w}" height="${hs.h}" preserveAspectRatio="none" clip-path="url(#${clipId})"></image>
    <g class="map-strip-lakes">${lakePaths}</g>
    <g class="map-strip-cantons">${cantonPaths}</g>
  </svg>`;
  _mapStripBgSvgCache[key] = svg;
  return svg;
}
function mapStripGetView(kind){
  return (state._mapStripView && state._mapStripView[kind]) || {zoom: MAP_STRIP_ZOOM_MIN, panX:0, panY:0};
}
function mapStripSetView(kind, view){
  if(!state._mapStripView) state._mapStripView = {};
  state._mapStripView[kind] = view;
}
// transform-origin ist bewusst 0/0 (siehe Inline-Style unten) -- Panning/Zoomen bleibt dadurch
// eine einfache translate-vor-Skalierung-Rechnung ohne Offset-Korrektur um die Mitte.
function mapStripClampView(view, containerW, containerH){
  view.zoom = Math.max(MAP_STRIP_ZOOM_MIN, Math.min(MAP_STRIP_ZOOM_MAX, view.zoom));
  const minPanX = containerW - containerW*view.zoom, minPanY = containerH - containerH*view.zoom;
  view.panX = Math.max(minPanX, Math.min(0, view.panX));
  view.panY = Math.max(minPanY, Math.min(0, view.panY));
  return view;
}
function mapStripApplyLiveTransform(wrap, view){
  wrap.style.transform = `translate(${view.panX}px, ${view.panY}px) scale(${view.zoom})`;
}
function mapStripZoomToPoint(kind, canvasEl, xPct, yPct){
  const view = mapStripGetView(kind);
  const rect = canvasEl.getBoundingClientRect();
  // Zoom VOR der Pan-Berechnung clampen -- sonst wird panX/panY passend zum unbegrenzten Zoom
  // zentriert und danach nur noch der Zoom selbst gekappt, wodurch das Zentrieren nicht mehr zum
  // tatsächlichen (gekappten) Zoom passt und der Punkt aus dem sichtbaren Bereich wandern kann.
  const nextZoom = Math.max(MAP_STRIP_ZOOM_MIN, Math.min(MAP_STRIP_ZOOM_MAX, view.zoom * MAP_STRIP_ZOOM_STEP));
  const px = xPct/100*rect.width, py = yPct/100*rect.height;
  const newView = mapStripClampView({ zoom: nextZoom, panX: rect.width/2 - px*nextZoom, panY: rect.height/2 - py*nextZoom }, rect.width, rect.height);
  mapStripSetView(kind, newView);
}
function mapStripResetView(kind){
  mapStripSetView(kind, {zoom: MAP_STRIP_ZOOM_MIN, panX:0, panY:0});
}
// Schliesst ein offenes Pin- oder Sammel-Pin-Popup (z.B. weil woanders auf die Karte getippt
// wurde) -- gibt zurück, ob überhaupt etwas offen war, damit Aufrufer nur bei Änderung neu rendern.
function mapStripCloseOpenPopups(){
  let changed = false;
  if(state._mapStripOpenPinId){ state._mapStripOpenPinId = null; changed = true; }
  if(state._mapStripOpenClusterId){ state._mapStripOpenClusterId = null; changed = true; }
  return changed;
}
// opts: {label, kind:'tour'|'klettergebiet', points:[{id,lat,lon,label}], emptyText, openPinId}
// Neuer Look (Schritt 2): Karte als "Bühne" oben, die Liste liegt als Blatt darüber und schiebt
// sich beim Scrollen über die Karte (siehe .fs-stage/.fs-sheet in look.css) — die Übersichtskarte
// ist damit immer sichtbar statt erst nach einem Klick.
/* ===== Startansicht: echte Karte, Liste = Kartenausschnitt =====
   Die Bühne der Listen (Touren, Hütten, Gebiete) zeigt die swisstopo-Karte statt der Skizze. Die
   Karte wird einmal erzeugt und bei jedem render() nur in den neuen Platzhalter umgehängt
   (Ausschnitt bleibt). Die Liste darunter zeigt nur, was im Ausschnitt liegt; «Alle anzeigen» hebt
   das auf. Ohne Internet bleibt die Skizze darunter sichtbar. */
let fsHomePts = null;      // {kind, openAct, points:[{id,lat,lon,label}]} aus dem letzten mapStripHtml
let fsHomeEl = null, fsHomeMap = null, fsHomeKey = '', fsHomeMarkers = [], fsHomeVisible = null, fsHomeAll = true, fsHomeFitting = false;
function fsHomeMount(){
  const slot = document.querySelector('.fs-home-slot');
  if(!slot || !fsHomePts || typeof maplibregl === 'undefined' && !window.fsmEnsureLoaded) return;
  if(!fsHomeEl){
    fsHomeEl = document.createElement('div');
    fsHomeEl.className = 'fs-home-map';
    fsHomeEl.innerHTML = '<div class="fs-home-map-inner" id="fs-home-map-inner"></div>';
  }
  // Gerade von einer Tour ausgeliehen (eine Karte für alles): nicht zurückholen
  if(fsCtxUsesHome) return;
  if(fsHomeEl.parentNode !== slot){ slot.appendChild(fsHomeEl); if(fsHomeMap) setTimeout(()=> fsHomeMap.resize(), 0); }
  if(fsHomeEl.classList.contains('ready')) slot.classList.add('has-map');
  if(!fsHomeMap){
    fsmEnsureLoaded().then(()=>{ if(!fsHomeMap) fsHomeCreateMap(); }).catch(()=>{ /* offline: Skizze bleibt */ });
  }else fsHomeSync();
}
// Die eine Karte der App: Startkarte, und in Tour/Gebiet ausgeliehen (fsCtxAcquire)
let fsCtxUsesHome = false, fsCtxOn3d = null, fsCtxSnap = null, fsCtxOwner = '';
function fsHomeCreateMap(){
  fsHomeMap = fsmCreateMap('fs-home-map-inner', {zoom: 7, ctlTop: 52, on3d: (m)=>{
    if(fsCtxOn3d){ fsCtxOn3d(m); return; }
    const c = m.getCenter(); fsOpen3d({lat:c.lat, lon:c.lng, zoom: Math.max(12, m.getZoom()), heading: m.getBearing()});
  }});
  fsmWireInfoClicks(fsHomeMap, {sac:{allowAttach:false}});
  fsmWireOrtHold(fsHomeMap);
  // Die Startkarte liegt teils unter Leiste und Blatt: mehr Spielraum, damit alle Touren über dem Blatt Platz finden
  fsHomeMap.setMaxBounds([[1.5, 39], [15.5, 50.5]]); // Süden grosszügig: die untere Hälfte liegt unter dem Blatt
  fsHomeMap.on('moveend', ()=>{ if(fsHomeFitting){ fsHomeFitting = false; return; } fsHomeAll = false; fsHomeFilter(); });
  fsHomeMap.on('zoom', ()=> fsHomeEl.classList.toggle('labels', fsHomeMap.getZoom() >= 8.5 || (fsHomePts && fsHomePts.points.length <= 12)));
  fsmWhenLoaded(fsHomeMap, ()=>{ fsHomeEl.classList.toggle('labels', fsHomeMap.getZoom() >= 8.5 || (fsHomePts && fsHomePts.points.length <= 12)); fsHomeEl.classList.add('ready'); fsHomeKey = ''; fsHomeSync(); const sl = fsHomeEl.parentNode; if(sl && sl.classList.contains('fs-home-slot')) sl.classList.add('has-map'); });
  return fsHomeMap;
}
// Tour/Gebiet: die Startkarte in den Kartenbereich hinter dem Blatt hängen; was danach dazukommt
// (Linien, Punkte, Orte der Tour) wird beim Schliessen wieder entfernt. Ausschnitt und Ebenen bleiben.
// owner: wer die Karte gerade hat ('ctx' = Tour/Gebiet, 'big' = Grosse Karte); nur der darf sie zurückgeben.
function fsCtxAcquire(innerId, on3d, owner){
  const inner = document.getElementById(innerId);
  fsCtxOwner = owner || 'ctx';
  if(!fsHomeEl){
    fsHomeEl = document.createElement('div');
    fsHomeEl.className = 'fs-home-map';
    fsHomeEl.innerHTML = '<div class="fs-home-map-inner" id="fs-home-map-inner"></div>';
  }
  inner.appendChild(fsHomeEl);
  fsHomeEl.classList.add('in-ctx');
  fsCtxUsesHome = true;
  fsCtxOn3d = on3d || null;
  const map = fsHomeMap || fsHomeCreateMap();
  // sofort neu messen (der Ausschnitt der Tour wird gleich danach eingepasst), dann nochmals nach dem Zeichnen
  try{ map.resize(); }catch(e){}
  setTimeout(()=>{ try{ map.resize(); }catch(e){} }, 0);
  fsCtxSnap = null;
  fsmWhenLoaded(map, ()=>{
    if(!fsCtxUsesHome || fsCtxSnap) return;
    const st = map.getStyle() || {layers:[], sources:{}};
    fsCtxSnap = {layers: new Set((st.layers || []).map(l=> l.id)), sources: new Set(Object.keys(st.sources || {})), markers: map._fsm.markers.length};
  });
  return map;
}
function fsCtxRelease(owner){
  if((owner || 'ctx') !== fsCtxOwner) return;
  fsCtxOwner = '';
  const map = fsHomeMap;
  fsCtxUsesHome = false; fsCtxOn3d = null;
  if(map && map._fsm){
    try{
      if(map._fsm.popup){ map._fsm.popup.remove(); map._fsm.popup = null; }
      const snap = fsCtxSnap;
      if(snap && map.getStyle()){
        // nur die eigenen Linien der Tour (own-…) bzw. der Grossen Karte (fl-…) entfernen, nichts von der Grundkarte
        const mine = (id)=> id.indexOf('own-') === 0 || id.indexOf('fl-') === 0;
        (map.getStyle().layers || []).map(l=> l.id).filter(id=> mine(id) && !snap.layers.has(id)).forEach(id=>{ try{ map.removeLayer(id); }catch(e){} });
        Object.keys(map.getStyle().sources || {}).filter(id=> mine(id) && !snap.sources.has(id)).forEach(id=>{ try{ map.removeSource(id); }catch(e){} });
        map._fsm.markers.splice(snap.markers).forEach(m=>{ try{ m.remove(); }catch(e){} });
      }
      map._fsm.orteIds = [];
      fsmOrteDraw(map);
      map._fsCoords = null;
    }catch(e){ dlog('Karte zurückgeben: ' + (e && e.message), 'err'); }
  }
  fsCtxSnap = null;
  if(fsHomeEl){ fsHomeEl.classList.remove('in-ctx', 'in-big'); fsHomeEl.remove(); }
  if(document.querySelector('.fs-home-slot')){ fsHomeMount(); fsHomeFilter(); }
}
// Marker zu den aktuellen Punkten der Liste
function fsHomeSync(){
  if(!fsHomeMap || !fsHomeMap._fsmLoaded || !fsHomePts) return;
  const key = fsHomePts.kind + '|' + fsHomePts.points.map(p=> p.id + ':' + p.lat.toFixed(4) + ',' + p.lon.toFixed(4)).join(';');
  if(key !== fsHomeKey){
    const kindChanged = fsHomeKey.split('|')[0] !== fsHomePts.kind;
    fsHomeKey = key;
    fsHomeMarkers.forEach(m=> m.remove()); fsHomeMarkers = [];
    fsHomePts.points.forEach(p=>{
      const el = document.createElement('button');
      el.type = 'button'; el.className = 'fs-home-pin';
      el.innerHTML = `<i></i><span>${esc(p.label || '')}</span>`;
      el.addEventListener('click', (e)=>{ e.stopPropagation(); fsHomeCard(p); });
      fsHomeMarkers.push(new maplibregl.Marker({element: el, anchor: 'left', offset: [-7, 0]}).setLngLat([p.lon, p.lat]).addTo(fsHomeMap));
    });
    if(kindChanged || fsHomeAll) fsHomeFitAll();
  }
  fsHomeFilter();
  fsHomeRoutesSync();
}
/* ===== Startkarte: Routen der Touren =====
   Übersicht: nur Pins. Ab mittlerem Zoom die Linien der Touren im Ausschnitt, dünn und halb
   durchsichtig. Eine Tour antippen: ihre Linie kräftig, die anderen blasser, dazu ihre Punkte. */
const FS_HOME_ROUTE_MINZOOM = 10.5;
let fsHomeSel = null, fsHomeSelMarkers = [], fsHomeRoutesKey = '';
function fsHomeAccent(){
  try{ return getComputedStyle(document.documentElement).getPropertyValue('--ice-deep').trim() || '#1F5F8B'; }catch(e){ return '#1F5F8B'; }
}
function fsHomeTourLines(t){
  const toLL = q=> Array.isArray(q) ? [+q[1], +q[0]] : [+(q.lon != null ? q.lon : q.lng), +q.lat];
  return fsTourRoutes(t).map(r=> (r.coords || []).map(toLL).filter(c=> isFinite(c[0]) && isFinite(c[1]))).filter(c=> c.length > 1);
}
function fsHomeRoutesSync(){
  const map = fsHomeMap;
  if(!map || !map._fsmLoaded || !map.getStyle()) return;
  const isTours = !!fsHomePts && (fsHomePts.kind === 'tour' || fsHomePts.kind === 'msl');
  const on = isTours && fsmOverlayOn(map, 'tourrouten');
  const ids = on ? fsHomePts.points.map(p=> p.id) : [];
  const tById = new Map((state.tours || []).map(t=> [t.id, t]));
  // Schlüssel: welche Touren + Stand ihrer Linien (neu zeichnen nur bei Änderungen)
  const key = ids.map(id=>{ const t = tById.get(id); return id + ':' + (t ? (t.updatedAt || '') + ':' + fsTourRoutes(t).map(r=> (r.coords || []).length).join('.') : ''); }).join(',');
  if(!map.getSource('fs-home-routes')){
    map.addSource('fs-home-routes', {type:'geojson', data:{type:'FeatureCollection', features:[]}});
    map._fsHomeSelKey = null; // neue Ebenen: Auswahl wieder setzen
    const color = fsHomeAccent();
    map.addLayer({id:'fs-home-routes', type:'line', source:'fs-home-routes', minzoom: FS_HOME_ROUTE_MINZOOM,
      layout:{'line-cap':'round', 'line-join':'round'}, paint:{'line-color': color, 'line-width': 3, 'line-opacity': 0.65}});
    map.addLayer({id:'fs-home-route-sel', type:'line', source:'fs-home-routes', filter:['==', ['get', 'id'], ''],
      layout:{'line-cap':'round', 'line-join':'round'}, paint:{'line-color': color, 'line-width': 5, 'line-opacity': 1}});
  }
  if(key !== fsHomeRoutesKey){
    fsHomeRoutesKey = key;
    const features = [];
    ids.forEach(id=>{ const t = tById.get(id); if(t) fsHomeTourLines(t).forEach(c=> features.push({type:'Feature', properties:{id}, geometry:{type:'LineString', coordinates:c}})); });
    map.getSource('fs-home-routes').setData({type:'FeatureCollection', features});
  }
  const sel = on ? (fsHomeSel || '') : '';
  const t = sel ? (state.tours || []).find(x=> x.id === sel) : null;
  // Nur bei Änderung der Auswahl neu setzen (wird oft aufgerufen)
  const selKey = sel + ':' + (t ? (t.updatedAt || '') + ':' + (t.points || []).length : '');
  if(map._fsHomeSelKey === selKey) return;
  map._fsHomeSelKey = selKey;
  map.setFilter('fs-home-route-sel', ['==', ['get', 'id'], sel]);
  map.setPaintProperty('fs-home-routes', 'line-opacity', sel ? 0.3 : 0.65);
  // Punkte nur der gewählten Tour
  fsHomeSelMarkers.forEach(m=> m.remove()); fsHomeSelMarkers = [];
  if(t) (t.points || []).forEach(pt=>{
    if(!isFinite(pt.lat) || !isFinite(pt.lon)) return;
    const el = document.createElement('div');
    el.className = 'fs-home-tpt';
    el.innerHTML = fsmCategoryMarkerHtml(pt.category || '');
    el.title = pt.label || '';
    fsHomeSelMarkers.push(new maplibregl.Marker({element: el, anchor: 'bottom'}).setLngLat([+pt.lon, +pt.lat]).addTo(map));
  });
}
// «Grosse Karte»: denselben Ausschnitt wie die Startkarte im Vollbild zeigen
// (Leaflet-Ersatz FL zählt den Zoom um 1 höher als MapLibre, siehe FMap.prototype.setView)
document.addEventListener('click', (e)=>{
  const el = e.target.closest && e.target.closest('[data-act="open-standalone-map"]');
  if(!el || !fsHomeMap || !fsHomeEl || !fsHomeEl.isConnected || !fsHomeEl.classList.contains('ready')) return;
  try{ const c = fsHomeMap.getCenter(); lastStandaloneMapView = {center: [c.lat, c.lng], zoom: fsHomeMap.getZoom() + 1}; fsBigMapKeepView = true; }catch(err){}
}, true);
let fsBigMapKeepView = false;
function fsHomeSelect(id){
  fsHomeSel = id || null;
  fsHomeRoutesSync();
  if(!fsHomeSel || !fsHomeMap || !fsmOverlayOn(fsHomeMap, 'tourrouten')) return;
  const t = (state.tours || []).find(x=> x.id === fsHomeSel);
  const lines = t ? fsHomeTourLines(t) : [];
  const pts = [];
  lines.forEach(l=> l.forEach(c=> pts.push(c)));
  ((t && t.points) || []).forEach(p=>{ if(isFinite(p.lat) && isFinite(p.lon)) pts.push([+p.lon, +p.lat]); });
  if(pts.length < 2) return;
  const b = new maplibregl.LngLatBounds(pts[0], pts[0]);
  pts.forEach(c=> b.extend(c));
  const card = fsHomeEl && fsHomeEl.querySelector('.fs-home-card');
  fsHomeFitting = true;
  const ins = fsHomeInset();
  fsHomeMap.fitBounds(b, {padding:{top: 70 + ins.top, left: 40, right: 70, bottom: (card && !card.hidden ? card.offsetHeight : 0) + 40 + ins.bottom}, maxZoom: 14, duration: 600});
}
// Kurzinfo unten auf der Karte; «öffnen» löst dieselbe Aktion aus wie ein Eintrag in der Liste
function fsHomeCard(p){
  if(!fsHomeEl) return;
  let card = fsHomeEl.querySelector('.fs-home-card');
  if(!card){
    card = document.createElement('div'); card.className = 'fs-home-card';
    ['click','pointerdown','touchstart','mousedown'].forEach(ev=> card.addEventListener(ev, e=> e.stopPropagation()));
    fsHomeEl.appendChild(card);
    if(fsHomeMap) fsHomeMap.on('click', ()=>{ card.hidden = true; fsHomeEl.querySelectorAll('.fs-home-pin.on').forEach(x=> x.classList.remove('on')); if(fsHomeSel) fsHomeSelect(null); });
  }
  const all = [].concat(state.tours || [], state.huts || [], state.gebiete || [], state.klettergebiete || [], state.sektoren || []);
  const x = all.find(o=> o && o.id === p.id) || {name: p.label};
  const kind = fsHomePts.kind, act = fsHomePts.openAct;
  const d = x.difficulty || x.climbGrade || x.mandatoryDifficulty || '';
  const facts = [d, x.targetAltitude ? x.targetAltitude + ' m' : (x.altitude ? x.altitude + ' m' : ''), x.elevationGain ? '↑ ' + x.elevationGain + ' Hm' : '', x.duration ? x.duration + ' h' : ''].filter(Boolean);
  const btnLabel = kind === 'hut' ? 'Hütte öffnen' : (kind === 'gebiet' || kind === 'klettergebiet') ? 'Gebiet öffnen' : 'Tour öffnen';
  card.innerHTML = `<button type="button" class="x" aria-label="Schliessen">×</button>
    <b class="n">${esc(x.name || p.label || '')}</b>
    ${x.routeName ? `<span class="s">${esc(x.routeName)}</span>` : ''}
    <span class="s">${esc([x.region, x.subregion].filter(Boolean).join(' – '))}</span>
    ${facts.length ? `<div class="f">${facts.map(f=> `<span>${esc(String(f))}</span>`).join('')}</div>` : ''}
    <button type="button" class="open" data-act="${act}" data-id="${esc(p.id)}">${btnLabel}</button>`;
  card.hidden = false;
  card.querySelector('.x').addEventListener('click', ()=>{ card.hidden = true; fsHomeSelect(null); });
  // Öffnen über den Eintrag der Liste (dieselbe Aktion wie dort), sonst über den Knopf selbst
  card.querySelector('.open').addEventListener('click', (e)=>{
    const li = document.querySelector('.fs-sheet .card[data-act="' + act + '"][data-id="' + CSS.escape(p.id) + '"]');
    if(li){
      e.preventDefault(); card.hidden = true;
      // In der Grossen Karte: erst schliessen; nach der Tour geht es zur Karte zurück
      if(fsHomeEl.classList.contains('in-big')){ modalOpenedFromStandaloneMap = true; closeTopOverlayLayer(); }
      li.click();
    }
  });
  fsHomeEl.querySelectorAll('.fs-home-pin.on').forEach(y=> y.classList.remove('on'));
  const idx = fsHomePts.points.indexOf(p);
  if(idx >= 0 && fsHomeMarkers[idx]) fsHomeMarkers[idx].getElement().classList.add('on');
  fsHomeSelect(p.id);
}
function fsHomeFitAll(dur){
  if(!fsHomeMap || !fsHomePts) return;
  const pts = fsHomePts.points;
  fsHomeAll = true; fsHomeFitting = true;
  if(!pts.length){ fsHomeMap.jumpTo({center:[8.2275, 46.8182], zoom:6.6}); return; }
  const b = new maplibregl.LngLatBounds();
  pts.forEach(p=> b.extend([p.lon, p.lat]));
  const ins = fsHomeInset();
  fsHomeMap.fitBounds(b, {padding:{top: 60 + ins.top, bottom: 40 + ins.bottom, left: 40, right: 70}, maxZoom: pts.length > 1 ? 11 : 8, duration: dur || 0});
  setTimeout(()=>{ fsHomeFitting = false; }, (dur || 0) + 300);
}
// Vorschaubild in den Listeneinträgen: erstes Topo/Foto des Eintrags (falls vorhanden)
function fsCardThumbs(sheet){
  const all = [].concat(state.tours || [], state.huts || [], state.gebiete || [], state.klettergebiete || [], state.sektoren || []);
  sheet.querySelectorAll('.card[data-id]').forEach(card=>{
    if(card._fsThumb || card.classList.contains('fs-tc')) return;
    card._fsThumb = true;
    const x = all.find(o=> o && o.id === card.getAttribute('data-id'));
    const img = x && Array.isArray(x.topoImages) && x.topoImages.find(i=> i && i.url);
    // Hat die Karte schon ein eigenes Bild (z. B. Klettergebiet), keine zweite Vorschau
    if(!img || card.querySelector('img')) return;
    const box = document.createElement('div');
    box.className = 'fs-card-thumb';
    box.innerHTML = topoImageBoxHtml(img, 76, 76, '', 'border-radius:14px;');
    card.classList.add('has-thumb');
    card.appendChild(box);
  });
}
// Liste auf den Kartenausschnitt beschränken (DOM-weit, gilt für alle Listen mit .card[data-id])
function fsHomeFilter(){
  const sheet = document.querySelector('.fs-sheet');
  if(!sheet || !fsHomePts) return;
  const act = fsHomePts.openAct;
  let vis = null;
  // Beim Suchen über alle Einträge, nicht nur den Kartenausschnitt
  const searching = typeof state !== 'undefined' && typeof state.search === 'string' && !!state.search.trim();
  if(!fsHomeAll && fsHomeMap && !searching){
    const b = fsHomeMap.getBounds();
    vis = new Set(fsHomePts.points.filter(p=> b.contains([p.lon, p.lat])).map(p=> p.id));
  }
  fsHomeVisible = vis;
  let shown = 0, total = 0;
  fsCardThumbs(sheet);
  sheet.querySelectorAll('.card').forEach(card=>{
    if(card.parentElement && card.parentElement.closest('.card')) return; // verschachtelte Karten: über die äussere
    const ids = [];
    if(card.getAttribute('data-act') === act && card.getAttribute('data-id')) ids.push(card.getAttribute('data-id'));
    card.querySelectorAll('[data-act="' + act + '"][data-id]').forEach(x=> ids.push(x.getAttribute('data-id')));
    if(!ids.length) return;
    total++;
    const on = !vis || ids.some(id=> vis.has(id));
    card.classList.toggle('fs-home-hidden', !on);
    if(on) shown++;
  });
  let bar = sheet.querySelector('.fs-home-count');
  if(!vis || shown === total){ if(bar) bar.remove(); return; }
  if(!bar){
    bar = document.createElement('div'); bar.className = 'fs-home-count';
    // nach der letzten Werkzeugzeile (Suchen/Filter) einfügen
    let tb = sheet.querySelector('.toolbar');
    while(tb && tb.nextElementSibling && tb.nextElementSibling.classList.contains('toolbar')) tb = tb.nextElementSibling;
    if(tb && tb.parentNode) tb.parentNode.insertBefore(bar, tb.nextSibling); else sheet.insertBefore(bar, sheet.firstChild);
  }
  const word = fsHomePts.kind === 'hut' ? 'Hütten' : (fsHomePts.kind === 'gebiet' || fsHomePts.kind === 'klettergebiet') ? 'Gebiete' : 'Touren';
  const k = shown + '/' + total + '/' + word;
  if(bar.dataset.k !== k){
    bar.dataset.k = k;
    bar.innerHTML = `<span><b>${shown}</b> von ${total} ${word} im Kartenausschnitt</span><button type="button" class="fs-home-all">Alle anzeigen</button>`;
    bar.querySelector('.fs-home-all').onclick = ()=>{ fsHomeFitAll(); fsHomeFilter(); };
  }
}
// Suchfeld in den Listen immer sichtbar, in derselben Zeile wie «Filter» (nur Klassen setzen: das Feld
// selbst nicht verschieben, sonst verliert es beim Neuzeichnen den Cursor).
function fsSearchCollapse(){
  const sheet = document.querySelector('.fs-sheet');
  const inp = sheet && sheet.querySelector('.search-input');
  if(!inp || inp._fsCollapsed) return;
  inp._fsCollapsed = true;
  const tb = inp.closest('.toolbar');
  const row = (tb && tb.nextElementSibling && tb.nextElementSibling.classList.contains('toolbar-row')) ? tb.nextElementSibling : null;
  tb.classList.add('fs-search-tb');
  if(row){ tb.classList.add('fs-search-has-row'); row.classList.add('fs-search-beside'); }
  inp.setAttribute('type', 'search');
  inp.setAttribute('aria-label', 'Touren durchsuchen');
}
(function(){
  if(typeof MutationObserver === 'undefined') return;
  let t = null;
  // Änderungen in der Karte selbst (Marker, Kacheln) und in der Zählzeile zählen nicht – sonst schaukelt sich
  // das auf: Filter schreibt die Zeile, die Zeile löst den Filter aus, … (Karte zeichnete dauernd neu)
  const own = n=>{ const el = n && (n.nodeType === 1 ? n : n.parentElement); return !!(el && el.closest && el.closest('.fs-home-map, .fs-home-count, .maplibregl-map, #fs-3d')); };
  const mo = new MutationObserver((recs)=>{ if(recs.every(r=> own(r.target))) return; clearTimeout(t); t = setTimeout(()=>{ fsSearchCollapse(); if(document.querySelector('.fs-home-slot')){ fsHomeMount(); fsHomeFilter(); } fsHomeLayout(); }, 30); });
  const start = ()=> mo.observe(document.body, {childList:true, subtree:true});
  if(document.body) start(); else document.addEventListener('DOMContentLoaded', start);
})();
/* ===== Startansicht: Karte als ganzer Hintergrund, Blatt mit drei Stufen =====
   Wie bei grossen Karten-Apps: die Karte füllt den Bildschirm, oben schwebt eine Glas-Leiste
   (Disziplin + Menü), die Liste ist ein Blatt mit drei Stufen – «karte» (nur Suche/Filter/Zählzeile),
   «mitte» (Standard) und «liste» (fast ganzer Bildschirm). Ziehen am Griff oder Kopf des Blatts
   wechselt die Stufe, in «karte»/«mitte» zieht man das ganze Blatt. Der Rest der Seite bleibt, wie die
   Apps ihn zeichnen; hier werden nach jedem Zeichnen nur Teile umgehängt (Segment ins Blatt, Menü in
   die Glas-Leiste). Gilt nur, solange eine Liste mit Startkarte zu sehen ist. */
let fsHomeDetent = 'mitte';
function fsHomeDetentPx(d){
  const vh = window.innerHeight;
  const top = (parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--fs-glass-bottom')) || 72) + 8;
  if(d === 'karte') return Math.min(240, Math.round(vh * 0.32));
  if(d === 'liste') return vh - top;
  return Math.round(vh * 0.55);
}
function fsHomeApply(animate){
  const root = document.documentElement;
  const sheet = document.querySelector('main .fs-sheet');
  if(!sheet) return;
  const full = fsHomeDetentPx('liste'), h = fsHomeDetentPx(fsHomeDetent);
  root.dataset.fsHome = fsHomeDetent;
  root.style.setProperty('--fs-home-full', full + 'px');
  root.style.setProperty('--fs-home-vis', h + 'px');
  sheet.style.transition = animate ? 'transform .38s cubic-bezier(.2,.9,.25,1)' : 'none';
  sheet.style.transform = 'translateY(' + (full - h) + 'px)';
  if(fsHomeDetent !== 'liste') sheet.scrollTop = 0;
  // Zeigt die Karte alle Einträge, bleiben sie über dem Blatt sichtbar
  if(animate && fsHomeAll && fsHomeDetent !== 'liste') try{ fsHomeFitAll(380); }catch(e){}
}
// Von Glas-Leiste und Blatt verdeckter Rand der Karte (nur in der Startansicht)
function fsHomeInset(){
  if(!document.documentElement.classList.contains('fs-mapmode')) return {top: 0, bottom: 0};
  return {top: (parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--fs-glass-bottom')) || 64) - 40,
    bottom: Math.min(fsHomeDetentPx(fsHomeDetent), Math.round(window.innerHeight * 0.6))};
}
function fsHomeSetDetent(d, animate){
  if(d === fsHomeDetent && document.documentElement.dataset.fsHome === d) return;
  fsHomeDetent = d;
  fsHomeApply(animate !== false);
}
function fsHomeLayout(){
  const root = document.documentElement;
  const slot = document.querySelector('main .fs-home-slot');
  const sheet = slot && document.querySelector('main .fs-sheet');
  if(!sheet){ root.classList.remove('fs-mapmode'); delete root.dataset.fsHome; document.querySelectorAll('body > .fs-fab').forEach(x=> x.remove()); return; }
  if(!root.classList.contains('fs-mapmode')){ root.classList.add('fs-mapmode'); setTimeout(()=>{ try{ if(fsHomeMap){ const all = fsHomeAll; fsHomeFitting = true; fsHomeMap.resize(); fsHomeFitting = false; fsHomeAll = all; if(all) fsHomeFitAll(); } }catch(e){} }, 0); }
  // Glas-Leiste: Disziplin-Umschalter und Menü
  const bar = document.querySelector('.app-switch-bar');
  let glass = document.getElementById('fs-glass');
  if(!glass){
    glass = document.createElement('div'); glass.id = 'fs-glass';
    glass.innerHTML = '<div class="fs-glass-menu"></div>';
    document.body.appendChild(glass);
    if(bar){
      glass.prepend(bar);
      // Kompakte Leiste (Stufe «karte»): Tipp auf die aktive Disziplin klappt alle auf
      bar.addEventListener('click', e=>{
        const a = e.target.closest('a');
        if(a && a.classList.contains('active') && root.dataset.fsHome === 'karte' && !bar.classList.contains('open')){ e.preventDefault(); bar.classList.add('open'); }
      }, true);
      document.addEventListener('pointerdown', e=>{ if(!e.target.closest('.app-switch-bar')) bar.classList.remove('open'); }, true);
    }
  }
  const menu = document.querySelector('#app .hero .who-menu');
  const mslot = glass.querySelector('.fs-glass-menu');
  if(menu && menu.parentNode !== mslot){ mslot.innerHTML = ''; mslot.appendChild(menu); }
  // Segment Gebiete/Touren/Hütten ins Blatt, Griff davor
  const tabs = document.querySelector('#app .hero .tabs');
  if(tabs && tabs.parentNode !== sheet) sheet.prepend(tabs);
  if(!sheet.querySelector(':scope > .fs-grip')){
    const g = document.createElement('div'); g.className = 'fs-grip'; g.setAttribute('role', 'button'); g.tabIndex = 0;
    g.setAttribute('aria-label', 'Blatt verschieben: Karte oder Liste');
    g.addEventListener('click', ()=>{ if(g._dragged) return; fsHomeSetDetent(fsHomeDetent === 'liste' ? 'karte' : fsHomeDetent === 'karte' ? 'mitte' : 'liste'); });
    g.addEventListener('keydown', e=>{ if(e.key === 'ArrowUp'){ e.preventDefault(); fsHomeSetDetent(fsHomeDetent === 'karte' ? 'mitte' : 'liste'); } if(e.key === 'ArrowDown'){ e.preventDefault(); fsHomeSetDetent(fsHomeDetent === 'liste' ? 'mitte' : 'karte'); } });
    sheet.prepend(g);
  }
  fsHomeHero(sheet);
  if(!sheet._fsDrag){ sheet._fsDrag = true; fsHomeWireDrag(sheet); }
  if(bar) bar.querySelectorAll('a').forEach(a=>{ if(!a.getAttribute('aria-label')) a.setAttribute('aria-label', a.textContent.trim()); });
  // «Neue Tour» läge im verschobenen Blatt (transform) sonst ausserhalb des Bildschirms
  const fab = sheet.querySelector('.fs-fab');
  if(fab){ document.querySelectorAll('body > .fs-fab').forEach(x=> x.remove()); document.body.appendChild(fab); }
  // Knopf «Karte» in der Stufe «liste»
  if(!document.getElementById('fs-home-mapbtn')){
    const b = document.createElement('button'); b.type = 'button'; b.id = 'fs-home-mapbtn'; b.className = 'fs-home-mapbtn';
    b.innerHTML = fsIconHtml('map') + '<span>Karte</span>';
    b.addEventListener('click', ()=> fsHomeSetDetent('mitte'));
    document.body.appendChild(b);
  }
  fsHomeApply(false);
}
// Kopf des Blatts in der Stufe «liste»: Bergfoto der App mit Titel und Bestand. Beim Scrollen zieht das
// Foto langsamer mit und blasst aus; ist es weg, steht der Titel klein im Griff.
function fsHomeCountsText(){
  const k = fsAppKey(), T = state.tours || [];
  const tours = k === 'fixseil' ? T.filter(t=> (t.tourCategory === 'msl') === (state.tourCategoryContext === 'msl')) : T;
  const gebiete = k === 'fixseil' ? (state.sektoren || []) : (state.gebiete || []);
  const n = (c, one, more)=> c ? c + ' ' + (c === 1 ? one : more) : '';
  return [n(tours.length, 'Tour', 'Touren'), n(gebiete.length, 'Gebiet', 'Gebiete'), n((state.huts || []).length, 'Hütte', 'Hütten')].filter(Boolean).join(' · ');
}
function fsHomeHero(sheet){
  const heroEl = document.querySelector('#app .hero');
  const title = ((heroEl && heroEl.querySelector('h1')) || {}).textContent || '';
  let img = 'none';
  try{ if(heroEl) img = getComputedStyle(heroEl, '::before').backgroundImage || 'none'; }catch(e){}
  let h = sheet.querySelector(':scope > .fs-sheet-hero');
  if(!h){
    h = document.createElement('div'); h.className = 'fs-sheet-hero';
    h.innerHTML = '<div class="fs-sheet-hero-img" aria-hidden="true"></div><div class="fs-sheet-hero-txt"><h2></h2><p></p></div>';
    const g = sheet.querySelector(':scope > .fs-grip');
    if(g) g.after(h); else sheet.prepend(h);
  }
  h.querySelector('.fs-sheet-hero-img').style.backgroundImage = img;
  h.classList.toggle('no-img', img === 'none');
  h.querySelector('h2').textContent = title;
  h.querySelector('p').textContent = fsHomeCountsText();
  const g = sheet.querySelector(':scope > .fs-grip');
  if(g){
    let gt = g.querySelector('.fs-grip-title');
    if(!gt){ gt = document.createElement('span'); gt.className = 'fs-grip-title'; gt.setAttribute('aria-hidden', 'true'); g.appendChild(gt); }
    gt.textContent = title;
  }
  if(!sheet._fsHeroScroll){
    sheet._fsHeroScroll = true;
    const upd = ()=>{ const hh = h.offsetHeight || 180; const pr = Math.max(0, Math.min(1, sheet.scrollTop / Math.max(1, hh - 20))); sheet.style.setProperty('--fs-hero-p', pr.toFixed(3)); sheet.classList.toggle('fs-hero-gone', pr >= 1); };
    sheet.addEventListener('scroll', upd, {passive: true});
    upd();
  }
}
// Ziehen: in «karte»/«mitte» das ganze Blatt, in «liste» nur Griff und Kopf (Segment, Suche, Filter)
// Ziehen: in «karte»/«mitte» das ganze Blatt, in «liste» Griff und Kopf (Segment, Suche, Filter) und,
// wenn die Liste ganz oben ist, jede Geste nach unten. Losgelassen zählt, wohin der Schwung trägt:
// ein kräftiger Wisch darf eine Stufe überspringen, langsames Ziehen landet bei der nächsten Stufe.
function fsHomeWireDrag(sheet){
  let st = null;
  const D = ['karte', 'mitte', 'liste'];
  const isHead = el=> !!(el.closest('.fs-grip') || el.closest('.tabs') || el.closest('.toolbar') || el.closest('.fs-home-count'));
  const begin = y=>{ const full = fsHomeDetentPx('liste'); st = {y0: y, base: full - fsHomeDetentPx(fsHomeDetent), full, moved: false, last: null, hist: []}; };
  const move = y=>{
    const dy = y - st.y0;
    if(!st.moved){ st.moved = true; sheet.style.transition = 'none'; }
    const max = st.full - fsHomeDetentPx('karte') + 40;
    const ty = Math.max(-20, Math.min(max, st.base + dy));
    sheet.style.transform = 'translateY(' + ty + 'px)';
    document.documentElement.style.setProperty('--fs-home-vis', (st.full - ty) + 'px');
    st.last = ty;
    const now = performance.now();
    st.hist.push({t: now, y}); while(st.hist.length > 2 && now - st.hist[0].t > 120) st.hist.shift();
  };
  const end = ()=>{
    const s = st; st = null;
    if(!s || !s.moved || s.last == null) return;
    const g = sheet.querySelector('.fs-grip'); if(g){ g._dragged = true; setTimeout(()=>{ g._dragged = false; }, 0); }
    // Kein Klick nach dem Ziehen (sonst öffnet sich die Tour unter dem Finger)
    // (nur kurz: kommt kein Klick, darf der nächste echte Tipp nicht verschluckt werden)
    const stop = ev=>{ ev.stopPropagation(); ev.preventDefault(); };
    sheet.addEventListener('click', stop, {capture: true, once: true});
    setTimeout(()=> sheet.removeEventListener('click', stop, {capture: true}), 350);
    const a = s.hist[0], b = s.hist[s.hist.length - 1];
    const v = (a && b && b.t > a.t) ? (b.y - a.y) / (b.t - a.t) : 0; // px/ms, positiv = nach unten
    const aim = (s.full - s.last) - v * 220; // sichtbare Höhe, wohin der Schwung trägt
    fsHomeDetent = D.map(d=> ({d, h: fsHomeDetentPx(d)})).reduce((m, o)=> Math.abs(o.h - aim) < Math.abs(m.h - aim) ? o : m).d;
    fsHomeApply(true);
  };
  // Maus, Stift und Finger auf Griff/Kopf (bzw. überall in «karte»/«mitte»)
  sheet.addEventListener('pointerdown', e=>{
    if(e.button > 0 || e.target.closest('input, select, textarea, .fs-filter-sheet')) return;
    if(fsHomeDetent === 'liste' && !isHead(e.target)) return;
    begin(e.clientY); st.id = e.pointerId; st.ptr = true;
  });
  sheet.addEventListener('pointermove', e=>{
    if(!st || !st.ptr || e.pointerId !== st.id) return;
    if(!st.moved && Math.abs(e.clientY - st.y0) < 8) return;
    if(!st.moved){ try{ sheet.setPointerCapture(e.pointerId); }catch(err){} }
    move(e.clientY);
  });
  const pend = e=>{ if(st && st.ptr && e.pointerId === st.id) end(); };
  sheet.addEventListener('pointerup', pend);
  sheet.addEventListener('pointercancel', pend);
  // Finger in der Liste («liste»), ganz oben, nach unten: Blatt statt Liste ziehen
  sheet.addEventListener('touchstart', e=>{
    if(fsHomeDetent !== 'liste' || st || e.touches.length !== 1 || isHead(e.target) || e.target.closest('input, select, textarea, .fs-filter-sheet')) return;
    sheet._fsPull = {y: e.touches[0].clientY, top: sheet.scrollTop <= 0};
  }, {passive: true});
  sheet.addEventListener('touchmove', e=>{
    const pl = sheet._fsPull;
    if(!pl) return;
    const y = e.touches[0].clientY;
    if(!st){
      if(!pl.top || y - pl.y < -4){ sheet._fsPull = null; return; }
      if(y - pl.y < 8) return;
      begin(pl.y);
    }
    e.preventDefault();
    move(y);
  }, {passive: false});
  const tend = ()=>{ if(sheet._fsPull){ sheet._fsPull = null; if(st && !st.ptr) end(); } };
  sheet.addEventListener('touchend', tend);
  sheet.addEventListener('touchcancel', tend);
  // Suchen braucht Platz für die Tastatur
  sheet.addEventListener('focusin', e=>{ if(e.target.matches('.search-input')) fsHomeSetDetent('liste'); });
}
window.addEventListener('resize', ()=>{ if(document.documentElement.classList.contains('fs-mapmode')) fsHomeApply(false); });

function stageLayoutHtml(mapHtml, sheetHtml){
  return `<div class="fs-stage">${mapHtml}</div><div class="fs-sheet">${sheetHtml}</div>`;
}
function mapStripHtml(opts){
  const { label, kind, points, emptyText, openPinId } = opts;
  const positioned = mapStripPositions(points || []);
  const view = mapStripGetView(kind);
  const clusters = mapStripClusterPoints(positioned, view.zoom);
  const openAct = kind==='klettergebiet' ? 'open-klettergebiet' : kind==='hut' ? 'open-hut' : kind==='gebiet' ? 'open-gebiet' : 'open-tour';
  const linkLabel = (kind==='klettergebiet' || kind==='gebiet') ? 'Zum Gebiet' : kind==='hut' ? 'Zur Hütte' : 'Zur Tour';
  const openClusterId = state._mapStripOpenClusterId;
  const pinScale = 1 / view.zoom;
  fsHomePts = {kind, openAct, points: (points || []).filter(p=> p && isFinite(p.lat) && isFinite(p.lon))};
  return `<div class="fs-home-slot">
    <div class="map-strip">
      <div class="map-strip-head">
        <span class="map-strip-label">🗺️ ${esc(label)}</span>
        <span class="map-strip-head-actions">
          ${view.zoom > MAP_STRIP_ZOOM_MIN + 0.01 ? `<button type="button" class="map-strip-hint" data-act="map-strip-reset" data-kind="${kind}">↺ Ganze Schweiz</button>` : ''}
          <button type="button" class="map-strip-hint" data-act="open-standalone-map">⛶ Grosse Karte</button>
        </span>
      </div>
      <div class="map-strip-canvas" data-kind="${kind}">
        <div class="map-strip-zoomwrap" style="transform: translate(${view.panX}px, ${view.panY}px) scale(${view.zoom}); transform-origin: 0 0;">
          ${mapStripBackgroundSvg()}
          ${clusters.map(c=>{
            if(c.isCluster){
              const open = openClusterId===c.id;
              // Statt einer nichtssagenden Zahl im Kreis: Name des ersten Punkts + Anzahl weiterer
              // -- gibt wenigstens etwas Orientierung, welche Gegend der Sammel-Pin überhaupt meint.
              const clusterLabel = c.points[0].label + (c.points.length>1 ? ` +${c.points.length-1}` : '');
              return `
                <div class="map-strip-pin map-strip-cluster ${open ? 'open' : ''}" style="left:${c.xPct}%; top:${c.yPct}%; transform:translate(-50%,-50%) scale(${pinScale});">
                  <button type="button" class="map-strip-dot map-strip-cluster-dot" data-act="map-strip-cluster" data-kind="${kind}" data-id="${esc(c.id)}" data-cx="${c.xPct}" data-cy="${c.yPct}" title="${c.points.length} Ziele hier"></button>
                  ${open ? `
                    <div class="map-strip-popup map-strip-popup-list">
                      ${c.points.map(p=>`<button type="button" data-act="${openAct}" data-id="${esc(p.id)}">${esc(p.label)}</button>`).join('')}
                    </div>
                  ` : `<div class="map-strip-nlabel" data-act="map-strip-cluster" data-kind="${kind}" data-id="${esc(c.id)}" data-cx="${c.xPct}" data-cy="${c.yPct}" aria-hidden="true">${esc(clusterLabel)}</div>`}
                </div>`;
            }
            const p = c;
            return `
              <div class="map-strip-pin ${openPinId===p.id ? 'open' : ''}" style="left:${p.xPct}%; top:${p.yPct}%; transform:translate(-50%,-50%) scale(${pinScale});">
                <button type="button" class="map-strip-dot" data-act="map-strip-toggle" data-id="${esc(p.id)}" title="${esc(p.label)}" aria-label="${esc(p.label)}"></button>
                ${openPinId===p.id ? `
                  <div class="map-strip-popup">
                    <strong>${esc(p.label)}</strong>
                    <button type="button" data-act="${openAct}" data-id="${esc(p.id)}">${linkLabel} →</button>
                  </div>
                ` : `<div class="map-strip-nlabel" data-act="map-strip-toggle" data-id="${esc(p.id)}" aria-hidden="true">${esc(p.label)}</div>`}
              </div>`;
          }).join('')}
        </div>
        <div class="map-strip-compass"><div class="n"></div>N</div>
        ${!positioned.length ? `<div class="map-strip-empty">${esc(emptyText || '')}</div>` : ''}
      </div>
    </div>
    </div>
  `;
}
// Nach jedem render()/renderListOnly() aufrufen (siehe wireGlobalHandlers in index.html/fixseil.html):
// verdrahtet Pinch-Zoom, Verschieben (Finger + Maus zum Testen) und Doppeltipp/-klick live direkt
// auf dem DOM-Knoten, OHNE während der Geste render() aufzurufen (das würde die Geste durch das
// Neuaufbauen des ganzen Kartenstreifens abreissen) — erst am Gesten-Ende wird der Zustand in
// state._mapStripView committet und einmalig neu gerendert, damit die Cluster-Bildung zum neuen
// Zoom passt.
function wireMapStripCanvases(){
  document.querySelectorAll('.map-strip-canvas').forEach(canvasEl=>{
    const kind = canvasEl.getAttribute('data-kind');
    const wrap = canvasEl.querySelector('.map-strip-zoomwrap');
    if(!wrap || !kind) return;
    let view = mapStripGetView(kind);
    let pinchStartDist = null, pinchStartZoom = 1, pinchWorldX = 0, pinchWorldY = 0;
    let panStartX = null, panStartY = null, panOriginX = 0, panOriginY = 0;
    let gestureMoved = false;
    let lastTapTime = 0, lastTapX = 0, lastTapY = 0;
    // Bei der Standardansicht (ganze Schweiz, nicht reingezoomt) gibt es nichts zu verschieben --
    // ein Einzelfinger-Wisch soll dann ganz normal die Seite runterscrollen, statt (wirkungslos)
    // als Kartenverschieben abgefangen zu werden. Erst gezoomt macht Ein-Finger-Pan Sinn, dann
    // braucht die Karte die Geste exklusiv fuer sich (siehe touch-action unten).
    function updateTouchAction(){ canvasEl.style.touchAction = view.zoom > MAP_STRIP_ZOOM_MIN + 0.01 ? 'none' : 'pan-y'; }
    updateTouchAction();

    function touchDist(t){ return Math.hypot(t[0].clientX-t[1].clientX, t[0].clientY-t[1].clientY); }
    function commit(){
      const rect = canvasEl.getBoundingClientRect();
      mapStripClampView(view, rect.width, rect.height);
      mapStripSetView(kind, view);
      render();
    }
    function maybeDoubleTap(clientX, clientY){
      const now = Date.now();
      const isDoubleTap = (now - lastTapTime < 350) && Math.hypot(clientX-lastTapX, clientY-lastTapY) < 30;
      lastTapTime = isDoubleTap ? 0 : now; lastTapX = clientX; lastTapY = clientY;
      if(!isDoubleTap){
        // Einfacher Tipp auf die Karte (nicht auf einen Pin) -- ein offenes Popup soll dabei
        // wieder einklappen, genau wie ein zweiter Klick auf denselben Pin.
        if(mapStripCloseOpenPopups()) render();
        return;
      }
      const rect = canvasEl.getBoundingClientRect();
      if(view.zoom > MAP_STRIP_ZOOM_MIN + 0.01){ mapStripResetView(kind); }
      else{ mapStripZoomToPoint(kind, canvasEl, (clientX-rect.left)/rect.width*100, (clientY-rect.top)/rect.height*100); }
      render();
    }

    canvasEl.addEventListener('touchstart', (e)=>{
      gestureMoved = false;
      if(e.touches.length===2){
        panStartX = null;
        pinchStartDist = touchDist(e.touches);
        pinchStartZoom = view.zoom;
        const rect = canvasEl.getBoundingClientRect();
        const midX = (e.touches[0].clientX+e.touches[1].clientX)/2 - rect.left;
        const midY = (e.touches[0].clientY+e.touches[1].clientY)/2 - rect.top;
        pinchWorldX = (midX - view.panX)/view.zoom;
        pinchWorldY = (midY - view.panY)/view.zoom;
      }else if(e.touches.length===1){
        pinchStartDist = null;
        panStartX = e.touches[0].clientX; panStartY = e.touches[0].clientY;
        panOriginX = view.panX; panOriginY = view.panY;
      }
    }, {passive:true});

    canvasEl.addEventListener('touchmove', (e)=>{
      if(e.touches.length===2 && pinchStartDist){
        e.preventDefault(); gestureMoved = true;
        const rect = canvasEl.getBoundingClientRect();
        const newDist = touchDist(e.touches);
        const newZoom = Math.max(MAP_STRIP_ZOOM_MIN, Math.min(MAP_STRIP_ZOOM_MAX, pinchStartZoom * (newDist/pinchStartDist)));
        const midX = (e.touches[0].clientX+e.touches[1].clientX)/2 - rect.left;
        const midY = (e.touches[0].clientY+e.touches[1].clientY)/2 - rect.top;
        view = mapStripClampView({ zoom: newZoom, panX: midX - pinchWorldX*newZoom, panY: midY - pinchWorldY*newZoom }, rect.width, rect.height);
        mapStripApplyLiveTransform(wrap, view);
      }else if(e.touches.length===1 && panStartX!==null){
        if(view.zoom <= MAP_STRIP_ZOOM_MIN + 0.01) return; // nicht gezoomt -> Seite normal scrollen lassen
        e.preventDefault(); gestureMoved = true;
        const rect = canvasEl.getBoundingClientRect();
        view.panX = panOriginX + (e.touches[0].clientX-panStartX);
        view.panY = panOriginY + (e.touches[0].clientY-panStartY);
        mapStripClampView(view, rect.width, rect.height);
        mapStripApplyLiveTransform(wrap, view);
      }
    }, {passive:false});

    canvasEl.addEventListener('touchend', (e)=>{
      if(e.touches.length>0) return;
      const wasPinch = !!pinchStartDist, wasPan = panStartX!==null;
      pinchStartDist = null; panStartX = null; panStartY = null;
      if(!wasPinch && !wasPan) return;
      if(gestureMoved){ commit(); return; }
      // Tap ohne Bewegung und nicht auf einem Pin (der hat sein eigenes data-act) -> Doppeltipp prüfen.
      const touch = e.changedTouches[0];
      if(touch && !(touch.target && touch.target.closest && touch.target.closest('.map-strip-pin'))){
        maybeDoubleTap(touch.clientX, touch.clientY);
      }
    });

    // Maus-Verschieben + Doppelklick zum Testen am Desktop (Pinch geht nur mit Touch).
    canvasEl.addEventListener('mousedown', (e)=>{
      if(e.button!==0 || (e.target.closest && e.target.closest('.map-strip-pin'))) return;
      gestureMoved = false;
      const startX = e.clientX, startY = e.clientY;
      panOriginX = view.panX; panOriginY = view.panY;
      const onMove = (ev)=>{
        gestureMoved = true;
        const rect = canvasEl.getBoundingClientRect();
        view.panX = panOriginX + (ev.clientX-startX);
        view.panY = panOriginY + (ev.clientY-startY);
        mapStripClampView(view, rect.width, rect.height);
        mapStripApplyLiveTransform(wrap, view);
      };
      const onUp = ()=>{
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
        if(gestureMoved) commit();
      };
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
    });
    canvasEl.addEventListener('dblclick', (e)=>{
      if(e.target.closest && e.target.closest('.map-strip-pin')) return;
      e.preventDefault();
      const rect = canvasEl.getBoundingClientRect();
      if(view.zoom > MAP_STRIP_ZOOM_MIN + 0.01){ mapStripResetView(kind); }
      else{ mapStripZoomToPoint(kind, canvasEl, (e.clientX-rect.left)/rect.width*100, (e.clientY-rect.top)/rect.height*100); }
      render();
    });
    // Einfacher Klick auf die Karte (nicht auf einen Pin, keine Verschieben-Geste) -- Desktop-
    // Pendant zum Einfach-Tipp oben: schliesst ein offenes Popup wieder.
    canvasEl.addEventListener('click', (e)=>{
      if(e.target.closest && e.target.closest('.map-strip-pin')) return;
      if(gestureMoved) return;
      if(mapStripCloseOpenPopups()) render();
    });
  });
}
function fmtDate(iso){
  if(!iso) return '';
  const d = new Date(iso);
  return d.toLocaleDateString('de-CH', {day:'2-digit', month:'2-digit', year:'numeric'}) + ' ' + d.toLocaleTimeString('de-CH',{hour:'2-digit',minute:'2-digit'});
}
function fmtDateOnly(isoDate){
  if(!isoDate) return '';
  const d = new Date(isoDate+'T00:00:00');
  if(isNaN(d.getTime())) return isoDate;
  return d.toLocaleDateString('de-CH', {day:'2-digit', month:'2-digit', year:'numeric'});
}
function fmtDateShort(dateStr){
  if(!dateStr) return '';
  const d = new Date(dateStr+'T00:00:00');
  if(isNaN(d.getTime())) return dateStr;
  return d.toLocaleDateString('de-CH', {day:'2-digit', month:'2-digit', year:'numeric'});
}
function fmtWeekday(dateStr){
  if(!dateStr) return '';
  const d = new Date(dateStr+'T00:00:00');
  if(isNaN(d.getTime())) return '';
  return d.toLocaleDateString('de-CH', {weekday:'short'});
}
function todayStr(){ return new Date().toISOString().slice(0,10); }
function isPastAgendaItem(item){
  const ref = item.endDate || item.startDate;
  if(!ref) return false;
  return ref < todayStr();
}
function showToast(message, isError){
  const old = document.querySelector('.toast');
  if(old) old.remove();
  const el = document.createElement('div');
  el.className = 'toast' + (isError ? ' error' : '');
  // Screenreader: Fehler sofort, sonst höflich vorlesen
  el.setAttribute('role', isError ? 'alert' : 'status');
  el.textContent = message;
  document.body.appendChild(el);
  setTimeout(()=>{ el.remove(); }, isError ? 5000 : 2500);
}
function markUnsaved(){ state.hasUnsavedChanges = true; }
function markSaved(){ state.hasUnsavedChanges = false; }

