/* ================= Topo-Bilder (MSL/Hochtour) — Cloud Storage ================= */
const TOPO_IMAGES_PATH = 'topoImages';
const TOPO_IMAGE_MAX_COUNT = 10;

function compressImageFile(file, maxWidth, quality){
  return new Promise((resolve, reject)=>{
    const reader = new FileReader();
    reader.onload = ()=>{
      const img = new Image();
      img.onload = ()=>{
        let w = img.width, h = img.height;
        if(w > maxWidth){ h = Math.round(h * (maxWidth / w)); w = maxWidth; }
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);
        canvas.toBlob((blob)=>{
          if(blob) resolve(blob); else reject(new Error('Komprimierung fehlgeschlagen.'));
        }, 'image/jpeg', quality);
      };
      img.onerror = ()=> reject(new Error('Bild konnte nicht gelesen werden — ist es eine gültige Bilddatei?'));
      img.src = reader.result;
    };
    reader.onerror = ()=> reject(new Error('Datei konnte nicht gelesen werden.'));
    reader.readAsDataURL(file);
  });
}

async function uploadTopoImageBlob(blob, storagePath){
  await ensureValidAuthToken();
  const url = `https://firebasestorage.googleapis.com/v0/b/${STORAGE_BUCKET}/o?name=${encodeURIComponent(storagePath)}`;
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + authState.idToken, 'Content-Type': 'image/jpeg' },
    body: blob
  });
  if(!res.ok) throw new Error('Upload fehlgeschlagen (Status ' + res.status + ')');
  const data = await res.json();
  const token = data.downloadTokens;
  return `https://firebasestorage.googleapis.com/v0/b/${STORAGE_BUCKET}/o/${encodeURIComponent(storagePath)}?alt=media&token=${token}`;
}

async function deleteTopoImageFile(storagePath){
  try{
    await ensureValidAuthToken();
    const url = `https://firebasestorage.googleapis.com/v0/b/${STORAGE_BUCKET}/o/${encodeURIComponent(storagePath)}`;
    const res = await fetch(url, { method:'DELETE', headers:{ 'Authorization': 'Bearer ' + authState.idToken } });
    return res.ok;
  }catch(e){ return false; }
}

// cropRect: {x,y,w,h,naturalW,naturalH} — x..h als Brüche 0..1 relativ zum UNROTIERTEN
// Originalbild; das Original bleibt in Storage unverändert.
// Ein Baustein für alle Stellen, die ein Topo-Bild mit Ausschnitt zeigen (Miniaturen, Galerie,
// Karten-Popup, Vollbild): Ausschnitt UND Drehung werden gemeinsam berücksichtigt, und der
// Ausschnitt wird nie verzerrt. Rechnet in echten Pixeln (naturalW/H aus dem Zuschneiden):
// ein Fenster in der Grösse des Ausschnitts (gedreht), darin das ganze Bild verschoben.
// fit: 'cover' füllt die Box (z. B. quadratische Miniatur), 'contain' zeigt den ganzen Ausschnitt.
function topoCropGeometry(img, boxW, boxH, fit){
  const c = img.cropRect;
  const rot = ((img.rotation||0) % 360 + 360) % 360;
  const swapped = rot===90 || rot===270;
  const cw = c.w * c.naturalW, ch = c.h * c.naturalH;
  const dw = swapped ? ch : cw, dh = swapped ? cw : ch;
  if(!boxH) boxH = boxW * dh / dw;
  const s = fit==='contain' ? Math.min(boxW/dw, boxH/dh) : Math.max(boxW/dw, boxH/dh);
  return { boxW, boxH, rot, swapped, frameW: cw*s, frameH: ch*s,
    imgW: c.naturalW*s, imgH: c.naturalH*s, imgX: -c.x*c.naturalW*s, imgY: -c.y*c.naturalH*s };
}
function topoCropInnerHtml(img, g){
  return `<div style="position:absolute; left:50%; top:50%; width:${g.frameW.toFixed(1)}px; height:${g.frameH.toFixed(1)}px; overflow:hidden; transform:translate(-50%,-50%) rotate(${g.rot}deg);"><img src="${esc(img.url)}" alt="" draggable="false" style="position:absolute; left:${g.imgX.toFixed(1)}px; top:${g.imgY.toFixed(1)}px; width:${g.imgW.toFixed(1)}px; height:${g.imgH.toFixed(1)}px; max-width:none; max-height:none;"/></div>`;
}
function hasUsableCrop(img){
  return !!(img && img.cropRect && img.cropRect.naturalW && img.cropRect.naturalH);
}
// Topo-Bild in einer Box: boxW×boxH (beide gesetzt) = gefüllte Box; boxH leer = Höhe aus dem
// Ausschnitt (eigenes Seitenverhältnis), dabei höchstens maxH hoch.
function topoImageBoxHtml(img, boxW, boxH, attrs, extraStyle, maxH){
  attrs = attrs || ''; extraStyle = extraStyle || '';
  if(hasUsableCrop(img)){
    let g = topoCropGeometry(img, boxW, boxH, 'cover');
    if(!boxH && maxH && g.boxH > maxH) g = topoCropGeometry(img, maxH * boxW / g.boxH, maxH, 'cover');
    return `<div ${attrs} style="position:relative; overflow:hidden; flex-shrink:0; width:${g.boxW.toFixed(1)}px; height:${g.boxH.toFixed(1)}px; ${extraStyle}">${topoCropInnerHtml(img, g)}</div>`;
  }
  const rot = img.rotation ? ` transform:rotate(${img.rotation}deg);` : '';
  if(boxH) return `<img src="${esc(img.url)}" ${attrs} style="width:${boxW}px; height:${boxH}px; object-fit:cover; flex-shrink:0;${rot} ${extraStyle}"/>`;
  return `<img src="${esc(img.url)}" ${attrs} style="max-width:${boxW}px; max-height:${maxH||230}px; object-fit:contain;${rot} ${extraStyle}"/>`;
}
// Für data-images (Vollbild): Ausschnitt mitgeben, sonst zeigt das Vollbild immer das Original.
function topoImagesJsonForViewer(images){
  return esc(JSON.stringify(images.map(img=>({id:img.id, url:img.url, rotation:img.rotation||0, cropRect:img.cropRect||null}))));
}

// images wird explizit übergeben (statt aus dem hiddenListId-Feld gelesen): beim allerersten
// Rendern eines Formulars existiert das zugehörige Hidden-Input im DOM noch gar nicht — das
// Formular-HTML wird ja gerade erst als String gebaut. Ein DOM-Read an dieser Stelle liefe daher
// leer, und die Miniaturansicht (samt Dreh-/Entfernen-Buttons) würde beim Öffnen fehlen.
function topoImageThumbsHtml(images, hiddenListId){
  if(!images || !images.length) return '';
  const imagesJson = topoImagesJsonForViewer(images);
  return `<div class="chips" style="margin-top:8px;">${images.map((img,i)=>
    `<span class="chip" style="background:var(--ice-light); border-color:transparent; padding:3px 8px 3px 3px; display:inline-flex; align-items:center; gap:6px;">
      ${topoImageBoxHtml(img, 32, 32, `data-act="view-topo-image" data-images='${imagesJson}' data-index="${i}"`, 'border-radius:2px; cursor:pointer;')}
      Bild ${i+1}${img.cropRect ? ' · ✂️' : ''}
      <button type="button" data-act="crop-topo-image-local" data-hidden-id="${hiddenListId}" data-image-id="${esc(img.id)}" title="Ausschnitt festlegen — nur dieser Teil wird in Listen/Details gezeigt, das Originalbild bleibt erhalten" style="background:none; border:none; color:var(--ink-soft); cursor:pointer; font-size:14px; line-height:1; padding:0 2px;">✂️</button>
      <button type="button" data-act="rotate-topo-image-local" data-hidden-id="${hiddenListId}" data-image-id="${esc(img.id)}" title="90° drehen — z. B. wenn quer statt hoch hochgeladen" style="background:none; border:none; color:var(--ink-soft); cursor:pointer; font-size:14px; line-height:1; padding:0 2px;">🔄</button>
      ${i > 0 ? `<button type="button" class="fs-topo-move" onclick="moveTopoImageLocal('${hiddenListId}','${esc(img.id)}',-1)" aria-label="Nach vorne">←</button>` : ''}
      ${i < images.length - 1 ? `<button type="button" class="fs-topo-move" onclick="moveTopoImageLocal('${hiddenListId}','${esc(img.id)}',1)" aria-label="Nach hinten">→</button>` : ''}
      <button type="button" data-act="remove-topo-image-local" data-hidden-id="${hiddenListId}" data-image-id="${esc(img.id)}" style="background:none; border:none; color:var(--danger); cursor:pointer; font-size:14px; line-height:1; padding:0 2px;">×</button>
    </span>`
  ).join('')}</div>`;
}

// Reihenfolge der Topos ändern (Bild 1 wird in Listen und Details zuerst gezeigt)
function moveTopoImageLocal(hiddenListId, imageId, dir){
  const hiddenInput = document.getElementById(hiddenListId);
  let images = [];
  try{ images = hiddenInput && hiddenInput.value ? JSON.parse(hiddenInput.value) : []; }catch(e){ images = []; }
  const i = images.findIndex(img=> img.id === imageId), j = i + dir;
  if(i < 0 || j < 0 || j >= images.length) return;
  [images[i], images[j]] = [images[j], images[i]];
  if(hiddenInput) hiddenInput.value = JSON.stringify(images);
  markModalDirty();
  const thumbContainer = document.getElementById(hiddenListId + '-thumbs');
  if(thumbContainer) thumbContainer.innerHTML = topoImageThumbsHtml(images, hiddenListId);
}
function removeTopoImageLocal(hiddenListId, imageId){
  const hiddenInput = document.getElementById(hiddenListId);
  let images = [];
  try{ images = hiddenInput && hiddenInput.value ? JSON.parse(hiddenInput.value) : []; }catch(e){ images = []; }
  if(!confirm('Dieses Bild entfernen? Wird erst mit «Speichern» übernommen.')) return;
  images = images.filter(img=>img.id!==imageId);
  if(hiddenInput) hiddenInput.value = JSON.stringify(images);
  markModalDirty();
  // Die Bilddatei bleibt im Speicher: beim Abbrechen zeigt der Eintrag sie weiter, und ein Sektor
  // kann dieselbe Datei verwenden. Nicht mehr verknüpfte Dateien kosten kaum Platz.
  const thumbContainer = document.getElementById(hiddenListId + '-thumbs');
  if(thumbContainer) thumbContainer.innerHTML = topoImageThumbsHtml(images, hiddenListId);
}

// Dreht ein Topo-Bild um 90° (nur die Anzeige-Drehung als Metadatum — das Original-Bild bleibt
// unverändert). Praktisch für Bilder, die quer statt hoch hochgeladen wurden.
function rotateTopoImageLocal(hiddenListId, imageId){
  const hiddenInput = document.getElementById(hiddenListId);
  let images = [];
  try{ images = hiddenInput && hiddenInput.value ? JSON.parse(hiddenInput.value) : []; }catch(e){ images = []; }
  const img = images.find(im=>im.id===imageId);
  if(!img) return;
  img.rotation = ((img.rotation||0) + 90) % 360;
  if(hiddenInput) hiddenInput.value = JSON.stringify(images);
  markModalDirty();
  const thumbContainer = document.getElementById(hiddenListId + '-thumbs');
  if(thumbContainer) thumbContainer.innerHTML = topoImageThumbsHtml(images, hiddenListId);
}

// Setzt/löscht den Ausschnitt (cropRect) eines Topo-Bilds — reine Anzeige-Metadaten wie bei
// rotation, das Original bleibt in Storage unverändert; cropRect:null zeigt sofort wieder das
// ganze Bild ("Zurücksetzen").
function setTopoImageCropLocal(hiddenListId, imageId, cropRect){
  const hiddenInput = document.getElementById(hiddenListId);
  let images = [];
  try{ images = hiddenInput && hiddenInput.value ? JSON.parse(hiddenInput.value) : []; }catch(e){ images = []; }
  const img = images.find(im=>im.id===imageId);
  if(!img) return;
  img.cropRect = cropRect || null;
  if(hiddenInput) hiddenInput.value = JSON.stringify(images);
  markModalDirty();
  const thumbContainer = document.getElementById(hiddenListId + '-thumbs');
  if(thumbContainer) thumbContainer.innerHTML = topoImageThumbsHtml(images, hiddenListId);
}

// Rechnet ein auf dem angezeigten (ggf. rotierten) Bild gezogenes Auswahlrechteck
// (dx,dy,dw,dh — Brüche 0..1 relativ zur Anzeige) zurück in Brüche relativ zum UNROTIERTEN
// Originalbild — nötig, weil cropRect immer im Original-Koordinatensystem gespeichert wird
// (unabhängig von der aktuellen rotation), damit ein späteres Drehen den Ausschnitt nicht
// verschiebt. rotation ist immer ein Vielfaches von 90°, daher bildet sich ein Rechteck exakt
// auf ein Rechteck ab (keine Interpolation nötig).
function topoCropDisplayRectToOriginal(dx, dy, dw, dh, rotation){
  const rot = ((rotation||0) % 360 + 360) % 360;
  if(rot === 90) return { x: dy, y: 1 - dx - dw, w: dh, h: dw };
  if(rot === 180) return { x: 1 - dx - dw, y: 1 - dy - dh, w: dw, h: dh };
  if(rot === 270) return { x: 1 - dy - dh, y: dx, w: dh, h: dw };
  return { x: dx, y: dy, w: dw, h: dh };
}

// Vollbild-Editor: Ausschnitt für ein Topo-Bild markieren (ziehen = neues Rechteck). Zeigt das
// Bild in seiner aktuellen Drehung an (wie überall sonst) — die Auswahl wird beim Übernehmen ins
// unrotierte Original-Koordinatensystem zurückgerechnet (siehe topoCropDisplayRectToOriginal),
// damit ein späteres 🔄 Drehen den einmal gewählten Ausschnitt nicht verschiebt.
function openTopoCropEditor(hiddenListId, imageId){
  const hiddenInput = document.getElementById(hiddenListId);
  let images = [];
  try{ images = hiddenInput && hiddenInput.value ? JSON.parse(hiddenInput.value) : []; }catch(e){ images = []; }
  const imgData = images.find(im=>im.id===imageId);
  if(!imgData) return;
  const rotation = ((imgData.rotation||0) % 360 + 360) % 360;

  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.92); z-index:210; display:flex; flex-direction:column; touch-action:none;';

  const topBar = document.createElement('div');
  topBar.style.cssText = 'padding:14px 16px; display:flex; align-items:center; justify-content:space-between; color:#fff; font-weight:600; font-size:14px; letter-spacing:0.02em;';
  topBar.innerHTML = `<span>✂️ AUSSCHNITT WÄHLEN</span>`;
  const closeBtn = document.createElement('button');
  closeBtn.type = 'button'; closeBtn.textContent = '×';
  closeBtn.style.cssText = 'background:rgba(255,255,255,0.15); border:none; color:#fff; width:30px; height:30px; border-radius:50%; font-size:16px; cursor:pointer;';
  closeBtn.onclick = ()=> closeTopOverlayLayer();
  topBar.appendChild(closeBtn);
  overlay.appendChild(topBar);

  const stageOuter = document.createElement('div');
  stageOuter.style.cssText = 'flex:1; position:relative; display:flex; align-items:center; justify-content:center; overflow:hidden;';
  overlay.appendChild(stageOuter);

  const hint = document.createElement('p');
  hint.textContent = 'Rahmen verschieben oder an Ecken/Kanten ziehen · Original bleibt immer erhalten';
  hint.style.cssText = 'margin:0; padding:10px 16px 4px; text-align:center; font-size:12px; color:rgba(255,255,255,0.75);';
  overlay.appendChild(hint);

  const bottomBar = document.createElement('div');
  bottomBar.style.cssText = 'padding:10px 16px 18px; display:flex; gap:10px;';
  const resetBtn = document.createElement('button');
  resetBtn.type = 'button'; resetBtn.textContent = 'Zurücksetzen';
  resetBtn.style.cssText = 'flex:1; padding:12px; border-radius:8px; border:1px solid rgba(255,255,255,0.3); background:transparent; color:#fff; font-size:14px; font-weight:600; cursor:pointer;';
  const applyBtn = document.createElement('button');
  applyBtn.type = 'button'; applyBtn.textContent = '✓ Übernehmen';
  applyBtn.style.cssText = 'flex:1; padding:12px; border-radius:8px; border:none; background:var(--signal); color:var(--ice-deep); font-size:14px; font-weight:600; cursor:pointer;';
  bottomBar.appendChild(resetBtn); bottomBar.appendChild(applyBtn);
  overlay.appendChild(bottomBar);

  const raw = new Image();
  raw.onload = ()=>{
    const naturalW = raw.naturalWidth, naturalH = raw.naturalHeight;
    const swapped = rotation === 90 || rotation === 270;
    const availW = Math.min(window.innerWidth * 0.94, 640);
    const availH = stageOuter.clientHeight || (window.innerHeight * 0.55);
    const dispNatW = swapped ? naturalH : naturalW, dispNatH = swapped ? naturalW : naturalH;
    const scale = Math.min(availW / dispNatW, availH / dispNatH);
    const stageW = dispNatW * scale, stageH = dispNatH * scale;

    const stage = document.createElement('div');
    stage.dataset.cropStage = '1';
    stage.style.cssText = `position:relative; width:${stageW}px; height:${stageH}px; overflow:visible; background:#F7F3EA; touch-action:none;`;
    const innerImg = document.createElement('img');
    innerImg.src = imgData.url;
    innerImg.style.cssText = `position:absolute; top:50%; left:50%; width:${naturalW*scale}px; height:${naturalH*scale}px; transform:translate(-50%,-50%) rotate(${rotation}deg); max-width:none; max-height:none;`;
    stage.appendChild(innerImg);
    stageOuter.appendChild(stage);

    // Vorbelegung: bestehender Ausschnitt (zurückgerechnet ins Anzeige-Koordinatensystem) oder
    // das ganze Bild.
    function originalToDisplayRect(o){
      if(rotation === 90) return { x: 1 - o.y - o.h, y: o.x, w: o.h, h: o.w };
      if(rotation === 180) return { x: 1 - o.x - o.w, y: 1 - o.y - o.h, w: o.w, h: o.h };
      if(rotation === 270) return { x: o.y, y: 1 - o.x - o.w, w: o.h, h: o.w };
      return { x: o.x, y: o.y, w: o.w, h: o.h };
    }
    let sel = imgData.cropRect ? originalToDisplayRect(imgData.cropRect) : { x:0, y:0, w:1, h:1 };

    // Rahmen mit 8 Griffen (Ecken + Kanten). Jeder Griff hat eine grosse, unsichtbare
    // Trefferfläche (44 px, auch mit nassen Handschuh-Fingern treffbar), sichtbar ist nur der Punkt.
    // In den Rahmen tippen und ziehen = Rahmen verschieben; ausserhalb tippen = nichts (früher
    // startete das eine neue Auswahl — der Rahmen "sprang" ständig).
    const selEl = document.createElement('div');
    selEl.style.cssText = 'position:absolute; border:2.5px solid var(--signal); box-sizing:border-box; box-shadow:0 0 0 4000px rgba(0,0,0,0.55); touch-action:none; cursor:move;';
    stage.appendChild(selEl);
    const HANDLES = ['nw','n','ne','e','se','s','sw','w'];
    const HIT = 44;
    HANDLES.forEach(pos=>{
      const handle = document.createElement('div');
      handle.dataset.handle = pos;
      handle.style.cssText = `position:absolute; width:${HIT}px; height:${HIT}px; touch-action:none; display:flex; align-items:center; justify-content:center; cursor:${pos}-resize;`;
      const dot = document.createElement('div');
      dot.style.cssText = pos.length===2
        ? 'width:22px; height:22px; border-radius:50%; background:var(--signal); border:2px solid #fff; pointer-events:none;'
        : `${pos==='n'||pos==='s' ? 'width:28px; height:8px;' : 'width:8px; height:28px;'} border-radius:4px; background:var(--signal); border:2px solid #fff; pointer-events:none;`;
      handle.appendChild(dot);
      selEl.appendChild(handle);
    });

    function paintSel(){
      const W = sel.w*stageW, H = sel.h*stageH;
      selEl.style.left = (sel.x*stageW) + 'px';
      selEl.style.top = (sel.y*stageH) + 'px';
      selEl.style.width = W + 'px';
      selEl.style.height = H + 'px';
      selEl.querySelectorAll('[data-handle]').forEach(h=>{
        const pos = h.dataset.handle;
        const cx = pos.includes('w') ? 0 : pos.includes('e') ? W : W/2;
        const cy = pos.includes('n') ? 0 : pos.includes('s') ? H : H/2;
        h.style.left = (cx - HIT/2) + 'px';
        h.style.top = (cy - HIT/2) + 'px';
      });
    }
    paintSel();

    const MIN_FRAC = 0.06;
    function clampSel(){
      sel.w = Math.max(MIN_FRAC, Math.min(1, sel.w));
      sel.h = Math.max(MIN_FRAC, Math.min(1, sel.h));
      sel.x = Math.max(0, Math.min(1 - sel.w, sel.x));
      sel.y = Math.max(0, Math.min(1 - sel.h, sel.y));
    }

    let dragMode = null, startSel = null, startX = 0, startY = 0;
    function onPointerMove(ev){
      if(!dragMode) return;
      ev.preventDefault();
      const dx = (ev.clientX - startX) / stageW, dy = (ev.clientY - startY) / stageH;
      if(dragMode==='move'){
        sel = { ...startSel, x: Math.max(0, Math.min(1 - startSel.w, startSel.x + dx)), y: Math.max(0, Math.min(1 - startSel.h, startSel.y + dy)) };
      }else{
        // Gegenüberliegende Kante bleibt fest; die gezogene Kante darf nicht über sie hinaus.
        let left = startSel.x, top = startSel.y, right = startSel.x + startSel.w, bottom = startSel.y + startSel.h;
        if(dragMode.includes('w')) left = Math.max(0, Math.min(right - MIN_FRAC, left + dx));
        if(dragMode.includes('e')) right = Math.min(1, Math.max(left + MIN_FRAC, right + dx));
        if(dragMode.includes('n')) top = Math.max(0, Math.min(bottom - MIN_FRAC, top + dy));
        if(dragMode.includes('s')) bottom = Math.min(1, Math.max(top + MIN_FRAC, bottom + dy));
        sel = { x:left, y:top, w:right-left, h:bottom-top };
      }
      paintSel();
    }
    function onPointerUp(){
      dragMode = null;
      clampSel(); paintSel();
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerup', onPointerUp);
      window.removeEventListener('pointercancel', onPointerUp);
    }
    selEl.addEventListener('pointerdown', (e)=>{
      e.preventDefault();
      e.stopPropagation();
      const handle = e.target.closest('[data-handle]');
      dragMode = handle ? handle.dataset.handle : 'move';
      startSel = { ...sel }; startX = e.clientX; startY = e.clientY;
      window.addEventListener('pointermove', onPointerMove, { passive:false });
      window.addEventListener('pointerup', onPointerUp);
      window.addEventListener('pointercancel', onPointerUp);
    });

    resetBtn.onclick = ()=>{
      setTopoImageCropLocal(hiddenListId, imageId, null);
      closeTopOverlayLayer();
    };
    applyBtn.onclick = ()=>{
      clampSel();
      const orig = topoCropDisplayRectToOriginal(sel.x, sel.y, sel.w, sel.h, rotation);
      setTopoImageCropLocal(hiddenListId, imageId, { x:orig.x, y:orig.y, w:orig.w, h:orig.h, naturalW, naturalH });
      closeTopOverlayLayer();
    };
  };
  raw.onerror = ()=>{ closeTopOverlayLayer(); showToast('Bild konnte nicht geladen werden.', true); };
  raw.src = imgData.url;

  document.body.appendChild(overlay);
  // Ohne eigenen History-Eintrag verlässt die Hardware-/Browser-Zurück-Taste hier komplett die
  // App statt nur den Editor zu schliessen (kein popstate-Ziel registriert). pushOverlayLayer
  // reiht den Editor stattdessen in den bestehenden Overlay-Stack ein (siehe openImageCropDialog).
  pushOverlayLayer(()=> overlay.remove());
}

function handleTopoImageUpload(fileInputEl, tourIdHiddenId, hiddenListId, statusId){
  const files = fileInputEl.files;
  if(!files || !files.length) return;
  const statusEl = document.getElementById(statusId);
  const hiddenInput = document.getElementById(hiddenListId);
  const tourIdInput = document.getElementById(tourIdHiddenId);
  let images = [];
  try{ images = hiddenInput && hiddenInput.value ? JSON.parse(hiddenInput.value) : []; }catch(e){ images = []; }
  let tourId = tourIdInput ? tourIdInput.value : '';
  if(!tourId){ tourId = uid('t'); if(tourIdInput) tourIdInput.value = tourId; }
  const filesToAdd = Array.from(files).slice(0, Math.max(0, TOPO_IMAGE_MAX_COUNT - images.length));
  if(!filesToAdd.length){
    if(statusEl) statusEl.textContent = `Maximal ${TOPO_IMAGE_MAX_COUNT} Bilder pro Tour — zuerst eins entfernen.`;
    fileInputEl.value = '';
    return;
  }
  (async ()=>{
    for(let i=0; i<filesToAdd.length; i++){
      const rawFile = filesToAdd[i];
      const cropped = await openImageCropDialog(rawFile);
      if(!cropped) continue; // "Bild überspringen" oder Zurück-Taste — dieses Bild nicht übernehmen
      const file = cropped;
      if(statusEl) statusEl.textContent = `Bild ${images.length+1}/${TOPO_IMAGE_MAX_COUNT} wird komprimiert…`;
      try{
        const blob = await compressImageFile(file, 1200, 0.78);
        const imgId = uid('img');
        const storagePath = `${TOPO_IMAGES_PATH}/${tourId}/${imgId}.jpg`;
        if(statusEl) statusEl.textContent = `Bild ${images.length+1}/${TOPO_IMAGE_MAX_COUNT} wird hochgeladen…`;
        const url = await uploadTopoImageBlob(blob, storagePath);
        // Liste neu lesen: währenddessen kann ein anderes Bild dazugekommen, entfernt oder verschoben worden sein
        try{ images = hiddenInput && hiddenInput.value ? JSON.parse(hiddenInput.value) : images; }catch(e){}
        images.push({id: imgId, url, storagePath});
        if(hiddenInput) hiddenInput.value = JSON.stringify(images);
        markModalDirty();
        const thumbContainer = document.getElementById(hiddenListId + '-thumbs');
        if(thumbContainer) thumbContainer.innerHTML = topoImageThumbsHtml(images, hiddenListId);
      }catch(err){
        if(statusEl) statusEl.textContent = 'Fehler beim Hochladen: ' + (err && err.message ? err.message : err);
        fileInputEl.value = '';
        return;
      }
    }
    if(statusEl) statusEl.textContent = images.length ? `✓ ${images.length}/${TOPO_IMAGE_MAX_COUNT} Bilder hochgeladen.` : 'Noch keine Bilder hochgeladen.';
    fileInputEl.value = '';
  })();
}

function topoImagesGalleryHtml(images){
  if(!images || !images.length) return '';
  const imagesJson = topoImagesJsonForViewer(images);
  // Ganzes Foto (bzw. ganzer Ausschnitt) im eigenen Seitenverhältnis statt in ein Quadrat
  // gepresst — dieselbe schon geladene Bilddatei, kein zusätzlicher Datentraffic.
  return `<div class="chips topo-gallery" style="margin-top:6px;">${images.map((img,i)=>
    topoImageBoxHtml(img, 170, null, `data-act="view-topo-image" data-images='${imagesJson}' data-index="${i}"`, 'border-radius:var(--radius); border:1px solid var(--line); cursor:pointer;', 230)
  ).join('')}</div>`;
}

function showTopoImageLightbox(images, startIndex, offlineId){
  if(!images || !images.length) return;
  let idx = startIndex || 0;
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.9); z-index:200; display:flex; align-items:center; justify-content:center; padding:20px; touch-action:pan-y;';

  const IMG_CSS = 'max-width:100%; max-height:100%; object-fit:contain; border-radius:4px; touch-action:none; transform-origin:center center;';
  const imgEl = document.createElement('img');
  imgEl.style.cssText = IMG_CSS;
  overlay.appendChild(imgEl);
  // Ausschnitt-Ansicht: ein Fenster in Ausschnitt-Grösse (gedreht), darin dasselbe <img> verschoben
  // (siehe topoCropGeometry). Gezoomt/verschoben wird dann dieses Fenster statt des Bilds.
  const cropBox = document.createElement('div');
  cropBox.style.cssText = 'position:relative; display:none; flex:none; touch-action:none; transform-origin:center center;';
  const cropFrame = document.createElement('div');
  cropFrame.style.cssText = 'position:absolute; left:50%; top:50%; overflow:hidden; border-radius:4px;';
  cropBox.appendChild(cropFrame);
  overlay.appendChild(cropBox);
  let zoomEl = imgEl, showCrop = true;

  // ===== Zoom (Pinch, Doppeltipp, Mausrad) & Verschieben im gezoomten Zustand =====
  const ZOOM_MIN = 1, ZOOM_MAX = 4;
  let scale = 1, panX = 0, panY = 0, currentRotation = 0;
  function applyTransform(withTransition){
    imgEl.style.transition = withTransition ? 'transform 0.18s ease-out' : 'none';
    // Im Ausschnitt-Modus steckt die Drehung schon im Fenster (cropFrame).
    zoomEl.style.transition = imgEl.style.transition;
    zoomEl.style.transform = (zoomEl===imgEl ? `rotate(${currentRotation}deg) ` : '') + `translate(${panX}px, ${panY}px) scale(${scale})`;
  }
  function clampPan(){
    // Grobe Begrenzung, damit das Bild beim Verschieben nicht zu weit aus dem Bild verschwindet.
    const maxOffset = (scale - 1) * (zoomEl.clientWidth || overlay.clientWidth) * 0.6;
    panX = Math.max(-maxOffset, Math.min(maxOffset, panX));
    const maxOffsetY = (scale - 1) * (zoomEl.clientHeight || overlay.clientHeight) * 0.6;
    panY = Math.max(-maxOffsetY, Math.min(maxOffsetY, panY));
  }
  function resetZoom(withTransition){
    scale = 1; panX = 0; panY = 0;
    applyTransform(withTransition);
  }

  function closeLightbox(){ overlay.remove(); }

  const closeBtn = document.createElement('button');
  closeBtn.type = 'button'; closeBtn.textContent = '×';
  closeBtn.style.cssText = 'position:absolute; top:16px; right:16px; background:rgba(255,255,255,0.15); color:#fff; border:none; border-radius:50%; width:40px; height:40px; font-size:22px; line-height:1;';
  closeBtn.addEventListener('click', (e)=>{ e.stopPropagation(); closeTopOverlayLayer(); });
  overlay.appendChild(closeBtn);

  // Ist ein Ausschnitt gesetzt, zeigt das Vollbild zuerst ihn — mit diesem Knopf jederzeit das
  // ganze Originalbild (z. B. um im Gelände den Rest des Topos anzuschauen).
  const cropToggleBtn = document.createElement('button');
  cropToggleBtn.type = 'button';
  cropToggleBtn.style.cssText = 'position:absolute; top:16px; left:16px; background:rgba(255,255,255,0.15); color:#fff; border:none; border-radius:20px; padding:0 14px; height:40px; font-size:13px; font-weight:600; display:none;';
  cropToggleBtn.addEventListener('click', (e)=>{ e.stopPropagation(); showCrop = !showCrop; resetZoom(false); updateImage(); });
  overlay.appendChild(cropToggleBtn);

  let counterEl = null;
  function goTo(n){ idx = (n + images.length) % images.length; resetZoom(false); updateImage(); }
  if(images.length > 1){
    const prevBtn = document.createElement('button');
    prevBtn.type = 'button'; prevBtn.textContent = '‹';
    prevBtn.style.cssText = 'position:absolute; left:10px; top:50%; transform:translateY(-50%); background:rgba(255,255,255,0.15); color:#fff; border:none; border-radius:50%; width:44px; height:44px; font-size:24px;';
    prevBtn.addEventListener('click', (e)=>{ e.stopPropagation(); goTo(idx-1); });
    const nextBtn = document.createElement('button');
    nextBtn.type = 'button'; nextBtn.textContent = '›';
    nextBtn.style.cssText = 'position:absolute; right:10px; top:50%; transform:translateY(-50%); background:rgba(255,255,255,0.15); color:#fff; border:none; border-radius:50%; width:44px; height:44px; font-size:24px;';
    nextBtn.addEventListener('click', (e)=>{ e.stopPropagation(); goTo(idx+1); });
    counterEl = document.createElement('div');
    counterEl.style.cssText = 'position:absolute; bottom:16px; left:50%; transform:translateX(-50%); color:#fff; font-size:13px; background:rgba(0,0,0,0.5); padding:4px 12px; border-radius:12px;';
    overlay.appendChild(prevBtn);
    overlay.appendChild(nextBtn);
    overlay.appendChild(counterEl);
  }

  // Für gebietsweite Sammel-Galerien (mehrere Topos aus verschiedenen Klettergärten/Touren):
  // jedes Bild kann eine Quelle tragen (ownerLabel/ownerModalType/ownerId) -- ein Tap auf den
  // Button springt direkt zur zugehörigen Seite. Bei normalen Einzel-Galerien (kein ownerLabel
  // gesetzt) bleibt der Button einfach weg.
  let ownerBtn = null;
  if(images.some(im=>im.ownerLabel)){
    ownerBtn = document.createElement('button');
    ownerBtn.type = 'button';
    ownerBtn.style.cssText = 'position:absolute; bottom:16px; left:50%; transform:translateX(-50%); background:rgba(255,255,255,0.95); color:var(--ink); border:none; border-radius:16px; padding:8px 16px; font-size:13px; font-weight:600; cursor:pointer; max-width:82vw; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;';
    ownerBtn.addEventListener('click', (e)=>{
      e.stopPropagation();
      const item = images[idx];
      if(!item.ownerModalType) return;
      closeTopOverlayLayer();
      navigateToModal({type:item.ownerModalType, payload:item.ownerId});
    });
    overlay.appendChild(ownerBtn);
    if(counterEl) counterEl.style.bottom = '62px';
  }

  function updateImage(){
    const item = images[idx];
    // Bei um 90°/270° gedrehten Bildern vertauschen sich Breite/Höhe der sichtbaren Fläche —
    // sonst würde das gedrehte Bild über den Bildschirmrand hinausragen bzw. winzig erscheinen.
    currentRotation = item.rotation || 0;
    const useCrop = showCrop && hasUsableCrop(item);
    cropToggleBtn.style.display = hasUsableCrop(item) ? '' : 'none';
    cropToggleBtn.textContent = showCrop ? '⤢ Ganzes Bild' : '✂️ Ausschnitt';
    if(useCrop){
      const g = topoCropGeometry(item, window.innerWidth - 40, window.innerHeight - 40, 'contain');
      cropBox.style.width = (g.swapped ? g.frameH : g.frameW) + 'px';
      cropBox.style.height = (g.swapped ? g.frameW : g.frameH) + 'px';
      cropFrame.style.width = g.frameW + 'px';
      cropFrame.style.height = g.frameH + 'px';
      cropFrame.style.transform = `translate(-50%,-50%) rotate(${g.rot}deg)`;
      imgEl.style.cssText = `position:absolute; left:${g.imgX}px; top:${g.imgY}px; width:${g.imgW}px; height:${g.imgH}px; max-width:none; max-height:none; touch-action:none;`;
      if(imgEl.parentNode !== cropFrame) cropFrame.appendChild(imgEl);
      cropBox.style.display = '';
      zoomEl = cropBox;
    }else{
      imgEl.style.cssText = IMG_CSS;
      if(imgEl.parentNode !== overlay) overlay.insertBefore(imgEl, cropBox);
      cropBox.style.display = 'none';
      cropBox.style.transform = '';
      zoomEl = imgEl;
      if(currentRotation===90 || currentRotation===270){
        imgEl.style.maxWidth = 'calc(100vh - 40px)';
        imgEl.style.maxHeight = 'calc(100vw - 40px)';
      }
    }
    applyTransform(false);
    // Bild sofort anzeigen — nicht auf die Offline-Prüfung warten, damit im
    // Zweifel (z. B. hängender IndexedDB-Zugriff) trotzdem etwas erscheint.
    imgEl.src = item.url;
    if(counterEl) counterEl.textContent = `${idx+1} / ${images.length}`;
    if(ownerBtn) ownerBtn.style.display = item.ownerLabel ? '' : 'none';
    if(ownerBtn && item.ownerLabel) ownerBtn.textContent = '→ ' + item.ownerLabel + ' öffnen';
    if(offlineId && item.id){
      const myIdx = idx;
      idbGet('images', offlineId + '_' + item.id).then(blob=>{
        if(blob && idx===myIdx){ imgEl.src = URL.createObjectURL(blob); } // nur ersetzen, falls zwischenzeitlich nicht weitergeblättert wurde
      }).catch(()=>{ /* kein Offline-Bild vorhanden — angezeigte URL bleibt bestehen */ });
    }
  }
  updateImage();

  overlay.addEventListener('click', (e)=>{ if(e.target===overlay && scale===1) closeTopOverlayLayer(); });

  function touchDist(touches){
    const dx = touches[0].clientX - touches[1].clientX;
    const dy = touches[0].clientY - touches[1].clientY;
    return Math.hypot(dx, dy);
  }

  let touchStartX = null;
  let pinchStartDist = null, pinchStartScale = 1;
  let panStartX = null, panStartY = null, panOriginX = 0, panOriginY = 0;
  let lastTapTime = 0, lastTapX = 0, lastTapY = 0;

  overlay.addEventListener('touchstart', (e)=>{
    if(e.touches.length === 2){
      touchStartX = null;
      pinchStartDist = touchDist(e.touches);
      pinchStartScale = scale;
    }else if(e.touches.length === 1){
      pinchStartDist = null;
      if(scale > 1){
        panStartX = e.touches[0].clientX; panStartY = e.touches[0].clientY;
        panOriginX = panX; panOriginY = panY;
      }else{
        touchStartX = e.touches[0].clientX;
      }
    }
  }, {passive:true});

  overlay.addEventListener('touchmove', (e)=>{
    if(e.touches.length === 2 && pinchStartDist){
      e.preventDefault();
      const newDist = touchDist(e.touches);
      scale = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, pinchStartScale * (newDist / pinchStartDist)));
      clampPan();
      applyTransform(false);
    }else if(e.touches.length === 1 && panStartX !== null){
      e.preventDefault();
      panX = panOriginX + (e.touches[0].clientX - panStartX);
      panY = panOriginY + (e.touches[0].clientY - panStartY);
      clampPan();
      applyTransform(false);
    }
  }, {passive:false});

  overlay.addEventListener('touchend', (e)=>{
    if(e.touches.length > 0) return; // erst reagieren, wenn wirklich alle Finger weg sind
    if(pinchStartDist){
      pinchStartDist = null;
      if(scale < 1.05) resetZoom(true);
      return;
    }
    if(panStartX !== null){
      panStartX = null; panStartY = null;
      return;
    }
    if(touchStartX !== null){
      const touch = e.changedTouches[0];
      const dx = touch.clientX - touchStartX;
      touchStartX = null;
      if(Math.abs(dx) > 50){ goTo(dx>0 ? idx-1 : idx+1); return; }
      // Doppeltipp erkennen (zwei kurz aufeinanderfolgende Taps am gleichen Ort) → rein-/rauszoomen
      const now = Date.now();
      const closeToLastTap = Math.hypot(touch.clientX - lastTapX, touch.clientY - lastTapY) < 40;
      if(now - lastTapTime < 300 && closeToLastTap){
        if(scale > 1) resetZoom(true);
        else{ scale = 2.5; applyTransform(true); }
        lastTapTime = 0;
      }else{
        lastTapTime = now; lastTapX = touch.clientX; lastTapY = touch.clientY;
      }
    }
  }, {passive:true});

  // Doppelklick (Desktop/Maus) zoomt rein/raus
  imgEl.addEventListener('dblclick', (e)=>{
    e.stopPropagation();
    if(scale > 1) resetZoom(true);
    else{ scale = 2.5; applyTransform(true); }
  });
  // Mausrad zoomt rein/raus (Desktop)
  overlay.addEventListener('wheel', (e)=>{
    e.preventDefault();
    scale = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, scale - e.deltaY * 0.0025));
    if(scale <= 1.01){ resetZoom(false); }else{ clampPan(); applyTransform(false); }
  }, {passive:false});

  document.body.appendChild(overlay);
  pushOverlayLayer(closeLightbox);
}

/* ================= Kletterrouten-Liste (mehrere benannte Routen an einer Wand) =================
   Anders als eine einzelne MSL-Tour (= eine Route mit einer Schwierigkeit) kann ein Sektor mehrere
   benannte Kletterrouten haben, die sich ein gemeinsames Topo-Bild teilen (z. B. ein ganzer
   Klettergarten-Sektor mit 16 Routen an einer Wand — "Klettergarten" ist dabei nur das Etikett für
   einen Sektor mit einer solchen Liste, keine eigene Tour). Die Liste lässt sich Zeile für Zeile von
   Hand pflegen ODER als Text einfügen — z. B. das Ergebnis, wenn man einer Chat-KI (Claude/ChatGPT/
   Gemini), die man ohnehin schon abonniert hat, ein Foto der Führerbuch-Seite gibt und um eine Liste
   "Nr. | Name | Grad" bittet. parseKletterroutenText() zerlegt das automatisch. */
function kletterrouteGradeTier(grad){
  const m = String(grad||'').match(/(\d+)/);
  if(!m) return 'mid';
  const num = parseInt(m[1], 10);
  if(num <= 4) return 'easy';
  if(num === 5) return 'mid';
  return 'hard';
}
const KLETTERROUTE_GRADE_COLORS = { easy: '#3C7A52', mid: '#A87A1F', hard: '#B0392C' };

// Sortierwert für französische Kletter-Grade (3a < 3a+ < 3b < … < 4a < …) — nur zum Vergleichen/
// Sortieren gedacht, kein exaktes Schwierigkeitsmass. Liefert null bei unbekanntem Format.
function kletterrouteGradeSortValue(grad){
  const m = String(grad||'').match(/^(\d+)\s*([a-c])?\s*(\+)?/i);
  if(!m) return null;
  const num = parseInt(m[1], 10);
  const letterVal = { a:0, b:1, c:2 }[(m[2]||'a').toLowerCase()] || 0;
  return num*10 + letterVal*3 + (m[3] ? 1 : 0);
}
// Kurze Grad-Spanne für Sektor-Kärtchen (z. B. "3a–7a") — damit man beim Durchblättern mehrerer
// Sektoren eines Klettergebiets auf einen Blick sieht, was einen erwartet.
function kletterroutenGradeRangeText(routes){
  const values = (routes||[]).map(r=>({grad:r.grad, v:kletterrouteGradeSortValue(r.grad)})).filter(x=>x.v!==null);
  if(!values.length) return '';
  values.sort((a,b)=>a.v-b.v);
  const min = values[0].grad, max = values[values.length-1].grad;
  return min===max ? min : `${min}–${max}`;
}

// Erkennt mit |, ; , Komma oder Tab getrennte Zeilen (auch als Markdown-Tabelle mit
// führendem/abschliessendem |) sowie reine Leerzeichen-Trennung — dann gilt: erstes Token = Nr.
// (falls rein numerisch), letztes gradartig aussehende Token = Grad, alles dazwischen = Name.
// Kopfzeilen ("Nr. | Name | Grad") werden erkannt und übersprungen. Zeilen ohne erkennbare Nummer
// bekommen automatisch die nächste freie ab startNr.
function parseKletterroutenText(text, startNr){
  const GRADE_RE = /^\d{1,2}[a-c]?[+-]?$/i;
  const lines = String(text||'').split('\n').map(l=>l.trim()).filter(Boolean);
  const out = [];
  let autoNr = startNr || 1;
  lines.forEach(line=>{
    let parts;
    if(/[|;,\t]/.test(line)){
      parts = line.split(/[|;,\t]/).map(p=>p.trim()).filter(p=>p!=='');
    }else{
      parts = line.split(/\s+/).filter(Boolean);
    }
    if(parts.length < 2) return;
    // Kopfzeile erkennen und überspringen (z. B. "Nr. | Name | Grad" oder "Nr Route Grad Beg.").
    const looksLikeHeader = parts.every(p => !/\d/.test(p)) && /nr\.?$|name|route|grad/i.test(line);
    if(looksLikeHeader) return;
    let nr = null;
    if(/^\d+\.?$/.test(parts[0])){
      nr = parseInt(parts[0], 10);
      parts = parts.slice(1);
    }
    if(!parts.length) return;
    let grad = '';
    if(GRADE_RE.test(parts[parts.length-1])){
      grad = parts[parts.length-1];
      parts = parts.slice(0, -1);
    }
    const name = parts.join(' ').trim();
    if(!name) return;
    out.push({ id: uid('kr'), nr: nr!==null ? nr : autoNr, name, grad });
    autoNr = (nr!==null ? nr : autoNr) + 1;
  });
  return out;
}

// Reine Anzeige (Sektor-Detailansicht) — nicht editierbar.
function kletterroutenTableHtml(routes){
  if(!routes || !routes.length) return '';
  const sorted = routes.slice().sort((a,b)=> (a.nr||0) - (b.nr||0));
  return `<table style="width:100%; border-collapse:collapse; font-size:14px; margin-top:8px;">
    <thead><tr>
      <th style="text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:0.05em; color:var(--ink-faint); padding:0 8px 6px 0; border-bottom:1px solid var(--line);">Nr.</th>
      <th style="text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:0.05em; color:var(--ink-faint); padding:0 8px 6px 0; border-bottom:1px solid var(--line);">Route</th>
      <th style="text-align:center; font-size:11px; text-transform:uppercase; letter-spacing:0.05em; color:var(--ink-faint); padding:0 0 6px 0; border-bottom:1px solid var(--line); width:56px;">Grad</th>
    </tr></thead>
    <tbody>${sorted.map(r=>`
      <tr style="border-bottom:1px solid var(--line);">
        <td class="mono" style="padding:7px 8px 7px 0; color:var(--ink-faint); font-weight:600;">${esc(r.nr!=null ? String(r.nr) : '')}</td>
        <td style="padding:7px 8px 7px 0; font-weight:600;">${esc(r.name||'')}</td>
        <td style="padding:7px 0; text-align:center;">${r.grad ? `<span style="display:inline-block; min-width:32px; padding:2px 6px; border-radius:10px; font-weight:700; font-size:12.5px; color:#fff; background:${KLETTERROUTE_GRADE_COLORS[kletterrouteGradeTier(r.grad)]};">${esc(r.grad)}</span>` : ''}</td>
      </tr>`).join('')}
    </tbody>
  </table>`;
}

function blobToBase64(blob){
  return new Promise((resolve, reject)=>{
    const reader = new FileReader();
    reader.onload = ()=> resolve(String(reader.result).split(',')[1] || '');
    reader.onerror = ()=> reject(new Error('Datei konnte nicht gelesen werden.'));
    reader.readAsDataURL(blob);
  });
}

// Schickt ein Topo-Foto an die Cloud Function scanKletterrouten (siehe functions/index.js) und
// trägt die erkannten Routen automatisch in die Kletterrouten-Liste ein — bestehende Zeilen
// bleiben erhalten, erkannte kommen dazu. Das Foto kommt entweder frisch aus dem Datei-Feld, oder
// (falls dort gerade nichts ausgewählt ist) vom zuletzt hochgeladenen Topo-Bild: der Datei-Input
// wird von handleTopoImageUpload nach jedem Upload geleert (siehe dort), daher ist "oben ein Foto
// ausgewählt" für ein Bild, das man gerade erst hochgeladen hat, sonst nie mehr erfüllbar.
async function scanTopoImageForRoutes(fileInputEl, hiddenInputId, containerId, statusElId, topoImagesHiddenId){
  const statusEl = document.getElementById(statusElId);
  if(!SCAN_KLETTERROUTEN_URL){
    showToast('Foto-Scan ist noch nicht eingerichtet — siehe functions/README.md.', true);
    return;
  }
  const file = fileInputEl && fileInputEl.files && fileInputEl.files[0];
  let imageBase64, mediaType;
  if(file){
    if(statusEl) statusEl.textContent = 'Erkenne Routen …';
    imageBase64 = await blobToBase64(file);
    mediaType = file.type || 'image/jpeg';
  }else{
    const topoImagesInput = topoImagesHiddenId ? document.getElementById(topoImagesHiddenId) : null;
    let topoImages = [];
    try{ topoImages = topoImagesInput && topoImagesInput.value ? JSON.parse(topoImagesInput.value) : []; }catch(e){ topoImages = []; }
    const lastImg = topoImages.length ? topoImages[topoImages.length-1] : null;
    if(!lastImg || !lastImg.url){
      showToast('Bitte zuerst oben ein Foto auswählen.', true);
      return;
    }
    if(statusEl) statusEl.textContent = 'Lade hochgeladenes Foto …';
    try{
      const blob = await fetch(lastImg.url).then(r=>{
        if(!r.ok) throw new Error('Foto konnte nicht geladen werden (' + r.status + ')');
        return r.blob();
      });
      imageBase64 = await blobToBase64(blob);
      mediaType = blob.type || 'image/jpeg';
    }catch(e){
      if(statusEl) statusEl.textContent = '';
      showToast('Hochgeladenes Foto konnte nicht geladen werden: ' + (e.message || e), true);
      return;
    }
    if(statusEl) statusEl.textContent = 'Erkenne Routen …';
  }
  try{
    await ensureValidAuthToken();
    const res = await fetch(SCAN_KLETTERROUTEN_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + authState.idToken },
      body: JSON.stringify({ imageBase64, mediaType }),
    });
    if(!res.ok){
      const errBody = await res.json().catch(()=>({}));
      throw new Error(errBody.error || ('Serverfehler ' + res.status));
    }
    const data = await res.json();
    const hiddenInput = document.getElementById(hiddenInputId);
    let existing = [];
    try{ existing = hiddenInput && hiddenInput.value ? JSON.parse(hiddenInput.value) : []; }catch(e){ existing = []; }
    const nextNr = existing.reduce((max,r)=> Math.max(max, r.nr||0), 0) + 1;
    const added = (data.routes||[]).map((r,i)=>({
      id: uid('kr'),
      nr: (r.nr!=null) ? r.nr : (nextNr+i),
      name: r.name || ('Route ' + (nextNr+i)),
      grad: r.grad || '',
    }));
    if(hiddenInput) hiddenInput.value = JSON.stringify(existing.concat(added));
    const infoFilled = fsFillSektorFormInfo(data.info);
    markModalDirty(); // erkannte Routen sind eine Änderung: Schliessen fragt nach, Entwurf wird gesichert
    renderKletterroutenEditor(containerId, hiddenInputId);
    if(statusEl) statusEl.textContent = (added.length ? `✓ ${added.length} Route(n) erkannt` : 'Keine Routen erkannt') + (infoFilled.length ? ' · ausgefüllt: ' + infoFilled.join(', ') : '') + (added.length || infoFilled.length ? ' — bitte kurz prüfen.' : '.');
    showToast(added.length ? (added.length + ' Route(n) erkannt und übernommen.') : 'Keine Routen erkannt — Foto evtl. unscharf oder falscher Ausschnitt.', !added.length);
  }catch(e){
    if(statusEl) statusEl.textContent = '';
    showToast('Foto-Scan fehlgeschlagen: ' + (e.message || e), true);
  }
}

// Sektor-Angaben aus dem Foto-Scan (info: absicherung, exen, seil, routenlaenge, ausrichtung, hinweise,
// zitat). Führer machen sie meist pro Sektor oder fürs ganze Gebiet; sie landen in den bestehenden
// Sektor-Feldern Absicherung, Anzahl Exen, Seillänge und Hinweise – nur wo diese noch leer sind.
function fsSektorInfoHas(info){ return !!(info && (info.absicherung || info.exen || info.seil || info.routenlaenge || info.ausrichtung || info.hinweise)); }
function fsSektorInfoNotes(info){
  return [info.ausrichtung ? 'Ausrichtung: ' + info.ausrichtung : '', info.routenlaenge ? 'Routenlänge: ' + info.routenlaenge : '', info.hinweise || ''].filter(Boolean).join(' · ');
}
function fsSektorInfoSummary(info){
  const prot = (typeof PROTECTION_LEVELS !== 'undefined' && PROTECTION_LEVELS.find(p=> p.value === info.absicherung)) || null;
  return [prot ? 'Absicherung ' + prot.label.replace(/^[●○\s]+/, '') : '', info.exen ? info.exen + ' Exen' : '', info.seil ? 'Seil ' + info.seil : '',
    info.routenlaenge ? 'Routen ' + info.routenlaenge : '', info.ausrichtung ? 'Ausrichtung ' + info.ausrichtung : ''].filter(Boolean).join(' · ');
}
function fsSektorInfoReviewHtml(info, i){
  if(!fsSektorInfoHas(info)) return '';
  return `<label class="fs-scan-row" style="margin-top:10px;"><input type="checkbox" class="scan-sector-info" data-index="${i}" checked>
    <span><small>Sektor-Infos übernehmen</small><b>${esc(fsSektorInfoSummary(info) || 'Hinweise')}</b>${info.hinweise ? `<em style="color:var(--ink-soft); font-weight:600;">${esc(info.hinweise)}</em>` : ''}${info.zitat ? `<q>${esc(info.zitat)}</q>` : ''}</span></label>`;
}
// Neuer Sektor aus dem Gebiets-Scan
function fsApplySektorInfo(sek, info){
  if(!fsSektorInfoHas(info)) return;
  if(info.absicherung && !sek.protection) sek.protection = info.absicherung;
  if(info.exen && !sek.quickdrawCount) sek.quickdrawCount = String(info.exen).replace(/[^\d]/g, '');
  if(info.seil && !sek.ropeLength) sek.ropeLength = info.seil;
  const notes = fsSektorInfoNotes(info);
  if(notes) sek.klettergartenNotes = [sek.klettergartenNotes, notes].filter(Boolean).join('\n');
}
// Offenes Formular «Topo & Routen» eines Sektors: leere Felder füllen, Chips mitschalten
function fsFillSektorFormInfo(info){
  if(!fsSektorInfoHas(info)) return [];
  const filled = [];
  const chip = (hiddenId, chipSel, attr, val, label)=>{
    const h = document.getElementById(hiddenId);
    if(!h || h.value || !val) return;
    h.value = val;
    document.querySelectorAll(chipSel).forEach(c=>{ const on = c.getAttribute(attr) === val; c.classList.toggle('on', on); c.style.background = on ? 'var(--ice-deep)' : ''; });
    filled.push(label);
  };
  chip('sektor-protection-hidden', '.sektor-protection-chip', 'data-value', info.absicherung, 'Absicherung');
  chip('sektor-rope-length-hidden', '.sektor-rope-length-chip', 'data-rope-length', info.seil, 'Seillänge');
  const ex = document.querySelector('#sektor-topo-routen-form [name="quickdrawCount"]');
  if(ex && !ex.value && info.exen){ ex.value = String(info.exen).replace(/[^\d]/g, ''); filled.push('Exen'); }
  const notes = document.querySelector('#sektor-topo-routen-form [name="klettergartenNotes"]');
  const add = fsSektorInfoNotes(info);
  if(notes && add && notes.value.indexOf(add) < 0){ notes.value = [notes.value.trim(), add].filter(Boolean).join('\n'); filled.push('Hinweise'); }
  return filled;
}

// Wie scanTopoImageForRoutes, aber für ein oder mehrere Fotos mit MEHREREN Sektoren gleichzeitig
// (z. B. eine ganze Führerbuch-Seite eines Klettergebiets, oder mehrere Seiten auf einmal, falls
// das Gebiet sich über mehrere Seiten erstreckt). Jedes Foto wird einzeln an die Cloud Function
// geschickt; alle erkannten Sektoren landen zusammengeführt in EINEM Prüf-Fenster, statt die
// Routen direkt zu übernehmen, da hier gleich mehrere neue Sektoren entstehen. Jeder Sektor trägt
// eine Referenz auf sein Quellfoto (_sourceFile), damit beim Übernehmen das richtige Topo-Bild
// hochgeladen wird statt (bei mehreren Fotos) versehentlich immer dasselbe.
async function scanKlettergebietPhoto(gebId, fileInputEl, statusElId){
  const statusEl = document.getElementById(statusElId);
  if(!SCAN_KLETTERGEBIET_URL){
    showToast('Mehrfach-Sektor-Scan ist noch nicht eingerichtet — siehe functions/README.md.', true);
    return;
  }
  const files = fileInputEl && fileInputEl.files ? Array.from(fileInputEl.files) : [];
  if(!files.length){
    showToast('Bitte zuerst ein Foto auswählen.', true);
    return;
  }
  if(statusEl) statusEl.textContent = files.length>1 ? `Erkenne Sektoren auf ${files.length} Fotos …` : 'Erkenne Sektoren …';
  const allSectors = [];
  let gebietName = '';
  let failedCount = 0;
  await ensureValidAuthToken();
  for(const file of files){
    try{
      const imageBase64 = await blobToBase64(file);
      const res = await fetch(SCAN_KLETTERGEBIET_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + authState.idToken },
        body: JSON.stringify({ imageBase64, mediaType: file.type || 'image/jpeg' }),
      });
      if(!res.ok){
        const errBody = await res.json().catch(()=>({}));
        throw new Error(errBody.error || ('Serverfehler ' + res.status));
      }
      const data = await res.json();
      (data.sectors || []).filter(s=>s && s.name).forEach(s=> allSectors.push({ ...s, _sourceFile: file }));
      if(!gebietName && data.gebietName) gebietName = data.gebietName;
    }catch(e){
      failedCount++;
    }
  }
  if(statusEl) statusEl.textContent = '';
  if(!allSectors.length){
    showToast('Keine Sektoren erkannt — Foto(s) evtl. unscharf oder falscher Ausschnitt.', true);
    return;
  }
  if(failedCount){
    showToast(failedCount + ' von ' + files.length + ' Foto(s) konnten nicht ausgewertet werden — die übrigen wurden trotzdem erkannt.', true);
  }
  openKlettergebietScanReview(gebId, allSectors, gebietName);
}

// gebId===null bedeutet "neues Klettergebiet": submitKlettergebietScanReview legt dann zuerst
// ein neues Klettergebiet an (Name aus dem editierbaren Feld, vorbefüllt mit gebietName aus dem
// Scan) und hängt die erkannten Sektoren dort ein — sonst werden sie an ein bestehendes Gebiet
// (gebId) angehängt, wie beim Scan von der Klettergebiet-Detailseite aus.
function openKlettergebietScanReview(gebId, sectors, gebietName){
  // Vorschaubild pro Sektor cachen (statt bei jedem Render neu zu erzeugen) und jeder Route schon
  // hier eine stabile id geben — die braucht das "Route verschieben"-Werkzeug unten, um eine Route
  // eindeutig zwischen zwei Sektoren zu identifizieren, bevor sie überhaupt als Sektor gespeichert ist.
  sectors.forEach(sec=>{
    (sec.routes||[]).forEach(r=>{ if(!r.id) r.id = uid('kr'); });
    if(sec._sourceFile) sec._previewUrl = URL.createObjectURL(sec._sourceFile);
  });
  state.modal = { type:'klettergebiet-scan-review', payload:{ gebId, sectors, gebietName: gebietName || '' } };
  render();
}

function klettergebietScanReviewHtml(payload){
  const { sectors, gebId, gebietName } = payload;
  const isNewGebiet = !gebId;
  const photoCount = new Set(sectors.map(s=>s._sourceFile)).size;
  // Gleicher (normalisierter) Name in mehreren Sektoren deutet auf eine Doppelerkennung hin — z. B.
  // wenn zwei Fotos denselben Bereich überlappend zeigen. Sichtbar markieren statt stillschweigend
  // beide anzulegen, damit man es vor dem Übernehmen bemerkt.
  const nameCounts = {};
  sectors.forEach(s=>{ const key = (s.name||'').trim().toLowerCase(); if(key) nameCounts[key] = (nameCounts[key]||0) + 1; });
  return `<div class="modal" data-stop="1">
    <div class="modal-head"><h2>📷 ${isNewGebiet ? 'Neues Klettergebiet aus Foto' : 'Erkannte Sektoren'}</h2><button class="x-btn" data-act="close-modal">×</button></div>
    ${isNewGebiet ? `<div class="field" style="margin-bottom:14px;">
      <label>Klettergebiet-Name *</label>
      <input type="text" id="klettergebiet-scan-gebiet-name" value="${esc(gebietName||'')}" placeholder="z. B. Sewen"/>
      ${!gebietName ? `<p style="font-size:12.5px; color:var(--ink-soft); margin:4px 0 0 0;">Kein Titel auf dem Foto erkannt — bitte Namen eintragen.</p>` : ''}
    </div>` : ''}
    <p style="font-size:13px; color:var(--ink-soft);">${sectors.length} Sektor${sectors.length===1?'':'en'} erkannt${photoCount>1 ? ' aus ' + photoCount + ' Fotos' : ''} — Foto, Name und Routen vor dem Übernehmen kurz prüfen, jeder wird als eigener, neuer Sektor angelegt.</p>
    <div id="klettergebiet-scan-sectors">
      ${sectors.map((sec,i)=>{
        const key = (sec.name||'').trim().toLowerCase();
        const isDuplicate = !!key && nameCounts[key] > 1;
        const isUnsortiert = (sec.name||'').trim() === 'Unsortiert';
        const flagged = isDuplicate || isUnsortiert;
        return `
        <div class="field" style="border:1px solid ${flagged ? 'var(--danger)' : 'var(--line)'}; border-radius:var(--radius); padding:12px; margin-bottom:14px;">
          <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:10px;">
            <div style="flex:1;">
              <label>Sektor-Name</label>
              <input type="text" class="scan-sector-name" data-index="${i}" value="${esc(sec.name||'')}"/>
            </div>
            <button type="button" class="scan-sector-discard btn secondary" data-index="${i}" style="margin-top:20px; font-size:12px; padding:5px 10px; white-space:nowrap;">🗑️ Verwerfen</button>
          </div>
          ${isDuplicate ? `<p style="font-size:12px; color:var(--danger); margin:6px 0 0 0;">⚠ Möglicherweise doppelt erkannt — gleicher Name wie ein anderer Sektor unten. Bitte vergleichen, dann einen verwerfen oder Routen zusammenführen.</p>` : ''}
          ${isUnsortiert ? `<p style="font-size:12px; color:var(--danger); margin:6px 0 0 0;">⚠ Diese Routen konnten nicht eindeutig einem Sektor zugeordnet werden — bitte unten mit "Route verschieben" den richtigen Sektoren zuweisen.</p>` : ''}
          ${sec._previewUrl ? `<img src="${esc(sec._previewUrl)}" alt="Foto-Vorschau" style="display:block; max-width:100%; max-height:220px; margin-top:10px; border-radius:6px; cursor:zoom-in; object-fit:contain;" onclick="showTopoImageLightbox([{url:'${esc(sec._previewUrl)}'}],0)"/>` : ''}
          ${fsSektorInfoReviewHtml(sec.info, i)}
          <div id="scan-sector-editor-${i}" style="margin-top:10px;"></div>
          <input type="hidden" id="scan-sector-hidden-${i}" value='${esc(JSON.stringify(sec.routes||[]))}'/>
          ${sectors.length>1 ? `
          <div style="margin-top:12px; padding-top:10px; border-top:1px dashed var(--line); display:flex; gap:6px; flex-wrap:wrap; align-items:center;">
            <span style="font-size:12px; color:var(--ink-soft);">🔀 Route verschieben nach:</span>
            <select class="scan-move-route-select" data-index="${i}" style="flex:1; min-width:120px; font-size:12.5px; padding:4px;"></select>
            <select class="scan-move-target-select" data-index="${i}" style="flex:1; min-width:120px; font-size:12.5px; padding:4px;"></select>
            <button type="button" class="scan-move-btn btn secondary" data-index="${i}" style="font-size:12px; padding:5px 10px;">Verschieben</button>
          </div>` : ''}
        </div>
      `;}).join('')}
    </div>
    <div class="form-actions">
      <button type="button" class="btn secondary" data-act="close-modal">Abbrechen</button>
      <button type="button" id="klettergebiet-scan-apply-btn" class="btn">✓ ${isNewGebiet ? 'Gebiet mit Sektoren anlegen' : 'Als neue Sektoren übernehmen'}</button>
    </div>
  </div>`;
}

function wireKlettergebietScanReviewModal(){
  const applyBtn = document.getElementById('klettergebiet-scan-apply-btn');
  if(!applyBtn) return;
  const payload = state.modal && state.modal.payload;
  if(!payload) return;
  payload.sectors.forEach((sec,i)=> renderKletterroutenEditor('scan-sector-editor-'+i, 'scan-sector-hidden-'+i));
  applyBtn.addEventListener('click', ()=> submitKlettergebietScanReview());

  // Verwerfen: Karte einfach aus der Liste nehmen und die ganze Prüfansicht neu aufbauen — dadurch
  // verschieben sich die Indizes der übrigen Karten automatisch konsistent mit, kein Nachführen nötig.
  document.querySelectorAll('.scan-sector-discard').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const idx = parseInt(btn.getAttribute('data-index'), 10);
      payload.sectors.splice(idx, 1);
      render();
    });
  });

  // Route zwischen zwei erkannten Sektoren verschieben, bevor überhaupt etwas gespeichert wird —
  // behebt falsch gruppierte Routen (z. B. bei unübersichtlichen Mehrsektor-Fotos), ohne alles neu
  // abtippen zu müssen. Die Dropdown-Optionen werden erst bei Fokus aktuell befüllt (nicht fest im
  // HTML), da sich Routenlisten/Sektor-Namen währenddessen durch Bearbeiten laufend ändern können.
  function refreshMoveRouteOptions(i){
    const sel = document.querySelector('.scan-move-route-select[data-index="'+i+'"]');
    const hiddenInput = document.getElementById('scan-sector-hidden-'+i);
    if(!sel || !hiddenInput) return;
    let routes = [];
    try{ routes = JSON.parse(hiddenInput.value || '[]'); }catch(e){ routes = []; }
    sel.innerHTML = routes.length
      ? routes.map(r=>`<option value="${esc(r.id)}">${esc((r.nr!=null?r.nr+'. ':'') + (r.name||'—'))}</option>`).join('')
      : `<option value="">(keine Routen)</option>`;
  }
  function refreshMoveTargetOptions(i){
    const sel = document.querySelector('.scan-move-target-select[data-index="'+i+'"]');
    if(!sel) return;
    const nameInputs = document.querySelectorAll('.scan-sector-name');
    const opts = [];
    nameInputs.forEach((input, j)=>{
      if(j===i) return;
      opts.push(`<option value="${j}">${esc(input.value.trim() || ('Sektor ' + (j+1)))}</option>`);
    });
    sel.innerHTML = opts.join('');
  }
  document.querySelectorAll('.scan-move-route-select').forEach(sel=>{
    const i = parseInt(sel.getAttribute('data-index'), 10);
    refreshMoveRouteOptions(i);
    sel.addEventListener('focus', ()=> refreshMoveRouteOptions(i));
  });
  document.querySelectorAll('.scan-move-target-select').forEach(sel=>{
    const i = parseInt(sel.getAttribute('data-index'), 10);
    refreshMoveTargetOptions(i);
    sel.addEventListener('focus', ()=> refreshMoveTargetOptions(i));
  });
  document.querySelectorAll('.scan-move-btn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const i = parseInt(btn.getAttribute('data-index'), 10);
      const routeSel = document.querySelector('.scan-move-route-select[data-index="'+i+'"]');
      const targetSel = document.querySelector('.scan-move-target-select[data-index="'+i+'"]');
      const routeId = routeSel ? routeSel.value : '';
      const targetIdx = targetSel ? parseInt(targetSel.value, 10) : NaN;
      if(!routeId){ showToast('Keine Route zum Verschieben ausgewählt.', true); return; }
      if(isNaN(targetIdx)){ showToast('Kein Ziel-Sektor ausgewählt.', true); return; }
      const sourceHidden = document.getElementById('scan-sector-hidden-'+i);
      const targetHidden = document.getElementById('scan-sector-hidden-'+targetIdx);
      if(!sourceHidden || !targetHidden) return;
      let sourceRoutes = [], targetRoutes = [];
      try{ sourceRoutes = JSON.parse(sourceHidden.value || '[]'); }catch(e){ sourceRoutes = []; }
      try{ targetRoutes = JSON.parse(targetHidden.value || '[]'); }catch(e){ targetRoutes = []; }
      const routeIdx = sourceRoutes.findIndex(r=>r.id===routeId);
      if(routeIdx===-1) return;
      const [moved] = sourceRoutes.splice(routeIdx, 1);
      targetRoutes.push(moved);
      sourceHidden.value = JSON.stringify(sourceRoutes);
      targetHidden.value = JSON.stringify(targetRoutes);
      renderKletterroutenEditor('scan-sector-editor-'+i, 'scan-sector-hidden-'+i);
      renderKletterroutenEditor('scan-sector-editor-'+targetIdx, 'scan-sector-hidden-'+targetIdx);
      refreshMoveRouteOptions(i);
      showToast('Route verschoben.');
    });
  });
}

async function submitKlettergebietScanReview(){
  const payload = state.modal && state.modal.payload;
  if(!payload) return;
  const isNewGebiet = !payload.gebId;

  let gebId = payload.gebId;
  let newGeb = null;
  if(isNewGebiet){
    const nameInput = document.getElementById('klettergebiet-scan-gebiet-name');
    const gebietName = nameInput ? nameInput.value.trim() : '';
    if(!gebietName){ showToast('Bitte einen Namen für das Klettergebiet eintragen.', true); return; }
    newGeb = { id: uid('geb'), name: gebietName, region: '', subregion: '', description: '', points: [], manualTrack: [], createdBy: state.myName, createdAt: new Date().toISOString() };
    gebId = newGeb.id;
  }

  const nameInputs = document.querySelectorAll('.scan-sector-name');
  const created = [];
  nameInputs.forEach((input, i)=>{
    const name = input.value.trim();
    if(!name) return;
    let routes = [];
    try{ routes = JSON.parse(document.getElementById('scan-sector-hidden-'+i).value || '[]'); }catch(e){ routes = []; }
    const sek = { id: uid('sek'), name, klettergebietId: gebId, kletterrouten: routes, topoImages: [], createdBy: state.myName, createdAt: new Date().toISOString() };
    ensureSektorRouteArrays(sek);
    const sourceSector = payload.sectors[i];
    const infoBox = document.querySelector('.scan-sector-info[data-index="' + i + '"]');
    if(sourceSector && infoBox && infoBox.checked) fsApplySektorInfo(sek, sourceSector.info);
    if(sourceSector && sourceSector._sourceFile) sek._sourceFile = sourceSector._sourceFile;
    created.push(sek);
  });
  if(!created.length){ showToast('Bitte mindestens einen Sektor-Namen eintragen.', true); return; }

  for(const sek of created){
    if(!sek._sourceFile) continue;
    try{
      const blob = await compressImageFile(sek._sourceFile, 1200, 0.78);
      const imgId = uid('img');
      const storagePath = `${TOPO_IMAGES_PATH}/${sek.id}/${imgId}.jpg`;
      const url = await uploadTopoImageBlob(blob, storagePath);
      sek.topoImages = [{ id: imgId, url, storagePath }];
    }catch(e){ /* Topo-Bild kann später manuell ergänzt werden — kein Abbruch */ }
    delete sek._sourceFile;
  }

  if(newGeb) state.klettergebiete.unshift(newGeb);
  state.sektoren.unshift(...created);
  closeModal(false, true, true);
  state.modal = { type:'klettergebiet-detail', payload: gebId };
  render();

  const gebResult = newGeb ? await saveKlettergebietCloud(newGeb).catch(()=>false) : true;
  if(newGeb) newGeb._unsynced = !gebResult;
  const results = await Promise.all(created.map(sek=> saveSektorCloud(sek).catch(()=>false)));
  created.forEach((sek,i)=>{ sek._unsynced = !results[i]; });
  if(gebResult && results.every(r=>r)){
    showToast((newGeb ? 'Klettergebiet mit ' : '') + created.length + ' Sektor' + (created.length===1?'':'en') + ' angelegt und synchronisiert.');
  }else{
    markUnsaved();
    showToast('Einiges ist lokal gespeichert, konnte aber nicht synchronisiert werden. Prüfe deine Internetverbindung.', true);
  }
  render();
}

// Foto-Scan für einen einzelnen Zustieg/Abstieg — füllt direkt die gleichnamigen Formularfelder
// (name/elevation/elevationUp/duration/difficultyT/description), egal ob Hütten-Zustieg
// (accessRouteFormHtml), Tour-Route oder Sektor-Route: alle drei nutzen dieselben Feldnamen.
async function scanZustiegIntoForm(fileInputEl, formEl, statusElId){
  const statusEl = document.getElementById(statusElId);
  if(!SCAN_ZUSTIEG_URL){
    showToast('Foto-Scan ist noch nicht eingerichtet — siehe functions/README.md.', true);
    return;
  }
  const file = fileInputEl && fileInputEl.files && fileInputEl.files[0];
  if(!file){
    showToast('Bitte zuerst ein Foto auswählen.', true);
    return;
  }
  if(statusEl) statusEl.textContent = 'Erkenne Angaben …';
  try{
    const imageBase64 = await blobToBase64(file);
    await ensureValidAuthToken();
    const res = await fetch(SCAN_ZUSTIEG_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + authState.idToken },
      body: JSON.stringify({ imageBase64, mediaType: file.type || 'image/jpeg' }),
    });
    if(!res.ok){
      const errBody = await res.json().catch(()=>({}));
      throw new Error(errBody.error || ('Serverfehler ' + res.status));
    }
    const data = await res.json();
    const setIfPresent = (name, val)=>{
      if(!val) return;
      const el = formEl.querySelector('[name="'+name+'"]');
      if(el) el.value = val;
    };
    setIfPresent('name', data.name);
    setIfPresent('elevation', data.elevation);
    setIfPresent('elevationUp', data.elevationUp);
    setIfPresent('duration', data.duration);
    setIfPresent('description', data.description);
    if(data.difficultyT){
      const sel = formEl.querySelector('[name="difficultyT"]');
      if(sel) sel.value = data.difficultyT;
    }
    if(statusEl) statusEl.textContent = '✓ Angaben übernommen — bitte kurz prüfen.';
    showToast('Angaben erkannt und übernommen — bitte kurz prüfen.');
    markModalDirty();
  }catch(e){
    if(statusEl) statusEl.textContent = '';
    showToast('Foto-Scan fehlgeschlagen: ' + (e.message || e), true);
  }
}

// Wiederverwendbarer Foto-Scan-Block fürs Zustieg/Abstieg-Formular (Hütte/Tour/Sektor) —
// idPrefix macht die Element-IDs pro Formular eindeutig.
function scanZustiegButtonHtml(idPrefix){
  return `<div class="field">
    <button type="button" class="btn secondary" id="${idPrefix}-scan-btn">📷 Foto scannen</button>
    <input type="file" id="${idPrefix}-scan-input" accept="image/*" style="display:none;"/>
    <p id="${idPrefix}-scan-status" style="font-size:12.5px; color:var(--ink-soft); margin-top:6px;"></p>
    <div class="hint">Liest Name/Höhenmeter/Zeit/Beschreibung aus einem Foto der Führerbuch-Seite und trägt sie unten ein — bitte danach kurz prüfen.</div>
  </div>`;
}
function wireScanZustiegButton(idPrefix, formEl){
  const btn = document.getElementById(idPrefix+'-scan-btn');
  const input = document.getElementById(idPrefix+'-scan-input');
  if(!btn || !input || !formEl) return;
  btn.addEventListener('click', ()=> input.click());
  input.addEventListener('change', ()=> scanZustiegIntoForm(input, formEl, idPrefix+'-scan-status'));
}

// Editierbare Liste fürs Bearbeiten-Formular: Zeilen mit direkt editierbaren Feldern, ein
// "Liste einfügen"-Textfeld (nutzt parseKletterroutenText) und "+ Route hinzufügen" für einzelne
// neue Zeilen. Schreibt bei jeder Änderung sofort ins hiddenInputId-Feld zurück.
function renderKletterroutenEditor(containerId, hiddenInputId){
  const el = document.getElementById(containerId);
  const hiddenInput = document.getElementById(hiddenInputId);
  if(!el || !hiddenInput) return;
  let routes = [];
  try{ routes = hiddenInput.value ? JSON.parse(hiddenInput.value) : []; }catch(e){ routes = []; }

  function persist(){
    hiddenInput.value = JSON.stringify(routes);
    markModalDirty();
  }

  function makeFieldInput(value, placeholder, align, onCommit){
    const input = document.createElement('input');
    input.type = 'text';
    input.value = value;
    if(placeholder) input.placeholder = placeholder;
    input.style.cssText = `width:100%; border:1px solid transparent; background:transparent; font-family:inherit; font-size:13.5px; padding:4px 3px; border-radius:2px; ${align ? 'text-align:'+align+';' : ''}`;
    input.addEventListener('focus', ()=>{ input.style.borderColor = 'var(--line)'; input.style.background = '#fff'; });
    input.addEventListener('blur', ()=>{ input.style.borderColor = 'transparent'; input.style.background = 'transparent'; onCommit(input.value.trim()); });
    return input;
  }

  function redraw(){
    el.innerHTML = '';
    const wrap = document.createElement('div');

    const pasteHint = document.createElement('p');
    pasteHint.className = 'hint';
    pasteHint.style.marginBottom = '4px';
    pasteHint.textContent = 'Tipp: Foto der Führerbuch-Seite einer Chat-KI (z. B. Claude, ChatGPT, Gemini) geben und um eine Liste "Nr. | Name | Grad" bitten — das Ergebnis hier einfügen.';
    wrap.appendChild(pasteHint);

    const pasteArea = document.createElement('textarea');
    pasteArea.rows = 3;
    pasteArea.placeholder = '1 | Frog | 5c\n2 | Snake | 5b\n3 | Kreuzotter | 4b …';
    pasteArea.style.cssText = 'width:100%; font-family:inherit; font-size:13px; padding:8px; border:1px solid var(--line); border-radius:var(--radius); resize:vertical; box-sizing:border-box;';
    wrap.appendChild(pasteArea);

    const pasteBtn = document.createElement('button');
    pasteBtn.type = 'button'; pasteBtn.className = 'btn secondary';
    pasteBtn.style.cssText = 'margin-top:6px; font-size:12.5px; padding:6px 12px;';
    pasteBtn.textContent = '+ Liste übernehmen';
    pasteBtn.addEventListener('click', ()=>{
      const nextNr = routes.reduce((max,r)=> Math.max(max, r.nr||0), 0) + 1;
      const parsed = parseKletterroutenText(pasteArea.value, nextNr);
      if(!parsed.length){ showToast('Keine Routen erkannt — Format prüfen.', true); return; }
      routes = routes.concat(parsed);
      persist();
      pasteArea.value = '';
      redraw();
      showToast(parsed.length + ' Route(n) übernommen.');
    });
    wrap.appendChild(pasteBtn);

    const table = document.createElement('table');
    table.style.cssText = 'width:100%; border-collapse:collapse; font-size:13.5px; margin-top:14px;';
    const thead = document.createElement('thead');
    thead.innerHTML = `<tr>
      <th style="text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:0.05em; color:var(--ink-faint); padding:0 4px 6px 0; border-bottom:1px solid var(--line); width:38px;">Nr.</th>
      <th style="text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:0.05em; color:var(--ink-faint); padding:0 4px 6px 0; border-bottom:1px solid var(--line);">Route</th>
      <th style="text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:0.05em; color:var(--ink-faint); padding:0 4px 6px 0; border-bottom:1px solid var(--line); width:56px;">Grad</th>
      <th style="border-bottom:1px solid var(--line); width:26px;"></th>
    </tr>`;
    table.appendChild(thead);
    const tbody = document.createElement('tbody');
    routes.forEach((r)=>{
      const tr = document.createElement('tr');
      tr.style.borderBottom = '1px solid var(--line)';

      const nrTd = document.createElement('td');
      nrTd.style.padding = '4px 4px 4px 0';
      nrTd.appendChild(makeFieldInput(r.nr!=null ? String(r.nr) : '', 'Nr.', 'left', (v)=>{ r.nr = v ? parseInt(v,10) : null; persist(); }));
      tr.appendChild(nrTd);

      const nameTd = document.createElement('td');
      nameTd.style.padding = '4px';
      const nameInput = makeFieldInput(r.name || '', 'Name', null, (v)=>{ r.name = v; persist(); });
      nameInput.style.fontWeight = '600';
      nameTd.appendChild(nameInput);
      tr.appendChild(nameTd);

      const gradeTd = document.createElement('td');
      gradeTd.style.padding = '4px';
      gradeTd.appendChild(makeFieldInput(r.grad || '', '5c', 'center', (v)=>{ r.grad = v; persist(); }));
      tr.appendChild(gradeTd);

      const delTd = document.createElement('td');
      delTd.style.padding = '4px 0';
      const delBtn = document.createElement('button');
      delBtn.type = 'button'; delBtn.textContent = '🗑️';
      delBtn.title = 'Route entfernen';
      delBtn.style.cssText = 'background:none; border:none; color:var(--danger); cursor:pointer; font-size:14px; padding:0;';
      delBtn.addEventListener('click', ()=>{
        routes = routes.filter(x=>x!==r);
        persist();
        redraw();
      });
      delTd.appendChild(delBtn);
      tr.appendChild(delTd);

      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    if(routes.length) wrap.appendChild(table);
    else{
      const empty = document.createElement('p');
      empty.style.cssText = 'font-size:12.5px; color:var(--ink-faint); margin:10px 0 0 0;';
      empty.textContent = 'Noch keine Routen erfasst.';
      wrap.appendChild(empty);
    }

    const addBtn = document.createElement('button');
    addBtn.type = 'button'; addBtn.className = 'btn secondary';
    addBtn.style.cssText = 'margin-top:10px; font-size:12.5px; padding:6px 12px;';
    addBtn.textContent = '+ Route hinzufügen';
    addBtn.addEventListener('click', ()=>{
      const nextNr = routes.reduce((max,r)=> Math.max(max, r.nr||0), 0) + 1;
      routes.push({id: uid('kr'), nr: nextNr, name: '', grad: ''});
      persist();
      redraw();
    });
    wrap.appendChild(addBtn);

    el.appendChild(wrap);
  }
  redraw();
}

/* ================= Zuschneiden von Topo-Bildern vor dem Hochladen =================
   Bewusst VOR dem Hochladen, auf der lokal ausgewählten Datei: ein Zuschnitt am bereits
   hochgeladenen Bild müsste es per <canvas> aus der Firebase-Storage-URL neu einlesen — das
   scheitert ohne eigens am Storage-Bucket gesetzte CORS-Regeln. Die Dreh-Funktion oben umgeht
   dasselbe Problem, indem sie nur eine Anzeige-Metadaten-Drehung speichert statt die Pixel zu
   verändern; ein echter Zuschnitt braucht dagegen Pixelzugriff, den es nur vor dem Hochladen
   ohne Weiteres gibt. Gibt eine Promise zurück: das zugeschnittene Blob, die Originaldatei
   („Ohne Zuschneiden verwenden“ oder Zurück-Taste), oder null bei „Bild überspringen“.
   Bild überspringen liefert dasselbe null wie die Zurück-Taste — beides heisst "dieses Bild
   nicht übernehmen", ist also bewusst identisch behandelt. */
function openImageCropDialog(file){
  return new Promise((resolve)=>{
    const reader = new FileReader();
    reader.onload = ()=>{
      const img = new Image();
      img.onload = ()=>{
        const overlay = document.createElement('div');
        overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.92); z-index:210; display:flex; flex-direction:column; align-items:center; justify-content:center; padding:16px; touch-action:none;';

        const hint = document.createElement('div');
        hint.textContent = 'Ausschnitt wählen: Ecken ziehen zum Grösse ändern, Rahmen verschieben';
        hint.style.cssText = 'color:#fff; font-size:13px; margin-bottom:10px; text-align:center;';
        overlay.appendChild(hint);

        const stage = document.createElement('div');
        stage.style.cssText = 'position:relative; touch-action:none; line-height:0;';
        const imgEl = document.createElement('img');
        imgEl.src = reader.result;
        imgEl.draggable = false;
        imgEl.style.cssText = 'display:block; max-width:calc(100vw - 32px); max-height:60vh; user-select:none; -webkit-user-drag:none;';
        stage.appendChild(imgEl);

        const box = document.createElement('div');
        box.style.cssText = 'position:absolute; border:2px solid #fff; box-sizing:border-box; box-shadow:0 0 0 2000px rgba(0,0,0,0.55); touch-action:none; cursor:move;';
        stage.appendChild(box);

        const CORNERS = ['nw','ne','sw','se'];
        const handles = {};
        CORNERS.forEach(c=>{
          const h = document.createElement('div');
          h.style.cssText = `position:absolute; width:26px; height:26px; margin:-13px; background:#fff; border-radius:50%; touch-action:none; cursor:${(c==='nw'||c==='se')?'nwse-resize':'nesw-resize'};`;
          h.style[c.includes('n')?'top':'bottom'] = '0';
          h.style[c.includes('w')?'left':'right'] = '0';
          box.appendChild(h);
          handles[c] = h;
        });

        overlay.appendChild(stage);

        const btnRow = document.createElement('div');
        btnRow.style.cssText = 'display:flex; gap:10px; margin-top:16px; flex-wrap:wrap; justify-content:center;';
        const applyBtn = document.createElement('button');
        applyBtn.type = 'button'; applyBtn.textContent = '✓ Zuschnitt übernehmen'; applyBtn.className = 'btn';
        const skipBtn = document.createElement('button');
        skipBtn.type = 'button'; skipBtn.textContent = 'Ohne Zuschneiden verwenden'; skipBtn.className = 'btn secondary';
        const cancelBtn = document.createElement('button');
        cancelBtn.type = 'button'; cancelBtn.textContent = 'Bild überspringen'; cancelBtn.className = 'btn secondary';
        btnRow.appendChild(applyBtn); btnRow.appendChild(skipBtn); btnRow.appendChild(cancelBtn);
        overlay.appendChild(btnRow);

        document.body.appendChild(overlay);

        const MIN_SIZE = 30;
        let boxRect = {left:0, top:0, width:0, height:0};
        function renderBox(){
          box.style.left = boxRect.left + 'px';
          box.style.top = boxRect.top + 'px';
          box.style.width = boxRect.width + 'px';
          box.style.height = boxRect.height + 'px';
        }
        function initBox(){
          const iw = imgEl.clientWidth, ih = imgEl.clientHeight;
          stage.style.width = iw + 'px';
          stage.style.height = ih + 'px';
          const margin = Math.min(iw, ih) * 0.1;
          boxRect = { left: margin, top: margin, width: iw - margin*2, height: ih - margin*2 };
          renderBox();
        }
        // Läuft nach dem Layout — direkt nach dem Anhängen ist imgEl.clientWidth/Height noch 0.
        requestAnimationFrame(initBox);
        function clampBox(){
          const iw = imgEl.clientWidth, ih = imgEl.clientHeight;
          boxRect.width = Math.max(MIN_SIZE, Math.min(boxRect.width, iw));
          boxRect.height = Math.max(MIN_SIZE, Math.min(boxRect.height, ih));
          boxRect.left = Math.max(0, Math.min(boxRect.left, iw - boxRect.width));
          boxRect.top = Math.max(0, Math.min(boxRect.top, ih - boxRect.height));
        }

        let dragMode = null, dragStartX = 0, dragStartY = 0, startBox = null;
        function onPointerMove(e){
          if(!dragMode) return;
          const dx = e.clientX - dragStartX, dy = e.clientY - dragStartY;
          if(dragMode==='move'){
            boxRect.left = startBox.left + dx;
            boxRect.top = startBox.top + dy;
          }else{
            let {left, top, width, height} = startBox;
            if(dragMode.includes('w')){ left = startBox.left + dx; width = startBox.width - dx; }
            if(dragMode.includes('e')){ width = startBox.width + dx; }
            if(dragMode.includes('n')){ top = startBox.top + dy; height = startBox.height - dy; }
            if(dragMode.includes('s')){ height = startBox.height + dy; }
            if(width < MIN_SIZE){ if(dragMode.includes('w')) left = startBox.left + startBox.width - MIN_SIZE; width = MIN_SIZE; }
            if(height < MIN_SIZE){ if(dragMode.includes('n')) top = startBox.top + startBox.height - MIN_SIZE; height = MIN_SIZE; }
            boxRect = {left, top, width, height};
          }
          clampBox();
          renderBox();
        }
        function onPointerUp(){
          dragMode = null;
          document.removeEventListener('pointermove', onPointerMove);
          document.removeEventListener('pointerup', onPointerUp);
        }
        function onPointerDown(mode, e){
          e.preventDefault(); e.stopPropagation();
          dragMode = mode;
          dragStartX = e.clientX; dragStartY = e.clientY;
          startBox = {...boxRect};
          document.addEventListener('pointermove', onPointerMove);
          document.addEventListener('pointerup', onPointerUp);
        }
        box.addEventListener('pointerdown', (e)=>{ if(e.target===box) onPointerDown('move', e); });
        CORNERS.forEach(c=> handles[c].addEventListener('pointerdown', (e)=> onPointerDown(c, e)));

        // Genau ein Rückgabepfad: alle Buttons setzen pendingResult und schliessen dann über den
        // Overlay-Stack — so löst auch die Hardware-Zurück-Taste (popstate ruft denselben
        // registrierten closeFn) korrekt auf (dann bleibt pendingResult bei null = übersprungen).
        let pendingResult = null;
        pushOverlayLayer(()=>{ overlay.remove(); resolve(pendingResult); });
        function closeWith(result){ pendingResult = result; closeTopOverlayLayer(); }

        applyBtn.addEventListener('click', ()=>{
          const scaleX = img.naturalWidth / imgEl.clientWidth;
          const scaleY = img.naturalHeight / imgEl.clientHeight;
          const sx = Math.round(boxRect.left * scaleX), sy = Math.round(boxRect.top * scaleY);
          const sw = Math.round(boxRect.width * scaleX), sh = Math.round(boxRect.height * scaleY);
          const canvas = document.createElement('canvas');
          canvas.width = sw; canvas.height = sh;
          canvas.getContext('2d').drawImage(img, sx, sy, sw, sh, 0, 0, sw, sh);
          canvas.toBlob((blob)=> closeWith(blob || file), 'image/jpeg', 0.92);
        });
        skipBtn.addEventListener('click', ()=> closeWith(file));
        cancelBtn.addEventListener('click', ()=> closeWith(null));
      };
      img.onerror = ()=> resolve(file);
      img.src = reader.result;
    };
    reader.onerror = ()=> resolve(file);
    reader.readAsDataURL(file);
  });
}

/* ================= Offline-Download für unterwegs (Kartenkacheln + Bilder, 7 Tage) ================= */
const OFFLINE_DB_NAME = 'bergtourenbeta-offline';
const OFFLINE_DAYS = 7;
const OFFLINE_ZOOMS = [13, 14, 15, 16];
const OFFLINE_MAX_TILES = 500;

function openOfflineDB(){
  return new Promise((resolve, reject)=>{
    if(!window.indexedDB){ reject(new Error('Offline-Speicher wird von diesem Browser nicht unterstützt.')); return; }
    const req = indexedDB.open(OFFLINE_DB_NAME, 1);
    req.onupgradeneeded = (e)=>{
      const db = e.target.result;
      if(!db.objectStoreNames.contains('tiles')) db.createObjectStore('tiles');
      if(!db.objectStoreNames.contains('images')) db.createObjectStore('images');
      if(!db.objectStoreNames.contains('downloads')) db.createObjectStore('downloads');
    };
    req.onsuccess = ()=> resolve(req.result);
    req.onerror = ()=> reject(req.error || new Error('Offline-Datenbank konnte nicht geöffnet werden.'));
  });
}
async function idbPut(storeName, key, value){
  const db = await openOfflineDB();
  return new Promise((resolve, reject)=>{
    const tx = db.transaction(storeName, 'readwrite');
    tx.objectStore(storeName).put(value, key);
    tx.oncomplete = ()=> resolve();
    tx.onerror = ()=> reject(tx.error);
  });
}
async function idbGet(storeName, key){
  const db = await openOfflineDB();
  return new Promise((resolve, reject)=>{
    const tx = db.transaction(storeName, 'readonly');
    const req = tx.objectStore(storeName).get(key);
    req.onsuccess = ()=> resolve(req.result);
    req.onerror = ()=> reject(req.error);
  });
}
async function idbGetAllEntries(storeName){
  const db = await openOfflineDB();
  return new Promise((resolve, reject)=>{
    const tx = db.transaction(storeName, 'readonly');
    const store = tx.objectStore(storeName);
    const keysReq = store.getAllKeys();
    const valsReq = store.getAll();
    let keys=null, vals=null;
    keysReq.onsuccess = ()=> keys = keysReq.result;
    valsReq.onsuccess = ()=> vals = valsReq.result;
    tx.oncomplete = ()=> resolve((keys||[]).map((k,i)=>({key:k, value:(vals||[])[i]})));
    tx.onerror = ()=> reject(tx.error);
  });
}
async function idbDeleteByPrefix(storeName, prefix){
  const db = await openOfflineDB();
  return new Promise((resolve, reject)=>{
    const tx = db.transaction(storeName, 'readwrite');
    const store = tx.objectStore(storeName);
    const req = store.openCursor();
    req.onsuccess = (e)=>{
      const cursor = e.target.result;
      if(cursor){
        if(String(cursor.key).indexOf(prefix)===0) cursor.delete();
        cursor.continue();
      }
    };
    tx.oncomplete = ()=> resolve();
    tx.onerror = ()=> reject(tx.error);
  });
}
async function idbDeleteKey(storeName, key){
  const db = await openOfflineDB();
  return new Promise((resolve, reject)=>{
    const tx = db.transaction(storeName, 'readwrite');
    tx.objectStore(storeName).delete(key);
    tx.oncomplete = ()=> resolve();
    tx.onerror = ()=> reject(tx.error);
  });
}

function lonToTileX(lon, z){ return Math.floor((lon+180)/360*Math.pow(2,z)); }
function latToTileY(lat, z){
  const rad = lat*Math.PI/180;
  return Math.floor((1 - Math.log(Math.tan(rad)+1/Math.cos(rad))/Math.PI)/2 * Math.pow(2,z));
}

function computeOfflineTileList(allCoords){
  if(!allCoords.length) return [];
  let minLat=90, maxLat=-90, minLon=180, maxLon=-180;
  allCoords.forEach(([lat,lon])=>{
    if(lat<minLat) minLat=lat; if(lat>maxLat) maxLat=lat;
    if(lon<minLon) minLon=lon; if(lon>maxLon) maxLon=lon;
  });
  const buf = 0.01; // grober Puffer rund um die Route
  minLat-=buf; maxLat+=buf; minLon-=buf; maxLon+=buf;
  const tiles = [];
  OFFLINE_ZOOMS.forEach(z=>{
    const xMin = lonToTileX(minLon,z), xMax = lonToTileX(maxLon,z);
    const yMin = latToTileY(maxLat,z), yMax = latToTileY(minLat,z);
    for(let x=xMin; x<=xMax; x++){
      for(let y=yMin; y<=yMax; y++){
        tiles.push({z,x,y});
      }
    }
  });
  return tiles;
}

async function deleteTourOfflineData(offlineId){
  await idbDeleteByPrefix('tiles', offlineId + '_');
  await idbDeleteByPrefix('images', offlineId + '_');
  await idbDeleteKey('downloads', offlineId);
}

async function getTourOfflineStatus(offlineId){
  try{
    const record = await idbGet('downloads', offlineId);
    if(!record) return null;
    if(Date.now() > record.expiresAt){
      await deleteTourOfflineData(offlineId);
      return null;
    }
    return record;
  }catch(e){ return null; }
}

async function cleanupExpiredOfflineDownloads(){
  try{
    const all = await idbGetAllEntries('downloads');
    const now = Date.now();
    for(const entry of all){
      if(entry.value && entry.value.expiresAt < now){
        await deleteTourOfflineData(entry.key);
      }
    }
  }catch(e){ /* Offline-Speicher evtl. nicht verfügbar — kein Problem, still ignorieren */ }
}

async function downloadTourOffline(offlineId, tourName, allCoords, images, onProgress){
  await deleteTourOfflineData(offlineId);
  const tileList = computeOfflineTileList(allCoords || []);
  if(!tileList.length && (!images || !images.length)) throw new Error('Weder Standortdaten noch Topo-Bilder zum Herunterladen vorhanden.');
  if(tileList.length > OFFLINE_MAX_TILES) throw new Error('Das abgedeckte Gebiet ist zu gross für den Offline-Download (mehr als ' + OFFLINE_MAX_TILES + ' Kartenkacheln).');
  const totalSteps = tileList.length + (images ? images.length : 0);
  let done = 0;
  for(const {z,x,y} of tileList){
    try{
      const url = `https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.pixelkarte-farbe/default/current/3857/${z}/${x}/${y}.jpeg`;
      const res = await fetch(url);
      if(res.ok){
        const blob = await res.blob();
        await idbPut('tiles', `${offlineId}_${z}_${x}_${y}`, blob);
      }
    }catch(e){ /* einzelne Kachel überspringen, Rest weiter versuchen */ }
    done++;
    if(onProgress) onProgress(done, totalSteps);
  }
  if(images && images.length){
    for(const img of images){
      try{
        const res = await fetch(img.url);
        if(res.ok){
          const blob = await res.blob();
          await idbPut('images', `${offlineId}_${img.id}`, blob);
        }
      }catch(e){}
      done++;
      if(onProgress) onProgress(done, totalSteps);
    }
  }
  const now = Date.now();
  const expiresAt = now + OFFLINE_DAYS*24*60*60*1000;
  await idbPut('downloads', offlineId, { offlineId, tourName, downloadedAt: now, expiresAt, tileCount: tileList.length, imageCount: (images?images.length:0) });
  return true;
}

function formatOfflineRemaining(expiresAt){
  const msLeft = expiresAt - Date.now();
  if(msLeft <= 0) return 'abgelaufen';
  const daysLeft = Math.floor(msLeft / (24*60*60*1000));
  const hoursLeft = Math.floor((msLeft % (24*60*60*1000)) / (60*60*1000));
  if(daysLeft >= 1) return `noch ${daysLeft} Tag${daysLeft===1?'':'e'} offline verfügbar`;
  return `noch ${hoursLeft} Std. offline verfügbar`;
}

/* ================= Live-GPS-Standort auf der Karte ================= */
let gpsWatchId = null;
let gpsMarker = null;
let gpsActiveOfflineId = null; // für welche Tour GPS aktuell läuft — überlebt einen Kartenwechsel (z. B. beim Öffnen der Vollbildansicht)
// Akku: Standort schaltet sich nach 5 Minuten selbst ab (erneut antippen = wieder 5 Minuten)
const FS_GPS_AUTO_OFF_MS = 5 * 60 * 1000;
let fsGpsOffTimer = null;
function startLiveGpsOnMap(map, offlineId){
  if(!navigator.geolocation) return;
  if(map && map._ml) map = map._ml; // FL-Karte: die MapLibre-Karte darunter
  stopLiveGpsOnMap();
  gpsActiveOfflineId = offlineId || null;
  gpsWatchId = navigator.geolocation.watchPosition((pos)=>{
    const latlng = [pos.coords.latitude, pos.coords.longitude];
    if(map && map._fsm){
      // MapLibre-Karte: blauer Punkt als HTML-Marker
      if(!gpsMarker){ const el = document.createElement('div'); el.className = 'fsm-gps'; gpsMarker = new maplibregl.Marker({element: el}).setLngLat([latlng[1], latlng[0]]).addTo(map); gpsMarker._fsmMap = map; }
      else gpsMarker.setLngLat([latlng[1], latlng[0]]);
      if(map._fsmFlyOnFix){ map._fsmFlyOnFix = false; map.easeTo({center:[latlng[1], latlng[0]], zoom: Math.max(map.getZoom(), 14), duration: 800}); }
      return;
    }
  }, (err)=>{
    dlog('GPS-Standort nicht verfügbar: ' + (err && err.message ? err.message : err), 'err');
    if(map && map._fsm && map._fsmFlyOnFix){ map._fsmFlyOnFix = false; showToast('Standort nicht verfügbar — Ortung erlaubt?', true); }
  }, { enableHighAccuracy:true, maximumAge:5000 });
  fsGpsOffTimer = setTimeout(()=>{
    if(gpsWatchId === null) return;
    stopLiveGpsOnMap();
    document.querySelectorAll('.fsm-btn[data-fsm="gps"].on').forEach(b=> b.classList.remove('on'));
    showToast('Standort nach 5 Minuten ausgeschaltet (Akku sparen). Antippen schaltet ihn wieder ein.');
  }, FS_GPS_AUTO_OFF_MS);
}
function stopLiveGpsOnMap(){
  if(fsGpsOffTimer){ clearTimeout(fsGpsOffTimer); fsGpsOffTimer = null; }
  gpsActiveOfflineId = null;
  if(gpsWatchId !== null){ try{ navigator.geolocation.clearWatch(gpsWatchId); }catch(e){} gpsWatchId = null; }
  if(gpsMarker){ try{ gpsMarker.remove(); }catch(e){} gpsMarker = null; }
}

/* ================= Offline-Bereich: Anzeige in der Detailansicht ================= */
function offlineSectionHtml(offlineId){
  return `<div class="detail-section" id="offline-section-${offlineId}">
    <h4>Für unterwegs</h4>
    <div id="offline-body-${offlineId}"><p style="font-size:13px; color:var(--ink-soft);">Lädt…</p></div>
  </div>`;
}

/* ================= Tour-Ansicht: eine Hauptaktion, Kacheln, "Mehr" (Phase 2b) =================
   Statt rund zehn gleichwertiger Knöpfe untereinander: oben EINE Hauptaktion (für unterwegs
   laden), darunter vier Kacheln (Karte, Wetter, 3D, Mehr). Selten Gebrauchtes (GPX, Export,
   Abgeschlossen markieren …) liegt im "Mehr"-Menü. Geteilt von Firnspur und Fixseil. */
function fsTileHtml(icon, label, attrs){
  return `<button type="button" class="fs-tile" ${attrs}>${fsIconHtml(icon)}<span>${label}</span></button>`;
}
// Ein Eintrag im "Mehr"-Menü. href gesetzt = externer Link statt Knopf.
/* ================= Anreise: Navigation, Fahrzeit und ÖV-Verbindung (fsTravel*) =================
   Pro Tour ein Block "Anreise" in der Tourenansicht:
   - Parkplatz (oder erster Punkt als Ausgangspunkt): "Navigieren" öffnet Google Maps / die Karten-App
     mit Route ab dem eigenen Standort; Fahrzeit ab Standort über openrouteservice (ohne Verkehr)
   - Haltestelle: nächste Verbindung aus dem Schweizer Fahrplan (transport.opendata.ch) ab der
     nächstgelegenen Haltestelle beim eigenen Standort; Link zur ÖV-Route
   Den Standort fragt die App erst auf Knopfdruck ab — ausser er ist schon erlaubt. */
function fsTravelTargets(t){
  const pts = (t && t.points) || [];
  const park = pts.filter(p=> p.category === 'parkplatz');
  const stops = pts.filter(p=> p.category === 'haltestelle');
  const car = park.length ? park : (pts.length && !stops.length ? [Object.assign({}, pts[0], {_start: true})] : []);
  return {car, stops};
}
function fsTravelHtml(t){
  const {car, stops} = fsTravelTargets(t);
  if(!car.length && !stops.length) return '';
  const gm = (p, mode)=> 'https://www.google.com/maps/dir/?api=1&destination=' + p.lat + ',' + p.lon + '&travelmode=' + mode;
  const row = (p, kind, i)=>{
    const label = p.label || (kind === 'car' ? (p._start ? 'Ausgangspunkt' : 'Parkplatz') : 'Haltestelle');
    return `<div class="fs-travel-row" data-kind="${kind}" data-i="${i}">
      <div class="fs-travel-head">
        <span class="fs-travel-ico">${kind === 'car' ? '🅿️' : '🚏'}</span>
        <strong>${esc(label)}</strong>
        <a class="fs-travel-go" href="${gm(p, kind === 'car' ? 'driving' : 'transit')}" target="_blank" rel="noopener noreferrer">${kind === 'car' ? 'Navigieren' : 'ÖV-Route'} ↗</a>
      </div>
      <div class="fs-travel-info" data-info></div>
    </div>`;
  };
  return `<div class="detail-section fs-travel" id="fs-travel-${t.id}" data-tour-id="${t.id}" data-pending="1">
    <h4>Anreise</h4>
    ${car.map((p, i)=> row(p, 'car', i)).join('')}
    ${stops.map((p, i)=> row(p, 'stop', i)).join('')}
    <button type="button" class="btn secondary fs-travel-calc" data-act="fs-travel-calc">${fsIconHtml('gps')}<span>Ab meinem Standort berechnen</span></button>
  </div>`;
}
let fsTravelPos = null, fsTravelPosAt = 0;
const fsTravelCache = new Map();
function fsTravelPosition(){
  if(fsTravelPos && Date.now() - fsTravelPosAt < 5 * 60000) return Promise.resolve(fsTravelPos);
  return new Promise((resolve, reject)=>{
    if(!navigator.geolocation){ reject(new Error('Standort nicht verfügbar')); return; }
    navigator.geolocation.getCurrentPosition(pos=>{ fsTravelPos = {lat: pos.coords.latitude, lon: pos.coords.longitude}; fsTravelPosAt = Date.now(); resolve(fsTravelPos); },
      err=> reject(new Error(err && err.code === 1 ? 'Standort nicht erlaubt' : 'Standort nicht verfügbar')), {enableHighAccuracy:false, maximumAge:300000, timeout:15000});
  });
}
const fsFmtDur = (s)=>{ const m = Math.round(s / 60); return m < 60 ? m + ' min' : Math.floor(m / 60) + ' h ' + String(m % 60).padStart(2, '0') + ' min'; };
async function fsTravelDrive(from, to){
  const key = 'car|' + from.lat.toFixed(3) + ',' + from.lon.toFixed(3) + '|' + to.lat + ',' + to.lon;
  if(fsTravelCache.has(key)) return fsTravelCache.get(key);
  const url = 'https://api.openrouteservice.org/v2/directions/driving-car?api_key=' + encodeURIComponent(OPENROUTESERVICE_API_KEY) + '&start=' + from.lon + ',' + from.lat + '&end=' + to.lon + ',' + to.lat;
  const res = await fetch(url);
  if(!res.ok) throw new Error('Fahrzeit nicht verfügbar');
  const d = await res.json();
  const s = d.features && d.features[0] && d.features[0].properties && d.features[0].properties.summary;
  if(!s) throw new Error('Keine Strassenverbindung gefunden');
  const g = d.features[0].geometry;
  const r = {durationS: s.duration, distanceM: s.distance, coords: g && Array.isArray(g.coordinates) ? g.coordinates : null};
  fsTravelCache.set(key, r);
  return r;
}
// Nächste Haltestelle(n) bei einer Koordinate (Schweizer Fahrplan)
async function fsTravelNearestStation(p){
  const res = await fetch('https://transport.opendata.ch/v1/locations?type=station&x=' + p.lat + '&y=' + p.lon);
  if(!res.ok) throw new Error('Fahrplan nicht erreichbar');
  const d = await res.json();
  const st = (d.stations || []).find(s=> s && s.id);
  if(!st) throw new Error('Keine Haltestelle in der Nähe');
  return st;
}
// opts {date:'YYYY-MM-DD', time:'HH:MM'}: Verbindung zu einem bestimmten Zeitpunkt (Tourenzettel)
async function fsTravelTransit(from, to, opts){
  opts = opts || {};
  const when = (opts.date ? '&date=' + opts.date : '') + (opts.time ? '&time=' + encodeURIComponent(opts.time) : '');
  const key = 'oev|' + from.lat.toFixed(3) + ',' + from.lon.toFixed(3) + '|' + to.lat + ',' + to.lon + when;
  if(fsTravelCache.has(key)) return fsTravelCache.get(key);
  const [a, b] = await Promise.all([fsTravelNearestStation(from), fsTravelNearestStation(to)]);
  if(a.id === b.id) return {same: true, station: a.name};
  const res = await fetch('https://transport.opendata.ch/v1/connections?limit=2&from=' + encodeURIComponent(a.id) + '&to=' + encodeURIComponent(b.id) + when);
  if(!res.ok) throw new Error('Fahrplan nicht erreichbar');
  const d = await res.json();
  const c = (d.connections || [])[0];
  if(!c) throw new Error('Keine Verbindung gefunden');
  const t = (iso)=> iso ? new Date(iso).toLocaleTimeString('de-CH', {hour:'2-digit', minute:'2-digit', timeZone:'Europe/Zurich'}) : '';
  const dm = /(\d+)d(\d+):(\d+)/.exec(c.duration || '');
  const r = {from: a.name, to: b.name, dep: t(c.from && c.from.departure), arr: t(c.to && c.to.arrival),
    durS: dm ? (+dm[1] * 1440 + +dm[2] * 60 + +dm[3]) * 60 : null, transfers: c.transfers,
    products: (c.products || []).filter(Boolean).join(', '),
    legs: (c.sections || []).filter(x=> x && x.journey).map(x=>({
      line: [x.journey.category, x.journey.number].filter(Boolean).join(' ') || x.journey.name || '',
      from: x.departure && x.departure.station ? x.departure.station.name : '', dep: t(x.departure && x.departure.departure),
      platform: x.departure && x.departure.platform ? x.departure.platform : '',
      to: x.arrival && x.arrival.station ? x.arrival.station.name : '', arr: t(x.arrival && x.arrival.arrival)}))};
  fsTravelCache.set(key, r);
  return r;
}
async function fsTravelCalc(box){
  const t = (state.tours || []).find(x=> String(x.id) === String(box.getAttribute('data-tour-id')));
  if(!t) return;
  box.setAttribute('data-pending', '0');
  const btn = box.querySelector('.fs-travel-calc');
  if(btn){ btn.disabled = true; btn.querySelector('span').textContent = 'Standort wird bestimmt …'; }
  let pos;
  try{ pos = await fsTravelPosition(); }
  catch(e){ if(btn){ btn.disabled = false; btn.querySelector('span').textContent = 'Ab meinem Standort berechnen'; } showToast(e.message + ' — Navigation über die Links geht trotzdem.', true); return; }
  if(btn) btn.remove();
  const {car, stops} = fsTravelTargets(t);
  box.querySelectorAll('.fs-travel-row').forEach(row=>{
    const kind = row.getAttribute('data-kind'), i = +row.getAttribute('data-i');
    const p = (kind === 'car' ? car : stops)[i], info = row.querySelector('[data-info]');
    if(!p) return;
    info.textContent = 'Berechne …';
    if(kind === 'car'){
      fsTravelDrive(pos, p).then(r=>{ info.innerHTML = `<b>🚗 ${fsFmtDur(r.durationS)}</b> · ${(r.distanceM / 1000).toFixed(0)} km ab deinem Standort <span class="fs-travel-note">(ohne Verkehr)</span>`; })
        .catch(e=>{ info.textContent = e.message; });
    }else{
      fsTravelTransit(pos, p).then(r=>{
        if(r.same){ info.textContent = 'Du bist schon bei ' + r.station + '.'; return; }
        info.innerHTML = `<b>🚆 ${esc(r.dep)} → ${esc(r.arr)}</b>${r.durS ? ' · ' + fsFmtDur(r.durS) : ''}${typeof r.transfers === 'number' ? ' · ' + (r.transfers === 0 ? 'direkt' : r.transfers + '× umsteigen') : ''}<br/><span class="fs-travel-note">ab ${esc(r.from)} bis ${esc(r.to)}${r.products ? ' · ' + esc(r.products) : ''}</span>`;
      }).catch(e=>{ info.textContent = e.message; });
    }
  });
}
// Automatisch berechnen, wenn der Standort schon erlaubt ist (sonst erst auf Knopfdruck)
let fsTravelPerm = null;
function fsTravelAutoFill(){
  const box = document.querySelector('.fs-travel[data-pending="1"]');
  if(!box) return;
  if(fsTravelPerm === 'granted'){ fsTravelCalc(box); return; }
  if(fsTravelPerm === null && navigator.permissions && navigator.permissions.query){
    fsTravelPerm = 'asking';
    navigator.permissions.query({name:'geolocation'}).then(s=>{ fsTravelPerm = s.state; if(s.state === 'granted') fsTravelAutoFill(); }).catch(()=>{ fsTravelPerm = 'unknown'; });
  }
}
document.addEventListener('click', (e)=>{
  const b = e.target.closest && e.target.closest('[data-act="fs-travel-calc"]');
  if(!b) return;
  e.preventDefault(); e.stopPropagation();
  fsTravelCalc(b.closest('.fs-travel'));
}, true);

/* ================= Treffpunkt mit Koordinaten (für die Anfahrt auf dem Tourenzettel) =================
   Im Termin-Formular: Ort suchen (swisstopo-Suche) oder auf der Karte setzen. Gespeichert werden
   meetingLat/meetingLon zusätzlich zum Freitext. */
function fsAgendaPhone(a, name){
  const hit = (a && Array.isArray(a.phones) ? a.phones : []).find(x=> x && x.name === name);
  return hit ? hit.phone : '';
}
function fsMeetToolsHtml(a){
  const has = a && a.meetingLat != null && a.meetingLon != null;
  return `<input type="hidden" name="meetingLat" value="${has ? a.meetingLat : ''}"/><input type="hidden" name="meetingLon" value="${has ? a.meetingLon : ''}"/>
    <div class="fs-meet-tools">
      <button type="button" class="btn secondary" data-act="meet-search">${fsIconHtml('search')} Ort suchen</button>
      <button type="button" class="btn secondary" data-act="meet-map">${fsIconHtml('pin')} Auf Karte</button>
      <span class="fs-meet-status">${has ? '✓ Ort gesetzt' : 'Ort für die Anfahrt-Route'}</span>
      ${has ? `<button type="button" class="fs-meet-clear" data-act="meet-clear" title="Ort entfernen">×</button>` : ''}
    </div>
    <div class="fs-meet-results"></div>
    <div class="fs-meet-map" hidden></div>`;
}
function fsMeetSet(box, lat, lon, label){
  box.querySelector('input[name="meetingLat"]').value = lat == null ? '' : lat.toFixed(5);
  box.querySelector('input[name="meetingLon"]').value = lon == null ? '' : lon.toFixed(5);
  const st = box.querySelector('.fs-meet-status');
  st.textContent = lat == null ? 'Ort für die Anfahrt-Route' : '✓ ' + (label || 'Ort gesetzt');
  let clr = box.querySelector('.fs-meet-clear');
  if(lat != null && !clr){ clr = document.createElement('button'); clr.type = 'button'; clr.className = 'fs-meet-clear'; clr.setAttribute('data-act', 'meet-clear'); clr.title = 'Ort entfernen'; clr.textContent = '×'; st.after(clr); }
  if(lat == null && clr) clr.remove();
  if(box._meetMap){
    if(box._meetMarker){ box._meetMarker.remove(); box._meetMarker = null; }
    if(lat != null) box._meetMarker = new maplibregl.Marker({color:'#B5652D'}).setLngLat([lon, lat]).addTo(box._meetMap);
  }
  if(typeof markModalDirty === 'function') markModalDirty();
}
async function fsMeetSearch(box){
  const res = box.querySelector('.fs-meet-results');
  // Uhrzeit ("06:30") aus dem Freitext weglassen, sonst findet die Suche nichts
  const q = (box.querySelector('input[name="meetingPoint"]').value || '').replace(/\b\d{1,2}[:.]\d{2}\b/g, '').replace(/\s+/g, ' ').trim();
  if(!q){ res.innerHTML = '<p class="fs-meet-hint">Zuerst einen Ort ins Feld schreiben, z. B. «Bahnhof Thun».</p>'; return; }
  res.innerHTML = '<p class="fs-meet-hint">Suche …</p>';
  try{
    const r = await fetch('https://api3.geo.admin.ch/rest/services/ech/SearchServer?type=locations&sr=4326&limit=6&searchText=' + encodeURIComponent(q));
    const d = await r.json();
    const hits = (d.results || []).map(x=> x.attrs).filter(x=> x && x.lat != null && x.lon != null);
    if(!hits.length){ res.innerHTML = '<p class="fs-meet-hint">Nichts gefunden — anders schreiben oder auf der Karte setzen.</p>'; return; }
    res.innerHTML = hits.map((h, i)=> `<button type="button" class="fs-meet-hit" data-act="meet-pick" data-lat="${h.lat}" data-lon="${h.lon}">${esc(String(h.label || '').replace(/<[^>]*>/g, ''))}</button>`).join('');
  }catch(e){ res.innerHTML = '<p class="fs-meet-hint">Suche nicht erreichbar (offline?).</p>'; }
}
async function fsMeetMap(box){
  const el = box.querySelector('.fs-meet-map');
  if(!el.hidden){ el.hidden = true; return; }
  el.hidden = false;
  if(box._meetMap) return;
  try{ await fsmEnsureLoaded(); }catch(e){ el.innerHTML = '<p class="fs-meet-hint">Karte nicht verfügbar.</p>'; return; }
  const lat = parseFloat(box.querySelector('input[name="meetingLat"]').value), lon = parseFloat(box.querySelector('input[name="meetingLon"]').value);
  const has = !isNaN(lat) && !isNaN(lon);
  const map = fsmCreateMap(el, {center: has ? [lat, lon] : [46.8, 8.2], zoom: has ? 13 : 7});
  box._meetMap = map;
  if(has) box._meetMarker = new maplibregl.Marker({color:'#B5652D'}).setLngLat([lon, lat]).addTo(map);
  map.on('click', e=> fsMeetSet(box, e.lngLat.lat, e.lngLat.lng, 'auf der Karte gesetzt'));
}
document.addEventListener('click', (e)=>{
  const b = e.target.closest && e.target.closest('[data-act^="meet-"]');
  if(!b) return;
  const box = b.closest('.fs-meet');
  if(!box) return;
  e.preventDefault(); e.stopPropagation();
  const act = b.getAttribute('data-act');
  if(act === 'meet-search') fsMeetSearch(box);
  else if(act === 'meet-map') fsMeetMap(box);
  else if(act === 'meet-clear') fsMeetSet(box, null, null);
  else if(act === 'meet-pick'){
    const lat = parseFloat(b.getAttribute('data-lat')), lon = parseFloat(b.getAttribute('data-lon'));
    fsMeetSet(box, lat, lon, b.textContent);
    box.querySelector('.fs-meet-results').innerHTML = '';
    if(box._meetMap) box._meetMap.jumpTo({center:[lon, lat], zoom: 14});
  }
}, true);

// Link zur Tourbeschreibung (SAC, Camptocamp, Hikr …) direkt in der Tourenansicht, mit Quelle
function fsTourLinkChipHtml(url){
  if(!url) return '';
  let host = ''; try{ host = new URL(url).hostname.replace(/^www\./, ''); }catch(e){}
  return `<a class="hut-link-chip fs-tourlink" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${fsIconHtml('link')}<span>Tourbeschreibung${host ? ' · ' + esc(host) : ''}</span> ↗</a>`;
}
/* ===== Weitere Links: nie einen Link durch einen neuen ersetzen =====
   t.moreLinks: zusätzliche Links (Tourbeschreibungen, GPX). Kommt ein zweiter Link dazu oder wird
   der Link im Formular geändert, bleibt der bisherige hier erhalten. */
function fsMoreLinksList(t){ return (t && Array.isArray(t.moreLinks)) ? t.moreLinks.filter(u=> typeof u === 'string' && u.trim()) : []; }
function fsAddLink(t, field, url){
  url = (url || '').trim();
  if(!url) return;
  if(!t[field]){ t[field] = url; return; }
  if([t.tourLink, t.gpxLink].concat(fsMoreLinksList(t)).includes(url)) return;
  t.moreLinks = fsMoreLinksList(t).concat(url);
}
// Beim Speichern eines Formulars: geänderte Links nicht verlieren, weitere Links übernehmen
function fsApplyLinksFromForm(t, form, existing){
  if(form.moreLinks !== undefined){ try{ t.moreLinks = JSON.parse(form.moreLinks || '[]').filter(u=> typeof u === 'string' && u.trim()).map(u=> u.trim()); }catch(e){} }
  ['tourLink', 'gpxLink'].forEach(f=>{
    const old = existing && existing[f] ? String(existing[f]).trim() : '';
    if(old && (t[f] || '').trim() !== old && ![t.tourLink, t.gpxLink].concat(fsMoreLinksList(t)).includes(old)) t.moreLinks = fsMoreLinksList(t).concat(old);
  });
  t.moreLinks = Array.from(new Set(fsMoreLinksList(t)));
}
function fsMoreLinksChipsHtml(t){
  return fsMoreLinksList(t).map(u=>{
    let host = ''; try{ host = new URL(u).hostname.replace(/^www\./, ''); }catch(e){}
    return `<a class="hut-link-chip fs-tourlink" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${fsIconHtml('link')}<span>${/\.gpx(\?|$)/i.test(u) ? 'GPX' : 'Link'}${host ? ' · ' + esc(host) : ''}</span> ↗</a>`;
  }).join('');
}
function fsMoreLinksFieldHtml(t){
  const list = fsMoreLinksList(t);
  return `<div class="field fs-more-links"><label>Weitere Links</label>
    <input type="hidden" name="moreLinks" class="fs-more-links-hidden" value='${esc(JSON.stringify(list))}'/>
    <div class="fs-more-links-list">${list.map(u=> fsMoreLinkRowHtml(u)).join('')}</div>
    <button type="button" class="btn secondary" data-fs-add-link onclick="fsAddLinkRow(this)">+ Weiteren Link</button>
    <div class="hint">Ein geänderter Link bleibt hier erhalten — nichts geht verloren.</div></div>`;
}
function fsMoreLinkRowHtml(u){
  return `<div class="fs-more-link-row"><input type="url" class="fs-more-link" value="${esc(u || '')}" placeholder="https://…" oninput="fsMoreLinkInput(this)"/><button type="button" class="fs-icon-btn" data-fs-del-link onclick="fsDelLinkRow(this)" aria-label="Link entfernen">${fsIconHtml('trash')}</button></div>`;
}
function fsSyncMoreLinks(box){
  const hid = box.querySelector('.fs-more-links-hidden');
  if(hid) hid.value = JSON.stringify(Array.from(box.querySelectorAll('.fs-more-link')).map(i=> i.value.trim()).filter(Boolean));
}
// Direkt am Element verdrahtet (die Maske hält Klicks vom document fern)
function fsAddLinkRow(btn){
  const box = btn.closest('.fs-more-links');
  box.querySelector('.fs-more-links-list').insertAdjacentHTML('beforeend', fsMoreLinkRowHtml(''));
  const ins = box.querySelectorAll('.fs-more-link'); ins[ins.length - 1].focus();
}
function fsDelLinkRow(btn){
  const box = btn.closest('.fs-more-links'), row = btn.closest('.fs-more-link-row');
  if(row.querySelector('.fs-more-link').value.trim() && !confirm('Diesen Link entfernen?')) return;
  row.remove(); fsSyncMoreLinks(box); if(typeof markModalDirty === 'function') markModalDirty();
}
function fsMoreLinkInput(inp){ fsSyncMoreLinks(inp.closest('.fs-more-links')); if(typeof markModalDirty === 'function') markModalDirty(); }
function fsMenuItemHtml(icon, label, attrs, href){
  if(href) return `<a class="fs-more-item" href="${esc(href)}" target="_blank" rel="noopener noreferrer">${fsIconHtml(icon)}<span>${label}</span></a>`;
  return `<button type="button" class="fs-more-item" ${attrs}>${fsIconHtml(icon)}<span>${label}</span></button>`;
}
function tourHasMapData(t){
  return !!((t.points && t.points.length) || t.trackSimplified || (t.manualTrack && t.manualTrack.length) || (t.altTracks && t.altTracks.length));
}
/* ===== Orte: gemeinsame Orte für alle Apps (Parkplatz, Maut, Biwak …) =====
   Sammlung «orte/<id>», von Skitour, Hochtour/Klettern und Wandern gemeinsam genutzt. Eine Tour
   verweist mit «orte: [id, …]» darauf. Jeder Ort hat ein Stand-Datum (beim Ändern automatisch heute,
   von Hand änderbar). Gespeichert wird über fbSet (Zusammenführen, alte Fassung unter versions/). */
const FS_ORT_KINDS = [
  {key:'parkplatz', label:'Parkplatz', icon:'parking'},
  {key:'maut', label:'Maut / Fahrverbot', short:'Maut', icon:'barrier'},
  {key:'haltestelle', label:'Haltestelle', icon:'bus'},
  {key:'biwak', label:'Biwak', icon:'tent'},
  {key:'wasser', label:'Wasser', icon:'drop'},
  {key:'toilette', label:'Toilette', icon:'wc'},
  {key:'einstieg', label:'Einstieg', icon:'entry'},
  {key:'ausstieg', label:'Ausstieg', icon:'exit'},
  {key:'gipfel', label:'Gipfel', icon:'mountain'},
  {key:'gefahr', label:'Gefahr', icon:'alert'},
  {key:'rast', label:'Rast', icon:'food'},
  {key:'abzweigung', label:'Abzweigung', icon:'compass'},
  {key:'rueckzug', label:'Rückzug', icon:'undo'},
  {key:'', label:'Anderer Ort', icon:'pin'}
];
const FS_ORTE_PATH = 'orte';
const FS_ORT_NEAR_KM = 5;
function fsOrtKind(k){ return FS_ORT_KINDS.find(x=> x.key === (k || '')) || FS_ORT_KINDS[FS_ORT_KINDS.length - 1]; }
function fsToday(){ const d = new Date(); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }
function fsOrteCacheKey(){ return (location.pathname.indexOf('/beta/') >= 0 ? 'firnspurbeta' : 'firnspur') + '-orte'; }
function fsOrteRaw(){ return (typeof state !== 'undefined' && state.orte) || []; } // inkl. offline gelöschter, noch nicht hochgeladener
function fsOrteAll(){ return fsOrteRaw().filter(o=> o && !o.deletedAt); }
function fsOrtById(id){ return fsOrteAll().find(o=> o.id === id) || null; }
// Gerätespeicher voll (oder gesperrt): einmal pro Sitzung sagen, dass Offline-Kopie fehlt
let fsStorageWarned = false;
function fsWarnStorageFull(e){
  if(fsStorageWarned) return;
  fsStorageWarned = true;
  if(typeof dlog === 'function') dlog('Gerätespeicher: ' + (e && (e.name + ' ' + e.message)), 'err');
  if(typeof showToast === 'function') setTimeout(()=> showToast('Gerätespeicher voll: Die Offline-Kopie konnte nicht gesichert werden. Gespeichert wird nur mit Internet.', true), 300);
}
// Der Speicher wird von allen drei Apps geteilt: noch nicht hochgeladene Orte einer anderen App behalten
function fsOrteCacheWrite(){
  try{
    const mine = fsOrteRaw(), ids = new Set(mine.map(o=> o && o.id));
    const others = fsOrteCacheRead().filter(o=> o && o._unsynced && !ids.has(o.id));
    localStorage.setItem(fsOrteCacheKey(), JSON.stringify(others.concat(mine)));
  }catch(e){ if(typeof dlog === 'function') dlog('Orte nicht im Gerät gesichert: ' + (e && e.message), 'err'); if(typeof fsWarnStorageFull === 'function') fsWarnStorageFull(e); }
}
function fsOrteCacheRead(){ try{ return JSON.parse(localStorage.getItem(fsOrteCacheKey()) || '[]') || []; }catch(e){ return []; } }
async function fsOrteLoad(){
  const cached = fsOrteCacheRead();
  if(!state.orte) state.orte = cached;
  const obj = await fbGet(FS_ORTE_PATH);
  // Offline oder leer: Gerätespeicher behalten; seine Fassung gilt als Ausgangsstand für Änderungen
  if(obj === null){ fsRememberCachedBases(FS_ORTE_PATH, state.orte); return; }
  const list = Object.values(obj || {}).filter(o=> o && o.id && !o.deletedAt);
  const unsynced = dedupeById([...state.orte.filter(o=> o._unsynced), ...cached.filter(o=> o._unsynced)]).filter(o=> fsKeepUnsynced(o, list, FS_ORTE_PATH));
  state.orte = [...unsynced, ...list];
  fsOrteCacheWrite();
  if(typeof render === 'function') render();
  fsmOrteRefresh();
  unsynced.forEach(o=> fsOrtPush(o));
}
async function fsOrtPush(o){
  // Direkt das Objekt speichern (lokale _-Felder gehen nicht mit): so kommt die zusammengeführte Fassung
  // samt Änderungen anderer zurück und gilt beim nächsten Speichern als Ausgangsstand
  const ok = await fbSet(FS_ORTE_PATH + '/' + o.id, o).catch(()=> false);
  o._unsynced = !ok;
  fsOrteCacheWrite();
  return ok;
}
async function fsOrtSave(o){
  if(!o || !String(o.name || '').trim()) return false;
  o.updatedAt = new Date().toISOString();
  o.updatedBy = state.myName || '';
  const list = fsOrteRaw().slice();
  const i = list.findIndex(x=> x.id === o.id);
  if(i >= 0) list[i] = o; else list.unshift(o);
  state.orte = list;
  o._unsynced = true;
  fsOrteCacheWrite();
  const ok = await fsOrtPush(o);
  if(typeof render === 'function') render();
  fsmOrteRefresh();
  showToast(ok ? 'Ort gespeichert.' : 'Ort lokal gespeichert, wird später hochgeladen.', !ok);
  return ok;
}
async function fsOrtDelete(o){
  if(!confirm('Ort «' + o.name + '» löschen? Er verschwindet bei allen Touren.')) return false;
  o.deletedAt = new Date().toISOString();
  o.updatedBy = state.myName || '';
  const ok = await fsOrtPush(o);
  // Offline: als gelöscht und «noch nicht hochgeladen» behalten (ausgeblendet), sonst käme er beim Laden zurück
  if(ok) state.orte = fsOrteRaw().filter(x=> x.id !== o.id);
  fsOrteCacheWrite();
  if(typeof render === 'function') render();
  fsmOrteRefresh();
  showToast(ok ? 'Ort gelöscht.' : 'Löschen nicht synchronisiert (Internet?).', !ok);
  return ok;
}
// Touren dieser App, die einen Ort nutzen
function fsOrtTours(id){ return (state.tours || []).filter(t=> Array.isArray(t.orte) && t.orte.indexOf(id) >= 0); }
function fsTourOrte(t){ return (Array.isArray(t.orte) ? t.orte : []).map(fsOrtById).filter(Boolean); }
function fsKm(a, b){
  const R = 6371, r = Math.PI / 180;
  const dLat = (b.lat - a.lat) * r, dLon = (b.lon - a.lon) * r;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * r) * Math.cos(b.lat * r) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}
// Bezugspunkte einer Tour: Punkte, sonst Anfang der Linie
function fsTourAnchors(t){
  const pts = (t.points || []).filter(p=> isFinite(p.lat) && isFinite(p.lon)).map(p=> ({lat:+p.lat, lon:+p.lon}));
  const line = (t.trackSimplified && t.trackSimplified.length) ? t.trackSimplified : (t.manualTrack || []);
  if(line.length){ const a = line[0], z = line[line.length - 1]; [a, z].forEach(q=>{ const lat = Array.isArray(q) ? q[0] : q.lat, lon = Array.isArray(q) ? q[1] : (q.lon != null ? q.lon : q.lng); if(isFinite(lat) && isFinite(lon)) pts.push({lat:+lat, lon:+lon}); }); }
  return pts;
}
function fsOrteNear(t, km){
  const anchors = fsTourAnchors(t);
  const linked = Array.isArray(t.orte) ? t.orte : [];
  return fsOrteAll().filter(o=> linked.indexOf(o.id) < 0 && isFinite(o.lat) && isFinite(o.lon))
    .map(o=> ({o, d: anchors.length ? Math.min(...anchors.map(a=> fsKm(a, o))) : Infinity}))
    .filter(x=> x.d <= (km || FS_ORT_NEAR_KM)).sort((a, b)=> a.d - b.d).map(x=> x.o);
}
function fsStandText(o){
  if(!o.stand) return '';
  const m = /^(\d{4})-(\d{2})/.exec(o.stand);
  return m ? 'Stand ' + m[2] + '/' + m[1] : 'Stand ' + o.stand;
}
function fsOrtSubline(o, tourId){
  const others = fsOrtTours(o.id).filter(t=> t.id !== tourId).length;
  return [fsOrtKind(o.kind).label, fsStandText(o), others ? 'auch bei ' + others + (others === 1 ? ' weiteren Tour' : ' weiteren Touren') : ''].filter(Boolean).join(' · ');
}
function fsOrtRowHtml(o, tourId, act){
  return `<button type="button" class="fs-ort-row" data-act="${act || 'fs-ort-open'}" data-ort="${esc(o.id)}" data-tour="${esc(tourId || '')}">
    <span class="fs-ort-ic">${fsIconHtml(fsOrtKind(o.kind).icon)}</span>
    <span class="fs-ort-tx"><b>${esc(o.name)}</b><small>${esc(fsOrtSubline(o, tourId))}</small></span>
    ${o._unsynced ? `<span class="fs-ort-flag" title="Noch nicht hochgeladen">${fsIconHtml('offline')}</span>` : ''}
  </button>`;
}
// Abschnitt «Orte» in der Tourenansicht: gemeinsame Orte oben, Knopf zum Verknüpfen im Bearbeiten-Modus
function fsTourOrteHtml(t){
  const list = fsTourOrte(t);
  return `<div class="fs-orte">
    ${list.map(o=> fsOrtRowHtml(o, t.id)).join('')}
    <button type="button" class="btn secondary fs-ort-addbtn" data-act="fs-ort-link" data-id="${esc(t.id)}">${fsIconHtml('plus')}Ort verknüpfen oder neu erfassen</button>
  </div>`;
}
async function fsTourSetOrte(t, ids){
  t.orte = ids;
  t.updatedAt = new Date().toISOString();
  t.updatedBy = state.myName;
  const ok = await saveTourCloud(t).catch(()=> false);
  t._unsynced = !ok;
  if(typeof render === 'function') render();
  return ok;
}
function fsSheet(html, onClose){
  const ov = document.createElement('div');
  ov.className = 'fs-cond-sheet fs-ort-sheet';
  ov.innerHTML = `<div class="in" role="dialog">${html}</div>`;
  document.body.appendChild(ov);
  // Eingaben gemacht: vor dem Schliessen ohne Speichern nachfragen
  ov.addEventListener('input', ()=>{ ov._dirty = true; });
  const tryClose = ()=>{ if(ov._dirty && !ov._saved){ if(!confirm('Eingaben verwerfen?')) return; if(ov._onDiscard) ov._onDiscard(); } closeTopOverlayLayer(); };
  ov.addEventListener('click', e=>{ if(e.target === ov) tryClose(); });
  ov.querySelectorAll('[data-close]').forEach(b=> b.addEventListener('click', tryClose));
  pushOverlayLayer(()=>{ ov.remove(); if(onClose) onClose(); });
  return ov;
}
// Ort ansehen (aus der Tour oder später von der Karte)
function fsOpenOrt(id, tourId){
  const o = fsOrtById(id);
  if(!o) return;
  const k = fsOrtKind(o.kind);
  const tours = fsOrtTours(o.id);
  const t = tourId ? (state.tours || []).find(x=> x.id === tourId) : null;
  const ov = fsSheet(`<button type="button" class="x-btn" data-close aria-label="Schliessen">×</button>
    <p class="fs-ort-kind">${fsIconHtml(k.icon)}${esc(k.label)}</p>
    <h3 class="fs-td-h">${esc(o.name)}</h3>
    ${o.stand ? `<p class="fs-ort-stand">Stand ${esc(fmtDateOnly(o.stand))}${o.updatedBy ? ' · ' + esc(o.updatedBy) : ''}</p>` : ''}
    ${o.photo && o.photo.url ? `<img class="fs-ort-photo" src="${esc(o.photo.url)}" alt="">` : ''}
    ${o.note ? `<p class="fs-ort-note">${esc(o.note)}</p>` : ''}
    <div class="fs-ort-btns">
      ${isFinite(o.lat) ? `<a class="btn secondary" href="https://www.google.com/maps/dir/?api=1&destination=${o.lat},${o.lon}" target="_blank" rel="noopener noreferrer">${fsIconHtml('car')}Navigieren</a>` : ''}
      ${isFinite(o.lat) ? `<button type="button" class="btn secondary" data-ort-cond>${fsIconHtml('partly')}Bedingungen</button>` : ''}
    </div>
    ${tours.length ? `<h4 class="fs-ort-h4">Genutzt von</h4><div class="fs-ort-tours">${tours.map(x=> `<button type="button" data-ort-tour="${esc(x.id)}">${esc(x.name)}${x.routeName ? ' – ' + esc(x.routeName) : ''}</button>`).join('')}</div>` : ''}
    <div class="fs-ort-btns fs-ort-edit">
      <button type="button" class="btn secondary" data-act="fs-ort-edit">Bearbeiten</button>
      ${t ? `<button type="button" class="btn secondary" data-act="fs-ort-unlink">Von Tour lösen</button>` : ''}
      <button type="button" class="btn secondary danger" data-act="fs-ort-delete">Löschen</button>
    </div>`);
  const q = s=> ov.querySelector(s);
  if(q('[data-ort-cond]')) q('[data-ort-cond]').addEventListener('click', ()=> fsOpenConditions(o.lat, o.lon, o.ele, o.name));
  ov.querySelectorAll('[data-ort-tour]').forEach(b=> b.addEventListener('click', ()=>{
    closeTopOverlayLayer();
    state.modal = {type:'tour-detail', payload: b.getAttribute('data-ort-tour')}; render();
  }));
  q('[data-act="fs-ort-edit"]').addEventListener('click', ()=>{ closeTopOverlayLayer(); fsOpenOrtForm(Object.assign({}, o)); });
  if(q('[data-act="fs-ort-unlink"]')) q('[data-act="fs-ort-unlink"]').addEventListener('click', async ()=>{
    closeTopOverlayLayer();
    await fsTourSetOrte(t, (t.orte || []).filter(x=> x !== o.id));
    showToast('Ort von der Tour gelöst.');
  });
  q('[data-act="fs-ort-delete"]').addEventListener('click', async ()=>{
    if(await fsOrtDelete(o)) closeTopOverlayLayer();
  });
}
// Verknüpfen: Orte in der Nähe, Tourpunkte übernehmen, neuen Ort erfassen
function fsOpenOrtLink(tourId){
  const t = (state.tours || []).find(x=> x.id === tourId);
  if(!t) return;
  const near = fsOrteNear(t);
  const pts = (t.points || []).map((p, i)=> ({p, i})).filter(x=> isFinite(x.p.lat) && isFinite(x.p.lon));
  const ov = fsSheet(`<button type="button" class="x-btn" data-close aria-label="Schliessen">×</button>
    <h3 class="fs-td-h">Ort verknüpfen</h3>
    <h4 class="fs-ort-h4">In der Nähe (bis ${FS_ORT_NEAR_KM} km)</h4>
    ${near.length ? near.map(o=> fsOrtRowHtml(o, tourId, 'fs-ort-pick')).join('') : `<p class="fs-ort-empty">Noch keine gemeinsamen Orte in der Nähe.</p>`}
    ${pts.length ? `<h4 class="fs-ort-h4">Tourpunkt zum gemeinsamen Ort machen</h4>
      ${pts.map(({p, i})=> `<button type="button" class="fs-ort-row" data-pt="${i}"><span class="fs-ort-ic">${fsIconHtml(fsOrtKind(MAP_POINT_TO_ORT[p.category || ''] || '').icon)}</span><span class="fs-ort-tx"><b>${esc(p.label || 'Punkt')}</b><small>${esc((MAP_POINT_CATEGORIES[p.category || ''] || MAP_POINT_CATEGORIES['']).label)}</small></span></button>`).join('')}` : ''}
    <button type="button" class="btn fs-ort-new">${fsIconHtml('plus')}Neuen Ort erfassen</button>`);
  ov.querySelectorAll('[data-act="fs-ort-pick"]').forEach(b=> b.addEventListener('click', async ()=>{
    closeTopOverlayLayer();
    await fsTourSetOrte(t, [...(t.orte || []), b.getAttribute('data-ort')]);
    showToast('Ort verknüpft.');
  }));
  ov.querySelectorAll('[data-pt]').forEach(b=> b.addEventListener('click', ()=>{
    const i = +b.getAttribute('data-pt'), p = t.points[i];
    closeTopOverlayLayer();
    fsOpenOrtForm({id: uid('o'), name: p.label || '', kind: MAP_POINT_TO_ORT[p.category || ''] || '', lat: +p.lat, lon: +p.lon, note: p.note || ''}, async (o)=>{
      // Punkt wird zum Ort: aus den Tourpunkten nehmen, damit er nicht doppelt erscheint
      t.points = (t.points || []).filter((_, j)=> j !== i);
      await fsTourSetOrte(t, [...(t.orte || []), o.id]);
    });
  }));
  ov.querySelector('.fs-ort-new').addEventListener('click', ()=>{
    closeTopOverlayLayer();
    const a = fsTourAnchors(t)[0] || {};
    fsOpenOrtForm({id: uid('o'), name: '', kind: '', lat: a.lat, lon: a.lon}, async (o)=>{ await fsTourSetOrte(t, [...(t.orte || []), o.id]); });
  });
}
const MAP_POINT_TO_ORT = {parkplatz:'parkplatz', haltestelle:'haltestelle', biwak:'biwak', wasser:'wasser', toilette:'toilette', gipfel:'gipfel', gefahr:'gefahr', rast:'rast', abzweigung:'abzweigung', rueckzug:'rueckzug'};
// Formular: Art, Name, Notiz, Stand, Position, Foto
function fsOpenOrtForm(o, onSaved){
  const isNew = !fsOrtById(o.id);
  const before = JSON.stringify([o.name, o.kind, o.note, o.lat, o.lon, o.photo && o.photo.url]);
  let standTouched = false;
  const ov = fsSheet(`<button type="button" class="x-btn" data-close aria-label="Schliessen">×</button>
    <h3 class="fs-td-h">${isNew ? 'Neuer Ort' : 'Ort bearbeiten'}</h3>
    <label class="fs-ort-lbl">Art</label>
    <div class="fs-ort-kinds">${FS_ORT_KINDS.map(k=> `<button type="button" data-kind="${k.key}" class="${(o.kind || '') === k.key ? 'on' : ''}" aria-pressed="${(o.kind || '') === k.key}">${fsIconHtml(k.icon)}<span>${esc(k.short || k.label)}</span></button>`).join('')}</div>
    <label class="fs-ort-lbl" for="fs-ort-name">Name</label>
    <input id="fs-ort-name" type="text" value="${esc(o.name || '')}" placeholder="z. B. Parkplatz Engstlenalp" autocomplete="off">
    <label class="fs-ort-lbl" for="fs-ort-note">Notiz</label>
    <textarea id="fs-ort-note" rows="3" placeholder="Gebühr, Öffnungszeiten, Zufahrt …">${esc(o.note || '')}</textarea>
    <label class="fs-ort-lbl" for="fs-ort-stand">Stand</label>
    <input id="fs-ort-stand" type="date" value="${esc(o.stand || fsToday())}">
    <label class="fs-ort-lbl">Position</label>
    <div class="fs-ort-pos"><span data-pos>${isFinite(o.lat) ? (+o.lat).toFixed(5) + ', ' + (+o.lon).toFixed(5) : 'noch keine'}</span>
      <button type="button" class="btn secondary" data-gps>${fsIconHtml('gps')}Mein Standort</button></div>
    <label class="fs-ort-lbl">Foto</label>
    <div class="fs-ort-photo-row"><span data-photo>${o.photo && o.photo.url ? `<img src="${esc(o.photo.url)}" alt="">` : ''}</span>
      <label class="btn secondary">${fsIconHtml('camera')}${o.photo && o.photo.url ? 'Foto ersetzen' : 'Foto wählen'}<input type="file" accept="image/*" hidden data-file></label></div>
    <p class="fs-ort-msg" data-msg></p>
    <div class="fs-ort-btns"><button type="button" class="btn secondary" data-close>Abbrechen</button><button type="button" class="btn" data-save>Speichern</button></div>`);
  const q = s=> ov.querySelector(s);
  ov.querySelectorAll('[data-kind]').forEach(b=> b.addEventListener('click', ()=>{
    o.kind = b.getAttribute('data-kind');
    ov.querySelectorAll('[data-kind]').forEach(x=>{ const on = x === b; x.classList.toggle('on', on); x.setAttribute('aria-pressed', on); });
    const nameEl = q('#fs-ort-name');
    if(!nameEl.value.trim() && o.kind) nameEl.placeholder = fsOrtKind(o.kind).label + ' …';
  }));
  q('#fs-ort-stand').addEventListener('input', ()=>{ standTouched = true; });
  q('[data-gps]').addEventListener('click', ()=>{
    if(!navigator.geolocation){ q('[data-msg]').textContent = 'Standort nicht verfügbar.'; return; }
    q('[data-msg]').textContent = 'Standort wird bestimmt …';
    navigator.geolocation.getCurrentPosition(pos=>{
      o.lat = +pos.coords.latitude.toFixed(6); o.lon = +pos.coords.longitude.toFixed(6);
      q('[data-pos]').textContent = o.lat.toFixed(5) + ', ' + o.lon.toFixed(5);
      q('[data-msg]').textContent = '';
    }, ()=>{ q('[data-msg]').textContent = 'Standort konnte nicht bestimmt werden.'; }, {enableHighAccuracy:true, timeout:15000});
  });
  q('[data-file]').addEventListener('change', async (e)=>{
    const f = e.target.files && e.target.files[0];
    if(!f) return;
    q('[data-msg]').textContent = 'Foto wird hochgeladen …';
    try{
      const blob = await compressImageFile(f, 1200, 0.78);
      const imgId = uid('img');
      const storagePath = `${TOPO_IMAGES_PATH}/${o.id}/${imgId}.jpg`;
      const url = await uploadTopoImageBlob(blob, storagePath);
      o.photo = {id: imgId, url, storagePath};
      q('[data-photo]').innerHTML = `<img src="${esc(url)}" alt="">`;
      q('[data-msg]').textContent = '';
    }catch(err){ q('[data-msg]').textContent = 'Foto konnte nicht hochgeladen werden (Internet?).'; }
  });
  q('[data-save]').addEventListener('click', async ()=>{
    o.name = q('#fs-ort-name').value.trim();
    o.note = q('#fs-ort-note').value.trim();
    if(!o.name){ q('[data-msg]').textContent = 'Bitte einen Namen eingeben.'; q('#fs-ort-name').focus(); return; }
    if(!isFinite(o.lat) || !isFinite(o.lon)){ q('[data-msg]').textContent = 'Bitte eine Position setzen (Mein Standort).'; return; }
    const changed = JSON.stringify([o.name, o.kind, o.note, o.lat, o.lon, o.photo && o.photo.url]) !== before;
    // Stand: von Hand gesetzt gilt; sonst beim Erfassen und bei jeder Änderung heute
    if(standTouched) o.stand = q('#fs-ort-stand').value || fsToday();
    else if(isNew || changed || !o.stand) o.stand = fsToday();
    if(isNew){ o.createdAt = new Date().toISOString(); o.createdBy = state.myName || ''; }
    closeTopOverlayLayer();
    await fsOrtSave(o);
    if(onSaved) await onSaved(o);
  });
  if(isNew) setTimeout(()=>{ try{ q('#fs-ort-name').focus(); }catch(e){} }, 50);
}
// Ebene «Orte» auf den Karten: ein Strich-Icon pro Ort, antippen öffnet das Blatt
const fsmOrteMaps = new Set();
function fsmOrteDraw(map){
  if(!map || !map._fsm || !window.maplibregl) return;
  (map._fsm.orteMk || []).forEach(m=> m.remove());
  map._fsm.orteMk = [];
  // Ebene an: alle Orte; sonst nur die Orte der gezeigten Tour (map._fsm.orteIds)
  const only = fsmOverlayOn(map, 'orte') ? null : (map._fsm.orteIds || []);
  if(only && !only.length) return;
  fsmOrteMaps.add(map);
  if(!map._fsOrteZoomWired){
    map._fsOrteZoomWired = true;
    const sync = ()=> map.getContainer().classList.toggle('fsm-ort-names', map.getZoom() >= 14);
    map.on('zoom', sync); sync();
  }
  fsOrteAll().filter(o=> !only || only.indexOf(o.id) >= 0).forEach(o=>{
    if(!isFinite(o.lat) || !isFinite(o.lon)) return;
    const k = fsOrtKind(o.kind);
    const el = document.createElement('button');
    el.type = 'button'; el.className = 'fsm-ort';
    el.setAttribute('aria-label', k.label + ': ' + o.name);
    el.innerHTML = fsIconHtml(k.icon) + `<span>${esc(o.name)}</span>`;
    el.addEventListener('click', (e)=>{ e.stopPropagation(); fsOpenOrt(o.id); });
    map._fsm.orteMk.push(new maplibregl.Marker({element: el, anchor: 'left', offset: [-13, 0]}).setLngLat([+o.lon, +o.lat]).addTo(map));
  });
}
function fsmOrteRefresh(){
  fsmOrteMaps.forEach(m=>{
    if(!m._fsm || !document.body.contains(m.getContainer())){ fsmOrteMaps.delete(m); return; }
    fsmOrteDraw(m);
  });
}
// Lange auf die Karte drücken (bzw. Rechtsklick): «Ort hier erfassen»
function fsmWireOrtHold(ml){
  if(!ml || ml._fsOrtHold) return;
  ml._fsOrtHold = true;
  const offer = (ll)=>{
    if(navigator.vibrate) try{ navigator.vibrate(25); }catch(e){}
    const wrap = document.createElement('div');
    wrap.className = 'fsm-ort-hold';
    wrap.innerHTML = `<button type="button">${fsIconHtml('plus')}Ort hier erfassen</button>`;
    wrap.querySelector('button').addEventListener('click', ()=>{
      if(ml._fsm && ml._fsm.popup) ml._fsm.popup.remove();
      fsOpenOrtForm({id: uid('o'), name: '', kind: '', lat: +ll.lat.toFixed(6), lon: +ll.lng.toFixed(6)});
    });
    fsmPopup(ml, ll, wrap, 8);
  };
  ml.on('contextmenu', (e)=>{ if(e.originalEvent && e.originalEvent._fsmHandled) return; offer(e.lngLat); });
  let timer = null, start = null;
  const cancel = ()=>{ if(timer){ clearTimeout(timer); timer = null; } };
  ml.on('touchstart', (e)=>{
    cancel();
    if(!e.originalEvent || e.originalEvent.touches.length !== 1) return;
    start = e.point; const ll = e.lngLat;
    timer = setTimeout(()=>{ timer = null; offer(ll); }, 650);
  });
  ml.on('touchmove', (e)=>{ if(start && Math.hypot(e.point.x - start.x, e.point.y - start.y) > 10) cancel(); });
  ['touchend', 'touchcancel', 'movestart', 'zoomstart'].forEach(ev=> ml.on(ev, cancel));
}
// Knöpfe in der Tourenansicht (Capture, weil das Dialogfenster Klicks sonst stoppt)
document.addEventListener('click', (e)=>{
  const el = e.target.closest && e.target.closest('[data-act="fs-ort-open"],[data-act="fs-ort-link"]');
  if(!el || el.closest('.fs-ort-sheet')) return;
  e.stopPropagation();
  if(el.getAttribute('data-act') === 'fs-ort-link') fsOpenOrtLink(el.getAttribute('data-id'));
  else fsOpenOrt(el.getAttribute('data-ort'), el.getAttribute('data-tour'));
}, true);

/* ===== Erfahrungen: Logbuch pro Tour =====
   Liste «erfahrungen» in der Tour: {id, by, date, at, text, photos}. Eine neue Erfahrung ist eine
   Ergänzung (darf jede/r direkt), die eigene darf man selbst entfernen; alles andere läuft über
   Eigentümer und Vorschläge (fsSafeSet). «In Beschreibung übernehmen» ändert ein Textfeld der Tour –
   beim Eigentümer direkt, sonst als Vorschlag. */
const FS_ERF_MAX_PHOTOS = 3;
function fsErfFields(){
  return [['special', 'Spezielles'], ['ascent', 'Aufstieg'], ['descent', fsAppKey() === 'firnspur' ? 'Abfahrt' : 'Abstieg'],
    ['crux', 'Schlüsselstelle'], ['approach', 'Anfahrt']];
}
function fsErfList(t){
  return (Array.isArray(t.erfahrungen) ? t.erfahrungen : []).filter(e=> e && e.id)
    .slice().sort((a, b)=> ((b.date || '') + (b.at || '')).localeCompare((a.date || '') + (a.at || '')));
}
function fsErfMine(e){ return !!(e && state.myName && fsNameKey(e.by) === fsNameKey(state.myName)); }
function fsErfEntryHtml(t, e){
  const photos = Array.isArray(e.photos) ? e.photos.filter(p=> p && p.url) : [];
  return `<article class="fs-erf">
    <header><b>${esc(e.by || '?')}</b><span>${esc(fmtDateOnly(e.date) || '')}</span></header>
    <p>${esc(e.text || '')}</p>
    ${photos.length ? topoImagesGalleryHtml(photos) : ''}
    <div class="fs-erf-acts">
      <button type="button" class="btn secondary" data-act="fs-erf-apply" data-id="${esc(t.id)}" data-erf="${esc(e.id)}" aria-label="In die Beschreibung übernehmen">In Text übernehmen</button>
      ${(fsErfMine(e) || fsCanEditDirect(t)) ? `<button type="button" class="btn secondary danger" data-act="fs-erf-delete" data-id="${esc(t.id)}" data-erf="${esc(e.id)}">Entfernen</button>` : ''}
    </div>
  </article>`;
}
// Abschnitt in der Tourenansicht; ohne Einträge nur im Bearbeiten-Modus sichtbar (editOnly)
function fsTourErfSection(t){
  const list = fsErfList(t);
  const html = `${list.map(e=> fsErfEntryHtml(t, e)).join('')}
    <button type="button" class="btn secondary fs-ort-addbtn" data-act="fs-nachtragen" data-id="${esc(t.id)}">${fsIconHtml('plus')}Nachtragen</button>`;
  return list.length ? html : {html, editOnly: true};
}
async function fsErfSaveTour(t, msg){
  t.updatedAt = new Date().toISOString();
  t.updatedBy = state.myName;
  const ok = await saveTourCloud(t).catch(()=> false);
  t._unsynced = !ok;
  if(!ok && typeof markUnsaved === 'function') markUnsaved();
  if(typeof render === 'function') render();
  showToast(ok ? msg : 'Lokal gespeichert, wird später hochgeladen.', !ok);
  return ok;
}
function fsErfMake(text, date, by, photos){
  return {id: uid('e'), by: (by || state.myName || '').trim(), date: date || fsToday(), at: new Date().toISOString(), text: String(text || '').trim(), photos: photos || []};
}
// «Nachtragen» nach der Tour, mit einem Tipp (kein Gedrückthalten): gemacht (Name + Datum), Erfahrung,
// Fotos, GPX. Alles sind Ergänzungen (neue Listeneinträge bzw. leere Linie füllen), dürfen also alle.
function fsOpenErfForm(tourId){ fsOpenNachtragen(tourId); }
function fsOpenNachtragen(tourId){
  const t = (state.tours || []).find(x=> x.id === tourId);
  if(!t) return;
  if(!state.myName && typeof ensureName === 'function'){ ensureName(()=> fsOpenNachtragen(tourId)); return; }
  const e = fsErfMake('', fsToday());
  let gpx = null; // {text, name, line}
  const ov = fsSheet(`<button type="button" class="x-btn" data-close aria-label="Schliessen">×</button>
    <h3 class="fs-td-h">Nachtragen</h3>
    <p class="fs-ort-stand">${esc(t.name)}${t.routeName ? ' – ' + esc(t.routeName) : ''}</p>
    <label class="fs-ort-lbl" for="fs-erf-date">Datum der Tour</label>
    <input id="fs-erf-date" type="date" value="${esc(e.date)}">
    <label class="fs-nt-done"><input type="checkbox" id="fs-nt-done" checked><span>Ich war dort – als gemacht eintragen (${esc(state.myName || '?')})</span></label>
    <label class="fs-ort-lbl" for="fs-erf-text">Was war anders, neu oder gut zu wissen? (optional)</label>
    <textarea id="fs-erf-text" rows="4" placeholder="z. B. Parkplatz neu gebührenpflichtig, Rinne bis Mitte Mai gut eingeschneit …"></textarea>
    <label class="fs-ort-lbl">Fotos (bis ${FS_ERF_MAX_PHOTOS})</label>
    <div class="fs-ort-photo-row"><span data-photos class="fs-erf-thumbs"></span>
      <label class="btn secondary">${fsIconHtml('camera')}Foto wählen<input type="file" accept="image/*" hidden data-file></label></div>
    <label class="fs-ort-lbl">GPX der Begehung (optional)</label>
    <div class="fs-ort-photo-row"><span data-gpx class="fs-nt-gpx"></span>
      <label class="btn secondary">${fsIconHtml('upload')}GPX wählen<input type="file" accept=".gpx,application/gpx+xml,application/xml,text/xml" hidden data-gpxfile></label></div>
    <p class="fs-ort-msg" data-msg></p>
    <div class="fs-ort-btns"><button type="button" class="btn secondary" data-close>Abbrechen</button><button type="button" class="btn" data-save>Speichern</button></div>`);
  const q = s=> ov.querySelector(s);
  const drawPhotos = ()=>{ q('[data-photos]').innerHTML = e.photos.map(p=> `<img src="${esc(p.url)}" alt="">`).join(''); };
  q('[data-file]').addEventListener('change', async (ev)=>{
    const f = ev.target.files && ev.target.files[0];
    ev.target.value = '';
    if(!f) return;
    if(e.photos.length >= FS_ERF_MAX_PHOTOS){ q('[data-msg]').textContent = 'Höchstens ' + FS_ERF_MAX_PHOTOS + ' Fotos.'; return; }
    q('[data-msg]').textContent = 'Foto wird hochgeladen …';
    try{
      const blob = await compressImageFile(f, 1200, 0.78);
      const imgId = uid('img');
      const storagePath = `${TOPO_IMAGES_PATH}/${t.id}/${imgId}.jpg`;
      const url = await uploadTopoImageBlob(blob, storagePath);
      e.photos.push({id: imgId, url, storagePath});
      ov._dirty = true;
      drawPhotos(); q('[data-msg]').textContent = '';
    }catch(err){ q('[data-msg]').textContent = 'Foto konnte nicht hochgeladen werden (Internet?).'; }
  });
  q('[data-gpxfile]').addEventListener('change', async (ev)=>{
    const f = ev.target.files && ev.target.files[0];
    ev.target.value = '';
    if(!f) return;
    try{
      const text = await f.text();
      const pts = parseGpxTrackPoints(text);
      if(pts.length < 2){ q('[data-msg]').textContent = 'In dieser Datei ist keine Linie.'; return; }
      const line = simplifyTrackForStorage(pts, 200).map(p=> [Math.round(p.lat * 1e6) / 1e6, Math.round(p.lon * 1e6) / 1e6]);
      gpx = {text, name: f.name.replace(/\.gpx$/i, ''), line};
      ov._dirty = true;
      q('[data-gpx]').textContent = f.name + ' · ' + pts.length + ' Punkte';
      q('[data-msg]').textContent = '';
    }catch(err){ q('[data-msg]').textContent = 'GPX-Datei konnte nicht gelesen werden.'; }
  });
  // Entwurf des Textes auf dem Gerät (übersteht beendeten Tab), beim Öffnen wieder einsetzen
  const dKey = 'fs-draft-erf:' + t.id;
  try{ const old = localStorage.getItem(dKey); if(old){ q('#fs-erf-text').value = old; ov._dirty = true; } }catch(err){}
  q('#fs-erf-text').addEventListener('input', ()=>{ try{ localStorage.setItem(dKey, q('#fs-erf-text').value); }catch(err){} });
  ov._onDiscard = ()=>{ try{ localStorage.removeItem(dKey); }catch(err){} };
  q('[data-save]').addEventListener('click', async ()=>{
    e.text = q('#fs-erf-text').value.trim();
    e.date = q('#fs-erf-date').value || fsToday();
    const done = q('#fs-nt-done').checked;
    if(!done && !e.text && !e.photos.length && !gpx){ q('[data-msg]').textContent = 'Bitte «gemacht» ankreuzen, etwas schreiben oder ein Foto oder GPX wählen.'; return; }
    ov._saved = true; try{ localStorage.removeItem(dKey); }catch(err){}
    closeTopOverlayLayer();
    const parts = [];
    if(done){
      t.completions = [...(Array.isArray(t.completions) ? t.completions : []), {by: state.myName, date: e.date}];
      if(!t.completed) t.completed = true;
      parts.push('gemacht am ' + fmtDateOnly(e.date));
    }
    if(e.text || e.photos.length){
      t.erfahrungen = [...(Array.isArray(t.erfahrungen) ? t.erfahrungen : []), e];
      parts.push(e.text ? 'Erfahrung' : (e.photos.length === 1 ? '1 Foto' : e.photos.length + ' Fotos'));
    }
    if(gpx){
      // Ohne Linie wird die GPX zur Route der Tour, sonst eine weitere Route (Variante)
      const name = gpx.name || ('GPX ' + state.myName + ' ' + fmtDateOnly(e.date));
      const file = {gpx: gpx.text, uploadedAt: new Date().toISOString(), fileName: (gpx.name || 'track') + '.gpx'};
      if(!(t.trackSimplified && t.trackSimplified.length) && !(t.manualTrack && t.manualTrack.length)){
        t.trackSimplified = gpx.line;
        fsQueueFile(GPX_TRACKS_PATH + '/' + t.id, file); // wird nach dem Speichern der Tour hochgeladen, bei Fehler erneut
        parts.push('GPX als Route');
      }else{
        const altId = 'alt_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
        t.altTracks = [...(Array.isArray(t.altTracks) ? t.altTracks : []), {id: altId, name, type: 'variante', trackSimplified: gpx.line}];
        fsQueueFile(GPX_TRACKS_PATH + 'Alt/' + t.id + '/' + altId, file);
        parts.push('GPX als weitere Route');
      }
    }
    await fsErfSaveTour(t, 'Nachgetragen: ' + parts.join(', ') + '.');
  });
}
// Erfahrung in ein Textfeld der Beschreibung übernehmen (vorgefüllt, anpassbar)
function fsOpenErfApply(tourId, erfId){
  const t = (state.tours || []).find(x=> x.id === tourId);
  const e = t && fsErfList(t).find(x=> x.id === erfId);
  if(!e) return;
  const fields = fsErfFields();
  const owner = fsCanEditDirect(t);
  const proposal = (k)=>{ const cur = String(t[k] || '').trim(); const add = e.text + ' (' + (e.by || '?') + ', ' + fmtDateOnly(e.date) + ')'; return cur ? cur + '\n\n' + add : add; };
  let field = fields[0][0];
  const ov = fsSheet(`<button type="button" class="x-btn" data-close aria-label="Schliessen">×</button>
    <h3 class="fs-td-h">In Beschreibung übernehmen</h3>
    <p class="fs-ort-stand">${owner ? 'Die Beschreibung wird direkt geändert.' : 'Wird als Vorschlag an den Eigentümer geschickt.'}</p>
    <label class="fs-ort-lbl">Feld</label>
    <div class="fs-erf-fields">${fields.map(([k, l], i)=> `<button type="button" data-field="${k}" class="${i ? '' : 'on'}" aria-pressed="${!i}">${esc(l)}</button>`).join('')}</div>
    <label class="fs-ort-lbl" for="fs-erf-ap">Neuer Text</label>
    <textarea id="fs-erf-ap" rows="8">${esc(proposal(field))}</textarea>
    <p class="fs-ort-msg" data-msg></p>
    <div class="fs-ort-btns"><button type="button" class="btn secondary" data-close>Abbrechen</button><button type="button" class="btn" data-save>${owner ? 'Übernehmen' : 'Vorschlagen'}</button></div>`);
  const q = s=> ov.querySelector(s);
  ov.querySelectorAll('[data-field]').forEach(b=> b.addEventListener('click', ()=>{
    field = b.getAttribute('data-field');
    ov.querySelectorAll('[data-field]').forEach(x=>{ const on = x === b; x.classList.toggle('on', on); x.setAttribute('aria-pressed', on); });
    q('#fs-erf-ap').value = proposal(field);
  }));
  q('[data-save]').addEventListener('click', async ()=>{
    const v = q('#fs-erf-ap').value.trim();
    if(v === String(t[field] || '').trim()){ q('[data-msg]').textContent = 'Der Text ist unverändert.'; return; }
    closeTopOverlayLayer();
    t[field] = v;
    await fsErfSaveTour(t, owner ? 'In die Beschreibung übernommen.' : 'Vorschlag gespeichert.');
  });
}
async function fsErfDelete(tourId, erfId){
  const t = (state.tours || []).find(x=> x.id === tourId);
  if(!t || !confirm('Diese Erfahrung entfernen?')) return;
  t.erfahrungen = (Array.isArray(t.erfahrungen) ? t.erfahrungen : []).filter(x=> x && x.id !== erfId);
  await fsErfSaveTour(t, 'Erfahrung entfernt.');
}
// «Als erledigt markieren»: optionales Feld, wird als Erfahrung gespeichert
function fsCompletionNoteFieldHtml(){
  return `<div class="field"><label for="fs-complete-note">Was war anders oder neu? (optional)</label>
    <textarea id="fs-complete-note" rows="3" placeholder="Wird als Erfahrung bei der Tour gespeichert"></textarea></div>`;
}
function fsCompletionNoteTake(t, by, date){
  const el = document.getElementById('fs-complete-note');
  const text = el ? el.value.trim() : '';
  if(!t || !text) return false;
  t.erfahrungen = [...(Array.isArray(t.erfahrungen) ? t.erfahrungen : []), fsErfMake(text, date, by)];
  return true;
}
document.addEventListener('click', (ev)=>{
  const el = ev.target.closest && ev.target.closest('[data-act="fs-erf-new"],[data-act="fs-nachtragen"],[data-act="fs-erf-apply"],[data-act="fs-erf-delete"]');
  if(!el) return;
  ev.stopPropagation();
  const act = el.getAttribute('data-act'), id = el.getAttribute('data-id'), erf = el.getAttribute('data-erf');
  if(act === 'fs-erf-new' || act === 'fs-nachtragen') fsOpenNachtragen(id);
  else if(act === 'fs-erf-apply') fsOpenErfApply(id, erf);
  else fsErfDelete(id, erf);
}, true);

/* ===== Datenprüfung: Sicherungen und Gerätekopie mit dem heutigen Stand vergleichen =====
   Die täglichen Sicherungen (backups/firnspur-JJJJ-MM-TT.json.gpg, verschlüsselt mit dem
   App-Passwort, siehe .github/workflows/backup.yml) werden NUR auf diesem Gerät entschlüsselt;
   das Passwort wird nicht gespeichert. Gezeigt wird pro Eintrag, was heute fehlt (Punkte, Routen,
   Fotos, Texte, ganze Einträge), mit der jüngsten Quelle, in der es noch vorhanden war.
   Zurückholen ergänzt nur (über fbSet, mit Version), überschreibt nichts. */
// Hütten liegen für alle Apps unter «huts» (fixseil/huts ist der alte, übernommene Bestand und wird nicht geprüft)
const FS_CHECK_COLLS = ['tours', 'huts', 'gebiete', 'orte', 'fixseil/tours', 'fixseil/sektoren', 'fixseil/klettergebiete',
  'fixseil/gipfel', 'wandern/tours', 'wandern/gebiete'];
const FS_CHECK_APP = {'tours':'Skitour', 'huts':'Hütte', 'gebiete':'Skitour · Gebiet', 'orte':'Ort',
  'fixseil/tours':'Hochtour/Klettern', 'fixseil/sektoren':'Klettern · Sektor', 'fixseil/klettergebiete':'Klettergebiet',
  'fixseil/gipfel':'Gipfel', 'fixseil/huts':'Hochtour · Hütte', 'wandern/tours':'Wandern', 'wandern/gebiete':'Wandern · Gebiet'};
const FS_CHECK_SKIP = new Set(['updatedAt', 'updatedBy', 'deletedAt', 'deletedBy', 'createdAt', 'createdBy', 'status', 'conditions',
  'completed', 'completedBy', 'completedDate', 'owner', 'editors', 'open', 'summitIdsParked']);
const FS_OPENPGP = 'https://unpkg.com/openpgp@5.11.2/dist/openpgp.min.js';
function fsCheckItemKey(x){
  if(x && typeof x === 'object'){
    if(x.id) return 'id:' + x.id;
    if(isFinite(x.lat) && isFinite(x.lon)) return 'pt:' + (+x.lat).toFixed(5) + ',' + (+x.lon).toFixed(5);
    if(x.url) return 'url:' + x.url;
  }
  return 'k:' + fsImportKey(x);
}
function fsCheckItemLabel(field, x){
  const f = FS_FIELD_LABELS[field] || field;
  if(!x || typeof x !== 'object'){
    // Verweis auf einen anderen Eintrag (z. B. Gipfel-ID): mit Namen anzeigen
    const sv = String(x);
    const ref = /^[a-z]+_[a-z0-9_]+$/i.test(sv) && typeof state !== 'undefined'
      ? [].concat(state.gipfel || [], state.tours || [], state.huts || [], state.sektoren || [], state.klettergebiete || [], state.gebiete || [], fsOrteAll()).find(o=> o && o.id === sv) : null;
    return f + ': ' + (ref ? (ref.name || sv) : sv);
  }
  if(field === 'points'){
    const cat = (MAP_POINT_CATEGORIES[x.category || ''] || MAP_POINT_CATEGORIES['']).label;
    return 'Punkt «' + (x.label || 'ohne Namen') + '»' + (x.category ? ' (' + cat + ')' : '');
  }
  if(field === 'completions') return 'Begehung ' + (x.by || '?') + (x.date ? ' · ' + fmtDateOnly(x.date) : '');
  if(field === 'erfahrungen') return 'Erfahrung ' + (x.by || '?') + (x.date ? ' · ' + fmtDateOnly(x.date) : '');
  if(field === 'topoImages') return 'Foto' + (x.name ? ' «' + x.name + '»' : '');
  return f + ' «' + (x.name || x.label || x.title || x.by || 'Eintrag') + '»';
}
// Was in «older» steht, in «newer» aber fehlt (pro Feld). Gemeinsame Grundlage für Datenprüfung
// und Versionsliste.
function fsCheckLosses(older, newer){
  const out = [];
  if(!older || typeof older !== 'object') return out;
  newer = newer || {};
  Object.keys(older).forEach(k=>{
    if(k[0] === '_' || FS_CHECK_SKIP.has(k)) return;
    const b = older[k], c = newer[k];
    if(fsCanon(b) === null) return;
    if(fsIsCoordList(b)){
      const n = Array.isArray(c) ? c.length : 0;
      if(n < b.length * 0.5) out.push({field:k, type:'line', value:b, label:(FS_FIELD_LABELS[k] || k) + (n ? ': von ' + b.length + ' auf ' + n + ' Punkte gekürzt' : ' fehlt (' + b.length + ' Punkte)'), safe: !n});
      return;
    }
    if(Array.isArray(b)){
      const have = new Set((Array.isArray(c) ? c : []).map(fsCheckItemKey));
      const haveLabels = new Set((Array.isArray(c) ? c : []).map(x=> x && typeof x === 'object' ? String(x.label || x.name || '').trim().toLowerCase() : '').filter(Boolean));
      b.forEach(x=>{
        if(have.has(fsCheckItemKey(x))) return;
        const lbl = x && typeof x === 'object' ? String(x.label || x.name || '').trim().toLowerCase() : '';
        const similar = !!lbl && haveLabels.has(lbl); // vermutlich nur verschoben/geändert
        out.push({field:k, type:'item', value:x, label: fsCheckItemLabel(k, x) + (similar ? ' – ähnlicher Eintrag ist noch da' : ''), safe: !similar});
      });
      return;
    }
    if(typeof b === 'string'){
      const cs = typeof c === 'string' ? c : '';
      if(!cs.trim()) out.push({field:k, type:'text', value:b, label:(FS_FIELD_LABELS[k] || k) + ' ist leer – vorher: «' + b.slice(0, 80) + (b.length > 80 ? '…' : '') + '»', safe:true});
      else if(b.length >= 40 && cs.length < b.length * 0.5) out.push({field:k, type:'text', value:b, label:(FS_FIELD_LABELS[k] || k) + ' stark gekürzt (' + b.length + ' → ' + cs.length + ' Zeichen) – vorher: «' + b.slice(0, 80) + '…»', safe:false});
      return;
    }
    if((c === undefined || c === null || c === '') && (typeof b === 'number' || typeof b === 'boolean')) out.push({field:k, type:'text', value:b, label:(FS_FIELD_LABELS[k] || k) + ' fehlt – vorher: ' + b, safe:true});
  });
  return out;
}
// Kurzbeschreibung der Änderungen zwischen zwei Fassungen (für die Versionsliste)
function fsCheckDiffText(older, newer){
  if(!older || !newer) return '';
  const lost = fsCheckLosses(older, newer), added = fsCheckLosses(newer, older);
  const parts = [];
  const lostPts = lost.filter(x=> x.field === 'points'), addPts = added.filter(x=> x.field === 'points');
  if(lostPts.length) parts.push('−' + lostPts.length + ' Punkte (' + lostPts.map(x=> (x.value && x.value.label) || '?').join(', ') + ')');
  if(addPts.length) parts.push('+' + addPts.length + ' Punkte');
  lost.filter(x=> x.field !== 'points').forEach(x=> parts.push('entfernt: ' + (x.type === 'item' ? fsCheckItemLabel(x.field, x.value) : (FS_FIELD_LABELS[x.field] || x.field))));
  added.filter(x=> x.field !== 'points' && x.type === 'item').forEach(x=> parts.push('neu: ' + fsCheckItemLabel(x.field, x.value)));
  const changed = Object.keys(Object.assign({}, older, newer)).filter(k=> k[0] !== '_' && !FS_CHECK_SKIP.has(k) && typeof (older[k] ?? newer[k]) === 'string' && String(older[k] || '') !== String(newer[k] || '') && !lost.some(l=> l.field === k) && !added.some(l=> l.field === k));
  if(changed.length) parts.push('geändert: ' + changed.map(k=> FS_FIELD_LABELS[k] || k).join(', '));
  return parts.join(' · ');
}
function fsCheckGet(obj, coll){ return coll.split('/').reduce((o, s)=> (o && typeof o === 'object') ? o[s] : undefined, obj); }
function fsCheckPagesRoot(){ const p = location.pathname; const i = p.indexOf('/beta/'); return i >= 0 ? p.slice(0, i + 1) : p.replace(/[^/]*$/, ''); }
async function fsCheckBackupList(){
  try{
    const r = await fetch('https://api.github.com/repos/domepfa/Firnspur/contents/backups');
    if(!r.ok) throw new Error('Liste nicht verfügbar');
    const j = await r.json();
    return j.map(x=> x.name).filter(n=> /^firnspur-\d{4}-\d{2}-\d{2}\.json\.gpg$/.test(n)).sort().reverse();
  }catch(e){ return []; }
}
async function fsCheckDecrypt(name, pw){
  let r = await fetch(fsCheckPagesRoot() + 'backups/' + name, {cache:'no-cache'}).catch(()=> null);
  if(!r || !r.ok) r = await fetch('https://raw.githubusercontent.com/domepfa/Firnspur/main/backups/' + name);
  if(!r.ok) throw new Error('Sicherung nicht ladbar');
  const bin = new Uint8Array(await r.arrayBuffer());
  const message = await openpgp.readMessage({binaryMessage: bin});
  const {data} = await openpgp.decrypt({message, passwords: [pw], format: 'utf8'});
  return JSON.parse(data);
}
// Kopien im Gerätespeicher (alle Apps, Haupt-App und Beta) in dieselbe Form wie die Sicherung bringen
function fsCheckDeviceSources(){
  const map = {firnspur: {tours:'tours', huts:'huts', gebiete:'gebiete'},
    fixseil: {tours:'fixseil/tours', sektoren:'fixseil/sektoren', klettergebiete:'fixseil/klettergebiete', gipfel:'fixseil/gipfel', huts:'huts'},
    wandern: {tours:'wandern/tours', gebiete:'wandern/gebiete', huts:'huts'}};
  const out = [];
  Object.keys(map).forEach(app=> ['', 'beta'].forEach(b=>{
    let c = null;
    try{ c = JSON.parse(localStorage.getItem(app + b + '-cache') || 'null'); }catch(e){ c = null; }
    if(!c) return;
    const data = {};
    Object.keys(map[app]).forEach(k=>{
      const arr = [...(c[k] || []), ...(c['trashed' + k.charAt(0).toUpperCase() + k.slice(1)] || [])];
      if(!arr.length) return;
      const obj = {}; arr.forEach(x=>{ if(x && x.id) obj[x.id] = x; });
      const segs = map[app][k].split('/'); let o = data;
      segs.slice(0, -1).forEach(s=>{ o = o[s] = o[s] || {}; });
      o[segs[segs.length - 1]] = obj;
    });
    out.push({label: 'Kopie auf diesem Gerät (' + (app === 'firnspur' ? 'Skitour' : app === 'fixseil' ? 'Hochtour/Klettern' : 'Wandern') + (b ? ', Beta' : '') + (c.cachedAt ? ', ' + fmtDate(c.cachedAt) : '') + ')', at: c.cachedAt || '', data});
  }));
  try{ const o = JSON.parse(localStorage.getItem(fsOrteCacheKey()) || '[]'); if(o.length){ const d = {orte:{}}; o.forEach(x=>{ if(x && x.id) d.orte[x.id] = x; }); out.push({label:'Orte auf diesem Gerät', at:'', data:d}); } }catch(e){}
  // Weitere Ablagen auf dem Gerät: Rettungsablage (fs-rescue-*), reichere Kopien (fs-better-*),
  // gemerkte Ausgangsstände einzelner Einträge (fs-base:<Pfad>)
  const put = (data, path, x)=>{ if(!x || !x.id) return; const segs = path.split('/'); let o = data; segs.forEach(sg=>{ o = o[sg] = o[sg] || {}; }); o[x.id] = x; };
  const baseData = {};
  let nBase = 0;
  for(let i = 0; i < localStorage.length; i++){
    const k = localStorage.key(i);
    if(!k) continue;
    let v = null;
    try{ v = JSON.parse(localStorage.getItem(k) || 'null'); }catch(e){ v = null; }
    if(!v || typeof v !== 'object') continue;
    const m = /^fs-(rescue|better)-(firnspur|fixseil|wandern)$/.exec(k);
    if(m){
      const data = {};
      Object.keys(v).forEach(c=>{ const path = (map[m[2]] || {})[c]; if(path && Array.isArray(v[c])) v[c].forEach(x=> put(data, path, x)); });
      if(Object.keys(data).length) out.push({label: (m[1] === 'rescue' ? 'Rettungsablage' : 'Ablage reicherer Kopien') + ' auf diesem Gerät (' + m[2] + ')', at:'', data});
      continue;
    }
    const b = /^fs-base:(.+)\/([^/]+)$/.exec(k);
    if(b && FS_CHECK_COLLS.indexOf(b[1]) >= 0 && v.id){ put(baseData, b[1], v); nBase++; }
  }
  if(nBase) out.push({label: 'Gemerkte Ausgangsstände auf diesem Gerät', at:'', data: baseData});
  return out;
}
// Punkt, der zum gemeinsamen Ort gemacht wurde («Tourpunkt zum gemeinsamen Ort machen»): kein Verlust
function fsCheckBecameOrt(l, co, now){
  if(l.field !== 'points' || l.type !== 'item' || !l.value || !isFinite(l.value.lat)) return false;
  const orte = Object.values((now && now.orte) || {}).filter(o=> o && !o.deletedAt && isFinite(o.lat) && isFinite(o.lon));
  const linked = Array.isArray(co && co.orte) ? co.orte : [];
  return orte.some(o=> linked.indexOf(o.id) >= 0 && fsKm({lat:+l.value.lat, lon:+l.value.lon}, o) < 0.1);
}
// Quellen (neueste zuerst) mit dem heutigen Stand vergleichen; je Fund die neueste Quelle
function fsCheckCompare(sources, now){
  const found = new Map();
  sources.forEach(src=>{
    FS_CHECK_COLLS.forEach(coll=>{
      const b = fsCheckGet(src.data, coll), c = fsCheckGet(now, coll) || {};
      if(!b || typeof b !== 'object') return;
      Object.keys(b).forEach(id=>{
        const bo = b[id];
        if(!bo || typeof bo !== 'object' || bo.deletedAt || !bo.id) return;
        const co = c[id];
        const path = coll + '/' + id;
        if(!co){
          const key = path + '|entry';
          if(!found.has(key)) found.set(key, {key, path, coll, id, name: bo.name || bo.title || id, type:'entry', value:bo, label:'Ganzer Eintrag fehlt', safe:true, src: src.label});
          return;
        }
        if(co.deletedAt) return; // bewusst gelöscht (Papierkorb)
        fsCheckLosses(bo, co).filter(l=> !fsCheckBecameOrt(l, co, now)).forEach(l=>{
          const key = path + '|' + l.field + '|' + (l.type === 'item' ? fsCheckItemKey(l.value) : l.type);
          if(!found.has(key)) found.set(key, Object.assign({key, path, coll, id, name: co.name || bo.name || id, src: src.label}, l));
        });
      });
    });
  });
  return Array.from(found.values());
}
async function fsCheckRestore(items){
  const byPath = new Map();
  items.forEach(it=>{ (byPath.get(it.path) || byPath.set(it.path, []).get(it.path)).push(it); });
  let ok = 0, fail = 0;
  for(const [path, list] of byPath){
    const entry = list.find(x=> x.type === 'entry');
    let cur = entry ? null : await fbGet(path);
    let obj;
    if(entry){ obj = JSON.parse(JSON.stringify(entry.value)); }
    else{
      if(!cur || typeof cur !== 'object'){ fail += list.length; continue; }
      obj = JSON.parse(JSON.stringify(cur));
      list.forEach(it=>{
        if(it.type === 'item'){
          const arr = Array.isArray(obj[it.field]) ? obj[it.field] : [];
          if(!arr.some(x=> fsCheckItemKey(x) === fsCheckItemKey(it.value))) arr.push(it.value);
          obj[it.field] = arr;
        }else obj[it.field] = it.value;
      });
    }
    obj.updatedAt = new Date().toISOString();
    obj.updatedBy = (state && state.myName) || '';
    const res = await fbSet(path, obj).catch(()=> false);
    if(res){ ok += list.length; fsCheckSyncState(path, obj, list); } else fail += list.length;
  }
  return {ok, fail};
}
// Zurückgeholtes sofort auch in die geladene Fassung übernehmen – sonst würde das nächste Speichern aus
// dem alten Stand (z. B. weil ein Formular offen ist und nicht neu geladen wird) es wieder entfernen
function fsCheckSyncState(path, obj, items){
  const id = String(path).split('/').pop();
  const lists = [state.tours, state.huts, state.gebiete, state.sektoren, state.klettergebiete, state.gipfel, state.agenda, state.orte,
    state.trashedTours, state.trashedHuts, state.trashedGebiete, state.trashedSektoren, state.trashedKlettergebiete, state.trashedGipfel].filter(Array.isArray);
  lists.forEach(l=> l.forEach(x=>{
    if(!x || x.id !== id) return;
    // Noch nicht hochgeladene eigene Änderung: nur das Zurückgeholte ergänzen, den Rest nicht anfassen
    if(x._unsynced && Array.isArray(items)){
      items.forEach(it=>{
        if(it.type === 'item'){ const arr = Array.isArray(x[it.field]) ? x[it.field] : (x[it.field] = []); if(!arr.some(y=> fsCheckItemKey(y) === fsCheckItemKey(it.value))) arr.push(JSON.parse(JSON.stringify(it.value))); }
        // Ganzer Eintrag: nur fehlende Felder ergänzen, die neueren eigenen Änderungen bleiben
        else if(it.type === 'entry') Object.keys(obj).forEach(k=>{ if(k[0] !== '_' && fsCanon(x[k]) === null) x[k] = JSON.parse(JSON.stringify(obj[k])); });
        // Linie/Text bewusst zurückgeholt: gilt, sonst nähme das nächste Hochladen es wieder weg
        else x[it.field] = JSON.parse(JSON.stringify(it.value));
      });
      return;
    }
    Object.keys(x).forEach(k=>{ if(k[0] !== '_' && !(k in obj)) delete x[k]; });
    Object.keys(obj).forEach(k=>{ if(k[0] !== '_') x[k] = JSON.parse(JSON.stringify(obj[k])); });
  }));
  if(typeof cacheLocalSnapshot === 'function') try{ cacheLocalSnapshot(); }catch(e){}
}
async function fsOpenDataCheck(){
  const box = document.createElement('div');
  box.className = 'fs-rescue fs-check';
  box.innerHTML = `<div class="fs-rescue-card" role="dialog" aria-modal="true"></div>`;
  document.body.appendChild(box);
  const card = box.querySelector('.fs-rescue-card');
  const close = ()=> box.remove();
  let lastSources = [], lastNow = {};
  // Verlauf eines Eintrags: was jede Quelle über ihn weiss (Punkte, Stand, wer zuletzt)
  const historyHtml = (q)=>{
    q = String(q || '').trim().toLowerCase();
    if(q.length < 3) return '';
    const rows = [];
    const scan = (label, data)=> FS_CHECK_COLLS.forEach(coll=>{
      const c = fsCheckGet(data, coll);
      if(!c || typeof c !== 'object') return;
      Object.values(c).forEach(x=>{
        if(!x || typeof x !== 'object' || !String(x.name || '').toLowerCase().includes(q)) return;
        const pts = (x.points || []).map(p=> p && (p.label || 'ohne Namen'));
        rows.push(`<div class="fs-check-hist"><b>${esc(label)}</b><span>${esc(x.name)} · ${esc(FS_CHECK_APP[coll] || coll)}${x.deletedAt ? ' · im Papierkorb' : ''}</span>
          <span>${pts.length ? pts.length + ' Punkte: ' + esc(pts.join(', ')) : 'keine Punkte'}${x.updatedAt ? ' · Stand ' + esc(fmtDate(x.updatedAt)) + (x.updatedBy ? ' von ' + esc(x.updatedBy) : '') : ''}</span></div>`);
      });
    });
    scan('Heute in der Datenbank', lastNow);
    lastSources.forEach(src=> scan(src.label, src.data));
    return rows.length ? rows.join('') : '<p class="fs-rescue-muted">In keiner Quelle gefunden.</p>';
  };
  const historyBox = ()=> `<div class="fs-check-histbox"><label class="fs-ort-lbl" for="fs-check-q">Verlauf eines Eintrags</label>
    <input id="fs-check-q" type="search" class="fs-check-input" placeholder="Name, z. B. Sustenlochspitz" autocomplete="off"><div data-hist></div></div>`;
  const wireHistory = ()=>{ const i = card.querySelector('#fs-check-q'); if(i) i.addEventListener('input', ()=>{ card.querySelector('[data-hist]').innerHTML = historyHtml(i.value); }); };
  const start = ()=>{
    card.innerHTML = `<h3>${fsIconHtml('shield')} Datenprüfung</h3>
      <p>Vergleicht die täglichen Sicherungen und die Kopie auf diesem Gerät mit dem heutigen Stand – für alle Apps. Gezeigt wird, was heute fehlt, und wann es zuletzt noch da war.</p>
      <p class="fs-rescue-muted">Die Sicherungen sind mit dem App-Passwort verschlüsselt. Es wird nur auf diesem Gerät zum Entschlüsseln verwendet und nicht gespeichert.</p>
      <label class="fs-ort-lbl" for="fs-check-pw">App-Passwort</label>
      <input id="fs-check-pw" type="password" autocomplete="off" class="fs-check-input">
      <p class="fs-ort-msg" data-msg></p>
      <div class="fs-ort-btns"><button type="button" class="btn secondary" data-close>Schliessen</button><button type="button" class="btn" data-run>Prüfen</button></div>
      <button type="button" class="btn secondary fs-check-dev" data-dev>Nur Gerätekopie prüfen (ohne Passwort)</button>`;
    card.querySelector('[data-close]').onclick = close;
    const run = async (withBackups)=>{
      const msg = card.querySelector('[data-msg]');
      const pw = card.querySelector('#fs-check-pw').value;
      if(withBackups && !pw){ msg.textContent = 'Bitte das App-Passwort eingeben.'; return; }
      card.querySelectorAll('button').forEach(b=> b.disabled = true);
      try{
        const sources = [];
        if(withBackups){
          msg.textContent = 'Lade Liste der Sicherungen …';
          if(!window.openpgp) await new Promise((res, rej)=>{ const s = document.createElement('script'); s.src = FS_OPENPGP; s.onload = res; s.onerror = ()=> rej(new Error('Entschlüsselung nicht ladbar (Internet?)')); document.head.appendChild(s); });
          const names = await fsCheckBackupList();
          if(!names.length) throw new Error('Keine Sicherungen gefunden (Internet?).');
          for(let i = 0; i < names.length; i++){
            msg.textContent = 'Entschlüssle Sicherung ' + (i + 1) + ' von ' + names.length + ' …';
            try{ sources.push({label: 'Sicherung vom ' + fmtDateOnly(names[i].slice(9, 19)), at: names[i].slice(9, 19), data: await fsCheckDecrypt(names[i], pw)}); }
            catch(e){ if(i === 0) throw new Error(/passw|decrypt|session key/i.test(String(e && e.message)) ? 'Passwort stimmt nicht.' : 'Sicherung konnte nicht gelesen werden: ' + (e && e.message)); }
          }
        }
        sources.push(...fsCheckDeviceSources());
        msg.textContent = 'Lade heutigen Stand …';
        const now = {};
        for(const coll of FS_CHECK_COLLS){
          // Direkt lesen, nicht über fbGet: das würde die gemerkten Ausgangsstände offener Bearbeitungen ersetzen
          let v = null;
          try{ const r = await fsRawFetch(coll); v = r.ok ? await r.json() : null; }catch(e){ v = null; }
          if(v === null && !navigator.onLine) throw new Error('Keine Verbindung zur Datenbank.');
          const segs = coll.split('/'); let o = now;
          segs.slice(0, -1).forEach(s=>{ o = o[s] = o[s] || {}; });
          o[segs[segs.length - 1]] = v || {};
        }
        lastSources = sources; lastNow = now;
        results(fsCheckCompare(sources, now), sources.length);
      }catch(e){
        msg.textContent = (e && e.message) || 'Prüfung fehlgeschlagen.';
        card.querySelectorAll('button').forEach(b=> b.disabled = false);
      }
    };
    card.querySelector('[data-run]').onclick = ()=> run(true);
    card.querySelector('[data-dev]').onclick = ()=> run(false);
  };
  const results = (found, nSources)=>{
    const groups = new Map();
    found.forEach((f, i)=>{ f._i = i; (groups.get(f.path) || groups.set(f.path, []).get(f.path)).push(f); });
    card.innerHTML = `<h3>${fsIconHtml('shield')} Datenprüfung</h3>
      ${found.length ? `<p><b>${found.length} ${found.length === 1 ? 'Sache fehlt' : 'Sachen fehlen'}</b> in ${groups.size} ${groups.size === 1 ? 'Eintrag' : 'Einträgen'} (verglichen mit ${nSources} Quellen). Angehakt ist, was sicher ergänzt werden kann; Zurückholen fügt nur hinzu.</p>
      <div class="fs-check-list">${Array.from(groups.values()).map(g=> `<div class="fs-check-group">
        <div class="fs-check-head"><b>${esc(g[0].name)}</b><span>${esc(FS_CHECK_APP[g[0].coll] || g[0].coll)}</span></div>
        ${g.map(f=> `<label class="fs-check-row"><input type="checkbox" data-i="${f._i}" ${f.safe ? 'checked' : ''}><span>${esc(f.label)}<small>zuletzt vorhanden: ${esc(f.src)}</small></span></label>`).join('')}
      </div>`).join('')}</div>
      <p class="fs-ort-msg" data-msg></p>
      <div class="fs-ort-btns"><button type="button" class="btn secondary" data-close>Schliessen</button><button type="button" class="btn" data-restore>Zurückholen</button></div>`
      : `<p><b>Nichts fehlt.</b> Alles, was in den ${nSources} geprüften Quellen stand, ist auch heute vorhanden.</p>
      <p class="fs-rescue-muted">Was hier nicht auftaucht, war in keiner Sicherung und in keiner Gerätekopie enthalten – also nie in der Datenbank angekommen.</p>
      <div class="fs-ort-btns"><button type="button" class="btn secondary" data-close>Schliessen</button><button type="button" class="btn secondary" data-again>Nochmals</button></div>`}
      ${historyBox()}`;
    wireHistory();
    card.querySelector('[data-close]').onclick = close;
    if(card.querySelector('[data-again]')) card.querySelector('[data-again]').onclick = start;
    const rb = card.querySelector('[data-restore]');
    if(rb) rb.onclick = async ()=>{
      const sel = Array.from(card.querySelectorAll('input[data-i]:checked')).map(x=> found[+x.getAttribute('data-i')]);
      if(!sel.length){ card.querySelector('[data-msg]').textContent = 'Nichts ausgewählt.'; return; }
      if(!confirm(sel.length + ' ' + (sel.length === 1 ? 'Sache' : 'Sachen') + ' zurückholen? Die jetzige Fassung wird vorher als Version gesichert.')) return;
      rb.disabled = true; rb.textContent = 'Wird zurückgeholt …';
      const r = await fsCheckRestore(sel);
      card.innerHTML = `<h3>${fsIconHtml('shield')} Datenprüfung</h3>
        <p><b>${r.ok} zurückgeholt</b>${r.fail ? `, ${r.fail} nicht (Internet?) – bitte nochmals prüfen` : ''}.</p>
        <div class="fs-ort-btns"><button type="button" class="btn" data-close>Fertig</button></div>`;
      card.querySelector('[data-close]').onclick = ()=>{ close(); if(typeof loadAll === 'function' && !(state.modal && modalIsDirty)) loadAll(); };
    };
  };
  start();
}
document.addEventListener('click', (e)=>{
  const el = e.target.closest && e.target.closest('[data-act="fs-datacheck"]');
  if(!el) return;
  e.stopPropagation();
  const d = el.closest('details'); if(d) d.removeAttribute('open');
  fsOpenDataCheck();
}, true);

/* ===== Gerätespeicher schützen und Nicht-Hochgeladenes anzeigen =====
   Der Browser darf den Speicher einer Website bei Platzmangel oder längerer Nichtnutzung löschen.
   persist() bittet ihn, das für diese App nicht zu tun (installierte App: meist sofort gewährt).
   Solange Änderungen nur auf dem Gerät liegen, zeigt ein Hinweis unten die Zahl und lädt auf Wunsch hoch. */
(function fsPersistStorage(){
  try{ if(navigator.storage && navigator.storage.persist) navigator.storage.persisted().then(p=>{ if(!p) navigator.storage.persist().catch(()=>{}); }).catch(()=>{}); }catch(e){}
})();
function fsUnsyncedCount(){
  if(typeof state === 'undefined') return 0;
  const lists = ['tours', 'huts', 'gebiete', 'sektoren', 'klettergebiete', 'gipfel', 'agenda', 'orte'];
  return lists.reduce((n, k)=> n + (Array.isArray(state[k]) ? state[k].filter(x=> x && x._unsynced).length : 0), 0);
}
// Nur das Ausstehende hochladen (kein vollständiges Neuladen: das würde offene Formulare und
// gemerkte Ausgangsstände durcheinanderbringen)
async function fsRetryUnsynced(){
  if(typeof state === 'undefined') return;
  const jobs = [];
  Object.keys(FS_RESCUE_COLLS).forEach(coll=>{
    const fn = window[FS_RESCUE_COLLS[coll][1]];
    if(typeof fn !== 'function' || !Array.isArray(state[coll])) return;
    [...state[coll], ...(state['trashed' + fsRescueCap(coll)] || [])].filter(x=> x && x._unsynced).forEach(x=> jobs.push(fn(x).catch(()=> false)));
  });
  if(typeof saveAgendaCloud === 'function') (state.agenda || []).filter(x=> x && x._unsynced).forEach(x=> jobs.push(saveAgendaCloud(x).catch(()=> false)));
  fsOrteRaw().filter(o=> o._unsynced).forEach(o=> jobs.push(fsOrtPush(o)));
  const res = await Promise.all(jobs);
  const ok = res.filter(Boolean).length;
  if(typeof render === 'function') render();
  showToast(res.length ? (ok === res.length ? 'Alles hochgeladen.' : ok + ' von ' + res.length + ' hochgeladen – der Rest später (Internet?).') : 'Nichts ausstehend.', ok !== res.length);
}
function fsUnsyncedSync(){
  const n = fsUnsyncedCount();
  let el = document.getElementById('fs-unsynced');
  if(!n){ if(el) el.remove(); return; }
  if(!el){
    el = document.createElement('div');
    el.id = 'fs-unsynced';
    el.className = 'fs-unsynced';
    el.setAttribute('role', 'status');
    document.body.appendChild(el);
    el.addEventListener('click', (e)=>{ const b = e.target.closest('button'); if(b){ b.disabled = true; fsRetryUnsynced().finally(()=>{ b.disabled = false; fsUnsyncedSync(); }); } });
  }
  const txt = n === 1 ? '1 Änderung noch nicht hochgeladen' : n + ' Änderungen noch nicht hochgeladen';
  if(el.dataset.n !== String(n)){
    el.dataset.n = String(n);
    el.innerHTML = `${fsIconHtml('offline')}<span>${txt} – nur auf diesem Gerät</span><button type="button">Hochladen</button>`;
  }
}
setInterval(fsUnsyncedSync, 4000);
window.addEventListener('online', ()=> setTimeout(fsUnsyncedSync, 500));
/* ===== Entwurf: nicht gespeicherte Eingaben überstehen Neuladen und beendete Tabs =====
   Android beendet Tabs im Hintergrund, ein Neuladen leert den Speicher. Solange ein Formular oder
   «Karte bearbeiten» ungespeicherte Änderungen hat, wird der Inhalt laufend auf dem Gerät abgelegt
   (alle Felder, Auswahl-Knöpfe, versteckte Felder mit Punkten/Linien). Beim nächsten Start bietet
   die App an, ihn wiederherzustellen. Nach dem Speichern oder bewussten Verwerfen wird er gelöscht. */
function fsDraftPrefix(){ return 'fs-draft:' + (location.pathname.indexOf('/beta/') >= 0 ? 'beta-' : '') + (typeof fsAppKey === 'function' ? fsAppKey() : 'app') + ':'; }
// Ein Entwurf pro Fenster (Formular bzw. «Karte bearbeiten» eines Eintrags)
function fsDraftKey(k){ return fsDraftPrefix() + (k || (typeof modalDirtyTrackingKey === 'function' && modalDirtyTrackingKey()) || 'x'); }
function fsDraftCapture(){
  if(typeof state === 'undefined' || !state.modal || !modalIsDirty) return null;
  const key = modalDirtyTrackingKey();
  if(!key) return null;
  const modal = document.querySelector('#modal-root .overlay > .modal');
  if(!modal) return null;
  const fields = [];
  modal.querySelectorAll('input, textarea, select').forEach(el=>{
    if(!el.id && !el.name) return;
    if(el.type === 'file' || el.type === 'button' || el.type === 'submit') return;
    fields.push({id: el.id || '', name: el.name || '', v: (el.type === 'checkbox' || el.type === 'radio') ? (el.checked ? '1' : '') : el.value, chk: el.type === 'checkbox' || el.type === 'radio'});
  });
  const chips = [];
  modal.querySelectorAll('button.chip[data-value]').forEach(b=> chips.push({cls: Array.from(b.classList).filter(c=> c !== 'chip' && c !== 'on').join('.'), v: b.getAttribute('data-value'), on: b.classList.contains('on')}));
  const p = state.modal.payload;
  const id = (p && (p.id || (p.route && p.route.id))) || (typeof p === 'string' ? p : '');
  const name = (modal.querySelector('[name="name"]') || {}).value || (p && p.name) || ((modal.querySelector('.modal-head h2') || {}).textContent || '').trim();
  let agendaDays = null;
  const dayBox = /agenda/.test(state.modal.type) ? modal.querySelector('#agenda-day-plan-container') : null;
  if(dayBox && dayBox.dataset.mode === 'multi' && typeof collectAgendaDayPlanFromDom === 'function'){ try{ agendaDays = collectAgendaDayPlanFromDom(dayBox); }catch(e){} }
  return {key, type: state.modal.type, id, payload: (p && typeof p === 'object') ? fsStripLocal(p) : p, quick: key.indexOf('|quick|') >= 0 ? state.quickEditOpenId : null, name, at: new Date().toISOString(), fields, chips, agendaDays};
}
// Entwürfe, die in dieser Sitzung geschrieben wurden. Ältere (z. B. aus einem beendeten Tab) werden
// nie still gelöscht oder überschrieben – nur nach Angebot und Antwort.
const fsDraftWritten = new Set();
// Gerade offenes Fenster sichern, auch wenn state.modal schon auf ein anderes zeigt (Notfallknopf, Link)
function fsDraftFlush(){
  if(!modalIsDirty || typeof fsLastRenderedModal === 'undefined' || !fsLastRenderedModal || typeof state === 'undefined') return;
  const cur = state.modal;
  try{ state.modal = fsLastRenderedModal; fsDraftSave(); }finally{ state.modal = cur; }
}
let fsDraftTimer = null;
function fsDraftSave(){
  clearTimeout(fsDraftTimer);
  const d = fsDraftCapture();
  if(!d) return;
  try{
    const sk = fsDraftKey(d.key);
    // Älterer Entwurf unter demselben Schlüssel (frühere Sitzung): beiseitelegen statt überschreiben
    if(!fsDraftWritten.has(d.key)){
      const old = localStorage.getItem(sk);
      if(old){ let o = null; try{ o = JSON.parse(old); }catch(e){} if(o && o.at) localStorage.setItem(sk + '#' + o.at, old); }
      fsDraftWritten.add(d.key);
    }
    localStorage.setItem(sk, JSON.stringify(d));
  }catch(e){ dlog('Entwurf nicht gespeichert: ' + (e && e.message), 'err'); }
}
function fsDraftSoon(){ clearTimeout(fsDraftTimer); fsDraftTimer = setTimeout(fsDraftSave, 600); }
// Löscht nur einen in dieser Sitzung geschriebenen Entwurf (force: auch einen älteren, nach Rückfrage)
function fsDraftClear(k, force){
  clearTimeout(fsDraftTimer);
  const key = k || (typeof lastDirtyTrackedModalKey !== 'undefined' ? lastDirtyTrackedModalKey : null);
  if(!key || (!force && !fsDraftWritten.has(key))) return;
  try{ localStorage.removeItem(fsDraftKey(key)); }catch(e){}
  fsDraftWritten.delete(key);
}
function fsDraftDrop(d){ try{ localStorage.removeItem(d && d._sk ? d._sk : fsDraftKey(d.key)); }catch(e){} if(d && !d._sk) fsDraftWritten.delete(d.key); }
function fsDraftRead(k){ try{ return JSON.parse(localStorage.getItem(fsDraftKey(k)) || 'null'); }catch(e){ return null; } }
function fsDraftAll(){
  const out = [], pre = fsDraftPrefix();
  try{ for(let i = 0; i < localStorage.length; i++){ const k = localStorage.key(i); if(k && k.startsWith(pre)){ try{ const d = JSON.parse(localStorage.getItem(k)); if(d && d.type){ if(k.indexOf('#') >= 0) d._sk = k; out.push(d); } }catch(e){} } } }catch(e){}
  return out.sort((a, b)=> (b.at || '').localeCompare(a.at || ''));
}
// Nach dem Speichern wird der Entwurf gelöscht; was übrig bleibt, wurde nie gespeichert. Nur sehr alte fallen weg.
function fsDraftIsStale(d){
  return !d || !d.at || Date.now() - new Date(d.at).getTime() > 30 * 864e5;
}
// Wurde der Eintrag nach dem Entwurf noch geändert? (für den Hinweis im Angebot)
function fsDraftEntity(d){
  if(typeof state === 'undefined' || !d || !d.id) return null;
  const lists = [state.tours, state.huts, state.gebiete, state.sektoren, state.klettergebiete, state.gipfel, state.agenda].filter(Array.isArray);
  for(const l of lists){ const x = l.find(y=> y && y.id === d.id); if(x) return x; }
  return null;
}
// Fenster mit ungespeicherten Angaben wurde ohne Speichern verlassen (z. B. Notfallknopf, Wischen):
// kurz warten, ob doch gespeichert wurde, sonst Wiederherstellen anbieten
function fsDraftCheckLeft(k){
  setTimeout(()=>{
    const d = fsDraftRead(k);
    if(!d) return;
    if(fsDraftIsStale(d)){ fsDraftClear(k, true); return; }
    // Gerade wieder am Bearbeiten (oder Notfallkarte offen): später nochmals
    if((modalIsDirty && typeof modalDirtyTrackingKey === 'function' && modalDirtyTrackingKey() && modalDirtyTrackingKey() !== k) || (typeof state !== 'undefined' && state.modal && state.modal.type === 'emergency')){ fsDraftCheckLeft(k); return; }
    if(modalIsDirty && modalDirtyTrackingKey() === k) return; // dasselbe Fenster wieder offen
    fsDraftOffer(d);
  }, 1500);
}
// Beim Wegwechseln (andere App, Bildschirm aus) sofort ablegen – danach kann der Tab beendet werden
document.addEventListener('visibilitychange', ()=>{ if(document.visibilityState === 'hidden') fsDraftFlush(); });
window.addEventListener('pagehide', fsDraftFlush);
// Werte eines Entwurfs ins (frisch geöffnete) Fenster schreiben
function fsDraftApply(d){
  const modal = document.querySelector('#modal-root .overlay > .modal');
  if(!modal || !d) return false;
  // Zweimal: zuerst mit change (abhängige Auswahl, z. B. Teilgebiet nach Region), dann still alle Werte
  [true, false].forEach(fire=> (d.fields || []).forEach(f=>{
    let el = f.id ? modal.querySelector('#' + CSS.escape(f.id)) : null;
    if(!el && f.name) el = modal.querySelector('[name="' + CSS.escape(f.name) + '"]');
    if(!el) return;
    const was = f.chk ? (el.checked ? '1' : '') : el.value;
    if(f.chk) el.checked = !!f.v; else el.value = f.v;
    // Abschnitt mit wiederhergestellter Angabe aufklappen
    if(fire && String(was) !== String(f.v) && el.name !== 'tourIdForTrack'){ const sec = el.closest('details.fs-fsec'); if(sec) sec.open = true; }
    if(fire && el.tagName === 'SELECT') el.dispatchEvent(new Event('change', {bubbles: true}));
  }));
  (d.chips || []).forEach(c=>{
    const sel = 'button.chip' + (c.cls ? '.' + c.cls.split('.').map(x=> CSS.escape(x)).join('.') : '') + '[data-value="' + CSS.escape(c.v) + '"]';
    const b = modal.querySelector(sel);
    if(b && b.classList.contains('on') !== !!c.on) b.click();
  });
  markModalDirty();
  return true;
}
async function fsDraftRestore(d){
  if(d.quick){
    // «Karte bearbeiten»: Ansicht öffnen, Punkte/Linie zurückschreiben, dann die Karte öffnen
    state.modal = {type: d.type, payload: d.id}; render();
    await new Promise(r=> setTimeout(r, 300));
    fsDraftApply(d);
    try{ fsEnterEditMode(); }catch(e){}
    const t = document.getElementById('quick-edit-toggle-' + d.id);
    if(t){ t._fsHoldOk = true; t.click(); t._fsHoldOk = false; }
    markModalDirty();
    return;
  }
  // Formular: mit dem heutigen Stand des Eintrags öffnen, die Werte des Entwurfs schon eingesetzt –
  // so zeichnen sich auch Listen (Links, Gipfel, Knöpfe) nach dem Entwurf, nicht nur die versteckten Felder
  let payload = d.payload;
  const ent = fsDraftEntity(d);
  if(ent && payload && typeof payload === 'object' && !payload.route){
    payload = Object.assign({}, ent);
    (d.fields || []).forEach(f=>{
      const k = f.name; if(!k || f.chk || k[0] === '_' || k === 'id') return;
      // Fehlt das Feld im Eintrag (leere Listen speichert Firebase nicht), nur Listen/Objekte übernehmen (erste Punkte, Linie)
      if(!(k in ent)){ if(/^[\[{]/.test(f.v || '')){ try{ const v = JSON.parse(f.v); if(v && typeof v === 'object' && (!Array.isArray(v) || v.length)) payload[k] = v; }catch(e){} } return; }
      // Links nicht vorbelegen: das Formular verschiebt einen ersetzten Link sonst nicht mehr unter «Weitere Links»
      if(k === 'tourLink' || k === 'gpxLink') return;
      const cur = ent[k];
      if(Array.isArray(cur) || (cur && typeof cur === 'object')){ try{ const v = JSON.parse(f.v || 'null'); if(v !== null) payload[k] = v; }catch(e){} }
      else if(typeof cur === 'string' || typeof cur === 'number') payload[k] = f.v;
    });
  }else if(ent && payload && typeof payload === 'object') payload = Object.assign({}, payload);
  if(/agenda/.test(d.type) && typeof agendaDayPlanDraft !== 'undefined') agendaDayPlanDraft = d.agendaDays ? JSON.parse(JSON.stringify(d.agendaDays)) : null;
  state.modal = {type: d.type, payload}; render();
  await new Promise(r=> setTimeout(r, 300));
  fsDraftApply(d);
  // Termin über mehrere Tage: Tagesplan aus dem Entwurf aufbauen
  const af = document.querySelector('#modal-root .overlay > .modal form');
  const box = af && af.querySelector('#agenda-day-plan-container');
  if(box && d.agendaDays && typeof syncAgendaDayPlanMode === 'function'){ box.dataset.mode = ''; agendaDayPlanDraft = JSON.parse(JSON.stringify(d.agendaDays)); syncAgendaDayPlanMode(af); markModalDirty(); }
}
function fsDraftOffer(given){
  let d = given;
  if(!d){
    const all = fsDraftAll();
    all.filter(fsDraftIsStale).forEach(x=> fsDraftDrop(x));
    // Nicht das Fenster anbieten, das gerade bearbeitet wird (Entwurf dieser Sitzung)
    d = all.find(x=> !fsDraftIsStale(x) && (x._sk || !fsDraftWritten.has(x.key)));
  }
  if(!d || !d.type) return;
  if(document.getElementById('fs-draft-offer')) return;
  // Gerade am Bearbeiten: nicht dazwischenfahren, später nochmals
  if(modalIsDirty && typeof modalDirtyTrackingKey === 'function' && modalDirtyTrackingKey()){ setTimeout(()=> fsDraftOffer(given), 5000); return; }
  const ent = fsDraftEntity(d);
  const changed = ent && ent.updatedAt && ent.updatedAt > d.at
    ? ` Seither wurde der Eintrag ${ent.updatedBy && ent.updatedBy !== (state.myName || '') ? 'von ' + esc(ent.updatedBy) + ' ' : ''}geändert – beim Wiederherstellen gelten deine Angaben, bitte vor dem Speichern prüfen.` : '';
  const box = document.createElement('div');
  box.id = 'fs-draft-offer';
  box.className = 'fs-rescue';
  box.innerHTML = `<div class="fs-rescue-card" role="dialog" aria-modal="true">
    <h3>${fsIconHtml('note')} Nicht gespeicherte Angaben</h3>
    <p>«${esc(d.name || 'Eintrag')}» wurde zuletzt am ${esc(fmtDate(d.at))} bearbeitet, aber nicht gespeichert (z. B. weil der Browser die Seite geschlossen hat).${changed}</p>
    <div class="fs-ort-btns"><button type="button" class="btn secondary" data-drop>Verwerfen</button><button type="button" class="btn" data-restore>Wiederherstellen</button></div>
  </div>`;
  document.body.appendChild(box);
  box.querySelector('[data-drop]').onclick = ()=>{ if(!confirm('Diese Angaben endgültig verwerfen?')) return; fsDraftDrop(d); box.remove(); setTimeout(()=> fsDraftOffer(), 300); };
  box.querySelector('[data-restore]').onclick = async ()=>{
    box.remove();
    // Ab jetzt gehört der Entwurf zur laufenden Sitzung (wird beim Weiterarbeiten fortgeschrieben)
    fsDraftDrop(d); try{ localStorage.setItem(fsDraftKey(d.key), JSON.stringify(Object.assign({}, d, {_sk: undefined}))); }catch(e){} fsDraftWritten.add(d.key);
    await fsDraftRestore(d); showToast('Angaben wiederhergestellt – bitte noch speichern.');
  };
}

/* ===== Formular in aufklappbaren Abschnitten =====
   Die Felder bleiben, wie sie sind (gleiche Namen, gleiche Logik beim Speichern); nach dem Zeichnen
   werden sie nur in Abschnitte gehängt. Offen ist zu Beginn nur der erste; der Kopf eines
   geschlossenen Abschnitts zeigt, was darin steht. Geschlossene Felder werden mitgespeichert.
   sections: [{key, title, sel: ['[name="crux"]', '#fs-tracks-field', …]}] – ein Feld ohne Treffer
   bleibt beim Abschnitt des Feldes davor. */
// Abschnitte des Tourenformulars (alle Apps; Felder, die eine App nicht hat, fallen einfach weg)
function fsTourFormSections(climb){
  const n = x=> '[name="' + x + '"]';
  return [
    {key:'grund', title:'Grunddaten', sel:[n('name'), n('routeName'), n('status'), n('tourCategory'), '#region-chips', '#subregion-field', '#summit-field', '.fs-owner-note']},
    {key:'zahlen', title:'Kennzahlen', sel:[n('targetAltitude'), n('elevationGain'), n('elevationLoss'), n('duration'), n('descentDuration'), n('distance'), '#pitchcount-field']},
    {key:'gelaende', title: climb ? 'Schwierigkeit & Material' : 'Gelände & Material', sel:['#hochtour-safety-fields', '#msl-safety-fields', n('glacier'), '.exposition-chip', '.gefahren-chip', '.material-chip', n('ropeType'), n('ropeLength'), n('quickdrawCount'), n('dog'), n('tourShape'), '.month-chip']},
    {key:'karte', title: climb ? 'Karte, Route & Topo' : 'Karte & Route', sel:['#fs-tracks-field', n('gpxLink'), n('points'), n('topoImages')]},
    {key:'text', title:'Beschreibung', sel:[n('crux'), n('special'), n('ascent'), n('descent'), n('tourLink'), '.fs-more-links', '#descent-freetext-field']},
    {key:'anreise', title:'Anreise', sel:['#approach-type-chips', '#stay-type-chips', n('approach')]},
    {key:'link', title:'Verknüpfungen & Rechte', sel:[n('hutId'), n('gebietId'), '#sektor-field', n('ownerOpen')]}
  ];
}
function fsFormSectionize(form, sections){
  if(!form || form.dataset.fsSec || !Array.isArray(sections) || !sections.length) return;
  form.dataset.fsSec = '1';
  const keep = el=> el.matches('.form-actions, .fab-save, [id^="delete-"], .form-error, [id$="-error"]');
  const kids = Array.from(form.children).filter(el=> !keep(el));
  if(!kids.length) return;
  const anchor = kids[0];
  const boxes = sections.map((sec, i)=>{
    const d = document.createElement('details');
    d.className = 'fs-fsec'; d.dataset.sec = sec.key;
    if(i === 0) d.open = true;
    d.innerHTML = `<summary><span class="fs-fsec-t">${esc(sec.title)}</span><span class="fs-fsec-i"></span></summary><div class="fs-fsec-b"></div>`;
    return d;
  });
  let cur = 0;
  kids.forEach(el=>{
    const hit = sections.findIndex(sec=> (sec.sel || []).some(q=>{ try{ return el.matches(q) || el.querySelector(q); }catch(e){ return false; } }));
    if(hit >= 0) cur = hit;
    boxes[cur].querySelector('.fs-fsec-b').appendChild(el);
  });
  boxes.forEach(b=>{ if(b.querySelector('.fs-fsec-b').children.length) form.insertBefore(b, form.querySelector('.form-actions') || null); });
  // Kurzinfo im Kopf: was steht drin
  const info = b=>{
    const body = b.querySelector('.fs-fsec-b');
    const json = id=>{ const el = body.querySelector(id); try{ const v = el && el.value ? JSON.parse(el.value) : null; return v; }catch(e){ return null; } };
    const parts = [];
    const pts = json('[name="points"]'); if(Array.isArray(pts) && pts.length) parts.push(pts.length === 1 ? '1 Punkt' : pts.length + ' Punkte');
    const man = json('[name="manualTrack"]'); if(Array.isArray(man) && man.length > 1) parts.push('Linie');
    const trk = json('[name="trackSimplified"]'); if(Array.isArray(trk) && trk.length) parts.push('GPX');
    const topo = json('[name="topoImages"]'); if(Array.isArray(topo) && topo.length) parts.push(topo.length === 1 ? '1 Topo' : topo.length + ' Topos');
    let n = 0;
    body.querySelectorAll('input, textarea, select').forEach(el=>{
      if(!el.name || el.type === 'file' || /^(points|manualTrack|trackSimplified|topoImages|tourIdForTrack)$/.test(el.name)) return;
      if(el.closest('[style*="display:none"], [style*="display: none"]')) return;
      const v = (el.type === 'checkbox' || el.type === 'radio') ? (el.checked ? '1' : '') : String(el.value || '').trim();
      if(v && v !== '[]' && v !== 'nein') n++;
    });
    n += Array.from(body.querySelectorAll('.chips')).filter(c=> !c.parentElement.querySelector('input[type="hidden"][name]') && c.querySelector('button.chip.on')).length;
    if(n) parts.push(n === 1 ? '1 Angabe' : n + ' Angaben');
    b.querySelector('.fs-fsec-i').textContent = parts.length ? parts.join(' · ') : 'leer';
  };
  const all = Array.from(form.querySelectorAll(':scope > details.fs-fsec'));
  all.forEach(info);
  let t = null;
  const upd = ()=>{ clearTimeout(t); t = setTimeout(()=> all.forEach(info), 250); };
  form.addEventListener('input', upd); form.addEventListener('change', upd); form.addEventListener('click', upd);
  // Karten in einem eben geöffneten Abschnitt neu ausmessen (waren unsichtbar)
  all.forEach(b=> b.addEventListener('toggle', ()=>{ if(b.open) setTimeout(()=>{ try{ window.dispatchEvent(new Event('resize')); }catch(e){} }, 60); }));
}

/* ===== Routen-Check: Hangneigung, Exposition und Lawinenbulletin entlang der Linie =====
   Hangneigung aus der offiziellen swisstopo-Karte «Hangneigung über 30°» (swissALTI3D, Klassen
   30–35/35–40/40–45/45–50/über 50°): die Kachel-Farbe am Punkt der Linie, im Umkreis von wenigen
   Metern. Höhe und Exposition aus dem Geländemodell der 3D-Karte (FS3D_DEM, ca. 30 m), mit der
   Horn-Formel. Nur in der Schweiz. Das Bulletin (kritische Expositionen ab einer Höhe) tippt man
   selbst an; es gilt am selben Tag für alle Touren auf diesem Gerät. */
const FS_RC_SLOPE_URL = 'https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.hangneigung-ueber_30/default/current/3857/{z}/{x}/{y}.png';
const FS_RC_CLASSES = [
  {k:1, label:'30–35°', rgb:[242,229,10]}, {k:2, label:'35–40°', rgb:[244,111,36]}, {k:3, label:'40–45°', rgb:[222,5,91]},
  {k:4, label:'45–50°', rgb:[200,137,187]}, {k:5, label:'über 50°', rgb:[75,75,75]}
];
const FS_RC_ASP = ['N','NE','E','SE','S','SW','W','NW'];
const fsRcCache = new Map(), fsRcRunning = new Set(), fsRcTiles = new Map();
function fsRcLine(t){
  const r = fsTourRoutes(t)[0];
  if(!r) return null;
  const c = (r.coords || []).map(p=> Array.isArray(p) ? [+p[0], +p[1]] : [+p.lat, +(p.lon != null ? p.lon : p.lng)]).filter(p=> isFinite(p[0]) && isFinite(p[1]));
  return c.length > 1 ? c : null;
}
function fsRcKey(t, c){ return t.id + ':' + c.length + ':' + c[0].join(',') + ':' + c[c.length - 1].join(','); }
function fsRcHav(a, b){
  const R = 6371000, la1 = a[0] * Math.PI / 180, la2 = b[0] * Math.PI / 180, dLa = la2 - la1, dLo = (b[1] - a[1]) * Math.PI / 180;
  const h = Math.sin(dLa / 2) ** 2 + Math.cos(la1) * Math.cos(la2) * Math.sin(dLo / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}
function fsRcPx(lat, lon, z){
  const n = 256 * Math.pow(2, z), la = lat * Math.PI / 180;
  return [(lon + 180) / 360 * n, (1 - Math.log(Math.tan(la) + 1 / Math.cos(la)) / Math.PI) / 2 * n];
}
function fsRcTile(tpl, z, x, y){
  const url = tpl.replace('{z}', z).replace('{x}', x).replace('{y}', y);
  if(!fsRcTiles.has(url)) fsRcTiles.set(url, fetch(url).then(r=> r.ok ? r.blob() : null).then(async b=>{
    if(!b) return null;
    const bmp = await createImageBitmap(b);
    const cv = document.createElement('canvas'); cv.width = 256; cv.height = 256;
    const cx = cv.getContext('2d', {willReadFrequently: true}); cx.drawImage(bmp, 0, 0);
    return cx.getImageData(0, 0, 256, 256).data;
  }).catch(()=> { fsRcTiles.delete(url); return undefined; }));
  return fsRcTiles.get(url);
}
// Pixel an globaler Pixelposition; Kacheln vorher geladen (tiles: Map "z/x/y" → Daten)
function fsRcPix(tiles, z, px, py){
  const tx = Math.floor(px / 256), ty = Math.floor(py / 256), d = tiles.get(z + '/' + tx + '/' + ty);
  if(!d) return null;
  const i = ((Math.floor(py) - ty * 256) * 256 + (Math.floor(px) - tx * 256)) * 4;
  return [d[i], d[i + 1], d[i + 2], d[i + 3]];
}
async function fsRcLoad(tpl, z, pts, pad){
  const need = new Set();
  pts.forEach(p=>{ const [x, y] = fsRcPx(p[0], p[1], z); [[-pad, -pad], [pad, -pad], [-pad, pad], [pad, pad]].forEach(([dx, dy])=> need.add(z + '/' + Math.floor((x + dx) / 256) + '/' + Math.floor((y + dy) / 256))); });
  const tiles = new Map();
  let failed = 0;
  await Promise.all(Array.from(need).map(async k=>{ const [zz, x, y] = k.split('/'); const d = await fsRcTile(tpl, zz, x, y); if(d === undefined) failed++; tiles.set(k, d); }));
  return {tiles, failed};
}
function fsRcClass(px){
  if(!px || px[3] < 100) return 0;
  let best = 0, bd = 1e9;
  FS_RC_CLASSES.forEach(c=>{ const d = (px[0] - c.rgb[0]) ** 2 + (px[1] - c.rgb[1]) ** 2 + (px[2] - c.rgb[2]) ** 2; if(d < bd){ bd = d; best = c.k; } });
  return bd < 9000 ? best : 0;
}
const fsRcEle = px=> px ? px[0] * 256 + px[1] + px[2] / 256 - 32768 : null;
async function fsRcCompute(c){
  // Linie alle ~15 m abtasten (höchstens 1200 Punkte)
  const cum = [0];
  for(let i = 1; i < c.length; i++) cum.push(cum[i - 1] + fsRcHav(c[i - 1], c[i]));
  const total = cum[cum.length - 1];
  if(total < 50) return {error: 'Die Linie ist zu kurz.'};
  const step = Math.max(15, total / 1200), pts = [];
  for(let d = 0, j = 0; d <= total; d += step){
    while(j < c.length - 2 && cum[j + 1] < d) j++;
    const f = cum[j + 1] > cum[j] ? (d - cum[j]) / (cum[j + 1] - cum[j]) : 0;
    pts.push({d, lat: c[j][0] + (c[j + 1][0] - c[j][0]) * f, lon: c[j][1] + (c[j + 1][1] - c[j][1]) * f});
  }
  const inCH = pts.some(p=> p.lat > 45.8 && p.lat < 47.9 && p.lon > 5.9 && p.lon < 10.6);
  const ll = pts.map(p=> [p.lat, p.lon]);
  const ZS = 15, ZD = 13;
  const [sl, dem] = await Promise.all([inCH ? fsRcLoad(FS_RC_SLOPE_URL, ZS, ll, 3) : {tiles: new Map(), failed: 0}, fsRcLoad(FS3D_DEM, ZD, ll, 2)]);
  if(dem.failed && dem.failed >= dem.tiles.size) return {error: navigator.onLine === false ? 'Offline – der Routen-Check braucht Internet.' : 'Geländedaten nicht erreichbar.', retry: true};
  pts.forEach(p=>{
    if(inCH){
      const [x, y] = fsRcPx(p.lat, p.lon, ZS);
      let k = 0;
      for(let dx = -2; dx <= 2; dx++) for(let dy = -2; dy <= 2; dy++) k = Math.max(k, fsRcClass(fsRcPix(sl.tiles, ZS, x + dx, y + dy)));
      p.k = k;
    }else p.k = 0;
    const [x, y] = fsRcPx(p.lat, p.lon, ZD);
    const e = (dx, dy)=> fsRcEle(fsRcPix(dem.tiles, ZD, x + dx, y + dy));
    const a = e(-1, -1), b = e(0, -1), cc = e(1, -1), dd = e(-1, 0), ff = e(1, 0), g = e(-1, 1), h = e(0, 1), ii = e(1, 1);
    p.ele = e(0, 0);
    if([a, b, cc, dd, ff, g, h, ii].every(v=> v != null)){
      const cell = 40075016.686 * Math.cos(p.lat * Math.PI / 180) / (256 * Math.pow(2, ZD));
      const gx = ((cc + 2 * ff + ii) - (a + 2 * dd + g)) / (8 * cell), gn = ((a + 2 * b + cc) - (g + 2 * h + ii)) / (8 * cell);
      p.asp = ((Math.atan2(-gx, -gn) * 180 / Math.PI) + 360) % 360;
      p.ai = Math.round(p.asp / 45) % 8;
    }
  });
  return {pts, total, step, inCH};
}
function fsRcBulletin(){
  let mode = 'auto';
  try{ mode = localStorage.getItem('fs-rc-mode') || 'auto'; }catch(e){}
  try{ const b = JSON.parse(localStorage.getItem('fs-rc-bulletin') || 'null'); if(b && b.day === fsToday()) return Object.assign(b, {mode}); }catch(e){}
  return {day: fsToday(), asp: [], minEle: 0, mode};
}
// Lawinenprobleme des Bulletins (heute oder morgen, wie in «Bedingungen» gewählt), ohne «günstig»
function fsRcSlfBul(slf){
  if(!slf) return null;
  return (state._slfDay === 'next' && slf.next) || (!slf.cur && slf.next) ? slf.next : slf.cur;
}
function fsRcSlfProblems(bul){
  return bul ? bul.problems.filter(pr=> pr.raw !== 'favourable_situation' && pr.raw !== 'no_distinct_avalanche_problem') : [];
}
function fsRcInProblem(p, pr){
  if(p.k < 1 || p.ai == null) return false;
  if(pr.aspects.length && pr.aspects.indexOf(FS_RC_ASP[p.ai]) < 0) return false;
  if(pr.lower && p.ele != null && p.ele < pr.lower) return false;
  if(pr.upper && p.ele != null && p.ele > pr.upper) return false;
  return true;
}
function fsRcSetBulletin(b){ try{ localStorage.setItem('fs-rc-bulletin', JSON.stringify(b)); }catch(e){} }
const fsRcFmtM = m=> m >= 1000 ? (m / 1000).toFixed(1).replace('.0', '') + ' km' : Math.round(m / 10) * 10 + ' m';
const fsRcFmtE = e=> String(Math.round(e)).replace(/\B(?=(\d{3})+(?!\d))/g, '’');
const FS_RC_ASP_LONG = {N:'Nord', NE:'Nordost', E:'Ost', SE:'Südost', S:'Süd', SW:'Südwest', W:'West', NW:'Nordwest'};
// Was Kurz- und Vollansicht gemeinsam brauchen: Bulletin-Abgleich, Längen, steilste Stelle
function fsRcModel(res, withBulletin){
  const {pts, step} = res;
  const b = fsRcBulletin();
  const bul = withBulletin ? fsRcSlfBul(res.slf) : null;
  const auto = !!(bul && b.mode !== 'manual');
  const probs = auto ? fsRcSlfProblems(bul) : [];
  const crit = new Set(auto ? probs.reduce((a, pr)=> a.concat(pr.aspects.length ? pr.aspects : FS_RC_ASP), []) : b.asp);
  const isCrit = auto ? (p=> probs.some(pr=> fsRcInProblem(p, pr)))
    : (p=> withBulletin && crit.size && p.k >= 1 && p.ai != null && crit.has(FS_RC_ASP[p.ai]) && (p.ele == null || p.ele >= (b.minEle || 0)));
  const flags = pts.map(p=> !!isCrit(p));
  const maxK = Math.max(0, ...pts.map(p=> p.k));
  let spots = 0; flags.forEach((f, i)=>{ if(f && !(i && flags[i - 1])) spots++; });
  return {res, withBulletin, b, bul, auto, probs, crit, isCrit, flags, maxK, spots,
    steep: maxK ? pts.find(p=> p.k === maxK) : null,
    len: k=> pts.filter(p=> p.k >= k).length * step,
    critLen: flags.filter(Boolean).length * step,
    byAsp: FS_RC_ASP.map((a, i)=> pts.filter(p=> p.k >= 1 && p.ai === i).length * step),
    showCrit: !!(withBulletin && (crit.size || probs.length))};
}
// Die Aussage in ganzen Sätzen: wie viel steil, wo die steilste Stelle, was das Bulletin dazu sagt
function fsRcSummaryHtml(m){
  const {pts, total} = m.res, fmtM = fsRcFmtM, fmtE = fsRcFmtE;
  const st = m.steep;
  const s1 = !m.maxK ? `Entlang der ganzen Route (${fmtM(total)}) ist kein Hang steiler als 30°.`
    : `Auf <b>${fmtM(m.len(1))}</b> von ${fmtM(total)} führt die Route durch Hänge steiler als 30°${m.len(2) ? `, davon <b>${fmtM(m.len(2))}</b> steiler als 35°` : ''}. `
      + `Die steilste Stelle (${FS_RC_CLASSES[m.maxK - 1].label}) liegt${st.ele != null ? ' auf ' + fmtE(st.ele) + ' m' : ''}${st.ai != null ? ', Exposition ' + FS_RC_ASP_LONG[FS_RC_ASP[st.ai]] : ''}.`;
  let s2 = '';
  if(m.withBulletin && m.auto){
    const top = m.bul.ratings[0], lvl = top ? ` (Gefahrenstufe ${top.level} ${esc(top.label)})` : '';
    const types = m.probs.filter(pr=> pts.some(p=> fsRcInProblem(p, pr))).map(pr=> esc(pr.type));
    s2 = !m.probs.length ? `Das Lawinenbulletin${lvl} meldet keine ausgeprägten Lawinenprobleme.`
      : m.critLen ? `Laut Lawinenbulletin${lvl} liegen <b>${fmtM(m.critLen)}</b>${m.spots > 1 ? ' an ' + m.spots + ' Stellen' : ''} im Problembereich: ${types.join(', ')}.`
      : `Laut Lawinenbulletin${lvl} liegt keine steile Stelle der Route im Problembereich.`;
  }else if(m.withBulletin && m.b.asp.length){
    s2 = m.critLen ? `In den gewählten kritischen Expositionen liegen <b>${fmtM(m.critLen)}</b>${m.spots > 1 ? ' an ' + m.spots + ' Stellen' : ''}.` : 'Keine steile Stelle liegt in den gewählten kritischen Expositionen.';
  }
  return `<div class="fs-rc-sum${m.critLen ? ' warn' : ''}"><p>${s1}</p>${s2 ? `<p>${m.critLen ? fsIconHtml('alert') : ''}${s2}</p>` : ''}</div>`;
}
// Höhenprofil: Linie farbig, wo der Hang steiler als 30° ist; darunter die Bänder Steilheit und Bulletin.
// big: Vollansicht mit Strecken-Marken, Beschriftung der Bänder und Lauf-Strich zum Antippen.
function fsRcProfileSvg(m, big){
  const {pts, total, step} = m.res, fmtM = fsRcFmtM, fmtE = fsRcFmtE;
  const W = 600, top = big ? 22 : 14, chartH = big ? 190 : 120;
  const b1 = top + chartH + (big ? 62 : 14), b2 = b1 + (big ? 60 : 22), bh = big ? 22 : 16;
  const H = (m.showCrit ? b2 : b1) + bh + (big ? 4 : 2);
  const eles = pts.map(p=> p.ele).filter(v=> v != null);
  const mn = Math.min(...eles), mx = Math.max(...eles), span = Math.max(50, mx - mn);
  const X = d=> (d / total * W).toFixed(1), Y = e=> (top + chartH - (e - mn) / span * chartH).toFixed(1);
  const line = pts.filter(p=> p.ele != null).map(p=> X(p.d) + ',' + Y(p.ele)).join(' ');
  let segs = '', band = '', cband = '';
  for(let i = 0; i < pts.length - 1; i++){
    const p = pts[i], q = pts[i + 1], w = (Math.max(step, q.d - p.d) / total * W + 0.6).toFixed(1);
    if(p.k && p.ele != null && q.ele != null) segs += `<line x1="${X(p.d)}" y1="${Y(p.ele)}" x2="${X(q.d)}" y2="${Y(q.ele)}" class="fs-rc-k${p.k}" stroke-width="${big ? 6 : 5}" stroke-linecap="round"/>`;
    if(p.k) band += `<rect x="${X(p.d)}" y="${b1}" width="${w}" height="${bh}" class="fs-rc-f${p.k}"/>`;
    if(m.flags[i]) cband += `<rect x="${X(p.d)}" y="${b2}" width="${w}" height="${bh}" class="fs-rc-crit"/>`;
  }
  let ticks = '';
  if(big){
    const km = total / 1000, every = km > 16 ? 5 : km > 8 ? 2 : km > 3 ? 1 : 0.5;
    for(let v = every; v < km - every * 0.3; v += every){
      const x = (v * 1000 / total * W).toFixed(1);
      ticks += `<line x1="${x}" x2="${x}" y1="${top}" y2="${top + chartH}" class="fs-rc-grid"/><text x="${x}" y="${top + chartH + 26}" text-anchor="middle" class="fs-rc-t">${String(v).replace('.', ',')} km</text>`;
    }
  }
  const st = m.steep;
  return `<svg class="fs-rc-svg${big ? ' fs-rcf-prof' : ' fs-rc-mini'}" viewBox="0 0 ${W} ${H}" ${big ? 'role="slider" tabindex="0" aria-label="Stelle auf der Route wählen" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"' : 'role="button" tabindex="0" data-rc-open aria-label="Routen-Check gross ansehen"'}>
    <defs><pattern id="fs-rc-hatch" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="8" height="8" class="fs-rc-critbg"/><line x1="0" y1="0" x2="0" y2="8" class="fs-rc-hatchline" stroke-width="4"/></pattern></defs>
    ${ticks}
    <polygon points="0,${top + chartH} ${line} ${W},${top + chartH}" class="fs-rc-area"/>
    <polyline points="${line}" class="fs-rc-line" fill="none" stroke-width="2.5"/>
    ${segs}
    ${big ? `<text x="0" y="${b1 - 8}" class="fs-rc-bl">Steilheit neben der Route</text>` : ''}
    <rect x="0" y="${b1}" width="${W}" height="${bh}" class="fs-rc-bandbg"/>${band}
    ${m.showCrit ? `${big ? `<text x="0" y="${b2 - 8}" class="fs-rc-bl">Im Problembereich des Bulletins</text>` : ''}<rect x="0" y="${b2}" width="${W}" height="${bh}" class="fs-rc-bandbg"/>${cband}` : ''}
    ${st && st.ele != null ? `<circle cx="${X(st.d)}" cy="${Y(st.ele)}" r="9" class="fs-rc-steep"/>` : ''}
    <text x="6" y="${top + 12}" class="fs-rc-t">${fmtE(mx)} m</text><text x="6" y="${top + chartH - 6}" class="fs-rc-t">${fmtE(mn)} m</text>
    ${big ? '' : `<text x="${W - 6}" y="${top + chartH - 6}" class="fs-rc-t" text-anchor="end">${fmtM(total)}</text>`}
    ${big ? `<line data-rcf="cursor" x1="-10" x2="-10" y1="0" y2="${H}" class="fs-rcf-cursor" stroke-width="2.5"/>` : ''}
  </svg>`;
}
function fsRcRoseSvg(m){
  const fmtM = fsRcFmtM, {crit, byAsp, withBulletin, auto} = m;
  const maxA = Math.max(1, ...byAsp);
  const sec = i=>{ const r0 = 22, r1 = 34 + 62 * Math.sqrt(byAsp[i] / maxA), a0 = (i * 45 - 22.5 - 90) * Math.PI / 180, a1 = (i * 45 + 22.5 - 90) * Math.PI / 180;
    const P = (r, a)=> (r * Math.cos(a)).toFixed(1) + ' ' + (r * Math.sin(a)).toFixed(1);
    return `M${P(r0, a0)} L${P(r1, a0)} A${r1} ${r1} 0 0 1 ${P(r1, a1)} L${P(r0, a1)} A${r0} ${r0} 0 0 0 ${P(r0, a0)}Z`; };
  return `<svg class="fs-rc-rose" viewBox="-112 -112 224 224" role="group" aria-label="Exposition der Hänge über 30°${withBulletin ? '; antippen markiert kritische Expositionen aus dem Bulletin' : ''}">
    <circle r="96" class="fs-rc-ring"/>
    ${FS_RC_ASP.map((a, i)=> `<path d="${sec(i)}" class="fs-rc-sec${crit.has(a) ? ' crit' : ''}${byAsp[i] ? ' has' : ''}" ${withBulletin && !auto ? `data-rc-asp="${a}" role="button" tabindex="0" aria-pressed="${crit.has(a)}" aria-label="${FS_SLF_ASPECTS[a]}: ${fmtM(byAsp[i])} über 30°"` : `aria-label="${FS_SLF_ASPECTS[a]}: ${fmtM(byAsp[i])} über 30°"`}/>`).join('')}
    ${FS_RC_ASP.map((a, i)=>{ const an = (i * 45 - 90) * Math.PI / 180; return `<text x="${(106 * Math.cos(an)).toFixed(1)}" y="${(106 * Math.sin(an) + 4).toFixed(1)}" text-anchor="middle" class="fs-rc-al${crit.has(a) ? ' crit' : ''}">${FS_SLF_ASPECTS[a]}</text>`; }).join('')}
  </svg>`;
}
function fsRcErrorHtml(res){
  return `<p class="fs-rc-note">${esc(res.error)}</p>${res.retry ? '<button type="button" class="btn secondary" data-rc-retry>Nochmals versuchen</button>' : ''}`;
}
// In der Tour: Aussage, kleines Profil, «Gross ansehen» und «Vorbeiflug»
function fsRcBodyHtml(res, withBulletin){
  if(res.error) return fsRcErrorHtml(res);
  const m = fsRcModel(res, withBulletin);
  return `${fsRcSummaryHtml(m)}
    ${fsRcProfileSvg(m, false)}
    <div class="fs-rc-actions">
      <button type="button" class="btn fs-rc-open" data-rc-open>${fsIconHtml('expand')}Gross ansehen</button>
      <button type="button" class="btn secondary fs-rc-fly" data-rc-fly>${fsIconHtml('play')}Vorbeiflug</button>
    </div>`;
}
// Vollansicht: Karte mit der eingefärbten Route, grosses Profil zum Antippen, Legende in Worten, Exposition und Bulletin
function fsRcFullHtml(res, withBulletin){
  if(res.error) return fsRcErrorHtml(res);
  const m = fsRcModel(res, withBulletin), {pts, step, inCH} = res, fmtM = fsRcFmtM;
  const say = withBulletin
    ? ['steil – ab etwa 30° können Schneebretter anbrechen', 'sehr steil – hier lösen sich die meisten Schneebretter', 'extrem steil', 'extrem steil, oft felsdurchsetzt', 'Fels und Wände']
    : ['steil – Trittsicherheit nötig', 'sehr steil – Ausrutschen kann gefährlich sein', 'extrem steil', 'extrem steil, oft felsdurchsetzt', 'Fels und Wände'];
  const keys = FS_RC_CLASSES.filter(c=> pts.some(p=> p.k === c.k)).map(c=>
    `<li><i class="fs-rc-f${c.k}"></i><b>${c.label}</b><span>${say[c.k - 1]} · ${fmtM(pts.filter(p=> p.k === c.k).length * step)}</span></li>`).join('');
  return `${fsRcSummaryHtml(m)}
    <p class="fs-rcf-read" data-rcf="read" aria-live="polite">${fsIconHtml('ruler')}<span>Profil oder Route antippen: zeigt Höhe, Steilheit und Exposition an dieser Stelle.</span></p>
    ${fsRcProfileSvg(m, true)}
    <button type="button" class="btn fs-rc-fly" data-rc-fly>${fsIconHtml('play')}Vorbeiflug in 3D</button>
    <h3 class="fs-rcf-h">So liest du das Profil</h3>
    <p class="fs-rc-note">Die Linie zeigt die Höhe über die Strecke. Farbig ist sie dort, wo der Hang neben der Route steiler als 30° ist; das Band darunter zeigt dasselbe ohne Höhe. Der Kreis markiert die steilste Stelle.</p>
    <ul class="fs-rcf-keys">${keys || '<li><span>Keine Hänge über 30° entlang der Linie.</span></li>'}
      ${m.showCrit ? `<li><i class="fs-rc-critkey"></i><b>schraffiert</b><span>${m.auto ? 'Exposition und Höhe passen zu einem Lawinenproblem des Bulletins' : 'Hang in einer gewählten kritischen Exposition'}</span></li>` : ''}</ul>
    <h3 class="fs-rcf-h">${withBulletin ? 'Exposition und Lawinenbulletin' : 'Exposition der steilen Hänge'}</h3>
    <p class="fs-rc-note">Die Rosette zeigt, in welche Himmelsrichtung die steilen Hänge schauen. Je grösser das Feld, desto länger die Strecke.</p>
    <div class="fs-rc-bottom">
      ${fsRcRoseSvg(m)}
      <div class="fs-rc-bul">${withBulletin ? fsRcBulletinHtml(res, m.b, m.bul, m.auto, m.probs, pts, step, fmtM, fsRcFmtE, m.critLen, m.spots, [0, 1600, 1800, 2000, 2200, 2400, 2600, 2800, 3000]) : ''}</div>
    </div>
    <p class="fs-rc-src">${inCH ? 'Hangneigung: swisstopo (swissALTI3D), im Umkreis von wenigen Metern der Linie.' : 'Hangneigung nur in der Schweiz verfügbar.'} Höhe und Exposition geschätzt (Geländemodell ca. 30 m). Hilft bei der Planung, ersetzt keine Beurteilung vor Ort.</p>`;
}
function fsRcOpenFull(key){
  const res = fsRcCache.get(key), t = (state.tours || []).find(x=> key.indexOf(x.id + ':') === 0);
  if(!res || !res.pts || !t) return;
  const ov = document.createElement('div');
  ov.className = 'fs-rcf';
  ov.innerHTML = `<div class="fs-rcf-top"><button type="button" class="fs-rcf-back" data-rcf="close">‹ Zurück</button><div class="fs-rcf-title"><small>Routen-Check</small>${esc(t.name || '')}</div></div>
    <div class="fs-rcf-scroll"><div class="fs-rcf-map" id="fs-rcf-map"></div>
      <div class="fs-rc fs-rc-full" data-rc="${esc(key)}" data-rc-full="1"><div class="fs-rc-body">${fsRcFullHtml(Object.assign({key}, res), fsRcWithBulletin())}</div></div></div>`;
  document.body.appendChild(ov);
  let map = null, dot = null, sel = -1;
  pushOverlayLayer(()=>{ if(map){ try{ map.remove(); }catch(e){} } ov.remove(); });
  ov.querySelector('[data-rcf="close"]').addEventListener('click', ()=> closeTopOverlayLayer());
  const pts = res.pts, n = pts.length, fmtM = fsRcFmtM, fmtE = fsRcFmtE;
  // Ganze Route (k = -1) und darüber zusammenhängende Abschnitte gleicher Steilheit; einzelne 15-m-Stücke
  // fielen beim Herauszoomen der Vereinfachung zum Opfer
  const feats = ()=>{
    const crit = fsRcCritLabels(res), ll = p=> [p.lon, p.lat];
    const f = [{type:'Feature', properties:{k: -1, c: 0}, geometry:{type:'LineString', coordinates: pts.map(ll)}}];
    let run = null;
    for(let i = 0; i < n - 1; i++){
      const k = pts[i].k || 0, c = crit[i] ? 1 : 0;
      if(!run || run.properties.k !== k || run.properties.c !== c){
        run = {type:'Feature', properties:{k, c}, geometry:{type:'LineString', coordinates:[ll(pts[i])]}};
        f.push(run);
      }
      run.geometry.coordinates.push(ll(pts[i + 1]));
    }
    return {type:'FeatureCollection', features: f};
  };
  // Stelle i zeigen: Lauf-Strich im Profil, Punkt auf der Karte, Werte in Worten
  const show = (i)=>{
    sel = Math.max(0, Math.min(n - 1, i));
    const p = pts[sel], crit = fsRcCritLabels(res)[sel];
    const svg = ov.querySelector('.fs-rcf-prof'), cur = ov.querySelector('[data-rcf="cursor"]');
    if(cur){ const x = (p.d / res.total * 600).toFixed(1); cur.setAttribute('x1', x); cur.setAttribute('x2', x); }
    if(svg) svg.setAttribute('aria-valuenow', Math.round(sel / Math.max(1, n - 1) * 100));
    const read = ov.querySelector('[data-rcf="read"]');
    if(read){
      read.classList.toggle('warn', !!crit);
      read.innerHTML = (crit ? fsIconHtml('alert') : fsIconHtml('ruler')) + '<span><b>' + fmtM(p.d) + '</b> · ' + esc([p.ele != null ? fmtE(p.ele) + ' m' : '', p.k ? FS_RC_CLASSES[p.k - 1].label : 'flacher als 30°', p.ai != null ? FS_RC_ASP_LONG[FS_RC_ASP[p.ai]] : ''].filter(Boolean).join(' · ')) + (crit ? '<em>im Problembereich: ' + esc(crit) + '</em>' : '') + '</span>';
    }
    if(map && dot) dot.setLngLat([p.lon, p.lat]).getElement().style.visibility = 'visible';
  };
  const fromX = (svg, clientX)=>{ const r = svg.getBoundingClientRect(); return Math.round(Math.max(0, Math.min(1, (clientX - r.left) / r.width)) * (n - 1)); };
  ov.addEventListener('pointerdown', e=>{
    const svg = e.target.closest && e.target.closest('.fs-rcf-prof');
    if(!svg) return;
    e.preventDefault();
    try{ svg.setPointerCapture(e.pointerId); }catch(err){}
    show(fromX(svg, e.clientX));
    const mv = ev=> show(fromX(svg, ev.clientX)), up = ()=>{ svg.removeEventListener('pointermove', mv); svg.removeEventListener('pointerup', up); svg.removeEventListener('pointercancel', up); };
    svg.addEventListener('pointermove', mv); svg.addEventListener('pointerup', up); svg.addEventListener('pointercancel', up);
  });
  ov.addEventListener('keydown', e=>{
    if(!e.target.closest || !e.target.closest('.fs-rcf-prof') || (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight')) return;
    e.preventDefault(); show((sel < 0 ? 0 : sel) + (e.key === 'ArrowRight' ? 1 : -1) * Math.max(1, Math.round(n / 50)));
  });
  // Nach dem Neuzeichnen (Bulletin, Expositionen) Stelle und Karte nachführen
  ov.addEventListener('fs-rc-painted', ()=>{ if(sel >= 0) show(sel); try{ if(map && map.getSource('fsrcf')) map.getSource('fsrcf').setData(feats()); }catch(e){} });
  fsmEnsureLoaded().then(()=>{
    if(!document.body.contains(ov)) return;
    const mid = pts[Math.floor(n / 2)];
    map = fsmCreateMap('fs-rcf-map', {center:[mid.lat, mid.lon], zoom: 13, controls: false});
    fsmWhenLoaded(map, ()=>{
      const css = getComputedStyle(document.documentElement), col = k=> css.getPropertyValue('--slope-' + k).trim();
      const byK = ['match', ['get','k'], 1, col(1), 2, col(2), 3, col(3), 4, col(4), col(5)];
      try{
        map.addSource('fsrcf', {type:'geojson', data: feats(), tolerance: 0.2});
        map.addLayer({id:'fsrcf-case', type:'line', source:'fsrcf', filter:['==', ['get','k'], -1], layout:{'line-cap':'round','line-join':'round'}, paint:{'line-color':'#ffffff', 'line-width':10, 'line-opacity':0.85}});
        map.addLayer({id:'fsrcf-base', type:'line', source:'fsrcf', filter:['==', ['get','k'], -1], layout:{'line-cap':'round','line-join':'round'}, paint:{'line-color': css.getPropertyValue('--ink-soft').trim() || '#4A5A64', 'line-width':4}});
        map.addLayer({id:'fsrcf-steep', type:'line', source:'fsrcf', filter:['>', ['get','k'], 0], layout:{'line-cap':'round','line-join':'round'}, paint:{'line-color': byK, 'line-width':6}});
        map.addLayer({id:'fsrcf-crit', type:'line', source:'fsrcf', filter:['==', ['get','c'], 1], paint:{'line-color':'#0F1E27', 'line-width':3, 'line-dasharray':[1, 1.2], 'line-offset':7}});
      }catch(e){}
      fsmFit(map, pts.map(p=> [p.lat, p.lon]), 36, 15);
      dot = fsmAddMarker(map, mid.lat, mid.lon, '<div class="fsfly-dot"></div>', {anchor:'center'});
      dot.getElement().style.visibility = 'hidden';
      if(sel >= 0) show(sel);
      // Route auf der Karte antippen: nächste Stelle
      map.on('click', e=>{
        let best = -1, bd = Infinity;
        pts.forEach((p, i)=>{ const pp = map.project([p.lon, p.lat]), d = (pp.x - e.point.x) ** 2 + (pp.y - e.point.y) ** 2; if(d < bd){ bd = d; best = i; } });
        if(best >= 0 && bd < 40 * 40) show(best);
      });
    });
  }).catch(()=>{ const el = ov.querySelector('.fs-rcf-map'); if(el) el.hidden = true; });
}
function fsRcBulletinHtml(res, b, bul, auto, probs, pts, step, fmtM, fmtE, critLen, spots, minOpts){
  const asp = a=> a.length >= 8 || !a.length ? 'alle Expositionen' : a.map(x=> FS_SLF_ASPECTS[x] || x).join(' ');
  const seg = bul ? `<div class="fs-rc-seg" role="group" aria-label="Bulletin"><button type="button" data-rc-mode="auto" aria-pressed="${auto}">SLF-Bulletin</button><button type="button" data-rc-mode="manual" aria-pressed="${!auto}">Selbst wählen</button></div>` : '';
  if(auto){
    const top = bul.ratings[0];
    const day = (res.slf.cur && res.slf.next) ? `<div class="fs-slf-seg"><button type="button" class="${bul === res.slf.next ? '' : 'on'}" data-slf-day="cur">Heute</button><button type="button" class="${bul === res.slf.next ? 'on' : ''}" data-slf-day="next">Morgen</button></div>` : '';
    const rows = probs.map(pr=>{
      const len = pts.filter(p=> fsRcInProblem(p, pr)).length * step;
      return `<li><span><b>${esc(pr.type)}</b><em>${esc([asp(pr.aspects), pr.lower ? 'über ' + fmtE(pr.lower) + ' m' : pr.upper ? 'unter ' + fmtE(pr.upper) + ' m' : '', pr.later ? 'im Tagesverlauf' : ''].filter(Boolean).join(' · '))}</em></span><strong class="${len ? 'warn' : 'ok'}">${len ? fmtM(len) : 'nicht berührt'}</strong></li>`;
    }).join('');
    return `<p class="fs-rc-h">Lawinenbulletin SLF${bul.region ? ' · ' + esc(bul.region) : ''}</p>
      ${seg}${day}
      ${top ? `<p class="fs-rc-lvl"><span class="fs-slf-dot" style="--lvl:${top.color}; color:${top.level >= 3 ? '#fff' : '#0F1E27'}">${top.level}</span>${esc(top.label)}${top.elev ? ' · ' + esc(top.elev) : ''}<small>gültig bis ${esc(fsSlfFmt(bul.end))}</small></p>` : ''}
      ${rows ? `<ul class="fs-rc-probs">${rows}</ul>` : '<p class="fs-rc-note">Keine ausgeprägten Lawinenprobleme gemeldet.</p>'}
      ${probs.length ? `<p class="fs-rc-verdict ${critLen ? 'warn' : 'ok'}">${critLen
        ? `${fsIconHtml('alert')}Die Route führt auf ${fmtM(critLen)}${spots > 1 ? ' an ' + spots + ' Stellen' : ''} durch Hänge über 30° im Problembereich.`
        : `${fsIconHtml('check')}Die Route berührt keine Hänge über 30° im Problembereich.`}</p>` : ''}
      <p class="fs-rc-note">Abgleich nach Exposition, Höhe und Neigung. Das Bulletin ganz lesen bleibt nötig.</p>`;
  }
  return `<p class="fs-rc-h">Abgleich mit dem Lawinenbulletin</p>
    ${seg}
    <p class="fs-rc-note">${bul ? '' : 'Kein aktuelles SLF-Bulletin für diese Region. '}Kritische Expositionen in der Rosette antippen, Höhe wählen. Gilt heute für alle Touren.</p>
    <label class="fs-rc-lbl" for="fs-rc-min-${esc(String(res.key || ''))}">ab Höhe</label>
    <select id="fs-rc-min-${esc(String(res.key || ''))}" data-rc-min>${minOpts.map(v=> `<option value="${v}" ${(b.minEle || 0) === v ? 'selected' : ''}>${v ? 'über ' + fmtE(v) + ' m' : 'alle Höhen'}</option>`).join('')}</select>
    <p class="fs-rc-verdict ${b.asp.length ? (critLen ? 'warn' : 'ok') : ''}">${!b.asp.length ? 'Noch keine Exposition gewählt.' : critLen
      ? `${fsIconHtml('alert')}Die Route berührt kritische Hänge über 30° auf ${fmtM(critLen)}${spots > 1 ? ' an ' + spots + ' Stellen' : ''}.`
      : `${fsIconHtml('check')}Die Route berührt keine kritischen Hänge über 30°.`}</p>`;
}
// Pro Punkt: Name des Lawinenproblems (bzw. «kritische Exposition» bei «Selbst wählen»), sonst ''
function fsRcCritLabels(res){
  if(!res || !res.pts || !fsRcWithBulletin()) return [];
  const b = fsRcBulletin(), bul = fsRcSlfBul(res.slf), auto = !!(bul && b.mode !== 'manual');
  if(auto){ const probs = fsRcSlfProblems(bul); return res.pts.map(p=>{ const pr = probs.find(x=> fsRcInProblem(p, x)); return pr ? pr.type : ''; }); }
  const crit = new Set(b.asp);
  return res.pts.map(p=> (crit.size && p.k >= 1 && p.ai != null && crit.has(FS_RC_ASP[p.ai]) && (p.ele == null || p.ele >= (b.minEle || 0))) ? 'kritische Exposition' : '');
}
function fsRcWithBulletin(){ return fsAppKey() !== 'wandern'; }
function fsRouteCheckHtml(t){
  const c = fsRcLine(t);
  if(!c) return '';
  const key = fsRcKey(t, c), res = fsRcCache.get(key);
  if(!res) setTimeout(()=> fsRcRun(key, t), 0);
  return `<div class="fs-rc" data-rc="${esc(key)}"><h4 class="fs-rc-title">${fsIconHtml('mountain')}Routen-Check</h4><div class="fs-rc-body">${res ? fsRcBodyHtml(Object.assign({key}, res), fsRcWithBulletin()) : '<p class="fs-rc-note">Hangneigung entlang der Linie wird geladen …</p>'}</div></div>`;
}
function fsRcPaint(key){
  const res = fsRcCache.get(key);
  if(!res) return;
  document.querySelectorAll('.fs-rc[data-rc="' + CSS.escape(key) + '"] .fs-rc-body').forEach(el=>{
    const full = !!el.parentElement.getAttribute('data-rc-full');
    el.innerHTML = (full ? fsRcFullHtml : fsRcBodyHtml)(Object.assign({key}, res), fsRcWithBulletin());
    if(full) el.dispatchEvent(new CustomEvent('fs-rc-painted', {bubbles: true}));
  });
}
async function fsRcRun(key, t){
  if(fsRcCache.has(key) || fsRcRunning.has(key)) return;
  const c = fsRcLine(t);
  if(!c) return;
  fsRcRunning.add(key);
  let res;
  try{ res = await fsRcCompute(c); }catch(e){ res = {error: 'Routen-Check nicht möglich.', retry: true}; }
  // Lawinenbulletin der SLF-Region am höchsten Punkt der Route (nur Skitour/Hochtour, nur Schweiz)
  if(!res.error && res.inCH && fsRcWithBulletin()){
    const top = res.pts.reduce((m, p)=> (p.ele != null && (!m || p.ele > m.ele)) ? p : m, null) || res.pts[0];
    try{ res.slf = await fsSlfForPoint(top.lat, top.lon); }catch(e){ res.slf = null; }
  }
  fsRcRunning.delete(key);
  fsRcCache.set(key, res);
  fsRcPaint(key);
}
document.addEventListener('click', (ev)=>{
  const box = ev.target.closest && ev.target.closest('.fs-rc');
  if(!box) return;
  const key = box.getAttribute('data-rc');
  if(ev.target.closest('[data-rc-open]')){ fsRcOpenFull(key); return; }
  if(ev.target.closest('[data-rc-fly]')){
    const t = (state.tours || []).find(x=> key.indexOf(x.id + ':') === 0);
    if(t) fsFlyOpen(t);
    return;
  }
  const mode = ev.target.closest('[data-rc-mode]');
  if(mode){
    try{ localStorage.setItem('fs-rc-mode', mode.getAttribute('data-rc-mode')); }catch(e){}
    Array.from(fsRcCache.keys()).forEach(fsRcPaint);
    return;
  }
  if(ev.target.closest('[data-slf-day]')){ setTimeout(()=> Array.from(fsRcCache.keys()).forEach(fsRcPaint), 0); return; }
  const asp = ev.target.closest('[data-rc-asp]');
  if(asp){
    const b = fsRcBulletin(), a = asp.getAttribute('data-rc-asp');
    b.asp = b.asp.indexOf(a) >= 0 ? b.asp.filter(x=> x !== a) : b.asp.concat(a);
    fsRcSetBulletin(b);
    Array.from(fsRcCache.keys()).forEach(fsRcPaint);
    return;
  }
  if(ev.target.closest('[data-rc-retry]')){
    fsRcCache.delete(key); fsRcTiles.clear();
    const t = (state.tours || []).find(x=> key.indexOf(x.id + ':') === 0);
    box.querySelector('.fs-rc-body').innerHTML = '<p class="fs-rc-note">Wird geladen …</p>';
    if(t) fsRcRun(key, t);
  }
}, true); // Capture: die Tourenansicht stoppt Klicks (data-stop)
document.addEventListener('keydown', (ev)=>{
  if((ev.key === 'Enter' || ev.key === ' ') && ev.target.closest && ev.target.closest('[data-rc-asp], svg[data-rc-open]')){ ev.preventDefault(); ev.target.dispatchEvent(new MouseEvent('click', {bubbles: true})); }
});
document.addEventListener('change', (ev)=>{
  if(!ev.target.matches || !ev.target.matches('[data-rc-min]')) return;
  const b = fsRcBulletin(); b.minEle = +ev.target.value || 0; fsRcSetBulletin(b);
  Array.from(fsRcCache.keys()).forEach(fsRcPaint);
}, true);

/* ===== Tourenansicht: Abschnitte und Sprungleiste =====
   Reihenfolge: Bilder · Kennzahlen/Status · Beschreibung · Orte · Bedingungen · Anreise · Mehr.
   Leere Abschnitte fallen weg; die Sprungleiste zeigt nur, was es gibt. */
// [Schlüssel, Titel, kurzer Name in der Sprungleiste, Icon]
const FS_TD_SECTIONS = [
  ['beschreibung', 'Beschreibung', 'Info', 'note'], ['erfahrungen', 'Erfahrungen', 'Logbuch', 'users'], ['orte', 'Orte', 'Orte', 'pin'],
  ['bedingungen', 'Bedingungen', 'Wetter', 'partly'], ['anreise', 'Anreise', 'Anreise', 'car'],
  ['mehr', 'Mehr', 'Mehr', 'more']
];
function fsTdSection(key, id, inner, title){
  // inner: HTML oder {html, editOnly} – editOnly: nur im Bearbeiten-Modus sichtbar (z. B. leeres Logbuch)
  const editOnly = !!(inner && typeof inner === 'object' && inner.editOnly);
  if(inner && typeof inner === 'object') inner = inner.html;
  if(!inner || !String(inner).trim()) return '';
  const label = title || (FS_TD_SECTIONS.find(x=> x[0] === key) || [key, key])[1];
  // Gleichlautende Unterüberschrift (z. B. «Bedingungen», «Anreise» aus den Bausteinen) einmal weglassen
  inner = String(inner).replace(new RegExp('<h4([^>]*)>\\s*' + label + '\\s*</h4>', 'i'), '');
  return `<section class="fs-td-sec${editOnly ? ' fs-td-editonly' : ''}" id="td-${key}-${esc(id)}" data-td="${key}"><h3 class="fs-td-h">${label}</h3>${inner}</section>`;
}
// sections: {beschreibung:'html', orte:'html', …} – gibt Sprungleiste + Abschnitte zurück
function fsTdBodyHtml(id, sections){
  const htmlOf = v=> (v && typeof v === 'object') ? v.html : v;
  // Routen-Check unter der Karte, sobald die Tour eine Linie hat
  const rcTour = (typeof state !== 'undefined' && Array.isArray(state.tours)) ? state.tours.find(x=> x.id === id) : null;
  if(rcTour && typeof sections.orte === 'string' && sections.orte.trim()) sections = Object.assign({}, sections, {orte: sections.orte + fsRouteCheckHtml(rcTour)});
  const present = FS_TD_SECTIONS.filter(([k])=> htmlOf(sections[k]) && String(htmlOf(sections[k])).trim());
  // Leiste nur mit Abschnitten, die im Lesemodus sichtbar sind
  const shown = present.filter(([k])=> !(sections[k] && typeof sections[k] === 'object' && sections[k].editOnly));
  const jump = shown.length > 1 ? `<nav class="fs-td-jump" aria-label="Abschnitte" style="--n:${shown.length}">${shown.map(([k, l, short, icon])=>
    `<button type="button" data-act="fs-goto" data-target="td-${k}-${esc(id)}" aria-label="${l}">${fsIconHtml(icon)}<span>${short}</span></button>`).join('')}</nav>` : '';
  return jump + present.map(([k])=> fsTdSection(k, id, sections[k])).join('');
}
function fsTdImagesHtml(t){
  return (t.topoImages && t.topoImages.length) ? `<div class="fs-td-images">${topoImagesGalleryHtml(t.topoImages)}</div>` : '';
}
// «Mehr»: Tour starten, für unterwegs laden, Menüpunkte als Liste
function fsTourMoreHtml(t, moreItems){
  const hasOffline = (tourHasMapData(t) || (t.topoImages && t.topoImages.length)) && fsTourStatus(t) !== 'bereit'; // bereit: steht oben beim Status
  const items = (moreItems || []).filter(Boolean);
  items.push(fsMenuItemHtml('clock', 'Frühere Versionen', `data-act="fs-versions" data-id="${esc(t.id)}"`));
  const onTour = fsGetOnTour();
  const active = !!(onTour && String(onTour.id) === String(t.id));
  return `<div class="fs-actions">
    ${hasOffline ? `<div class="fs-primary">${offlineSectionHtml(t.id)}</div>` : ''}
    <div class="fs-more-list">${items.join('')}</div>
    <button type="button" class="fs-start-btn${active ? ' on' : ''}" data-act="${active ? 'fs-end-tour' : 'fs-start-tour'}" data-id="${t.id}">${fsIconHtml(active ? 'flag' : 'gps')}<span>${active ? 'Unterwegs · Tour beenden' : 'Tour starten'}</span></button>
  </div>`;
}
// "Auf einen Blick": Schlüsselstelle zuerst (das Wichtigste für die Entscheidung im Gelände),
// dann die Fakten als ruhige Zeilen statt je eines eigenen Abschnitts. rows: [[Label, Text]].
function tourGlanceHtml(crux, rows){
  const r = (rows || []).filter(x=> x && x[1]);
  if(!crux && !r.length) return '';
  return `<div class="detail-section fs-glance">
    <h4>Auf einen Blick</h4>
    ${crux ? `<div class="conditions-note fs-crux"><strong>Schlüsselstelle</strong>${esc(crux)}</div>` : ''}
    ${r.length ? `<dl class="fs-facts">${r.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>` : ''}
  </div>`;
}
// Kopf-Knopf "Bearbeiten" als Stift-Symbol (gedrückt halten, siehe HOLD_TO_EDIT_ACTS).
function editIconButtonHtml(act, id){
  return `<button type="button" class="fs-icon-btn" data-act="${act}" data-id="${id}" title="Bearbeiten (gedrückt halten)" aria-label="Bearbeiten, gedrückt halten">${fsIconHtml('edit')}</button>`;
}
// Standort-Chip antippen: Blatt klein machen und auf der Karte dahinter zum Punkt fliegen.
// Ohne Karte dahinter (z. B. Hütte): grosse Karte an dieser Stelle öffnen.
function fsGotoPoint(lat, lon, label){
  if(!isFinite(lat) || !isFinite(lon)) return;
  if(fsCtxMap && document.documentElement.classList.contains('fs-ctx-map')){
    fsSetSheetDetent('peek');
    const pad = {top: 70, left: 30, right: 70, bottom: fsSheetHeightPx('peek') + 20};
    fsCtxMap.flyTo({center: [lon, lat], zoom: Math.max(fsCtxMap.getZoom(), 15), padding: pad, duration: 700});
    fsCtxMap.once('moveend', ()=> fsmPopup(fsCtxMap, {lng: lon, lat}, '<b>' + esc(label || 'Punkt') + '</b>', 30));
    return;
  }
  if(typeof openStandaloneMap === 'function'){
    lastStandaloneMapView = {center: [lat, lon], zoom: 15};
    fsBigGotoView = lastStandaloneMapView;
    openStandaloneMap();
  }
}
document.addEventListener('click', (e)=>{
  const el = e.target.closest && e.target.closest('[data-act="fs-point-goto"]');
  if(!el) return;
  e.stopPropagation();
  fsGotoPoint(parseFloat(el.getAttribute('data-lat')), parseFloat(el.getAttribute('data-lon')), el.getAttribute('data-label'));
}, true);
// Kacheln "Karte"/"Wetter": zum Abschnitt springen; bei "Karte" die Karte gleich anzeigen.
document.addEventListener('click', (e)=>{
  const el = e.target.closest && e.target.closest('[data-act="fs-goto"],[data-act="fs-goto-map"]');
  if(!el) return;
  if(el.getAttribute('data-act') === 'fs-goto-map'){
    const id = el.getAttribute('data-id');
    // Tourenkarte liegt hinter dem Blatt: Blatt klein machen = Karte sehen.
    if(document.documentElement.classList.contains('fs-ctx-map')){ fsSetSheetDetent('peek'); return; }
    const sec = document.getElementById('tour-map-section-' + id);
    if(!sec) return;
    sec.scrollIntoView({behavior:'smooth', block:'start'});
    const mapDiv = document.getElementById('map-tour-' + id);
    const showBtn = sec.querySelector('[data-act="show-map"]');
    if(mapDiv && !mapDiv.children.length && showBtn) showBtn.click();
  }else{
    const target = document.getElementById(el.getAttribute('data-target'));
    if(target) target.scrollIntoView({behavior:'smooth', block:'start'});
  }
}, true); // Capture: Dialoge stoppen Klicks mit data-stop, bevor sie hier unten ankämen
// Status setzen (Knöpfe im Bearbeiten-Modus). Nach dem Halten-Mechanismus registriert, damit
// dessen Capture-Listener den Klick zuerst prüfen kann.
document.addEventListener('click', (e)=>{
  const el = e.target.closest && e.target.closest('[data-act="set-tour-status"]');
  if(!el) return;
  e.stopPropagation();
  toggleTourStatus(el.getAttribute('data-id'), el.getAttribute('data-value'));
}, true);
// "Mehr"-Menü schliessen: nach einer Auswahl oder beim Tippen daneben.
document.addEventListener('click', (e)=>{
  document.querySelectorAll('details.fs-more[open]').forEach(d=>{
    const inMenu = d.querySelector('.fs-more-menu').contains(e.target);
    if(inMenu || !d.contains(e.target)) d.removeAttribute('open');
  });
}, true);

/* ================= Darstellung: Dunkelmodus & hoher Kontrast (Phase 2e) =================
   Standard bleibt hell (auch wenn das Handy dunkel eingestellt ist — die Karte ist hell besser
   lesbar). Beides nur per Schalter im Profil-Menü, gespeichert auf dem Gerät. */
function fsThemePrefs(){
  try{ return JSON.parse(localStorage.getItem('fs-theme') || '{}') || {}; }catch(e){ return {}; }
}
function fsApplyThemeClasses(){
  const p = fsThemePrefs();
  document.documentElement.classList.toggle('fs-dark', !!p.dark);
  document.documentElement.classList.toggle('fs-contrast', !!p.contrast);
}
fsApplyThemeClasses(); // so früh wie möglich, damit nichts hell aufblitzt
function fsEnsureThemeToggles(){
  document.querySelectorAll('.who-menu .who-row').forEach(row=>{
    if(row.querySelector('.fs-theme-toggle')) return;
    [['dark','Dunkelmodus'],['contrast','Hoher Kontrast (Sonne)']].forEach(([key, label])=>{
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'fs-theme-toggle';
      b.setAttribute('role', 'switch');
      const on = !!fsThemePrefs()[key];
      b.setAttribute('aria-checked', on ? 'true' : 'false');
      b.innerHTML = `<span>${label}</span><span class="fs-switch" aria-hidden="true"><span></span></span>`;
      b.addEventListener('click', (e)=>{
        e.preventDefault(); e.stopPropagation();
        const prefs = fsThemePrefs();
        prefs[key] = !prefs[key];
        try{ localStorage.setItem('fs-theme', JSON.stringify(prefs)); }catch(err){}
        b.setAttribute('aria-checked', prefs[key] ? 'true' : 'false');
        fsApplyThemeClasses();
      });
      row.appendChild(b);
    });
  });
}

/* ================= Unterwegs-Modus (Phase 2e) =================
   "Tour starten" merkt sich die Tour (auch nach Neuladen, pro App). Erst dann erscheint SOS
   (beim Planen zuhause braucht es den nicht), oben steht "Unterwegs · Tourname" — ein Tipp
   öffnet die Tour, "Beenden" schliesst den Modus. */
// Welche App gerade läuft: wandern.html setzt APP_KEY selbst, Firnspur/Fixseil erkennt man wie
// bisher an SEKTOREN_PATH (gibt es nur in Fixseil).
function fsAppKey(){
  if(typeof APP_KEY !== 'undefined') return APP_KEY;
  return (typeof SEKTOREN_PATH !== 'undefined') ? 'fixseil' : 'firnspur';
}
function fsGetOnTour(){
  try{
    const v = JSON.parse(localStorage.getItem('fs-on-tour') || 'null');
    return (v && v.app === fsAppKey()) ? v : null;
  }catch(e){ return null; }
}
function fsStartTour(id){
  const t = (state.tours || []).find(x=> String(x.id) === String(id));
  if(!t) return;
  try{ localStorage.setItem('fs-on-tour', JSON.stringify({app: fsAppKey(), id: t.id, name: t.name, startedAt: new Date().toISOString()})); }catch(e){}
  if(typeof render === 'function') render();
  if(document.documentElement.classList.contains('fs-sheet-open')) fsSetSheetDetent('peek');
  showToast('Tour gestartet — SOS ist jetzt unten links. Gute Tour!');
}
function fsEndTour(){
  try{ localStorage.removeItem('fs-on-tour'); }catch(e){}
  if(typeof render === 'function') render();
  showToast('Tour beendet.');
}
function fsApplyOnTour(){
  const on = fsGetOnTour();
  const t = on && typeof state !== 'undefined' ? (state.tours || []).find(x=> String(x.id) === String(on.id)) : null;
  document.documentElement.classList.toggle('fs-on-tour', !!on);
  let pill = document.getElementById('fs-ontour-pill');
  if(!on){ if(pill) pill.remove(); return; }
  const name = t ? t.name : on.name;
  if(!pill){
    pill = document.createElement('div');
    pill.id = 'fs-ontour-pill';
    pill.className = 'fs-ontour-pill';
    pill.innerHTML = `<button type="button" class="fs-ontour-open"><span class="dot"></span><span class="t"></span></button><button type="button" class="fs-ontour-end">Beenden</button>`;
    pill.querySelector('.fs-ontour-open').addEventListener('click', ()=>{
      const cur = fsGetOnTour();
      if(!cur) return;
      if(state.modal && state.modal.type === 'tour-detail' && String(state.modal.payload) === String(cur.id)){ fsSetSheetDetent('half'); return; }
      if(typeof navigateToModal === 'function') navigateToModal({type:'tour-detail', payload: cur.id});
    });
    pill.querySelector('.fs-ontour-end').addEventListener('click', ()=>{ if(confirm('Tour beenden? SOS wird wieder ausgeblendet.')) fsEndTour(); });
    document.body.appendChild(pill);
  }
  const tEl = pill.querySelector('.t');
  const label = 'Unterwegs · ' + name;
  if(tEl.textContent !== label) tEl.textContent = label;
}
document.addEventListener('click', (e)=>{
  const el = e.target.closest && e.target.closest('[data-act="fs-start-tour"],[data-act="fs-end-tour"]');
  if(!el) return;
  e.preventDefault(); e.stopPropagation();
  if(el.getAttribute('data-act') === 'fs-start-tour') fsStartTour(el.getAttribute('data-id'));
  else if(confirm('Tour beenden? SOS wird wieder ausgeblendet.')) fsEndTour();
}, true);

/* ================= Tour als Blatt über der Karte (Phase 2c) =================
   Wie bei Apple Karten: eine geöffnete Tour liegt als Blatt unten, die Übersichtskarte bleibt
   oben sichtbar und bedienbar. Drei Stufen: klein (Name + Chips), halb (Standard), ganz.
   Griff antippen = nächste Stufe, Griff ziehen = hoch/runter, ganz unten weiterziehen schliesst.
   Im Inhalt nach oben scrollen öffnet das Blatt automatisch ganz.
   Umgesetzt über einen MutationObserver auf #modal-root, damit beide Apps (Firnspur/Fixseil)
   ohne eigene Anpassung mitmachen — alle anderen Dialoge bleiben normale Vollbild-Masken. */
let fsSheetDetent = 'half', fsSheetTourId = null, fsSheetSavedScroll = null, fsSheetInnerScroll = 0;
function fsSheetHeightPx(detent){
  const vh = window.innerHeight;
  if(detent === 'peek') return 196;
  if(detent === 'full') return Math.round(vh - Math.min(64, vh * 0.08));
  return Math.round(vh * 0.56);
}
function fsSetSheetDetent(detent){
  fsSheetDetent = detent;
  document.documentElement.dataset.fsDetent = detent;
  document.documentElement.style.setProperty('--fs-sheet-h', fsSheetHeightPx(detent) + 'px');
  const modal = document.querySelector('.overlay.fs-sheet-mode > .modal.td');
  if(modal){
    modal.dataset.detent = detent;
    if(detent !== 'full') modal.scrollTop = 0;
  }
}
function fsWireSheetGrabber(grabber, modal){
  let startY = null, startH = 0, moved = 0;
  grabber.addEventListener('pointerdown', (e)=>{
    startY = e.clientY; startH = modal.getBoundingClientRect().height; moved = 0;
    try{ grabber.setPointerCapture(e.pointerId); }catch(err){}
    document.documentElement.classList.add('fs-sheet-dragging');
  });
  grabber.addEventListener('pointermove', (e)=>{
    if(startY === null) return;
    moved = e.clientY - startY;
    const h = Math.max(120, Math.min(fsSheetHeightPx('full'), startH - moved));
    document.documentElement.style.setProperty('--fs-sheet-h', h + 'px');
  });
  const end = ()=>{
    if(startY === null) return;
    startY = null;
    document.documentElement.classList.remove('fs-sheet-dragging');
    const i = ['peek','half','full'].indexOf(fsSheetDetent);
    if(Math.abs(moved) < 6){
      // Antippen: klein → halb → ganz → halb
      fsSetSheetDetent(fsSheetDetent === 'peek' ? 'half' : fsSheetDetent === 'half' ? 'full' : 'half');
    }else if(moved < -40){
      fsSetSheetDetent(['peek','half','full'][Math.min(2, i + 1)]);
    }else if(moved > 40){
      if(fsSheetDetent === 'peek' && typeof closeModal === 'function'){ fsSetSheetDetent('peek'); closeModal(); }
      else fsSetSheetDetent(['peek','half','full'][Math.max(0, i - 1)]);
    }else{
      fsSetSheetDetent(fsSheetDetent);
    }
  };
  grabber.addEventListener('pointerup', end);
  grabber.addEventListener('pointercancel', end);
}
function fsApplyTourSheetMode(){
  const root = document.getElementById('modal-root');
  if(!root) return;
  const overlay = root.querySelector(':scope > .overlay');
  const modal = overlay ? overlay.querySelector(':scope > .modal.td') : null;
  const html = document.documentElement;
  if(!modal){
    html.classList.remove('fs-sheet-open');
    delete html.dataset.fsDetent;
    // Andere Maske darüber (z. B. Bearbeiten): Karte nur verstecken; ganz zu: weg damit.
    if(overlay) fsHideContextMap(); else fsDestroyContextMap();
    document.querySelectorAll('.map-strip-dot.fs-sel').forEach(d=> d.classList.remove('fs-sel'));
    // Ganz geschlossen (kein Dialog mehr): Liste wieder dort, wo man war.
    if(!overlay && fsSheetSavedScroll !== null){ window.scrollTo(0, fsSheetSavedScroll); fsSheetSavedScroll = null; }
    if(!overlay) fsSheetTourId = null;
    return;
  }
  if(overlay.classList.contains('fs-sheet-mode') && modal.querySelector(':scope > .fs-grabber')){
    // Gleiches Blatt neu gezeichnet ohne neue Daten: nichts zu tun. Sonst Karte auffrischen.
    fsSheetShowContext();
    return;
  }
  if(fsSheetSavedScroll === null) fsSheetSavedScroll = window.scrollY;
  window.scrollTo(0, 0); // Karte oben sichtbar
  html.classList.add('fs-sheet-open');
  overlay.classList.add('fs-sheet-mode');
  const tourId = (typeof state !== 'undefined' && state.modal) ? String(state.modal.payload) : null;
  // Dieselbe Tour neu gezeichnet (z. B. Heute/Morgen, Stern): an derselben Stelle bleiben
  const keepScroll = tourId === fsSheetTourId ? fsSheetInnerScroll : 0;
  if(tourId !== fsSheetTourId){ fsSheetTourId = tourId; fsSheetDetent = 'half'; }
  fsSheetInnerScroll = keepScroll;
  const grabber = document.createElement('button');
  grabber.type = 'button';
  grabber.className = 'fs-grabber';
  grabber.setAttribute('aria-label', 'Blatt grösser oder kleiner');
  modal.insertBefore(grabber, modal.firstChild);
  fsWireSheetGrabber(grabber, modal);
  modal.addEventListener('scroll', ()=>{
    if(fsSheetDetent !== 'full' && modal.scrollTop > 24) fsSetSheetDetent('full');
    fsSheetInnerScroll = modal.scrollTop;
  }, {passive:true});
  // Wie bei Apple: Inhalt ganz oben und weiter nach unten ziehen = Blatt eine Stufe kleiner
  // (auch ohne den Griff zu treffen).
  let pullStartY = null, pullArmed = false;
  modal.addEventListener('touchstart', (e)=>{
    pullStartY = e.touches[0].clientY;
    // Gesten am Griff behandelt der Griff selbst (sonst springt das Blatt zwei Stufen)
    pullArmed = modal.scrollTop <= 0 && !(e.target.closest && e.target.closest('.fs-grabber'));
  }, {passive:true});
  modal.addEventListener('touchmove', (e)=>{
    if(!pullArmed || pullStartY === null) return;
    const dy = e.touches[0].clientY - pullStartY;
    if(dy > 70){
      pullArmed = false;
      fsSetSheetDetent(fsSheetDetent === 'full' ? 'half' : 'peek');
    }
  }, {passive:true});
  modal.addEventListener('touchend', ()=>{ pullStartY = null; pullArmed = false; }, {passive:true});
  fsSetSheetDetent(fsSheetDetent);
  if(keepScroll && fsSheetDetent === 'full'){
    modal.scrollTop = keepScroll;
    // Später nachgeladene Teile (Routen-Check, Wetter) machen das Blatt erst noch länger
    setTimeout(()=>{ if(modal.isConnected && modal.scrollTop < keepScroll - 4) modal.scrollTop = keepScroll; }, 60);
  }
  fsSheetShowContext();
  // Punkt der offenen Tour auf der Karte hervorheben (nach dem Rendern der Karte)
  setTimeout(()=> document.querySelectorAll('.map-strip-dot').forEach(d=> d.classList.toggle('fs-sel', d.getAttribute('data-id') === tourId)), 0);
}
// Karte hinter dem offenen Blatt: bei einer Tour deren Karte, bei einem Gebiet alle seine Touren
// (die App liefert die Inhalte über fsAreaForMap(modal), siehe fsShowAreaContextMap).
function fsSheetShowContext(){
  if(typeof state === 'undefined' || !state.modal) return;
  const area = (typeof fsAreaForMap === 'function') ? fsAreaForMap(state.modal) : null;
  if(area){ fsShowAreaContextMap(area); return; }
  const t = (state.tours || []).find(x=> String(x.id) === String(state.modal.payload));
  if(t) fsShowContextMap(t);
}
/* ================= Eine Tourenkarte hinter dem Blatt (Phase 2, Schritt 3) =================
   Statt mehrerer einzelner Karten (Karte anzeigen, Zustieg, Abstieg, Hütte …) liegt hinter dem
   Tour-Blatt EINE bildschirmfüllende Karte mit allem, was zur Tour gehört: Punkte, GPX-Track,
   geplante Linie, Alternativrouten, eigener Zustieg/Abstieg, die verknüpfte Hütte und deren
   Zustiege. Jede Ebene lässt sich über die Legende oben ein-/ausblenden. Hütten-Zustiege:
   Skitour zeigt zuerst die Winter-, Hochtour die Sommerwege (der andere ist zuschaltbar).
   Der Ausschnitt passt sich so an, dass alles sichtbar ist — nicht näher als Zoom 14. */
const FS_CTX_COLORS = { track:'#E8384F', manual:'#1565C0', access:'#2F7D4A', descent:'#D9730D', hutRoute:'#2F7D4A', hutRouteOther:'#7A8B95' };
let fsCtxMap = null, fsCtxKey = null;
function fsRouteCoords(r){
  return (r && r.trackSimplified && r.trackSimplified.length) ? r.trackSimplified : ((r && r.manualTrack && r.manualTrack.length) ? r.manualTrack : null);
}
function fsTourHut(t){
  return (t && t.hutId && typeof state !== 'undefined' && state.huts) ? state.huts.find(h=>h.id===t.hutId) : null;
}
function fsTourHasContextData(t){
  if(!t) return false;
  if(tourHasMapData(t)) return true;
  if([...(t.accessRoutes||[]), ...(t.descentRoutes||[])].some(fsRouteCoords)) return true;
  if(fsTourOrte(t).some(o=> isFinite(o.lat) && isFinite(o.lon))) return true;
  const hut = fsTourHut(t);
  return !!(hut && ((hut.points && hut.points.length) || (hut.accessRoutes||[]).some(fsRouteCoords)));
}
function fsDestroyContextMap(){
  if(fsCtxMap){ if(fsCtxUsesHome && fsCtxMap === fsHomeMap) fsCtxRelease(); else { try{ fsCtxMap.remove(); }catch(e){} } fsCtxMap = null; }
  fsCtxKey = null;
  const el = document.getElementById('fs-tour-map');
  if(el) el.remove();
  document.documentElement.classList.remove('fs-ctx-map');
}
function fsHideContextMap(){
  const el = document.getElementById('fs-tour-map');
  if(el) el.style.display = 'none';
  document.documentElement.classList.remove('fs-ctx-map');
}
function fsFitContextMap(){
  if(!fsCtxMap || !fsCtxMap._fsCoords) return;
  const bottom = fsSheetHeightPx(fsSheetDetent === 'full' ? 'half' : fsSheetDetent);
  fsmFit(fsCtxMap, fsCtxMap._fsCoords, {top:70, left:30, right:70, bottom: bottom + 20}, 14);
}
function fsShowContextMap(t){
  // Die Grosse Karte hat die Karte gerade: nicht wegnehmen, beim Schliessen kommt sie zurück
  if(fsCtxOwner === 'big'){ fsBigRestoreCtx = true; return; }
  if(!fsTourHasContextData(t)){ fsDestroyContextMap(); return; }
  const key = t.id + '|' + (t.updatedAt || '') + '|' + (fsTourHut(t) ? (fsTourHut(t).updatedAt || '') : '');
  let el = document.getElementById('fs-tour-map');
  if(el && fsCtxKey === key){
    if(el.style.display === 'none'){
      el.style.display = '';
      document.documentElement.classList.add('fs-ctx-map');
      if(fsCtxMap) setTimeout(()=> fsCtxMap.resize(), 0);
    }
    return;
  }
  fsDestroyContextMap();
  fsCtxKey = key;
  el = document.createElement('div');
  el.id = 'fs-tour-map';
  el.className = 'fs-tour-map';
  el.innerHTML = '<div class="fs-tour-map-inner" id="fs-tour-map-inner"></div><div class="fs-ctx-legend" id="fs-ctx-legend"></div>';
  document.body.appendChild(el);
  document.documentElement.classList.add('fs-ctx-map');
  fsmEnsureLoaded().then(()=>{
    if(fsCtxKey !== key || !document.getElementById('fs-tour-map-inner')) return;
    if(fsCtxOwner === 'big'){ fsBigRestoreCtx = true; return; }
    const map = fsCtxAcquire('fs-tour-map-inner', (m)=>{
      const c = m.getCenter();
      fsOpen3d({lat:c.lat, lon:c.lng, zoom:14, tour:t, heading:m.getBearing()});
    });
    fsCtxMap = map;
    fsmWhenLoaded(map, ()=>{
      if(fsCtxMap !== map) return;
      const all = [];
      const groups = [];
      function group(label, color, on, dash){
        const g = {label, color, on, dash, items:[]};
        groups.push(g);
        return g;
      }
      function line(coords, color, opts){
        const l = fsmAddLine(map, coords, {color, dash: opts.dash, label: opts.label});
        opts.group.items.push(l);
        if(!opts.group.on) l.setVisible(false);
        coords.forEach(c=> all.push(c));
      }
      function marker(lat, lon, html, popup, anchor, g){
        const m = fsmAddMarker(map, lat, lon, html, {popup, anchor});
        g.items.push({setVisible:(v)=>{ m.getElement().style.display = v ? '' : 'none'; }});
        all.push([lat, lon]);
      }
      // Tour selbst — in Firnspur nach Art der Route (Aufstieg, Abfahrt, Variante …) gruppiert
      const typed = fsRouteTypesOn();
      const pointsGroup = {items:[], on:true};
      if(typed){
        const byType = {};
        fsTourRoutes(t).forEach(r=>{ (byType[r.type] = byType[r.type] || []).push(r); });
        FS_ROUTE_TYPE_ORDER.forEach(k=>{
          if(!byType[k]) return;
          const st = fsRouteStyle(byType[k][0]);
          const g = group(fsRouteLabel(k), st.color, true, st.dash);
          byType[k].forEach(r=>{ const rs = fsRouteStyle(r); line(r.coords, rs.color, {group:g, dash:rs.dash, label: r.name ? r.name + ' (' + fsRouteLabel(r.type) + ')' : fsRouteLabel(r.type)}); });
        });
      }else{
        const g = group('Tour', FS_CTX_COLORS.track, true);
        if(t.trackSimplified && t.trackSimplified.length) line(t.trackSimplified, FS_CTX_COLORS.track, {group:g, label:'GPX-Track'});
        if(t.manualTrack && t.manualTrack.length) line(t.manualTrack, FS_CTX_COLORS.manual, {group:g, label:'Geplante Linie'});
        const alts = (t.altTracks||[]).filter(a=> a.trackSimplified && a.trackSimplified.length);
        if(alts.length){
          const ag = group('Varianten', ALT_TRACK_COLORS[0], true, true);
          alts.forEach((a,i)=> line(a.trackSimplified, ALT_TRACK_COLORS[i % ALT_TRACK_COLORS.length], {group:ag, dash:true, label:a.name || 'Alternativroute'}));
        }
      }
      const acc = (t.accessRoutes||[]).filter(fsRouteCoords);
      if(acc.length){
        const g = group('Zustieg', FS_CTX_COLORS.access, true);
        acc.forEach(r=> line(fsRouteCoords(r), FS_CTX_COLORS.access, {group:g, label:'Zustieg: ' + (r.name || '')}));
      }
      const desc = (t.descentRoutes||[]).filter(fsRouteCoords);
      if(desc.length){
        const g = group('Abstieg', FS_CTX_COLORS.descent, true);
        desc.forEach(r=> line(fsRouteCoords(r), FS_CTX_COLORS.descent, {group:g, label:'Abstieg: ' + (r.name || '')}));
      }
      // Hütte + deren Zustiege (Saison passend zur App zuerst)
      const hut = fsTourHut(t);
      if(hut){
        const prefSeason = (fsAppKey() === 'firnspur') ? 'winter' : 'sommer';
        const hutRoutes = (hut.accessRoutes||[]).filter(fsRouteCoords);
        const main = hutRoutes.filter(r=> !r.season || r.season === prefSeason);
        const other = hutRoutes.filter(r=> r.season && r.season !== prefSeason);
        const hg = ((hut.points && hut.points.length) || main.length) ? group('Hütte', FS_CTX_COLORS.hutRoute, true) : {items:[], on:true};
        (hut.points||[]).slice(0,1).forEach(p=> marker(p.lat, p.lon, `<div class="fs-hut-marker">${fsIconHtml('hut')}</div>`, esc(hut.name), 'center', hg));
        main.forEach(r=> line(fsRouteCoords(r), FS_CTX_COLORS.hutRoute, {group:hg, label:'Hüttenzustieg: ' + (r.name || '')}));
        if(other.length){
          const og = group(prefSeason === 'winter' ? 'Sommerweg' : 'Winterweg', FS_CTX_COLORS.hutRouteOther, false, true);
          other.forEach(r=> line(fsRouteCoords(r), FS_CTX_COLORS.hutRouteOther, {group:og, dash:true, label:'Hüttenzustieg: ' + (r.name || '')}));
        }
      }
      // Punkte der Tour zuoberst
      (t.points||[]).forEach(p=> marker(p.lat, p.lon, fsmCategoryMarkerHtml(p.category), esc(p.label || t.name), 'bottom', pointsGroup));
      // Legende (nur wenn es mehr als eine Ebene gibt)
      const legend = document.getElementById('fs-ctx-legend');
      if(legend && groups.length > 1){
        groups.forEach(g=>{
          const b = document.createElement('button');
          b.type = 'button';
          b.className = 'fs-ctx-chip' + (g.on ? ' on' : '');
          b.innerHTML = `<span class="sw${g.dash ? ' dash' : ''}" style="--c:${g.color}"></span>${esc(g.label)}`;
          b.addEventListener('click', ()=>{
            g.on = !g.on;
            b.classList.toggle('on', g.on);
            g.items.forEach(it=> it.setVisible(g.on));
          });
          legend.appendChild(b);
        });
      }
      // Orte der Tour immer zeigen, auch ohne eingeschaltete Ebene «Orte»
      map._fsm.orteIds = Array.isArray(t.orte) ? t.orte.slice() : [];
      fsmOrteDraw(map);
      fsTourOrte(t).forEach(o=>{ if(isFinite(o.lat) && isFinite(o.lon)) all.push([+o.lat, +o.lon]); });
      if(all.length){
        map._fsCoords = all;
        fsFitContextMap();
      }
    });
  }).catch(()=>{
    const inner = document.getElementById('fs-tour-map-inner');
    if(inner){ const d = fsTourSketchData(t); inner.innerHTML = fsOfflineSketchHtml(d.lines, d.points); }
  });
}

/* ===== Gebiet als Blatt über der Karte: alle Touren und Hütten des Gebiets =====
   area: {key, name, tours:[Tour], huts:[Hütte], spots:[{lat, lon, label, open:()=>{}}], points:[Punkte des Gebiets]}
   Jede Tour hat eine eigene Farbe; ihr Schild auf der Karte antippen öffnet die Tour. */
function fsAreaHasData(a){
  return (a.points||[]).length || (a.spots||[]).length || (a.huts||[]).some(h=> h.points && h.points.length) || (a.tours||[]).some(t=> tourMapPoint(t) || fsTourRoutes(t).length);
}
function fsShowAreaContextMap(a){
  if(fsCtxOwner === 'big'){ fsBigRestoreCtx = true; return; }
  if(!fsAreaHasData(a)){ fsDestroyContextMap(); return; }
  const stamp = x=> (x.updatedAt || '') + (x.id || '');
  const key = 'area|' + a.key + '|' + [...(a.tours||[]), ...(a.huts||[])].map(stamp).join(',');
  let el = document.getElementById('fs-tour-map');
  if(el && fsCtxKey === key){
    if(el.style.display === 'none'){
      el.style.display = '';
      document.documentElement.classList.add('fs-ctx-map');
      if(fsCtxMap) setTimeout(()=> fsCtxMap.resize(), 0);
    }
    return;
  }
  fsDestroyContextMap();
  fsCtxKey = key;
  el = document.createElement('div');
  el.id = 'fs-tour-map';
  el.className = 'fs-tour-map';
  el.innerHTML = '<div class="fs-tour-map-inner" id="fs-tour-map-inner"></div><div class="fs-ctx-legend" id="fs-ctx-legend"></div>';
  document.body.appendChild(el);
  document.documentElement.classList.add('fs-ctx-map');
  fsmEnsureLoaded().then(()=>{
    if(fsCtxKey !== key || !document.getElementById('fs-tour-map-inner')) return;
    if(fsCtxOwner === 'big'){ fsBigRestoreCtx = true; return; }
    const map = fsCtxAcquire('fs-tour-map-inner', (m)=>{
      const c = m.getCenter();
      const lines = [];
      (a.tours||[]).forEach((t,i)=>{ const col = ACCESS_ROUTE_COLORS[i % ACCESS_ROUTE_COLORS.length]; fsTourRoutes(t).forEach(r=> lines.push({coords:r.coords, color:col})); });
      const pts = (a.tours||[]).map(t=>{ const p = tourMapPoint(t); return p ? {lat:p.lat, lon:p.lon, label:t.name} : null; }).filter(Boolean);
      fsOpen3d({lat:c.lat, lon:c.lng, zoom:13, heading:m.getBearing(), title:a.name, lines, points:pts});
    });
    fsCtxMap = map;
    fsmWhenLoaded(map, ()=>{
      if(fsCtxMap !== map) return;
      const all = [], groups = [];
      const group = (label, color, dash)=>{ const g = {label, color, dash, on:true, items:[]}; groups.push(g); return g; };
      const markerItem = (m)=> ({setVisible:(v)=>{ m.getElement().style.display = v ? '' : 'none'; }});
      const tg = group('Touren', ACCESS_ROUTE_COLORS[0]);
      (a.tours||[]).forEach((t,i)=>{
        const col = ACCESS_ROUTE_COLORS[i % ACCESS_ROUTE_COLORS.length];
        fsTourRoutes(t).forEach(r=>{
          tg.items.push(fsmAddLine(map, r.coords, {color: col, dash: r.src === 'alt', label: t.name}));
          r.coords.forEach(c=> all.push(c));
        });
        // Beschriftung beim Gipfel statt am Start, sonst liegen alle Namen auf dem Parkplatz
        const p = fsTourSummitPoint(t) || tourMapPoint(t);
        if(!p) return;
        const m = fsmAddMarker(map, p.lat, p.lon, `<button type="button" class="fs-area-pin" style="--c:${col}"><span class="sw"></span>${esc(t.name)}</button>`, {anchor:'bottom'});
        m.getElement().addEventListener('click', (e)=>{ e.stopPropagation(); if(typeof openTourDetail === 'function') openTourDetail(t.id); });
        tg.items.push(markerItem(m));
        all.push([p.lat, p.lon]);
      });
      // Gesetzte Punkte (Gipfel, Abseilstelle, Parkplatz …) der Touren, des Gebiets und seiner
      // Sektoren/Gipfel — wie auf der früheren Übersichtskarte
      const pts = [];
      (a.tours||[]).forEach(t=> (t.points||[]).forEach(p=>{ if(p && isFinite(p.lat) && isFinite(p.lon)) pts.push({lat:+p.lat, lon:+p.lon, category:p.category || '', label:p.label || '', owner:t.name}); }));
      (a.extraPoints||[]).forEach(p=> pts.push(p));
      if(pts.length){
        const pg = group('Punkte', '#4A3524');
        pts.forEach(p=>{
          const m = fsmAddMarker(map, p.lat, p.lon, fsmCategoryMarkerHtml(p.category), {anchor:'bottom', popup: `<b>${esc(p.label || 'Punkt')}</b>${p.owner ? '<br/>' + esc(p.owner) : ''}`});
          pg.items.push(markerItem(m));
          all.push([p.lat, p.lon]);
        });
      }
      const huts = (a.huts||[]).filter(h=> h.points && h.points.length);
      if(huts.length){
        const hg = group('Hütten', FS_CTX_COLORS.hutRoute);
        huts.forEach(h=>{
          const p = h.points[0];
          const m = fsmAddMarker(map, p.lat, p.lon, `<button type="button" class="fs-area-pin fs-area-hut">${fsIconHtml('hut')}${esc(h.name)}</button>`, {anchor:'bottom'});
          m.getElement().addEventListener('click', (e)=>{ e.stopPropagation(); if(typeof openHutDetail === 'function') openHutDetail(h.id); });
          hg.items.push(markerItem(m));
          all.push([p.lat, p.lon]);
        });
      }
      if((a.spots||[]).length){
        const sg = group(a.spotsLabel || 'Sektoren', '#7A8B95');
        a.spots.forEach(sp=>{
          const m = fsmAddMarker(map, sp.lat, sp.lon, `<button type="button" class="fs-area-pin fs-area-spot">${esc(sp.label)}</button>`, {anchor:'bottom'});
          m.getElement().addEventListener('click', (e)=>{ e.stopPropagation(); if(sp.open) sp.open(); });
          sg.items.push(markerItem(m));
          all.push([sp.lat, sp.lon]);
        });
      }
      const pg = {items:[]};
      (a.points||[]).forEach(p=>{ pg.items.push(markerItem(fsmAddMarker(map, p.lat, p.lon, fsmCategoryMarkerHtml(p.category), {popup: esc(p.label || a.name), anchor:'bottom'}))); all.push([p.lat, p.lon]); });
      const legend = document.getElementById('fs-ctx-legend');
      if(legend && groups.length > 1){
        groups.forEach(g=>{
          const b = document.createElement('button');
          b.type = 'button';
          b.className = 'fs-ctx-chip on';
          b.innerHTML = `<span class="sw${g.dash ? ' dash' : ''}" style="--c:${g.color}"></span>${esc(g.label)}`;
          b.addEventListener('click', ()=>{ g.on = !g.on; b.classList.toggle('on', g.on); g.items.forEach(it=> it.setVisible(g.on)); });
          legend.appendChild(b);
        });
      }
      if(all.length){ map._fsCoords = all; fsFitContextMap(); }
    });
  }).catch(()=>{
    const inner = document.getElementById('fs-tour-map-inner');
    if(inner){
      const lines = [], points = [];
      (a.tours || []).forEach(x=>{ const d = fsTourSketchData(x); d.lines.forEach(l=> lines.push(l)); });
      (a.points || []).filter(p=> p && isFinite(p.lat) && isFinite(p.lon)).forEach(p=> points.push({lat:+p.lat, lon:+p.lon, category:p.category || '', label:p.label || ''}));
      inner.innerHTML = fsOfflineSketchHtml(lines, points);
    }
  });
}

window.addEventListener('resize', ()=>{ if(document.documentElement.classList.contains('fs-sheet-open')) fsSetSheetDetent(fsSheetDetent); });
(function fsWatchModalRoot(){
  // Ganze Seite beobachten (die Apps bauen #modal-root beim Rendern teils neu auf), aber die
  // Prüfung höchstens einmal pro Bild ausführen.
  let queued = false;
  const start = ()=>{
    new MutationObserver((muts)=>{
      // Änderungen innerhalb der Tourenkarte selbst (Kacheln laden) ignorieren
      const ctx = document.getElementById('fs-tour-map');
      if(ctx && muts.every(m=> ctx.contains(m.target))) return;
      if(queued) return;
      queued = true;
      requestAnimationFrame(()=>{ queued = false; fsUpgradeFilterRows(); fsApplyTourSheetMode(); fsApplyEditMode(); fsApplyOnTour(); fsEnsureThemeToggles(); fsTravelAutoFill(); });
    }).observe(document.body, {childList:true, subtree:true});
    fsUpgradeFilterRows();
    fsApplyTourSheetMode();
    fsApplyEditMode();
    fsApplyOnTour();
    fsEnsureThemeToggles();
  };
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();

async function refreshOfflineSectionUI(offlineId){
  const bodyEl = document.getElementById('offline-body-' + offlineId);
  if(!bodyEl) return;
  const status = await getTourOfflineStatus(offlineId);
  if(status){
    bodyEl.innerHTML = `
      <p style="font-size:13px; color:var(--ok); margin:0 0 8px 0;">✓ ${formatOfflineRemaining(status.expiresAt)}</p>
      <div style="display:flex; gap:8px; flex-wrap:wrap;">
        <button type="button" class="btn secondary" id="gps-toggle-${offlineId}" data-act="toggle-live-gps" data-offline-id="${offlineId}">📍 Standort auf Karte zeigen</button>
        <button type="button" class="btn secondary" data-act="delete-offline" data-offline-id="${offlineId}" style="color:var(--danger);">🗑️ Offline-Daten löschen</button>
      </div>
    `;
  }else{
    bodyEl.innerHTML = `
      <p style="font-size:13px; color:var(--ink-soft); margin:0 0 8px 0;">Lädt Kartenausschnitt und Bilder herunter, ${OFFLINE_DAYS} Tage offline verfügbar — praktisch, bevor's losgeht.</p>
      <button type="button" class="btn secondary" id="download-offline-btn-${offlineId}" data-act="download-offline" data-offline-id="${offlineId}">🔽 Für unterwegs herunterladen</button>
    `;
  }
}

/* ================= Web-Share-Target: Fotos/Links aus anderen Apps direkt hier landen =====
   Android/Chrome schickt geteilte Inhalte per POST an share-target-*.html (siehe manifest*.json).
   sw.js fängt diesen POST ab, legt Text/Datei kurz im Cache ab und leitet auf ?shared=1 um.
   checkSharedContent() holt die Daten hier wieder ab — einmalig, danach wird der Cache geleert. */
const SHARE_TARGET_CACHE = 'share-target-v1';

async function checkSharedContent(){
  if(!('caches' in window)) return null;
  if(!location.search.includes('shared=1')) return null;
  history.replaceState(null, '', location.pathname);
  try{
    const cache = await caches.open(SHARE_TARGET_CACHE);
    const dataRes = await cache.match('/__shared-data');
    if(!dataRes) return null;
    const data = await dataRes.json();
    let fileBlob = null;
    if(data.fileCount > 0){
      const fileRes = await cache.match('/__shared-file-0');
      if(fileRes) fileBlob = await fileRes.blob();
    }
    await cache.delete('/__shared-data');
    for(let i=0; i<data.fileCount; i++) await cache.delete('/__shared-file-' + i);
    if(!fileBlob && !data.text && !data.url) return null;
    return { text: data.text || '', url: data.url || '', title: data.title || '', fileBlob };
  }catch(e){
    dlog('Geteilter Inhalt konnte nicht gelesen werden: ' + (e.message || e), 'err');
    return null;
  }
}

function openShareImportModal(shared){
  state.modal = { type: 'share-import', payload: shared };
  render();
}

function shareImportModalHtml(shared){
  const hasImage = !!shared.fileBlob;
  const linkText = shared.url || shared.text || '';
  const hasSektoren = typeof state.sektoren !== 'undefined';
  let body = '';
  if(hasImage){
    const objUrl = URL.createObjectURL(shared.fileBlob);
    if(hasSektoren && state.sektoren.length){
      body = `
        <img src="${objUrl}" style="width:100%; max-height:260px; object-fit:cover; border-radius:var(--radius); border:1px solid var(--line); margin-bottom:14px;"/>
        <div class="field"><label>Als Topo-Bild verwenden für Sektor …</label>
          <select id="share-import-sektor-select">
            ${state.sektoren.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}
          </select>
        </div>
        <button type="button" class="btn" id="share-import-image-btn" style="width:100%; margin-top:6px;">🧗 Als Topo-Bild übernehmen</button>
      `;
    }else{
      body = `
        <img src="${objUrl}" style="width:100%; max-height:260px; object-fit:cover; border-radius:var(--radius); border:1px solid var(--line); margin-bottom:14px;"/>
        <p style="font-size:13px; color:var(--ink-soft);">Geteilte Fotos werden in dieser App aktuell nicht weiterverarbeitet — dieses Feature gibt es bisher nur bei Kletter-Sektoren (Hochtour/MSL-App).</p>
      `;
    }
  }else if(linkText){
    body = `
      <div class="field"><label>Geteilter Link/Text</label>
        <p class="mono" style="font-size:12.5px; word-break:break-all; background:var(--ice-light); border-radius:var(--radius); padding:8px;">${esc(linkText)}</p>
      </div>
      ${state.tours.length ? `
        <div class="field"><label>Als GPX-Link speichern für Tour …</label>
          <select id="share-import-tour-select">
            ${state.tours.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}
          </select>
        </div>
        <button type="button" class="btn" id="share-import-link-btn" style="width:100%; margin-top:6px;">🔗 Als GPX-Link übernehmen</button>
      ` : `<p style="font-size:13px; color:var(--ink-soft);">Noch keine Tour vorhanden, der der Link zugeordnet werden könnte.</p>`}
    `;
  }else{
    body = `<p style="font-size:13px; color:var(--ink-soft);">Kein verwertbarer Inhalt empfangen.</p>`;
  }
  return `<div class="modal" data-stop="1">
    <div class="modal-head"><h2>📥 Geteilter Inhalt</h2><button class="x-btn" data-act="close-modal">×</button></div>
    ${body}
    <div class="form-actions"><button type="button" class="btn secondary" data-act="close-modal">Schliessen</button></div>
  </div>`;
}

function wireShareImportModal(){
  const imgBtn = document.getElementById('share-import-image-btn');
  if(imgBtn) imgBtn.addEventListener('click', ()=>{
    const sel = document.getElementById('share-import-sektor-select');
    const sektorId = sel ? sel.value : '';
    const shared = state.modal && state.modal.payload;
    if(!sektorId || !shared || !shared.fileBlob) return;
    applySharedImageToSektor(sektorId, shared.fileBlob);
  });
  const linkBtn = document.getElementById('share-import-link-btn');
  if(linkBtn) linkBtn.addEventListener('click', ()=>{
    const sel = document.getElementById('share-import-tour-select');
    const tourId = sel ? sel.value : '';
    const shared = state.modal && state.modal.payload;
    const link = shared ? (shared.url || shared.text || '') : '';
    if(!tourId || !link) return;
    submitShareImportGpxLink(tourId, link);
  });
}

// Öffnet den bestehenden Topo-&-Routen-Bereich eines Sektors und speist das geteilte Foto
// direkt in den vorhandenen Upload-Ablauf ein (Zuschneiden/Komprimieren/Hochladen) — per
// DataTransfer wird die Bild-Datei so ins Datei-Feld gelegt, als hätte man sie ausgewählt.
function applySharedImageToSektor(sektorId, blob){
  resetModalDirty(); // Teilen-Fenster ist erledigt
  openEditSektorTopoRouten(sektorId);
  const input = document.getElementById('sektor-topo-image-input');
  if(!input){ showToast('Sektor-Bearbeitung konnte nicht geöffnet werden.', true); return; }
  try{
    const dt = new DataTransfer();
    dt.items.add(new File([blob], 'geteiltes-foto.jpg', { type: blob.type || 'image/jpeg' }));
    input.files = dt.files;
    handleTopoImageUpload(input, 'sektor-id-for-topo', 'sektor-topo-images-hidden', 'sektor-topo-image-status');
  }catch(e){
    showToast('Geteiltes Foto konnte nicht übernommen werden: ' + (e.message || e), true);
  }
}

async function submitShareImportGpxLink(tourId, link){
  const t = state.tours.find(x=>x.id===tourId);
  if(!t){ showToast('Tour nicht gefunden.', true); return; }
  // Ein vorhandener GPX-Link bleibt, der neue kommt unter «Weitere Links» dazu
  fsAddLink(t, 'gpxLink', link);
  t.updatedAt = new Date().toISOString();
  t.updatedBy = state.myName;
  closeModal(false, true, true);
  state.modal = { type:'tour-detail', payload:t.id };
  render();
  const ok = await saveTourCloud(t).catch(()=>false);
  t._unsynced = !ok;
  if(!ok){
    markUnsaved();
    showToast('GPX-Link ist lokal gespeichert, konnte aber nicht synchronisiert werden. Prüfe deine Internetverbindung.', true);
  }else{
    showToast('GPX-Link gespeichert und synchronisiert.');
  }
  render();
}


