function resetHutFilters(){
  state.activeHutRegionFilters.clear();
  state.activeHutDiffFilters.clear();
  state.activeHutApproachTypeFilters.clear();
  state.activeHutStaffedMonthFilters.clear();
  state.activeHutWinterraumMonthFilters.clear();
  render();
}

function setSearch(v){ state.search = v; render(); }

function filteredHuts(){
  let list = state.huts;
  if(state.activeHutRegionFilters.size){
    list = list.filter(h=>state.activeHutRegionFilters.has(h.region));
  }
  if(state.activeHutDiffFilters.size){
    list = list.filter(h=>state.activeHutDiffFilters.has(h.accessDifficultySummer) || state.activeHutDiffFilters.has(h.accessDifficultyWinter) || state.activeHutDiffFilters.has(h.accessDifficultySummerT));
  }
  if(state.activeHutApproachTypeFilters.size){
    list = list.filter(h=>(h.approachTypes||[]).some(v=>state.activeHutApproachTypeFilters.has(v)));
  }
  if(state.activeHutStaffedMonthFilters.size){
    list = list.filter(h=>[...(h.staffedMonths||[]), ...(h.staffedMonthsPartial||[])].some(m=>state.activeHutStaffedMonthFilters.has(m)));
  }
  if(state.activeHutWinterraumMonthFilters.size){
    list = list.filter(h=>[...(h.winterraumMonths||[]), ...(h.winterraumMonthsPartial||[])].some(m=>state.activeHutWinterraumMonthFilters.has(m)));
  }
  if(state.search.trim()){
    const q = state.search.trim().toLowerCase();
    list = list.filter(h=> (h.name||'').toLowerCase().includes(q) || (h.region||'').toLowerCase().includes(q));
  }
  return sortHuts(list);
}

function huettenViewHtml(){
  const list = filteredHuts();
  const activeFilterCount = state.activeHutRegionFilters.size + state.activeHutDiffFilters.size + state.activeHutApproachTypeFilters.size + state.activeHutStaffedMonthFilters.size + state.activeHutWinterraumMonthFilters.size;
  const usedHutRegions = Array.from(new Set(state.huts.map(h=>h.region).filter(Boolean))).sort((a,b)=>a.localeCompare(b,'de'));
  const allDiffCodes = [...DIFF_ORDER, ...HIKE_SCALE_ORDER];
  return stageLayoutHtml(mapStripHtml({label:'Hütten auf der Karte', kind:'hut', points: list.filter(h=>h.points&&h.points.length).map(h=>({id:h.id, lat:h.points[0].lat, lon:h.points[0].lon, label:h.name})), emptyText:'Noch keine Hütte mit Kartenpunkt erfasst.', openPinId: state._mapStripOpenPinId}), `
    <div class="toolbar">
      <input class="search-input" type="text" placeholder="Hütte oder Region suchen…" value="${esc(state.search)}" data-act="search"/>
      <button class="btn fs-fab" data-act="add-hut">+ Neue Hütte</button>
      <button class="btn secondary" data-act="open-standalone-map">🗺️ Karte</button>
    </div>
    <div class="toolbar toolbar-row">
      <button type="button" class="btn secondary" id="hut-filter-toggle-btn">${fsIconHtml('sliders')} Filter${activeFilterCount ? ` (${activeFilterCount})` : ''}</button>
      ${sortControlHtml('hut', HUT_SORT_OPTIONS, state.hutSortBy, state.hutSortDir)}
    </div>
    <div id="hut-filter-panel" style="display:${state.hutFilterPanelOpen ? '' : 'none'}; margin-bottom:14px;">
      ${usedHutRegions.length ? `<div class="field"><label>Region</label>
        <div class="chips">
          ${usedHutRegions.map(r=>`<button class="chip ${state.activeHutRegionFilters.has(r)?'on':''}" style="${state.activeHutRegionFilters.has(r)?'background:var(--ice-deep)':''}" data-act="filter-hut-region" data-region="${esc(r)}">${esc(r)}</button>`).join('')}
        </div>
      </div>` : ''}
      <div class="field"><label>Schwierigkeit (Zustieg, SAC oder T)</label>
        <div class="chips">
          ${allDiffCodes.map(c=>`<button class="chip ${state.activeHutDiffFilters.has(c)?'on':''}" style="${state.activeHutDiffFilters.has(c)?'background:var(--ice-deep)':''}" data-act="filter-hut-diff" data-code="${c}">${c}</button>`).join('')}
        </div>
      </div>
      <div class="field"><label>Art der Anfahrt</label>
        <div class="chips">
          ${Object.keys(APPROACH_TYPE_LABELS).map(v=>`<button class="chip ${state.activeHutApproachTypeFilters.has(v)?'on':''}" style="${state.activeHutApproachTypeFilters.has(v)?'background:var(--ice-deep)':''}" data-act="filter-hut-approach-type" data-value="${v}">${APPROACH_TYPE_LABELS[v]}</button>`).join('')}
        </div>
      </div>
      <div class="field"><label>Bewartet in Monat(en)</label>
        <div class="chips">
          ${MONTHS.map(m=>`<button class="chip ${state.activeHutStaffedMonthFilters.has(m.key)?'on':''}" style="${state.activeHutStaffedMonthFilters.has(m.key)?'background:var(--ok)':''}" data-act="filter-hut-staffed-month" data-month="${m.key}">${m.label}</button>`).join('')}
        </div>
      </div>
      <div class="field"><label>Schutzraum offen in Monat(en)</label>
        <div class="chips">
          ${MONTHS.map(m=>`<button class="chip ${state.activeHutWinterraumMonthFilters.has(m.key)?'on':''}" style="${state.activeHutWinterraumMonthFilters.has(m.key)?'background:var(--ice-deep)':''}" data-act="filter-hut-winterraum-month" data-month="${m.key}">${m.label}</button>`).join('')}
        </div>
      </div>
      ${activeFilterCount ? `<button type="button" class="btn secondary" style="font-size:12.5px; padding:6px 12px;" data-act="reset-hut-filters">Filter zurücksetzen</button>` : ''}
    </div>
    ${list.length ? `<div class="grid">${list.map(hutCardHtml).join('')}</div>` : emptyHuts()}
  `);
}

function refreshExportText(){
  const ta = document.getElementById('export-text');
  if(ta) ta.value = JSON.stringify(buildExportData(), null, 2);
}

function nameModalHtml(){
  const errorMsg = state.modal && state.modal.error;
  return `<div class="modal" data-stop="1">
    <div class="modal-head"><h2>Wie heisst du?</h2></div>
    <p style="font-size:14px; color:var(--ink-soft); margin:0 0 10px 0;">Dein Name wird bei Touren und Hütten angezeigt, die du hinzufügst oder bearbeitest.</p>
    <div class="field"><label>Name</label><input type="text" id="name-input" value="${esc((state.myName||''))}" placeholder="z. B. Simone" autofocus/></div>
    <div class="field"><label>Passwort</label><input type="password" id="name-pin-input" placeholder="frei wählbar"/></div>
    <p style="font-size:12px; color:var(--ink-faint); margin:0 0 14px 0;">Schützt deinen Namen vor Verwechslungen: Beim ersten Mal legst du hier ein Passwort für diesen Namen fest — danach brauchst du es, um wieder als "dieser Name" zu gelten (auch auf einem anderen Gerät).</p>
    ${errorMsg ? `<p style="color:var(--danger); font-size:13px; margin:0 0 14px 0;">${esc(errorMsg)}</p>` : ''}
    <div class="form-actions">
      <button class="btn secondary" data-act="close-modal">Abbrechen</button>
      <button class="btn" data-act="submit-name">Weiter</button>
    </div>
  </div>`;
}

function buildPersonGroups(){
  const groups = {};
  state.tours.forEach(t=>{
    (t.completions||[]).forEach(c=>{
      const name = (c.by||'').trim() || '?';
      if(!groups[name]) groups[name] = {tours:[], huts:[]};
      if(!groups[name].tours.find(x=>x.id===t.id)) groups[name].tours.push(t);
    });
  });
  state.huts.forEach(h=>{
    (h.completions||[]).forEach(c=>{
      const name = (c.by||'').trim() || '?';
      if(!groups[name]) groups[name] = {tours:[], huts:[]};
      if(!groups[name].huts.find(x=>x.id===h.id)) groups[name].huts.push(h);
    });
  });
  return groups;
}

function toggleEmergencyCard(){
  if(state.modal && state.modal.type==='emergency'){ closeModal(); }
  else{ state.modal = {type:'emergency'}; render(); }
}

/* ===== Diagnose einblenden: Adresse mit ?diagnose öffnen ===== */
(function(){
  const show = ()=>{ if(/[?&]diagnose\b/.test(location.search)){ const b = document.getElementById('debug-toggle-btn'); if(b) b.style.display = 'block'; } };
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', show); else show();
})();
